INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数位", "is_correct": true, "explanation": "数位：数中每一个数码所占的位置，一万有五位。"}, {"text": "数轴", "is_correct": false, "explanation": "语义：数轴是画出来的直线，用来表示数的大小，不能数“五个”。"}, {"text": "数列", "is_correct": false, "explanation": "语义：数列是按顺序排列的一串数，一万不能有五个数列。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”不用“个”计数，不能说“五个数量”。"}], "explanations": {"数位": "数位：数中每一个数码所占的位置，一万有五位。", "数轴": "语义：数轴是画出来的直线，用来表示数的大小，不能数“五个”。", "数列": "语义：数列是按顺序排列的一串数，一万不能有五个数列。", "数量": "搭配：“数量”不用“个”计数，不能说“五个数量”。"}, "sentence_index": 0, "correct_answer": "数位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中的数位很靠前。", "explanation": "这里应该用〈名次〉。“数位”指数中某一位的位置，不指比赛中的排名。"}, {"text": "这张地图标出了每个城市的数位。", "explanation": "这里应该用〈位置〉。“数位”只指数字中每一位的位置，不指城市的地点。"}, {"text": "这个数的数位是四。", "explanation": "这里应该用〈位数〉。“位数”指数有几位，“数位”指某一位的位置，不能说“是四”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数位", "is_correct": true, "explanation": "数位：数中每一个数码所占的位置，最高的那一位就是最高数位。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“最高”不修饰学科名称，不能说“最高数学”。"}, {"text": "数据", "is_correct": false, "explanation": "语义：数据指一组用于分析的资料，不是数中的某一位。"}, {"text": "数论", "is_correct": false, "explanation": "语义：数论是数学的一个分支，不指数字中的位置。"}], "explanations": {"数位": "数位：数中每一个数码所占的位置，最高的那一位就是最高数位。", "数学": "搭配：“最高”不修饰学科名称，不能说“最高数学”。", "数据": "语义：数据指一组用于分析的资料，不是数中的某一位。", "数论": "语义：数论是数学的一个分支，不指数字中的位置。"}, "sentence_index": 6, "correct_answer": "数位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一万的数位很大，比一千还大。", "explanation": "这里应该用〈数值〉。“数值”指数的大小，“数位”指数中每一位的位置，不能说“很大”。"}, {"text": "黑板上写着一个数位，是他的名字。", "explanation": "这里应该用〈名字〉。“数位”指数中某一位的位置，不指人的名字。"}, {"text": "那个数的数位很重要，是最关键的一个。", "explanation": "这里应该用〈地位〉。“地位”指在某个范围中的重要程度，“数位”指数中某一位的位置，不能说“很重要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个数的每只数位上都有数字。", "corrected_sentence": "这个数的每个数位上都有数字。", "error_description": "量词错误：“每”后面的“数位”应用“个”计量，“只”用于动物，应改为“每个数位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们写出这个数每条数位上的数字。", "corrected_sentence": "老师让我们写出这个数每个数位上的数字。", "error_description": "量词错误：「数位」用「个」计量，不能说「每条数位」，应改为「每个数位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
