INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97284, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "书面约定；契约文书。", "primary_collocate": null, "pronunciation": "shū yuē", "ipa": "ʂu˥ yɛ˥", "syllable_count": 2, "sentences": [{"text": "博物馆里有一份清朝的书约。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份书约把房子的价钱写得很清楚。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人拿出书约，证明地是他家的。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书约上有双方的名字和日期。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民和地主签下书约，每年交粮食。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份书约已经有一百多年了。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书约里加了一句话，大家都同意。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照书约，店铺明年要还给原来的主人。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者正在研究这些古代的书约。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书约一式两份，每人拿一份。", "target_word": "书约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份书约", "label": "量词"}, {"form": "一张书约", "label": "量词"}], "register": "书面", "sense_fingerprint": "契约文书，多指旧时的合同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书约", "is_correct": true, "explanation": "正确：书约指旧时的契约文书，博物馆里陈列的清朝文书正属此类。"}, {"text": "手机", "is_correct": false, "explanation": "语义：清朝没有手机，不可能是清朝的东西。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：清朝没有电脑，与“清朝的”明显冲突。"}, {"text": "聊天记录", "is_correct": false, "explanation": "语义：清朝没有网络聊天，聊天记录不可能是清朝的东西。"}], "explanations": {"书约": "正确：书约指旧时的契约文书，博物馆里陈列的清朝文书正属此类。", "手机": "语义：清朝没有手机，不可能是清朝的东西。", "电脑": "语义：清朝没有电脑，与“清朝的”明显冲突。", "聊天记录": "语义：清朝没有网络聊天，聊天记录不可能是清朝的东西。"}, "sentence_index": 0, "correct_answer": "书约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校给每个学生发了一张书约，上面写着考试成绩。", "explanation": "这里应该用〈成绩单〉。书约是双方约定的契约文书，写考试成绩的单子不是书约。"}, {"text": "奶奶把每天的心情写成书约，留给孙女看。", "explanation": "这里应该用〈日记〉。书约是双方共同约定的文书，个人记录心情不能称作书约。"}, {"text": "那份书约只是口头的，并没有写下来。", "explanation": "这里应该用〈约定〉。书约指书面的约定或契约文书，口头说好的事用〈约定〉，不能说书约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书约", "is_correct": true, "explanation": "正确：书约是契约文书，可以在其中加写一句话，经双方同意后生效，句中语境正合。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是医疗记录，不能由大家一起加话表决。"}, {"text": "日记", "is_correct": false, "explanation": "语义：日记是个人记录，不需要大家都同意，与共同约定的语境不符。"}, {"text": "相册", "is_correct": false, "explanation": "搭配：相册里放的是照片，“加一句话，大家都同意”不成搭配。"}], "explanations": {"书约": "正确：书约是契约文书，可以在其中加写一句话，经双方同意后生效，句中语境正合。", "病历": "语义：病历是医疗记录，不能由大家一起加话表决。", "日记": "语义：日记是个人记录，不需要大家都同意，与共同约定的语境不符。", "相册": "搭配：相册里放的是照片，“加一句话，大家都同意”不成搭配。"}, "sentence_index": 6, "correct_answer": "书约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他寄来一张书约，邀请我参加婚礼。", "explanation": "这里应该用〈请柬〉。书约是双方约定的文书，邀请人参加婚礼要用〈请柬〉，不能说书约。"}, {"text": "他每天晚上睡觉前都读一章书约。", "explanation": "这里应该用〈书〉。书约是契约文书，不是按章阅读的书。"}, {"text": "这本书约很有趣，讲了一个侦探的故事。", "explanation": "这里把“书约”当成了〈书籍〉。书约指契约文书，不是讲故事的书，所以不能说有趣，也不能讲故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只书约是清朝留下来的，很珍贵。", "corrected_sentence": "这份书约是清朝留下来的，很珍贵。", "error_description": "量词错误：“书约”是纸面文书，应该用“份”或“张”计量，不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看了过这份书约，内容很清楚。", "corrected_sentence": "我看过这份书约，内容很清楚。", "error_description": "“了”与“过”重复：“过”已表示经历，不能再加“了”，应说“看过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
