INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧时民间秘密组织的称呼。", "primary_collocate": null, "pronunciation": "huì mén", "ipa": "xweɪ˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "旧时人们把民间的秘密组织叫会门。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上说，会门曾在各地出现。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝末年，南方有很多会门。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会门这个名字，现在很少有人用了。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了会门的来历。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的会门是为了反对官府才成立的。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在旧社会，穷人常常加入会门求帮助。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者写过一篇关于会门的文章。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会门多半在民间活动，外人很难知道。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电影里演了一个会门的头目。", "target_word": "会门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个会门", "label": "量词"}], "register": "书面", "sense_fingerprint": "旧时对民间秘密组织的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会门", "is_correct": true, "explanation": "正确：会门是旧时对民间秘密组织的称呼，句中“旧时……叫会门”正合。"}, {"text": "学校", "is_correct": false, "explanation": "语义：秘密组织不能叫作学校，两者性质不同。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：秘密组织不能叫作饭店，与语境明显不合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，不是秘密组织的名称，与句意不符。"}], "explanations": {"会门": "正确：会门是旧时对民间秘密组织的称呼，句中“旧时……叫会门”正合。", "学校": "语义：秘密组织不能叫作学校，两者性质不同。", "饭店": "语义：秘密组织不能叫作饭店，与语境明显不合。", "医院": "语义：医院是治病的地方，不是秘密组织的名称，与句意不符。"}, "sentence_index": 0, "correct_answer": "会门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在墙上看到一根会门。", "explanation": "这里量词用错。会门指团体，应该用〈个〉计量，“根”多用于细长的东西。"}, {"text": "他从小在会门读书，学到很多知识。", "explanation": "会门指旧时的秘密组织，不是读书的地方，这里把它当成了学校，用法不对。"}, {"text": "这个会门公开招收会员，每年都举办展览。", "explanation": "这里应该用〈社团〉。会门是秘密组织，不公开招收会员、举办展览；公开的团体才用〈社团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会门", "is_correct": true, "explanation": "正确：旧时穷人加入的民间互助组织正称会门，句中语境正合。"}, {"text": "公园", "is_correct": false, "explanation": "配价：“加入”后接的是团体，公园不是可以加入求帮助的组织。"}, {"text": "学堂", "is_correct": false, "explanation": "语义：学堂是教书读书的地方，不是穷人求帮助的组织。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，穷人不会靠加入银行来求帮助。"}], "explanations": {"会门": "正确：旧时穷人加入的民间互助组织正称会门，句中语境正合。", "公园": "配价：“加入”后接的是团体，公园不是可以加入求帮助的组织。", "学堂": "语义：学堂是教书读书的地方，不是穷人求帮助的组织。", "银行": "语义：银行是金融机构，穷人不会靠加入银行来求帮助。"}, "sentence_index": 6, "correct_answer": "会门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在的公司也叫会门，大家一起开会。", "explanation": "这里把“会门”用来指现代的商业团体，但会门是旧时民间秘密组织的称呼，商业团体应称〈企业〉。"}, {"text": "他是我的会门，我们每天一起吃饭。", "explanation": "这里把“会门”当成了〈朋友〉这类指人的词。会门指组织，不能用来称呼某一个人。"}, {"text": "我最喜欢吃会门，特别香。", "explanation": "会门指民间秘密组织，不是食物，不能吃，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时在村里加入过一条会门。", "corrected_sentence": "他年轻时在村里加入过一个会门。", "error_description": "量词错误：“会门”是团体，应该用“个”计量，不能用“条”（“条”多用于细长的东西，如路、河、鱼）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只会门已经成立很多年了。", "corrected_sentence": "这个会门已经成立很多年了。", "error_description": "量词错误：“会门”是团体，应该用“个”计量，不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97289, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "月底", "is_correct": true, "explanation": "反义：月底指每月末尾的几天，与“月初”正相反。"}, {"text": "午夜", "is_correct": false, "explanation": "午夜指夜里十二点前后，与“月初”不构成反义关系。"}, {"text": "深秋", "is_correct": false, "explanation": "深秋指秋季后期，与“月初”不构成反义关系。"}, {"text": "傍晚", "is_correct": false, "explanation": "傍晚指日落前后的时段，与“月初”不构成反义关系。"}], "correct_answer": "月底", "explanations": {"月底": "反义：月底指每月末尾的几天，与“月初”正相反。", "午夜": "午夜指夜里十二点前后，与“月初”不构成反义关系。", "深秋": "深秋指秋季后期，与“月初”不构成反义关系。", "傍晚": "傍晚指日落前后的时段，与“月初”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97289, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "月底", "is_correct": true, "explanation": "反义：月底指每月末尾的几天，与“月初”正相反。"}, {"text": "寒假", "is_correct": false, "explanation": "寒假指冬季的假期，与“月初”不构成反义关系。"}, {"text": "春天", "is_correct": false, "explanation": "春天指一年中的春季，与“月初”不构成反义关系。"}, {"text": "中午", "is_correct": false, "explanation": "中午指白天十二点前后的时段，与“月初”不构成反义关系。"}], "correct_answer": "月底", "explanations": {"月底": "反义：月底指每月末尾的几天，与“月初”正相反。", "寒假": "寒假指冬季的假期，与“月初”不构成反义关系。", "春天": "春天指一年中的春季，与“月初”不构成反义关系。", "中午": "中午指白天十二点前后的时段，与“月初”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个月刚开始的几天。", "primary_collocate": null, "pronunciation": "yuè chū", "ipa": "ɥe˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "下个月初我们要考试。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月初的时候，商店人很多。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说月初会给我打电话。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我月初买了一件新衣服。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月初，天一直在下雨。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月初太忙，我们月中见吧。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她月初搬到了新家。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家月初要交报告。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上个月初，我去看过奶奶。", "target_word": "月初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到月初，妈妈就去买菜、买水果。", "target_word": "月初", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个月刚开始的那几天，与月中、月底相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97289, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月初", "is_correct": true, "explanation": "正确：“下个月初”是时间词，与“我们要考试”搭配自然。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是时段，不能用“下个”修饰，句子讲的是考试时间。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不表示时段，句子讲的是考试的时间。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“下个”修饰时段，不修饰场所，“下个饭店”不成立。"}], "explanations": {"月初": "正确：“下个月初”是时间词，与“我们要考试”搭配自然。", "饮料": "语义：饮料不是时段，不能用“下个”修饰，句子讲的是考试时间。", "手机": "语义：手机不表示时段，句子讲的是考试的时间。", "饭店": "搭配：“下个”修饰时段，不修饰场所，“下个饭店”不成立。"}, "sentence_index": 0, "correct_answer": "月初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大桥的月初阶段花了十年。", "explanation": "这里应该用〈初期〉。月初只指每月开头的几天，不能指工程的开始阶段；“花了十年”说明这是整个工程的初期，与“月初”的时间含义矛盾。"}, {"text": "我们对这个问题只有月初的看法。", "explanation": "这里应该用〈初步〉。月初是时间词，不能修饰“看法”这类抽象概念。"}, {"text": "月初班的学生很认真。", "explanation": "这里应该用〈初级〉。初级班指入门班，月初只指每月开头的几天，不能用来指班级等级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月初", "is_correct": true, "explanation": "正确：“她月初搬到了新家”是通顺的时间表达。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“她”后需要的是时间状语，“钥匙”不表示时间，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不表示时间，也不能“搬到”新家。"}, {"text": "思想", "is_correct": false, "explanation": "搭配：“搬到”不搭配抽象的“思想”，句子讲的是具体的搬家。"}], "explanations": {"月初": "正确：“她月初搬到了新家”是通顺的时间表达。", "钥匙": "语义：“她”后需要的是时间状语，“钥匙”不表示时间，句意不通。", "天空": "语义：天空不表示时间，也不能“搬到”新家。", "思想": "搭配：“搬到”不搭配抽象的“思想”，句子讲的是具体的搬家。"}, "sentence_index": 6, "correct_answer": "月初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的月初版很珍贵。", "explanation": "这里应该用〈初版〉。月初只指每月开头的几天，不能指书籍的第一次出版。"}, {"text": "这家公司的月初规模很小。", "explanation": "这里应该用〈初创〉。月初只指每月开头的几天，不能指公司的创办初期。"}, {"text": "他对这件事只有月初的认识。", "explanation": "这里应该用〈初步〉。“初步的认识”指粗浅的了解，月初是时间词，不能修饰“认识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每到在月初，我们班就开会。", "corrected_sentence": "每到月初，我们班就开会。", "error_description": "介词错误：“每到”后直接接时间词“月初”，不能再加“在”。应改为“每到月初，我们班就开会。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下个月初了去找你。", "corrected_sentence": "我下个月初去找你。", "error_description": "了的位置错误：“了”不能放在时间词“下个月初”和动词“去”之间，应删去。应改为“我下个月初去找你。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97290, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "月底", "is_correct": true, "explanation": "反义：月底指每月末尾的几天，与“月初”正相反。"}, {"text": "周末", "is_correct": false, "explanation": "周末指一周末尾的两天，与“月初”不构成反义关系。"}, {"text": "年底", "is_correct": false, "explanation": "年底指一年末尾的时段，与“月初”不构成反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "清晨指一天刚开始的时段，与“月初”不构成反义关系。"}], "correct_answer": "月底", "explanations": {"月底": "反义：月底指每月末尾的几天，与“月初”正相反。", "周末": "周末指一周末尾的两天，与“月初”不构成反义关系。", "年底": "年底指一年末尾的时段，与“月初”不构成反义关系。", "清晨": "清晨指一天刚开始的时段，与“月初”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97290, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "月底", "is_correct": true, "explanation": "反义：月底指每月末尾的几天，与“月初”正相反。"}, {"text": "深夜", "is_correct": false, "explanation": "深夜指夜深的时段，与“月初”不构成反义关系。"}, {"text": "午后", "is_correct": false, "explanation": "午后指中午以后的时段，与“月初”不构成反义关系。"}, {"text": "春季", "is_correct": false, "explanation": "春季指一年中的春天，与“月初”不构成反义关系。"}], "correct_answer": "月底", "explanations": {"月底": "反义：月底指每月末尾的几天，与“月初”正相反。", "深夜": "深夜指夜深的时段，与“月初”不构成反义关系。", "午后": "午后指中午以后的时段，与“月初”不构成反义关系。", "春季": "春季指一年中的春天，与“月初”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每个月开头的几天。", "primary_collocate": null, "pronunciation": "yuè chū", "ipa": "ɥe˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "月初我常常很忙。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司月初发工资。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想月初去北京看朋友。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月初的天气还很冷。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个月初，我都会打扫房间。", "target_word": "月初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租要在月初交。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月初钱多，月底钱少。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他月初去过一次上海。", "target_word": "月初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校月初开学。", "target_word": "月初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书月初才到，我月中就看完了。", "target_word": "月初", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每个月开头的几天，常指发工资、交房租等时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月初", "is_correct": true, "explanation": "正确：月初指每月开头的几天，与“我常常很忙”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是时间，不能作“很忙”的时间状语。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很忙”不说“身高”，身高也不表示时段。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是钱，不是时段，句子讲的是忙碌的时间。"}], "explanations": {"月初": "正确：月初指每月开头的几天，与“我常常很忙”搭配自然。", "颜色": "语义：颜色不是时间，不能作“很忙”的时间状语。", "身高": "搭配：“很忙”不说“身高”，身高也不表示时段。", "工资": "语义：工资是钱，不是时段，句子讲的是忙碌的时间。"}, "sentence_index": 0, "correct_answer": "月初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种新药的月初效果很好。", "explanation": "这里应该用〈初期〉。月初只指每月开头的几天，不能指事情或事物的开始阶段。"}, {"text": "我们对这个方案只有月初的了解。", "explanation": "这里应该用〈初步〉。月初是时间词，不能修饰“了解”这类抽象概念。"}, {"text": "这项研究的月初阶段花了十年。", "explanation": "这里应该用〈初期〉。月初只指每月开头的几天，不能指研究的开始阶段；“花了十年”说明这是整个研究的初期，与“月初”的时间含义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月初", "is_correct": true, "explanation": "正确：“月初钱多”与“月底钱少”相对，构成自然的对比。"}, {"text": "月底", "is_correct": false, "explanation": "语义：与后句的“月底钱少”重复，两个“月底”对照不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能说“钱多”，句子讲的是钱的数量。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“多、少”修饰钱的数量，不能修饰“脚步”。"}], "explanations": {"月初": "正确：“月初钱多”与“月底钱少”相对，构成自然的对比。", "月底": "语义：与后句的“月底钱少”重复，两个“月底”对照不成立。", "天气": "语义：天气不能说“钱多”，句子讲的是钱的数量。", "脚步": "搭配：“多、少”修饰钱的数量，不能修饰“脚步”。"}, "sentence_index": 6, "correct_answer": "月初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案的月初版本很粗糙。", "explanation": "这里应该用〈初稿〉。月初只指每月开头的几天，不能指文件的第一稿。"}, {"text": "这位医生对病情只有月初的判断。", "explanation": "这里应该用〈初步〉。“初步的判断”指粗略的判断，月初是时间词，不能修饰“判断”。"}, {"text": "他的月初水平还不高，还要多练。", "explanation": "这里应该用〈初级〉。“初级水平”指入门阶段，月初只指每月开头的几天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我月初了去北京出差。", "corrected_sentence": "我月初去北京出差。", "error_description": "了的位置错误：“了”不能放在时间词“月初”和动词“去”之间，应删去。应改为“我月初去北京出差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每到在月初，我就去还房贷。", "corrected_sentence": "每到月初，我就去还房贷。", "error_description": "介词错误：“每到”后直接接时间词“月初”，不能再加“在”。应改为“每到月初，我就去还房贷。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
