INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97293, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "这样做不太方便，不好这样做。", "primary_collocate": null, "pronunciation": "wèi biàn", "ipa": "wei˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这件事还没公开，我未便多说。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在开会，我们未便打扰。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是家人，未便替她做决定。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子是别人的，我们未便乱改。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜已经很深了，未便再去敲门。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正难过，大家未便问原因。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有经理同意，我未便把文件给你。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是别人的隐私，朋友也未便打听。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人还在吃饭，我们未便先走。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人刚睡着，家人未便开灯。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "未便：碍于情面或处境，不太方便做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ff3a29a-476f-42a0-b870-bfa7edf8908b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未便", "is_correct": true, "explanation": "正确：“未便”表示碍于情面或处境而不便，与“还没公开”的语境相合，句意是不便多说。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要，与“还没公开”的保留语气相抵触，句意变成必须多说。"}, {"text": "应该", "is_correct": false, "explanation": "语义：“应该”表示应当，与“还没公开”的保留语气相抵触，句意变成应当多说。"}, {"text": "得", "is_correct": false, "explanation": "语域：“得”是口语说法，与这句书面色彩的“未便”不合，且同样表示需要，与“还没公开”相矛盾。"}], "explanations": {"未便": "正确：“未便”表示碍于情面或处境而不便，与“还没公开”的语境相合，句意是不便多说。", "必须": "语义：“必须”表示必要，与“还没公开”的保留语气相抵触，句意变成必须多说。", "应该": "语义：“应该”表示应当，与“还没公开”的保留语气相抵触，句意变成应当多说。", "得": "语域：“得”是口语说法，与这句书面色彩的“未便”不合，且同样表示需要，与“还没公开”相矛盾。"}, "sentence_index": 0, "correct_answer": "未便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的汉语很差，未便看懂这篇文章。", "explanation": "这里应该用〈不能〉。未便表示碍于情面或处境而不便做某事，不用来说能力不够。"}, {"text": "这个方法很有用，你未便试一试。", "explanation": "这里应该用〈不妨〉，表示可以这样做、建议对方试试。未便指不便、不宜，语气恰好相反。"}, {"text": "这么重的箱子，我一个人未便搬起来。", "explanation": "这里应该用〈搬不起来〉。未便指碍于情面或处境不便做某事，不表示力气不够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未便", "is_correct": true, "explanation": "正确：“未便”表示碍于情面，不便把文件交出，与“没有经理同意”的语境相合。"}, {"text": "该", "is_correct": false, "explanation": "语域：“该”是“应该”的口语简省形式，与书面的“未便”语域不合；且表示应当，与“没有经理同意”相矛盾。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以”表示允许，与“没有经理同意”的句意直接矛盾。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”含冒险、违规之意，与“没有经理同意”的受限语境相抵触。"}], "explanations": {"未便": "正确：“未便”表示碍于情面，不便把文件交出，与“没有经理同意”的语境相合。", "该": "语域：“该”是“应该”的口语简省形式，与书面的“未便”语域不合；且表示应当，与“没有经理同意”相矛盾。", "可以": "语义：“可以”表示允许，与“没有经理同意”的句意直接矛盾。", "敢": "语义：“敢”含冒险、违规之意，与“没有经理同意”的受限语境相抵触。"}, "sentence_index": 6, "correct_answer": "未便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗太凶，我未便靠近它。", "explanation": "这里应该用〈不敢〉。未便指碍于情面或处境不便做某事，不表示心里害怕。"}, {"text": "这道题太难，我未便做出来。", "explanation": "这里应该用〈做不出来〉。未便指碍于情面或处境而不便做某事，不用来表示能力不够。"}, {"text": "我今天太累了，未便跑完全程。", "explanation": "这里应该用〈跑不完〉。未便指碍于情面或处境不便做某事，不表示体力不够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的病情我未便了透露。", "corrected_sentence": "她的病情我未便透露。", "error_description": "词语误加：情态动词“未便”后不能直接加“了”，应说“我未便透露”，不能说“我未便了透露”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我不未便插手。", "corrected_sentence": "这件事我未便插手。", "error_description": "词语误加：“未便”本身已含否定，不能再加“不”，应说“未便插手”，不能说“不未便插手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
