INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不便；不宜（多用于书面语）。", "primary_collocate": null, "pronunciation": "wèi biàn", "ipa": "wei˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此事关系重大，现在未便公布。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "案子还在调查，记者未便透露细节。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本公司未便对外说明具体原因。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因涉及个人资料，我方未便提供。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方还没签字，未便提前宣布结果。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身份特殊，我们未便公开姓名。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情尚未查清，请恕我未便回答。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议内容保密，工作人员未便外传。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人情况不稳定，医生未便让家属探视。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公告里说，部分细节未便详述。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "未便：公文、公告中表示不宜做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ff3a29a-476f-42a0-b870-bfa7edf8908b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未便", "is_correct": true, "explanation": "正确：“未便”表示不宜、不便，与“关系重大”而需审慎的语境相合。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”含冒进、不顾后果之意，与“关系重大”而需审慎的语境相抵触。"}, {"text": "肯", "is_correct": false, "explanation": "语义：“肯”表示情愿，与“关系重大”而需慎重处理的语境不合。"}, {"text": "得", "is_correct": false, "explanation": "语域：“得”是口语说法，与书面的“未便”语域不合，且表示需要，与审慎的语境相悖。"}], "explanations": {"未便": "正确：“未便”表示不宜、不便，与“关系重大”而需审慎的语境相合。", "敢": "语义：“敢”含冒进、不顾后果之意，与“关系重大”而需审慎的语境相抵触。", "肯": "语义：“肯”表示情愿，与“关系重大”而需慎重处理的语境不合。", "得": "语域：“得”是口语说法，与书面的“未便”语域不合，且表示需要，与审慎的语境相悖。"}, "sentence_index": 0, "correct_answer": "未便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章太难，我未便读懂。", "explanation": "这里应该用〈读不懂〉。未便指碍于情面或处境而不便做，不指能力不足。"}, {"text": "这个办法很好，你未便先试试。", "explanation": "这里应该用〈不妨〉，表示可以这样做、建议对方先试。未便指不便、不宜，语气恰好相反。"}, {"text": "这只狗太凶了，孩子们未便靠近。", "explanation": "这里应该用〈不敢〉。未便指处境上不宜做某事，不表示心里害怕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未便", "is_correct": true, "explanation": "正确：“未便”表示不宜、不便，与“事情尚未查清”而请人谅解的语境相合。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以”表示许可，与“事情尚未查清”而需谨慎的语境直接矛盾。"}, {"text": "该", "is_correct": false, "explanation": "语域：“该”是口语简省形式，与书面的“未便”不合；且表示应当，与“尚未查清”相矛盾。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要，与“请恕我”的谦让语气及“尚未查清”的语境相抵触。"}], "explanations": {"未便": "正确：“未便”表示不宜、不便，与“事情尚未查清”而请人谅解的语境相合。", "可以": "语义：“可以”表示许可，与“事情尚未查清”而需谨慎的语境直接矛盾。", "该": "语域：“该”是口语简省形式，与书面的“未便”不合；且表示应当，与“尚未查清”相矛盾。", "必须": "语义：“必须”表示必要，与“请恕我”的谦让语气及“尚未查清”的语境相抵触。"}, "sentence_index": 6, "correct_answer": "未便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个字太难写，我未便写出来。", "explanation": "这里应该用〈写不出来〉。未便指碍于情面或处境而不便做某事，不用来表示能力不够。"}, {"text": "这么重的箱子，我一个人未便搬动。", "explanation": "这里应该用〈搬不动〉。未便指不宜、不便，不表示力气不够。"}, {"text": "这盘菜太辣，我未便吃。", "explanation": "这里应该用〈不爱吃〉。未便指不宜、不便，不表示个人口味上不喜欢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此事我们未便了公开细节。", "corrected_sentence": "此事我们未便公开细节。", "error_description": "词语误加：情态动词“未便”后不能直接加“了”，应说“未便公开细节”，不能说“未便了公开细节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
