INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97297, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "还没有起名字，没人叫得出来。", "primary_collocate": null, "pronunciation": "wèi míng", "ipa": "weɪ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "山上有一朵未名的小花。", "target_word": "未名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座山至今仍是一座未名的山。", "target_word": "未名", "complexity_tier": "T3", "furigana": "zhè zuò shān zhìjīn réng shì yí zuò wèimíng de shān.", "sentence_source": "generated"}, {"text": "我们在海边发现了一个未名小岛。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种未名的鸟，村里人都叫不出名字。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在森林里看到一种未名的虫子。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小路至今仍是一条未名的路。", "target_word": "未名", "complexity_tier": "T3", "furigana": "zhè tiáo xiǎolù zhìjīn réng shì yì tiáo wèimíng de lù.", "sentence_source": "generated"}, {"text": "山谷里有很多未名的湖。", "target_word": "未名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他给这个未名的小村子写了一首诗。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一颗未名的星，还没有人给它起名。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，我们走过一座未名的小桥。", "target_word": "未名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "事物还没有起名字，没人叫得出名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巨大", "is_correct": false, "explanation": "语义：“巨大”与“小花”的“小”相矛盾，不能说巨大的小花。"}, {"text": "未名", "is_correct": true, "explanation": "正确：“未名”修饰“小花”，表示这朵花还没有起名字。"}, {"text": "年老", "is_correct": false, "explanation": "搭配：“年老”说人的年纪，不能用来形容花。"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：“肥胖”形容人或动物的体形，不用于花。"}], "explanations": {"巨大": "语义：“巨大”与“小花”的“小”相矛盾，不能说巨大的小花。", "未名": "正确：“未名”修饰“小花”，表示这朵花还没有起名字。", "年老": "搭配：“年老”说人的年纪，不能用来形容花。", "肥胖": "体貌：“肥胖”形容人或动物的体形，不用于花。"}, "sentence_index": 0, "correct_answer": "未名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "长城是一座未名的古迹。", "explanation": "这里应该用〈著名〉。未名指还没有起名字，长城早已有名，不能用未名形容。"}, {"text": "李白是中国历史上一位未名的诗人。", "explanation": "这里应该用〈著名〉。未名指还没有起名字，李白人人皆知，不能用未名形容。"}, {"text": "这只小猫已经叫小白了，它是一只未名的猫。", "explanation": "这里应该用〈已取名〉。未名指还没有起名字，而这只猫已叫小白，不能用未名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唯一", "is_correct": false, "explanation": "语义：“唯一”与“很多”矛盾，不能说很多唯一的湖。"}, {"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”说物体的分量，湖不能用笨重来形容。"}, {"text": "未名", "is_correct": true, "explanation": "正确：“未名”修饰“湖”，表示这些湖还没有名字。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容人或动物的身体，不用于湖。"}], "explanations": {"唯一": "语义：“唯一”与“很多”矛盾，不能说很多唯一的湖。", "笨重": "搭配：“笨重”说物体的分量，湖不能用笨重来形容。", "未名": "正确：“未名”修饰“湖”，表示这些湖还没有名字。", "瘦弱": "体貌：“瘦弱”形容人或动物的身体，不用于湖。"}, "sentence_index": 6, "correct_answer": "未名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黄山是一座未名的山，每年都有很多人去。", "explanation": "这里应该用〈著名〉。未名指还没有起名字，黄山早已有名，不能用未名形容。"}, {"text": "这座未名的古镇，很多游客都知道它。", "explanation": "这里应该用〈有名〉。未名指还没有起名字，而这座古镇人人皆知，应说〈有名〉，不能用未名。"}, {"text": "他的小狗叫旺财，是一条未名的狗。", "explanation": "这里应该用〈已取名〉。未名指还没有起名字，而这条狗已叫旺财，说明已经取了名字，不能用未名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片海里有一座很未名的小岛。", "corrected_sentence": "这片海里有一座未名的小岛。", "error_description": "程度副词错误：“未名”表示还没有起名字，属于非程度形容词，不能受“很”修饰。应为“未名的小岛”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走过一条未名地小路。", "corrected_sentence": "我们走过一条未名的小路。", "error_description": "结构助词错误：修饰名词“小路”时应用“的”，不能用“地”。“地”用于修饰动词，“未名地小路”应改为“未名的小路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
