INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97298, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有名字；没有被命名。", "primary_collocate": null, "pronunciation": "wèi míng", "ipa": "weɪ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这是一首未名的歌，乐迷们一直在猜它的来历。", "target_word": "未名", "complexity_tier": "T3", "furigana": "zhè shì yì shǒu wèimíng de gē, yuèmímen yìzhí zài cāi tā de láilì.", "sentence_source": "generated"}, {"text": "他画了一幅未名的画。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上有很多未名的小岛。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市有一条未名的老街。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写了一篇未名的小说。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个未名的小山洞里很安静。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在路边看见一棵未名的树。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个未名的小镇很美。", "target_word": "未名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在雪山下发现了一个未名的湖。", "target_word": "未名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边有一座未名的小庙。", "target_word": "未名", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "事物没有名字，没有被命名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间的宽窄，不能用来形容歌。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物体的形体，不能用来形容歌。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容人或动物的身体，不能用来形容歌。"}, {"text": "未名", "is_correct": true, "explanation": "正确：“未名”修饰“歌”，表示这首歌没有名字、没有被命名。"}], "explanations": {"狭窄": "搭配：“狭窄”形容空间的宽窄，不能用来形容歌。", "高大": "搭配：“高大”形容人或物体的形体，不能用来形容歌。", "瘦弱": "体貌：“瘦弱”形容人或动物的身体，不能用来形容歌。", "未名": "正确：“未名”修饰“歌”，表示这首歌没有名字、没有被命名。"}, "sentence_index": 0, "correct_answer": "未名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条老街叫青石街，是一条未名的老街。", "explanation": "未名表示没有被命名，而这条街已叫青石街，应说〈已命名〉，不能用未名。"}, {"text": "我们对未名的前途充满信心。", "explanation": "这里应该用〈未知〉。未名指还没有起名字，不能形容前途；表示尚不确定应说〈未知〉。"}, {"text": "这棵大树人人都叫它“老槐”，却是一棵未名的树。", "explanation": "这里应该用〈有名字〉。未名指还没有起名字，而这棵树人人都叫它“老槐”，已经有名字了，不能用未名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能用来形容树。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”形容人或动物的生理状态，树不会饥饿。"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：“肥胖”形容人或动物的体形，不能用来形容树。"}, {"text": "未名", "is_correct": true, "explanation": "正确：“未名”修饰“树”，表示这棵树没有名字。"}], "explanations": {"嘹亮": "搭配：“嘹亮”形容声音，不能用来形容树。", "饥饿": "搭配：“饥饿”形容人或动物的生理状态，树不会饥饿。", "肥胖": "体貌：“肥胖”形容人或动物的体形，不能用来形容树。", "未名": "正确：“未名”修饰“树”，表示这棵树没有名字。"}, "sentence_index": 6, "correct_answer": "未名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天色未名，河边已经有人在钓鱼了。", "explanation": "这里应该用〈未明〉。未明指天还没有亮；未名指还没有起名字，与天色无关。"}, {"text": "这座小庙叫白云寺，是一座未名的小庙。", "explanation": "这里应该用〈已命名〉。未名指还没有起名字，而这座小庙已经叫白云寺，不能用未名。"}, {"text": "这座庙里有一位未名的和尚，大家都叫他明空。", "explanation": "这里应该用〈已有法号〉。未名指还没有起名字，而这位和尚已有法号，大家都叫他明空，不能用未名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有一个很未名的小山洞。", "corrected_sentence": "村里有一个未名的小山洞。", "error_description": "程度副词错误：“未名”表示没有被命名，属于非程度形容词，不能受“很”修饰。应为“未名的小山洞”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们爬上一座未名地山。", "corrected_sentence": "我们爬上一座未名的山。", "error_description": "结构助词错误：修饰名词“山”时应用“的”，不能用“地”。“地”用于修饰动词，“未名地山”应改为“未名的山”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已知", "is_correct": true, "explanation": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。"}, {"text": "明亮", "is_correct": false, "explanation": "与“未知”没有反义关系，只表示光线充足。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写面积大。"}, {"text": "干净", "is_correct": false, "explanation": "与“未知”没有反义关系，只表示没有污物。"}], "correct_answer": "已知", "explanations": {"已知": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。", "明亮": "与“未知”没有反义关系，只表示光线充足。", "宽阔": "与“未知”没有反义关系，只描写面积大。", "干净": "与“未知”没有反义关系，只表示没有污物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已知", "is_correct": true, "explanation": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。"}, {"text": "嘈杂", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写声音杂乱。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写外表好看。"}, {"text": "冰冷", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写温度低。"}], "correct_answer": "已知", "explanations": {"已知": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。", "嘈杂": "与“未知”没有反义关系，只描写声音杂乱。", "漂亮": "与“未知”没有反义关系，只描写外表好看。", "冰冷": "与“未知”没有反义关系，只描写温度低。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "还不知道，没有人弄明白。", "primary_collocate": null, "pronunciation": "wèi zhī", "ipa": "weɪ̯⁵¹ ʈʂɨ⁵⁵", "syllable_count": 2, "sentences": [{"text": "海底还有很多未知的东西。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病的原因目前还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙里有许多未知的星星。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的真相至今未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想找到未知的答案。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山洞里有什么，还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，这个问题的答案仍然未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在研究这些未知的现象。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深海里的未知生物让人好奇。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机为什么会失踪，原因到现在还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未知的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "还没有人弄明白的，尚不为人所知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。未知（wèi zhī）指还没有人弄明白。"}, {"text": "位置", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。"}, {"text": "未至", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。"}, {"text": "为之", "is_correct": false, "explanation": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。"}, {"text": "位址", "is_correct": false, "explanation": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}], "explanations": {"未知": "正确答案。未知（wèi zhī）指还没有人弄明白。", "位置": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。", "未至": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。", "为之": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。", "位址": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}, "sentence_index": null, "correct_answer": "未知"}, "level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“未知”修饰“东西”，表示还没有人弄明白的事物。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：海底是潮湿的水下环境，“干燥”与之冲突。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：“沸腾”指液体受热翻滚，不能用来描写海底泛指的“东西”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多用于声音和脆性食物，不用来形容泛指的东西。"}], "explanations": {"未知": "正确答案。“未知”修饰“东西”，表示还没有人弄明白的事物。", "干燥": "语义：海底是潮湿的水下环境，“干燥”与之冲突。", "沸腾": "语义：“沸腾”指液体受热翻滚，不能用来描写海底泛指的“东西”。", "清脆": "搭配：“清脆”多用于声音和脆性食物，不用来形容泛指的东西。"}, "sentence_index": 0, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班转来了一位未知的同学。", "explanation": "这里应该用〈陌生〉。未知指事情还没有人弄明白，不用来指刚转来、只是彼此不熟的同学。"}, {"text": "我对这条路很未知。", "explanation": "这里应该用〈生疏〉。未知说的是事情还没有人弄明白，不用来说自己对某条路不熟悉；这个意思要用“生疏”，如“我对这条路很生疏”。"}, {"text": "他对这份工作很未知，干起来却很顺手。", "explanation": "这里应该用〈熟悉〉。未知指事情还没有人弄明白，不用来说自己对工作很熟悉；“对这份工作很熟悉”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“仍然未知”说答案还没有被弄明白。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”描写质地，不能用来形容“答案”。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”只描写物体或环境，不能形容“答案”。"}, {"text": "圆润", "is_correct": false, "explanation": "体貌：“圆润”描写外形或声音，不能说答案“圆润”。"}], "explanations": {"未知": "正确答案。“仍然未知”说答案还没有被弄明白。", "柔软": "语义：“柔软”描写质地，不能用来形容“答案”。", "潮湿": "语义：“潮湿”只描写物体或环境，不能形容“答案”。", "圆润": "体貌：“圆润”描写外形或声音，不能说答案“圆润”。"}, "sentence_index": 6, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他突然辞职，让大家都很未知。", "explanation": "这里应该用〈意外〉。未知表示事情还没有人弄明白，不能表示事情出乎意料；“大家都很意外”才是这个意思。"}, {"text": "他未知地离开了房间。", "explanation": "这里应该用〈悄悄地〉。未知表示事情还没有人弄明白，不能用来描述离开的方式；“悄悄地离开”才是这个意思。"}, {"text": "这个孩子很未知，每天都爱说爱笑。", "explanation": "这里应该用〈活泼〉。未知表示还没有人弄明白，不用来形容孩子的性格；“很活泼”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个山洞里还有许多未知地角落。", "corrected_sentence": "这个山洞里还有许多未知的角落。", "error_description": "错误形式：“未知地角落”；正确形式：“未知的角落”。“未知”修饰名词时要用“的”；“地”是状语标志，不用来修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个洞穴的深度至今仍然未知的。", "corrected_sentence": "这个洞穴的深度至今仍然未知。", "error_description": "错误形式：“至今仍然未知的”；正确形式：“至今仍然未知”。作谓语的“仍然未知”句末不加“的”；“的”需要名词中心语，或用在“是……的”结构中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
