INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不了解；还不知道的。", "primary_collocate": null, "pronunciation": "wèi zhī", "ipa": "weɪ̯⁵¹ ʈʂɨ⁵⁵", "syllable_count": 2, "sentences": [{"text": "对他来说，新城市是未知的地方。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次出国，一切都是未知的。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕未知的困难。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对未知的路，她有点紧张。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对未知的东西总是很好奇。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工作怎么样，对我来说还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要勇敢地走进未知的世界。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，未来对他是未知的。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去一个未知的国家旅行，让她很兴奋。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的成绩，对大家都是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未知的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "对某人来说不了解、还不知道的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。未知（wèi zhī）指对某人来说还不了解。"}, {"text": "位置", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。"}, {"text": "未至", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。"}, {"text": "为之", "is_correct": false, "explanation": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。"}, {"text": "位址", "is_correct": false, "explanation": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}], "explanations": {"未知": "正确答案。未知（wèi zhī）指对某人来说还不了解。", "位置": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。", "未至": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。", "为之": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。", "位址": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}, "sentence_index": null, "correct_answer": "未知"}, "level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“未知的地方”指对他来说还不了解的地方。"}, {"text": "熟悉", "is_correct": false, "explanation": "语义：句子说的是刚到的“新城市”，与“熟悉”的意思相矛盾。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”描写质地，不能用来形容一个地方。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多用于声音，不能形容地方。"}], "explanations": {"未知": "正确答案。“未知的地方”指对他来说还不了解的地方。", "熟悉": "语义：句子说的是刚到的“新城市”，与“熟悉”的意思相矛盾。", "柔软": "语义：“柔软”描写质地，不能用来形容一个地方。", "清脆": "搭配：“清脆”多用于声音，不能形容地方。"}, "sentence_index": 0, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从小在这里长大，对这条街很未知。", "explanation": "这里应该用〈熟悉〉。未知表示不了解，不能用来说在这里长大、对街道很熟悉的情况。"}, {"text": "他的英语很未知，每次说话都要想半天。", "explanation": "这里应该用〈不熟练〉。未知说的是不了解的情况，不用来形容语言水平；说英语不熟练才对。"}, {"text": "听到这个好消息，我心里很未知。", "explanation": "这里应该用〈高兴〉。未知表示还不了解，不能用来形容心情；听到好消息应说“高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“未知的世界”指我们还不了解的世界。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”描写道路，与“勇敢地走进”的探索语境不协调。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”描写环境，不能用来形容“世界”这样的整体概念。"}, {"text": "圆润", "is_correct": false, "explanation": "体貌：“圆润”描写外形，不能用来形容“世界”。"}], "explanations": {"未知": "正确答案。“未知的世界”指我们还不了解的世界。", "平坦": "语义：“平坦”描写道路，与“勇敢地走进”的探索语境不协调。", "潮湿": "语义：“潮湿”描写环境，不能用来形容“世界”这样的整体概念。", "圆润": "体貌：“圆润”描写外形，不能用来形容“世界”。"}, "sentence_index": 6, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的父母很未知，我们经常一起吃饭。", "explanation": "这里应该用〈亲近〉。未知表示不了解，不能用来形容与父母的关系；“我和父母很亲近”才是这个意思。"}, {"text": "她未知地摇了摇头。", "explanation": "这里应该用〈轻轻地〉。未知表示不了解，不能用来形容摇头的样子；“轻轻地摇了摇头”才是这个意思。"}, {"text": "我和他是多年的老朋友，对他的脾气很未知。", "explanation": "这里应该用〈熟悉〉。未知表示不了解，老朋友的脾气应该说“熟悉”，不能用“未知”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对我来说，这条山路是未知地。", "corrected_sentence": "对我来说，这条山路是未知的。", "error_description": "错误形式：“是未知地”；正确形式：“是未知的”。“地”是状语标志，不用于句中的表语位置；“是……的”结构中应用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对我来说，那个岛上的情况仍然未知的。", "corrected_sentence": "对我来说，那个岛上的情况仍然未知。", "error_description": "错误形式：“至今仍然未知的”；正确形式：“至今仍然未知”。作谓语的“仍然未知”句末不加“的”；“的”需要名词中心语，或用在“是……的”结构中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
