INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97307, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "打仗时，人们可以安全待着、慢慢壮大的地方。", "primary_collocate": null, "pronunciation": "gēn jù dì", "ipa": "kən tɕy ti", "syllable_count": 3, "sentences": [{"text": "打仗时，战士们在山里有一个根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个根据地很安全，伤员可以慢慢休息。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们先找到根据地，再慢慢壮大队伍。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人找不到山里的根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们把粮食送回了根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，当年他们住在根据地里。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有根据地，队伍就没有安全的地方。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争开始后，大家都回到了根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子曾经是一个根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在根据地种菜，也学习写字。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "根據地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战时安全落脚并发展壮大的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根据地", "is_correct": true, "explanation": "“根据地”指打仗时可以安全落脚、慢慢壮大的地方，与“打仗时”“在山里”的语境相符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：打仗时的山里不会有超市，与“打仗时”的语境矛盾。"}, {"text": "海滩", "is_correct": false, "explanation": "语义：海滩位于海边，“山里”不可能有海滩，两个地点互相矛盾。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：量词“一个”不搭配“大海”，应说“一片大海”，而且山里没有大海。"}], "explanations": {"根据地": "“根据地”指打仗时可以安全落脚、慢慢壮大的地方，与“打仗时”“在山里”的语境相符。", "超市": "语义：打仗时的山里不会有超市，与“打仗时”的语境矛盾。", "海滩": "语义：海滩位于海边，“山里”不可能有海滩，两个地点互相矛盾。", "大海": "搭配：量词“一个”不搭配“大海”，应说“一片大海”，而且山里没有大海。"}, "sentence_index": 0, "correct_answer": "根据地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在根据地里做饭，饭菜特别香。", "explanation": "这里应该用〈厨房〉。根据地指战时可以安全待着、慢慢壮大的地区，做饭的场所应说厨房。"}, {"text": "他每天在根据地里练琴，琴声传到了邻居家。", "explanation": "这里应该用〈琴房〉。根据地指战时可以安全待着、慢慢壮大的地区，练琴的房间应说琴房。"}, {"text": "我们周末去根据地看电影。", "explanation": "这里应该用〈电影院〉。根据地是战时长期活动和发展的地区，看电影的场所应说电影院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根据地", "is_correct": true, "explanation": "“没有根据地”之后，“队伍就没有安全的地方”，“根据地”正是队伍安全落脚的地方，句意完整。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：队伍需要的是安全的落脚处，游乐场与战时队伍的处境不符。"}, {"text": "咖啡馆", "is_correct": false, "explanation": "语义：咖啡馆不能替代队伍的安全落脚处，“没有咖啡馆，队伍就没有安全的地方”句意不通。"}, {"text": "大米", "is_correct": false, "explanation": "搭配：“大米”是食物，不能与“安全的地方”组成让队伍落脚的意思，句子不成立。"}], "explanations": {"根据地": "“没有根据地”之后，“队伍就没有安全的地方”，“根据地”正是队伍安全落脚的地方，句意完整。", "游乐场": "语义：队伍需要的是安全的落脚处，游乐场与战时队伍的处境不符。", "咖啡馆": "语义：咖啡馆不能替代队伍的安全落脚处，“没有咖啡馆，队伍就没有安全的地方”句意不通。", "大米": "搭配：“大米”是食物，不能与“安全的地方”组成让队伍落脚的意思，句子不成立。"}, "sentence_index": 6, "correct_answer": "根据地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息没有根据地，大家都不相信。", "explanation": "这里应该用〈依据〉。根据地指战时可以安全待着、慢慢壮大的地区，表示理由、证据的意思应说依据。"}, {"text": "根据地里挤满了旅客，大家都在等车。", "explanation": "这里应该用〈车站〉。根据地是战时长期活动和发展的地区，旅客候车的场所应说车站。"}, {"text": "周末我们去根据地散步。", "explanation": "这里应该用〈公园〉。根据地是战时长期活动和发展的地区，不能用来指散步的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "战士们在山里找到了一条根据地。", "corrected_sentence": "战士们在山里找到了一个根据地。", "error_description": "错误：量词“条”用于细长的东西，根据地是地区，应该用量词“个”。正确说法是“找到了一个根据地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只根据地现在很热闹。", "corrected_sentence": "这块根据地现在很热闹。", "error_description": "错误：量词“只”用于动物，根据地是地区，应该用“块”。正确说法是“这块根据地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
