INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在战争中建立的、作为长期活动和发展基地的地区。", "primary_collocate": null, "pronunciation": "gēn jù dì", "ipa": "kən tɕy ti", "syllable_count": 3, "sentences": [{"text": "红军在山区建立了新的根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块根据地后来发展得很快。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把农村作为长期活动的根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗日战争时期，这里有一个根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据地的人民支持军队打仗。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗战时期，他们在这片山区建立了一个根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观过根据地以后，我知道了很多历史。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队在根据地里办了学校和工厂。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在边远地区开辟了根据地。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个根据地在战争中不断扩大。", "target_word": "根据地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "革命根据地", "label": "复合"}, {"form": "根據地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战争中建立的长期活动发展基地地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根据地", "is_correct": true, "explanation": "“根据地”指在战争中建立的、长期活动和发展的基地，与“红军”“在山区建立”相符。"}, {"text": "商场", "is_correct": false, "explanation": "语义：红军在山区建立的不会是商场，与“红军”“山区”的语境矛盾。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：动词“建立”不与“阳光”搭配，不能说“建立了新的阳光”。"}, {"text": "游乐园", "is_correct": false, "explanation": "语义：游乐园是供人游玩的地方，与战时红军建立的据点性质不符。"}], "explanations": {"根据地": "“根据地”指在战争中建立的、长期活动和发展的基地，与“红军”“在山区建立”相符。", "商场": "语义：红军在山区建立的不会是商场，与“红军”“山区”的语境矛盾。", "阳光": "搭配：动词“建立”不与“阳光”搭配，不能说“建立了新的阳光”。", "游乐园": "语义：游乐园是供人游玩的地方，与战时红军建立的据点性质不符。"}, "sentence_index": 0, "correct_answer": "根据地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶每天在根据地里晾衣服，阳光很好。", "explanation": "这里应该用〈阳台〉。根据地指战争中建立的长期活动基地，晾衣服的地方应说阳台。"}, {"text": "天黑了，农民把牛都赶进根据地里过夜。", "explanation": "这里应该用〈牛棚〉。根据地指战争中建立的长期活动基地，关牛过夜的棚子应说牛棚。"}, {"text": "工人们在根据地里装配机器，每天生产上百台。", "explanation": "这里应该用〈厂房〉。根据地是战时活动的地区，装配机器的生产场所应说厂房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根据地", "is_correct": true, "explanation": "“参观过根据地”指参观战时建立的基地，因而能了解历史，句意通顺。"}, {"text": "超市", "is_correct": false, "explanation": "语义：参观超市并不能让人了解历史，与“我知道了很多历史”的语境矛盾。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场与历史无关，参观它不会让人知道很多历史。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“参观”的对象应是场所或展览，不能参观“天气”。"}], "explanations": {"根据地": "“参观过根据地”指参观战时建立的基地，因而能了解历史，句意通顺。", "超市": "语义：参观超市并不能让人了解历史，与“我知道了很多历史”的语境矛盾。", "游乐场": "语义：游乐场与历史无关，参观它不会让人知道很多历史。", "天气": "搭配：“参观”的对象应是场所或展览，不能参观“天气”。"}, "sentence_index": 6, "correct_answer": "根据地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的话没有根据地，谁也不相信。", "explanation": "这里应该用〈依据〉。根据地指战争中建立的长期活动基地，表示理由、证据的意思应说依据。"}, {"text": "根据地里停满了货船，工人们忙着卸货。", "explanation": "这里应该用〈码头〉。根据地是战时长期活动和发展的地区，停靠货船的地方应说码头。"}, {"text": "周末我们去根据地游泳。", "explanation": "这里应该用〈游泳馆〉。根据地是战时长期活动和发展的地区，不能用来指游泳的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红军在山区建立了一条新的根据地。", "corrected_sentence": "红军在山区建立了一块新的根据地。", "error_description": "错误：量词“条”用于细长的东西，根据地是地区，应该用“块”。正确说法是“一块新的根据地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条根据地曾经保护过很多伤员。", "corrected_sentence": "这块根据地曾经保护过很多伤员。", "error_description": "错误：量词“条”用于细长的东西，根据地是地区，应该用“块”。正确说法是“这块根据地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
