INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都学习的好样子。", "primary_collocate": null, "pronunciation": "mó fàn", "ipa": "mwo˧˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "他是我们班的学习模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是大家心中的模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师应该给学生做个模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的行动成了大家的模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥一直是我的模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母要在孩子面前做好模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人是邻居们学习的模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都把她当成模范。", "target_word": "模范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的行动给同学们做了模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小村子出了一位让人敬佩的模范。", "target_word": "模范", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位模范", "label": "量词"}, {"form": "模范生", "label": "复合"}, {"form": "模範", "label": "繁体"}], "register": "中性", "sense_fingerprint": "模范：值得大家学习的好样子、好人物（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b8aedc-5ff5-4137-89ea-9c5261b723e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模范", "is_correct": true, "explanation": "模范：值得大家学习的好样子，与“学习模范”搭配，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不能指“他”这样的人。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“电视”是家电，不能指人，“学习电视”不成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是练习任务，不是人，不能说“他是……的作业”。"}], "explanations": {"模范": "模范：值得大家学习的好样子，与“学习模范”搭配，符合句意。", "课本": "语义：“课本”是书，不能指“他”这样的人。", "电视": "语义：“电视”是家电，不能指人，“学习电视”不成立。", "作业": "语义：“作业”是练习任务，不是人，不能说“他是……的作业”。"}, "sentence_index": 0, "correct_answer": "模范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这架飞机模范是我一个星期做好的。", "explanation": "这里应该用〈模型〉。模范指值得学习的人或事，不指可以做出来的实物模型。"}, {"text": "这家工厂用模范做月饼。", "explanation": "这里应该用〈模具〉。模范指值得学习的好榜样，不指用来做东西的模子。"}, {"text": "孩子喜欢模范大人的动作。", "explanation": "这里应该用〈模仿〉。模范是名词，表示好榜样，不能表示“照着做”的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模范", "is_correct": true, "explanation": "模范：可供学习的好人物，与“邻居们学习的”搭配，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是交通工具，不能指“这位老人”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“学习”不能修饰“房子”，“学习的房子”不成立。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是机器，不能作“这位老人是……的”的身份。"}], "explanations": {"模范": "模范：可供学习的好人物，与“邻居们学习的”搭配，符合句意。", "汽车": "语义：“汽车”是交通工具，不能指“这位老人”。", "房子": "搭配：“学习”不能修饰“房子”，“学习的房子”不成立。", "电脑": "语义：“电脑”是机器，不能作“这位老人是……的”的身份。"}, "sentence_index": 6, "correct_answer": "模范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是一位模范，常常在时装周上走秀。", "explanation": "这里应该用〈模特〉。模范指值得学习的好榜样，不指职业模特。"}, {"text": "这份报告直接套用了公司的模范。", "explanation": "这里应该用〈模板〉。模范指值得学习的人或事，不指可以套用的格式文件。"}, {"text": "夜里的照片有点模范。", "explanation": "这里应该用〈模糊〉。模范用于人或事的榜样意义，不能形容照片的清晰度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有一只模范。", "corrected_sentence": "我们班有一位模范。", "error_description": "错误：“一只模范”；正确：“一位模范”。“模范”指人，量词应用“位”，“只”不用于指人的名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在工厂里是一只出名的劳动模范。", "corrected_sentence": "她在工厂里是一位出名的劳动模范。", "error_description": "错误：“一只劳动模范”；正确：“一位劳动模范”。“劳动模范”指人，量词应用“位”，“只”不用于指人的名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
