INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人可以做什么、不可以做什么的范围。", "primary_collocate": null, "pronunciation": "quán xiàn", "ipa": "tɕʰyɛn˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我没有权限打开这个文件。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员可以改变你的权限。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的账号权限不够，不能删除照片。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了学生查看成绩的权限。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机应用想要使用你的位置权限。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先打开相机权限，再拍照。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站对新用户的权限很少。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每个人不同的权限。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了密码，所以没有权限进去。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有管理员有这个权限。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "访问权限", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人或账号被允许进行的操作范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“没有……打开这个文件”搭配，句子不通"}, {"text": "权限", "is_correct": true, "explanation": "“权限”指允许进行的操作范围，与“打开这个文件”相呼应"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能用“没有……打开文件”来说，句子不通"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”与“打开这个文件”没有关系，句子不通"}], "explanations": {"颜色": "搭配：“颜色”不能与“没有……打开这个文件”搭配，句子不通", "权限": "“权限”指允许进行的操作范围，与“打开这个文件”相呼应", "味道": "搭配：“味道”不能用“没有……打开文件”来说，句子不通", "名字": "语义：“名字”与“打开这个文件”没有关系，句子不通"}, "sentence_index": 0, "correct_answer": "权限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的权限有点儿咸，我不太喜欢。", "explanation": "这里应该用〈味道〉。“权限”指可以做什么的范围，不能用来说菜的口味，应说“味道”。"}, {"text": "他的权限很高，有一米九。", "explanation": "这里应该用〈个子〉。“权限”指可以做什么的范围，不能用来说身高，应说“个子”。"}, {"text": "今天的权限很冷，多穿点衣服。", "explanation": "这里应该用〈天气〉。“权限”指可以做什么的范围，不能用来说冷热，应说“天气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能用来说网站对用户的规定，句子不通"}, {"text": "权限", "is_correct": true, "explanation": "“权限”指允许进行的操作范围，与“很少”相呼应"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能用来说网站对新用户的规定，句子不通"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”形容人的体形，不能用于网站的规定"}], "explanations": {"温度": "搭配：“温度”不能用来说网站对用户的规定，句子不通", "权限": "“权限”指允许进行的操作范围，与“很少”相呼应", "年龄": "语义：“年龄”不能用来说网站对新用户的规定，句子不通", "体重": "体貌：“体重”形容人的体形，不能用于网站的规定"}, "sentence_index": 6, "correct_answer": "权限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忘了自己的权限，只能重新注册。", "explanation": "这里应该用〈密码〉。“权限”指可以做什么的范围，忘记登录凭证应说“密码”。"}, {"text": "这所学校的权限很好吃，学生都爱吃。", "explanation": "这里应该用〈饭菜〉。“权限”指可以做什么的范围，不能用来说食物好吃，应说“饭菜”。"}, {"text": "这位歌手的权限很好听，唱歌特别动人。", "explanation": "这里应该用〈嗓音〉。“权限”指可以做什么的范围，不能用来形容声音，应说“嗓音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "管理员给了我一把修改资料的权限。", "corrected_sentence": "管理员给了我一项修改资料的权限。", "error_description": "量词错误：“权限”的量词应为“项”，不能用“把”（“把”多用于有柄的器具）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管理员有权限了删除这个账号。", "corrected_sentence": "管理员有权限删除这个账号。", "error_description": "助词错误：“有权限”后面直接接动词“删除”，中间不能加“了”。正确：“管理员有权限删除这个账号。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97314, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97314, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "职权范围，也指允许做的限度。", "primary_collocate": null, "pronunciation": "quán xiàn", "ipa": "tɕʰyɛn˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "经理的权限比普通员工大。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不在我的权限之内。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的权限很大，可以决定学校的大事。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的权限是法律规定的。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他超出了自己的权限，老板很生气。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长把一部分权限交给了副部长。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门的权限只限于管理文件。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁给了你这么大的权限？", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王刚来公司，权限还不大。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定了政府部门的权限。", "target_word": "权限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "管理权限", "label": "复合"}], "register": "中性", "sense_fingerprint": "职务或机构所拥有的职权范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”没有大小的比较，不能说“经理的颜色比普通员工大”"}, {"text": "权限", "is_correct": true, "explanation": "“权限”指职务范围，可以比较大小，与后半句“比普通员工大”相呼应"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或口感，与经理的职权范围无关，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与人无关，不能说“经理的天气比普通员工大”。"}], "explanations": {"颜色": "搭配：“颜色”没有大小的比较，不能说“经理的颜色比普通员工大”", "权限": "“权限”指职务范围，可以比较大小，与后半句“比普通员工大”相呼应", "味道": "语义：“味道”指气味或口感，与经理的职权范围无关，句子不通。", "天气": "语义：“天气”与人无关，不能说“经理的天气比普通员工大”。"}, "sentence_index": 0, "correct_answer": "权限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的权限太小了，我穿不上。", "explanation": "这里应该用〈尺寸〉。“权限”指职权范围，不能用来说衣服的大小，应说“尺寸”。"}, {"text": "这所医院的权限很干净，病人都很满意。", "explanation": "这里应该用〈环境〉。“权限”指职权范围，不能用来说卫生状况，应说“环境”。"}, {"text": "他的权限很好，能参加长跑比赛。", "explanation": "这里应该用〈体力〉。“权限”指职权范围或允许做的限度，不能用来形容身体状况，应说“体力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：“工资”与“只限于管理文件”不相符，句子不通"}, {"text": "权限", "is_correct": true, "explanation": "“权限”指职权范围，与“只限于管理文件”相呼应"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”与“只限于管理文件”没有关系，句子不通"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能用来说部门的范围，句子不通"}], "explanations": {"工资": "语义：“工资”与“只限于管理文件”不相符，句子不通", "权限": "“权限”指职权范围，与“只限于管理文件”相呼应", "年龄": "语义：“年龄”与“只限于管理文件”没有关系，句子不通", "温度": "搭配：“温度”不能用来说部门的范围，句子不通"}, "sentence_index": 6, "correct_answer": "权限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方法的权限很多，大家都说很好用。", "explanation": "这里应该用〈优点〉。“权限”指职权范围或允许做的限度，不能用来说方法的好处，应说“优点”。"}, {"text": "这个孩子的权限特别好，每次考试都是第一名。", "explanation": "这里应该用〈成绩〉。“权限”指职权范围或允许做的限度，不能用来说学习的好坏，应说“成绩”。"}, {"text": "他的权限很强，连续三天没有睡觉。", "explanation": "这里应该用〈精力〉。“权限”指职权范围，不能用来说身体的状态，应说“精力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部门经理有一只权限决定这笔开支。", "corrected_sentence": "部门经理有一项权限决定这笔开支。", "error_description": "量词错误：“权限”应用量词“项”，“只”多用于动物等，不能用来计量“权限”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拥有一封权限，可以查看这些资料。", "corrected_sentence": "他拥有一项权限，可以查看这些资料。", "error_description": "量词错误：“权限”应用量词“项”，“封”多用于信件、文件，不能用来计量“权限”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
