INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97317, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "说话的人现在所在的这个地方。", "primary_collocate": null, "pronunciation": "cǐ dì", "ipa": "tsʰɨ˨˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "我在此地住了三年了。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎你们来到此地。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚来此地，还不认识路。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地冬天很冷，你要多穿衣服。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，此地有没有银行？", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在此地等你，你快点来。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地的人都很热情。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想离开此地，朋友都在这儿。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在此地工作，每天坐地铁上班。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家人都不在此地，我一个人生活很孤单。", "target_word": "此地", "complexity_tier": "T3", "furigana": "wǒ de jiārén dōu bú zài cǐdì, wǒ yí gè rén shēnghuó hěn gūdān", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "说话人指自己此刻所在的地方，相当于“这里”，常见于“我在此地”“来到此地”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此地", "is_correct": true, "explanation": "此地：说话人此刻所在的地方，作“住”的处所，句意通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能作为“住”的处所，句意不通。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“报纸”是印刷品，不能说“在报纸住”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开门用的工具，不能作为居住的处所。"}], "explanations": {"此地": "此地：说话人此刻所在的地方，作“住”的处所，句意通顺。", "椅子": "语义：“椅子”是家具，不能作为“住”的处所，句意不通。", "报纸": "搭配：“报纸”是印刷品，不能说“在报纸住”。", "钥匙": "语义：“钥匙”是开门用的工具，不能作为居住的处所。"}, "sentence_index": 0, "correct_answer": "此地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候住在很远的山村，此地冬天特别冷。", "explanation": "此句把“此地”用成了“那里”的意思（指远处的地方）。“此地”只能指说话人现在所在的地方，这里不能用。"}, {"text": "我十岁前一直在山里长大，此地的冬天很冷。", "explanation": "此句把“此地”用成了“故乡”的意思（指说话人以前生活的地方）。“此地”只能指说话人现在所在的地方。"}, {"text": "我住在上海，可是我的家人都在北京，此地的家人很想念我。", "explanation": "此句把“此地”用成了“外地”的意思（指家人所在的别处）。“此地”只能指说话人现在所在的地方，句中家人并不在此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此地", "is_correct": true, "explanation": "此地：说话人此刻所在的地方，用在“的人”前表示这个地方的人，句意通顺。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”是天体，不是地方，不能说“月亮的人”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”是物质，不能与“的人”构成搭配。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的器具，不能指代一个地方的人。"}], "explanations": {"此地": "此地：说话人此刻所在的地方，用在“的人”前表示这个地方的人，句意通顺。", "月亮": "语义：“月亮”是天体，不是地方，不能说“月亮的人”。", "石头": "搭配：“石头”是物质，不能与“的人”构成搭配。", "黑板": "语义：“黑板”是教室里的器具，不能指代一个地方的人。"}, "sentence_index": 6, "correct_answer": "此地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在北京，你在广州，你们此地最近天气怎么样？", "explanation": "此句把“此地”用成了“那边”的意思（指对方所在的广州）。“此地”只能指说话人现在所在的地方，问对方那里应说“那边”。"}, {"text": "隔着河望去，此地炊烟袅袅。", "explanation": "此句把“此地”用成了“对岸”的意思（指河对面的村子）。“此地”只能指说话人所在的地方，炊烟在河的另一边。"}, {"text": "我的朋友去年去了欧洲留学，此地的冬天很长。", "explanation": "此句把“此地”用成了“那边”的意思（指朋友所在的地方）。“此地”只能指说话人现在所在的地方，这里不能指朋友那边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在这个此地教书，学生都很可爱。", "corrected_sentence": "我在此地教书，学生都很可爱。", "error_description": "“此地”本身已有指示作用，前面不能再加“这个”；这里多加了“这个”，应去掉，写作“在此地教书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们此地吃饭，每个周末都很热闹。", "corrected_sentence": "我们在此地吃饭，每个周末都很热闹。", "error_description": "表示动作发生的地点时，“此地”前要加介词“在”，应写作“在此地吃饭”；这里漏掉了“在”，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
