INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "这个地方；这里。", "primary_collocate": null, "pronunciation": "cǐ dì", "ipa": "tsʰɨ˨˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他们离开了此地，再也没有回来。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地有一座很老的桥。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地风景很美，游客很多。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说此地以前是一条河。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在此地生活了一辈子。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地离市中心不太远。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经来过此地，所以认得路。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地的人们喜欢喝茶。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，此地是一个小村子。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在此地，然后去买东西。", "target_word": "此地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "叙述或介绍时指代已提到的某个地方，相当于“这个地方”，多用于第三人称叙述（此地风景、离开此地）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此地", "is_correct": true, "explanation": "此地：叙述中已提到的地方，作“离开”的宾语，句意通顺。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”是学习任务，不能说“离开了作业”。"}, {"text": "发票", "is_correct": false, "explanation": "语义：“发票”是凭证，不是可以离开的地方，句意不通。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”是心理状态，与“离开了”的搭配不当。"}], "explanations": {"此地": "此地：叙述中已提到的地方，作“离开”的宾语，句意通顺。", "作业": "搭配：“作业”是学习任务，不能说“离开了作业”。", "发票": "语义：“发票”是凭证，不是可以离开的地方，句意不通。", "感情": "搭配：“感情”是心理状态，与“离开了”的搭配不当。"}, "sentence_index": 0, "correct_answer": "此地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "此地很晚了，你该回家了。", "explanation": "此句把“此地”用成了“此时”的意思（指时间）。“此地”只指地点，表示时间应说“此时”。"}, {"text": "此地是我的父亲，他很严厉。", "explanation": "此句把“此地”用成了“此人”的意思（指一个人）。“此地”指地方，指人应说“此人”。"}, {"text": "此地是我昨天买的，很便宜。", "explanation": "此句把“此地”用成了“此物”的意思（指一件东西）。“此地”只指地点，指物应说“此物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此地", "is_correct": true, "explanation": "此地：叙述中已提到的地方，作“来过”的宾语，与“认得路”前后呼应。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：“梦想”是心中的愿望，不是可以去到的地方，与“来过”不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是计时器具，不能作为“来过”的对象。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”是情绪，不能与“来过”搭配。"}], "explanations": {"此地": "此地：叙述中已提到的地方，作“来过”的宾语，与“认得路”前后呼应。", "梦想": "语义：“梦想”是心中的愿望，不是可以去到的地方，与“来过”不符。", "闹钟": "语义：“闹钟”是计时器具，不能作为“来过”的对象。", "心情": "搭配：“心情”是情绪，不能与“来过”搭配。"}, "sentence_index": 6, "correct_answer": "此地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "此地以后，我们再也没有联系。", "explanation": "此句把“此地”用成了“此后”的意思（指时间之后）。“此地”只指地点，表示之后应说“此后”。"}, {"text": "此地，还有一件事要说。", "explanation": "此句把“此地”用成了“此外”的意思（表示补充）。“此地”只指地点，补充说明应说“此外”。"}, {"text": "此地是我的好朋友，我们认识十年了。", "explanation": "此句把“此地”用成了“此人”的意思（指一个人）。“此地”只指地点，指人应说“此人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当年这个此地是一个热闹的码头。", "corrected_sentence": "当年此地是一个热闹的码头。", "error_description": "“此地”本身已有指示作用，前面不能再加“这个”；这里多加了“这个”，应去掉，写作“当年此地是一个热闹的码头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人在这个此地住了几十年，从没离开过。", "corrected_sentence": "老人在此地住了几十年，从没离开过。", "error_description": "“此地”本身已有指示作用，前面不能再加“这个”；这里在“此地”前多加了“这个”，应去掉，写作“在此地住了几十年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
