INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97321, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很久以前有名的人。", "primary_collocate": null, "pronunciation": "lì shǐ rén wù", "ipa": "li˥˩ ʂʅ˨˩ ʐən˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "孔子是一位很有名的历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的历史人物是诸葛亮。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园里有很多历史人物的雕像。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写一个历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有这位历史人物用过的东西。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想拍一部电影，讲一个历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前的历史人物，我们只能从书里认识。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李白是中国最有名的历史人物之一。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢听历史人物的故事。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪位历史人物是唐朝的皇帝吗？", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "很久以前出名的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史人物", "is_correct": true, "explanation": "正确：「历史人物」指很久以前有名的人，可以用「一位」修饰，符合句意。"}, {"text": "文物", "is_correct": false, "explanation": "语义：文物是器物或遗迹，不是人，不能用来指「孔子」。"}, {"text": "时代", "is_correct": false, "explanation": "搭配：「一位」只用于人，不能用来数「时代」，「一位很有名的时代」不成立。"}, {"text": "名胜", "is_correct": false, "explanation": "语义：名胜是景点，不是人，不能说「孔子是一位很有名的名胜」。"}], "explanations": {"历史人物": "正确：「历史人物」指很久以前有名的人，可以用「一位」修饰，符合句意。", "文物": "语义：文物是器物或遗迹，不是人，不能用来指「孔子」。", "时代": "搭配：「一位」只用于人，不能用来数「时代」，「一位很有名的时代」不成立。", "名胜": "语义：名胜是景点，不是人，不能说「孔子是一位很有名的名胜」。"}, "sentence_index": 0, "correct_answer": "历史人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "辛亥革命是中国近代的重大历史人物。", "explanation": "这里应该用〈历史事件〉。辛亥革命是事件，不是人物。"}, {"text": "长城是中国著名的历史人物。", "explanation": "这里应该用〈古迹〉。长城是建筑遗迹，不是人。"}, {"text": "汉朝是中国很重要的历史人物。", "explanation": "这里应该用〈朝代〉。汉朝是一段时期，不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史人物", "is_correct": true, "explanation": "正确：「历史人物」指很久以前有名的人，与「很久以前的」「只能从书里认识」搭配，能填入空格。"}, {"text": "现代人物", "is_correct": false, "explanation": "语义：「现代人物」与「很久以前」时间矛盾，句子不成立。"}, {"text": "网红", "is_correct": false, "explanation": "语域：「网红」是口语化的新词，与书面化的「从书里认识」不协调，也与「很久以前」矛盾。"}, {"text": "当代明星", "is_correct": false, "explanation": "语义：「当代明星」与「很久以前」矛盾，不能说「很久以前的当代明星」。"}], "explanations": {"历史人物": "正确：「历史人物」指很久以前有名的人，与「很久以前的」「只能从书里认识」搭配，能填入空格。", "现代人物": "语义：「现代人物」与「很久以前」时间矛盾，句子不成立。", "网红": "语域：「网红」是口语化的新词，与书面化的「从书里认识」不协调，也与「很久以前」矛盾。", "当代明星": "语义：「当代明星」与「很久以前」矛盾，不能说「很久以前的当代明星」。"}, "sentence_index": 6, "correct_answer": "历史人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻居是一位历史人物。", "explanation": "这里把〈历史人物〉用成了〈当代人〉的意思。历史人物指很久以前有名的人，不能用来说现在住在身边的人。"}, {"text": "这位历史人物昨天在电视上接受了采访。", "explanation": "这里把〈历史人物〉用成了〈名人〉的意思。历史人物已经过世很久，不能说昨天接受采访的人。"}, {"text": "这位历史人物的孩子今年才三岁。", "explanation": "这里把〈历史人物〉用成了〈在世的人〉的意思。历史人物指很久以前有名的人，不能说他的孩子今年三岁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一位很久以前就很有名历史人物。", "corrected_sentence": "他是一位很久以前就很有名的历史人物。", "error_description": "错误：「很有名」和「历史人物」之间漏了「的」。修饰语和中心语之间要用「的」连接。正确：很有名的历史人物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很佩服这件历史人物的勇气。", "corrected_sentence": "他很佩服这位历史人物的勇气。", "error_description": "量词错误：「历史人物」指人，量词应用「位」，不能用「件」（「件」多用于物品、事情）。正确：「这位历史人物的勇气」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
