INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "历史上有影响的人物。", "primary_collocate": null, "pronunciation": "lì shǐ rén wù", "ipa": "li˥˩ ʂʅ˨˩ ʐən˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "秦始皇是影响中国的历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位改变了国家的历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙中山是近代很重要的历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史人物对社会的影响很大。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位历史人物的想法影响了很多人。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "郑和是明朝著名的历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要正确看待历史人物的功过。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把他看成伟大的历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱因斯坦也是改变世界的历史人物。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要了解一个历史人物，得多读书。", "target_word": "历史人物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "在历史上产生过重要影响的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史人物", "is_correct": true, "explanation": "正确：「历史人物」指在历史上产生过影响的人，与「影响中国的」搭配，能填入空格。"}, {"text": "古迹", "is_correct": false, "explanation": "语义：古迹是遗址或建筑，不是人，「秦始皇是影响中国的古迹」不成立。"}, {"text": "朝代", "is_correct": false, "explanation": "语义：朝代是一段历史时期，不是人，不能说「秦始皇是……朝代」。"}, {"text": "网红", "is_correct": false, "explanation": "语域：「网红」是口语化的新词，不用于评价历史人物，与「影响中国」也不搭。"}], "explanations": {"历史人物": "正确：「历史人物」指在历史上产生过影响的人，与「影响中国的」搭配，能填入空格。", "古迹": "语义：古迹是遗址或建筑，不是人，「秦始皇是影响中国的古迹」不成立。", "朝代": "语义：朝代是一段历史时期，不是人，不能说「秦始皇是……朝代」。", "网红": "语域：「网红」是口语化的新词，不用于评价历史人物，与「影响中国」也不搭。"}, "sentence_index": 0, "correct_answer": "历史人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "历史人物发生在公元前三世纪。", "explanation": "这里应该用〈战役〉。「发生」说的是事件，人物不能「发生」。"}, {"text": "历史人物在去年爆发了。", "explanation": "这里应该用〈战争〉。「爆发」用于战争、疫情等事件，不用于人物。"}, {"text": "历史人物修于明朝。", "explanation": "这里应该用〈宫殿〉。「修建」的对象是建筑，人物不能「修」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史人物", "is_correct": true, "explanation": "正确：「历史人物」是在历史上有影响的人，「看待……的功过」正合句意，能填入空格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能说「看待天气的功过」。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是内心感受，不能用来评价功过，句子不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：「脚步」是行走的动作，不能用来评价功过，句子不通。"}], "explanations": {"历史人物": "正确：「历史人物」是在历史上有影响的人，「看待……的功过」正合句意，能填入空格。", "天气": "语义：天气不是人，不能说「看待天气的功过」。", "心情": "语义：「心情」是内心感受，不能用来评价功过，句子不通。", "脚步": "语义：「脚步」是行走的动作，不能用来评价功过，句子不通。"}, "sentence_index": 6, "correct_answer": "历史人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位历史人物，研究历史已经很多年了。", "explanation": "这里把〈历史人物〉用成了〈历史学家〉的意思。历史人物指历史上有影响的人，研究历史的人要用历史学家，不能用它。"}, {"text": "他是一个没有任何影响的历史人物。", "explanation": "这里把〈历史人物〉用成了〈普通人〉的意思。历史人物指历史上有影响的人，不能用来说毫无影响的普通人。"}, {"text": "历史人物都用手机，每天刷微博。", "explanation": "这里把〈历史人物〉用成了〈现代人〉的意思。历史人物指历史上有影响的人，不能指现在用手机的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
