INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "僧道为超度、祈福等举行的宗教仪式。", "primary_collocate": null, "pronunciation": "fǎ shì", "ipa": "fa˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "家里请了和尚为去世的爷爷做法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寺里每年都会举行祈福的法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了超度亲人，他们办了一场法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场法事从早上一直做到中午。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法事上，和尚们念着经，大家安静地站着。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶想请道士为全家做一场祈福法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加过一次超度亲人的法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里办法事的时候，很多人来了。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法事结束后，主人给和尚送了水果。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在庙里为病人做了法事，希望他快点好。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场法事", "label": "量词"}], "register": "中性", "sense_fingerprint": "和尚或道士为超度亡人、祈求平安而举行的宗教仪式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97326, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法事", "is_correct": true, "explanation": "法事（fǎ shì）：和尚或道士为超度、祈福等举行的宗教仪式。"}, {"text": "发誓", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，意思是发誓。"}, {"text": "发式", "is_correct": false, "explanation": "fà（第四声）与 fǎ（第三声）声调不同，意思是发式（发型）。"}, {"text": "法师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是法师（僧人）。"}, {"text": "法治", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是法治。"}], "explanations": {"法事": "法事（fǎ shì）：和尚或道士为超度、祈福等举行的宗教仪式。", "发誓": "fā（第一声）与 fǎ（第三声）声调不同，意思是发誓。", "发式": "fà（第四声）与 fǎ（第三声）声调不同，意思是发式（发型）。", "法师": "shī（第一声）与 shì（第四声）声调不同，意思是法师（僧人）。", "法治": "zhì 与 shì 声母不同（zh 与 sh），意思是法治。"}, "sentence_index": null, "correct_answer": "法事"}, "level_3": {"options": [{"text": "法事", "is_correct": true, "explanation": "法事：和尚或道士为超度、祈福等举行的宗教仪式，为去世的爷爷做的就是法事。"}, {"text": "生意", "is_correct": false, "explanation": "语义：和尚为去世的人做的不是生意，与超度无关。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏与超度亡人的宗教活动无关。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗操作，不能为去世的爷爷做。"}], "explanations": {"法事": "法事：和尚或道士为超度、祈福等举行的宗教仪式，为去世的爷爷做的就是法事。", "生意": "语义：和尚为去世的人做的不是生意，与超度无关。", "游戏": "语义：游戏与超度亡人的宗教活动无关。", "手术": "语义：手术是医疗操作，不能为去世的爷爷做。"}, "sentence_index": 0, "correct_answer": "法事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校的开学法事很隆重。", "explanation": "这里应该用〈仪式〉。“法事”指和尚道士为超度、祈福办的宗教仪式，开学不用“法事”。"}, {"text": "运动会的法事很精彩。", "explanation": "这里应该用〈开幕式〉。“法事”是宗教仪式，不用于体育活动。"}, {"text": "毕业法事上，校长讲了话。", "explanation": "这里应该用〈典礼〉。“法事”专指宗教仪式，毕业典礼不能说“法事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97326, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "法事", "is_correct": true, "explanation": "法事（fǎ shì）：和尚或道士为超度、祈福等举行的宗教仪式。"}, {"text": "法术", "is_correct": false, "explanation": "shù 与 shì 韵母不同（u 与 i），意思是法术。"}, {"text": "法制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是法制（法律制度）。"}, {"text": "法系", "is_correct": false, "explanation": "xì 与 shì 声母不同（x 与 sh），意思是法系（法律体系）。"}, {"text": "方式", "is_correct": false, "explanation": "fāng 与 fǎ 韵母不同（-ang 与 -a），意思是方式。"}], "explanations": {"法事": "法事（fǎ shì）：和尚或道士为超度、祈福等举行的宗教仪式。", "法术": "shù 与 shì 韵母不同（u 与 i），意思是法术。", "法制": "zhì 与 shì 声母不同（zh 与 sh），意思是法制（法律制度）。", "法系": "xì 与 shì 声母不同（x 与 sh），意思是法系（法律体系）。", "方式": "fāng 与 fǎ 韵母不同（-ang 与 -a），意思是方式。"}, "sentence_index": null, "correct_answer": "法事"}, "level_3": {"options": [{"text": "法事", "is_correct": true, "explanation": "法事：和尚或道士为超度、祈福等举行的宗教仪式，超度亲人用的就是法事。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是庆祝结婚的仪式，与超度亲人无关。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是文娱活动，不用于超度亲人。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“超度”的对象是亡人，不与“生日”组合。"}], "explanations": {"法事": "法事：和尚或道士为超度、祈福等举行的宗教仪式，超度亲人用的就是法事。", "婚礼": "语义：婚礼是庆祝结婚的仪式，与超度亲人无关。", "晚会": "语义：晚会是文娱活动，不用于超度亲人。", "生日": "搭配：“超度”的对象是亡人，不与“生日”组合。"}, "sentence_index": 6, "correct_answer": "法事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校在礼堂举行了一场法事，很多人来看。", "explanation": "这里应该用〈演出〉。“法事”是和尚道士的宗教仪式，不指文艺演出。"}, {"text": "村里召开了一场法事，大家讨论农事。", "explanation": "这里应该用〈会议〉。“法事”指宗教仪式，不指为讨论事情而开的会。"}, {"text": "这次法事有五位选手参加。", "explanation": "这里应该用〈比赛〉。“选手”用于比赛，“法事”是宗教仪式，不能说有选手参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们办了一只法事为亲人祈福。", "corrected_sentence": "他们办了一场法事为亲人祈福。", "error_description": "量词错误：“法事”应用“场”计量，“只”用于动物，不能说“一只法事”，应改为“一场法事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们吃法事，大家都累了。", "corrected_sentence": "他们做法事，大家都累了。", "error_description": "动词错误：“法事”应与“做”搭配，不能说“吃法事”，应改为“做法事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
