INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97329, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97329, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大学里学习法律知识的专业。", "primary_collocate": null, "pronunciation": "fǎ xué", "ipa": "fa˨˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他大学读的是法学，现在想当律师。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习法学需要记很多法律条文。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐对法学很感兴趣，常去听课。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打算毕业以后继续学法学。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法学课上，老师讲了一个有名的案子。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过很多法学书，所以懂法律。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学法学的人以后可以当律师或法官。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的专业是法学，不是医学。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要学好法学，先得多读法律条文。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在大学教法学，学生都很喜欢他。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法学院", "label": "复合"}, {"form": "法學", "label": "繁体"}], "register": "正式", "sense_fingerprint": "大学中学习法律知识的专业，侧重就读与学习", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法学", "is_correct": true, "explanation": "正确：“法学”是可以读的专业，与“想当律师”的语境相符。"}, {"text": "法院", "is_correct": false, "explanation": "语义：法院是审理案件的机关，不是学习的专业，不能说“读的是法院”。"}, {"text": "律师", "is_correct": false, "explanation": "搭配：“读的是”后要接学科或专业名称，“律师”是职业，不能用来“读”。"}, {"text": "法官", "is_correct": false, "explanation": "语义：法官是审判案件的职业，不是可以学习的专业，与“读的是”不合。"}], "explanations": {"法学": "正确：“法学”是可以读的专业，与“想当律师”的语境相符。", "法院": "语义：法院是审理案件的机关，不是学习的专业，不能说“读的是法院”。", "律师": "搭配：“读的是”后要接学科或专业名称，“律师”是职业，不能用来“读”。", "法官": "语义：法官是审判案件的职业，不是可以学习的专业，与“读的是”不合。"}, "sentence_index": 0, "correct_answer": "法学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的法学规定，每个人都要遵守。", "explanation": "这里应该用〈法律〉。法学是研究法律的学问，本身不是法律条文；“规定”和“遵守”的对象应是法律。"}, {"text": "这起案子已经交给法学审理了。", "explanation": "这里应该用〈法院〉。法学是学科，不能审理案件；审理案件的是法院。"}, {"text": "他找了法学当自己的代理人。", "explanation": "这里应该用〈律师〉。“找”和“当代理人”的对象应是人，法学是学问，不能当代理人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法学", "is_correct": true, "explanation": "正确：“法学”是可以学习的专业，“学法学的人”成立。"}, {"text": "围棋", "is_correct": false, "explanation": "语义：围棋是棋类，与律师、法官无关，句意不符。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱是场所，不是学习的内容，“学监狱”说不通。"}, {"text": "天文", "is_correct": false, "explanation": "语义：天文是另一门学科，与律师、法官无关，句意不符。"}], "explanations": {"法学": "正确：“法学”是可以学习的专业，“学法学的人”成立。", "围棋": "语义：围棋是棋类，与律师、法官无关，句意不符。", "监狱": "语义：监狱是场所，不是学习的内容，“学监狱”说不通。", "天文": "语义：天文是另一门学科，与律师、法官无关，句意不符。"}, "sentence_index": 6, "correct_answer": "法学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家去年颁布了新法学。", "explanation": "这里应该用〈法规〉。“颁布”的对象是法规等成文规定，法学是学问，不能被颁布。"}, {"text": "他听取了证人的法学。", "explanation": "这里应该用〈证词〉。“听取”的对象是证词等陈述，法学是学问，不是证人的陈述。"}, {"text": "他终于实现了自己的法学。", "explanation": "这里应该用〈梦想〉。“实现”的对象是梦想、愿望，法学是学科，不能被实现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法学是一只很难的学科。", "corrected_sentence": "法学是一门很难的学科。", "error_description": "量词错误：学科要用量词“门”，“只”用于动物等，不能用来数学科。应改为“法学是一门很难的学科。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我朋友正在学过法学。", "corrected_sentence": "我朋友学过法学。", "error_description": "体标错误：“正在”表示动作进行中，与表示经历的“过”不能同时使用。应删去“正在”，改为“我朋友学过法学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
