INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究法律和法律现象的学科。", "primary_collocate": null, "pronunciation": "fǎ xué", "ipa": "fa˨˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "法学是一门研究法律的学科。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授研究法学已经三十年了。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法学和经济学都是大学里的重要学科。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在法学方面写过不少文章。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法学研究要看法律，也要看社会。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的法学研究很有名，很多学者来这里交流。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是研究法学的专家，常在书里引用法律条文。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在写一篇关于法学的论文。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的法学越来越受到重视。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法学要研究法律为什么这样规定。", "target_word": "法学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法学院", "label": "复合"}, {"form": "法學", "label": "繁体"}], "register": "正式", "sense_fingerprint": "研究法律与法律现象的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法学", "is_correct": true, "explanation": "正确：“法学”是研究法律的学科，与后文的解释一致。"}, {"text": "医学", "is_correct": false, "explanation": "语义：医学研究的是人体和疾病，与“研究法律”不符。"}, {"text": "历史学", "is_correct": false, "explanation": "语义：历史学研究的是过去的事件，不研究法律，与后文矛盾。"}, {"text": "律师", "is_correct": false, "explanation": "搭配：“是一门……学科”要接学科名称，“律师”是职业，不能这样用。"}], "explanations": {"法学": "正确：“法学”是研究法律的学科，与后文的解释一致。", "医学": "语义：医学研究的是人体和疾病，与“研究法律”不符。", "历史学": "语义：历史学研究的是过去的事件，不研究法律，与后文矛盾。", "律师": "搭配：“是一门……学科”要接学科名称，“律师”是职业，不能这样用。"}, "sentence_index": 0, "correct_answer": "法学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家颁布了新的法学，大家都要遵守。", "explanation": "这里应该用〈法律〉。“颁布”和“遵守”的对象应是法律条文，法学是研究法律的学问。"}, {"text": "判决是法学作出的。", "explanation": "这里应该用〈法院〉。“作出判决”的是法院，法学是学科，不能作出判决。"}, {"text": "他仔细听取了证人的法学。", "explanation": "这里应该用〈证词〉。“听取”的对象应是证词，法学是学问，不是证人的陈述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法学", "is_correct": true, "explanation": "正确：“法学”是研究法律的学问，“研究法学的专家”成立。"}, {"text": "围棋", "is_correct": false, "explanation": "语义：围棋是棋类，与法律条文无关，句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是法律研究的对象，与“引用法律条文”无关，句意不符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是技艺，与法律研究无关，句意不符。"}], "explanations": {"法学": "正确：“法学”是研究法律的学问，“研究法学的专家”成立。", "围棋": "语义：围棋是棋类，与法律条文无关，句意不符。", "天气": "语义：天气不是法律研究的对象，与“引用法律条文”无关，句意不符。", "烹饪": "语义：烹饪是技艺，与法律研究无关，句意不符。"}, "sentence_index": 6, "correct_answer": "法学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法学是去年才颁布的。", "explanation": "这里应该用〈法规〉。“颁布”的对象是法规，法学是学问，不能被颁布。"}, {"text": "他请了法学来打这场官司。", "explanation": "这里应该用〈律师〉。“请”的对象应是人，法学是学问，不能被请来打官司。"}, {"text": "她终于实现了自己的法学。", "explanation": "这里应该用〈理想〉。“实现”的对象是理想、愿望，法学是学科，不能被实现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在研究过法学。", "corrected_sentence": "他研究过法学。", "error_description": "体标错误：“正在”表示动作进行中，与表示经历的“过”不能同时使用。应删去“正在”，改为“他研究过法学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法学是一只重要的学科。", "corrected_sentence": "法学是一门重要的学科。", "error_description": "量词错误：学科要用量词“门”，“只”不能用来数学科。应改为“法学是一门重要的学科。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
