INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在家里洗澡的小房间。", "primary_collocate": null, "pronunciation": "yù shì", "ipa": "y ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "我家的浴室很小，只有一个窗户。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在浴室里洗澡，没听到电话。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室里的镜子上有很多水汽。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把毛巾挂在浴室的墙上。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子有两个卧室和一个浴室。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室的地很滑，小心一点。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在浴室里放了一盆花。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上都在浴室里唱歌。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室门开着，里面有热水的声音。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把脏衣服拿到了浴室。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}], "register": "中性", "sense_fingerprint": "家里洗澡用的小房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97333, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浴室", "is_correct": true, "explanation": "浴室：yù shì，指在家里洗澡的小房间。"}, {"text": "玉石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是玉石，不是浴室。"}, {"text": "雨势", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨势，不是浴室。"}, {"text": "叙事", "is_correct": false, "explanation": "xù 与 yù 声母不同（xù 多了声母 x），意思是叙述事情，不是浴室。"}], "explanations": {"浴室": "浴室：yù shì，指在家里洗澡的小房间。", "玉石": "shí（第二声）与 shì（第四声）声调不同，意思是玉石，不是浴室。", "雨势": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨势，不是浴室。", "叙事": "xù 与 yù 声母不同（xù 多了声母 x），意思是叙述事情，不是浴室。"}, "sentence_index": null, "correct_answer": "浴室"}, "level_3": {"options": [{"text": "浴室", "is_correct": true, "explanation": "“浴室”是家里洗澡的小房间，与“只有一个窗户”的小房间描述相符。"}, {"text": "车站", "is_correct": false, "explanation": "语义：家里不会有车站，“我家的车站”与家庭语境矛盾。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“很小，只有一个窗户”描述房间，电话不能用来这样描述。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是背在身上的袋子，不会有窗户，与「只有一个窗户」的描述矛盾。"}], "explanations": {"浴室": "“浴室”是家里洗澡的小房间，与“只有一个窗户”的小房间描述相符。", "车站": "语义：家里不会有车站，“我家的车站”与家庭语境矛盾。", "电话": "搭配：“很小，只有一个窗户”描述房间，电话不能用来这样描述。", "书包": "语义：书包是背在身上的袋子，不会有窗户，与「只有一个窗户」的描述矛盾。"}, "sentence_index": 0, "correct_answer": "浴室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在浴室里做饭，香味飘满了整个屋子。", "explanation": "这里应该用〈厨房〉。浴室是在家里洗澡的小房间，做饭的地方应说厨房。"}, {"text": "他每天晚上在浴室里写作业。", "explanation": "这里应该用〈书房〉。浴室是在家里洗澡的小房间，写作业的地方应说书房。"}, {"text": "他们每晚都在浴室里看电视。", "explanation": "这里应该用〈客厅〉。浴室是在家里洗澡的小房间，看电视的地方应说客厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97333, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "浴室", "is_correct": true, "explanation": "浴室：yù shì，指在家里洗澡的小房间。"}, {"text": "去世", "is_correct": false, "explanation": "qù 比 yù 多了声母 q，意思是去世，不是浴室。"}, {"text": "议事", "is_correct": false, "explanation": "yì 与 yù 韵母不同，意思是商议事情，不是浴室。"}, {"text": "鱼市", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是卖鱼的市场，不是浴室。"}, {"text": "于是", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，是连词，不是浴室。"}], "explanations": {"浴室": "浴室：yù shì，指在家里洗澡的小房间。", "去世": "qù 比 yù 多了声母 q，意思是去世，不是浴室。", "议事": "yì 与 yù 韵母不同，意思是商议事情，不是浴室。", "鱼市": "yú（第二声）与 yù（第四声）声调不同，意思是卖鱼的市场，不是浴室。", "于是": "yú（第二声）与 yù（第四声）声调不同，是连词，不是浴室。"}, "sentence_index": null, "correct_answer": "浴室"}, "level_3": {"options": [{"text": "浴室", "is_correct": true, "explanation": "“妈妈在浴室里放了一盆花”，“浴室”是房间，可以放花，句意完整。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：妈妈不会在海洋里放一盆花，与日常生活的语境矛盾。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机是机械部件，不能放花，与“放了一盆花”的语境矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“手机里”指手机内部，不能说在手机里放一盆花。"}], "explanations": {"浴室": "“妈妈在浴室里放了一盆花”，“浴室”是房间，可以放花，句意完整。", "海洋": "语义：妈妈不会在海洋里放一盆花，与日常生活的语境矛盾。", "发动机": "语义：发动机是机械部件，不能放花，与“放了一盆花”的语境矛盾。", "手机": "搭配：“手机里”指手机内部，不能说在手机里放一盆花。"}, "sentence_index": 6, "correct_answer": "浴室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每晚回到浴室里睡觉。", "explanation": "这里应该用〈卧室〉。浴室是在家里洗澡的小房间，睡觉的地方应说卧室。"}, {"text": "农民在浴室里种了一大片玉米。", "explanation": "这里应该用〈田里〉。浴室是在家里洗澡的小房间，种玉米的地方应说田里。"}, {"text": "他把车停在浴室里，车门都打不开。", "explanation": "这里应该用〈车库〉。浴室是在家里洗澡的小房间，停车的地方应说车库。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "浴室里有两条镜子。", "corrected_sentence": "浴室里有两面镜子。", "error_description": "错误：量词“条”用于细长的东西，镜子应该用“面”。正确说法是“两面镜子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "浴室的里有一个新的花洒。", "corrected_sentence": "浴室里有一个新的花洒。", "error_description": "错误：方位词“里”前面多加了“的”。正确说法是“浴室里”，方位词直接接在名词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
