INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专供洗澡的房间。", "primary_collocate": null, "pronunciation": "yù shì", "ipa": "y ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "这家酒店的每个房间都有浴室。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的浴室晚上七点开门。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里有专门给工人用的浴室。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室里有热水，也有干净的毛巾。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳以后，我们去浴室洗澡。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间浴室只用来洗澡，不放别的东西。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室外面有一排小柜子。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们新建了一间大浴室。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每个周末都去村里的浴室。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室的灯坏了，里面很黑。", "target_word": "浴室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}], "register": "中性", "sense_fingerprint": "专门用来洗澡的房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浴室", "is_correct": true, "explanation": "浴室：yù shì，指专门用来洗澡的房间。"}, {"text": "玉石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是玉石，不是浴室。"}, {"text": "雨势", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨势，不是浴室。"}, {"text": "叙事", "is_correct": false, "explanation": "xù 与 yù 声母不同（xù 多了声母 x），意思是叙述事情，不是浴室。"}], "explanations": {"浴室": "浴室：yù shì，指专门用来洗澡的房间。", "玉石": "shí（第二声）与 shì（第四声）声调不同，意思是玉石，不是浴室。", "雨势": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨势，不是浴室。", "叙事": "xù 与 yù 声母不同（xù 多了声母 x），意思是叙述事情，不是浴室。"}, "sentence_index": null, "correct_answer": "浴室"}, "level_3": {"options": [{"text": "浴室", "is_correct": true, "explanation": "“每个房间都有浴室”，专供洗澡的房间是酒店房间的常见配置，句意通顺。"}, {"text": "花园", "is_correct": false, "explanation": "语义：酒店的房间里不会都有花园，与“每个房间都有”的语境不符。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原是广阔的自然地带，不可能是每个房间都有的东西。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“房间都有”的对象应是房间的设施，“星期”不能作房间所拥有的东西。"}], "explanations": {"浴室": "“每个房间都有浴室”，专供洗澡的房间是酒店房间的常见配置，句意通顺。", "花园": "语义：酒店的房间里不会都有花园，与“每个房间都有”的语境不符。", "草原": "语义：草原是广阔的自然地带，不可能是每个房间都有的东西。", "星期": "搭配：“房间都有”的对象应是房间的设施，“星期”不能作房间所拥有的东西。"}, "sentence_index": 0, "correct_answer": "浴室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每天上午在浴室里给学生上数学课。", "explanation": "这里应该用〈教室〉。浴室是专供洗澡的房间，上课的地方应说教室。"}, {"text": "工厂的浴室里摆满了机器，工人在这里装配产品。", "explanation": "这里应该用〈车间〉。浴室是专供洗澡的房间，装配产品的场所应说车间。"}, {"text": "这家酒店的浴室里摆着一张餐桌，供客人吃饭。", "explanation": "这里应该用〈餐厅〉。浴室是专供洗澡的房间，供客人吃饭的地方应说餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97334, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "浴室", "is_correct": true, "explanation": "浴室：yù shì，指专门用来洗澡的房间。"}, {"text": "去世", "is_correct": false, "explanation": "qù 比 yù 多了声母 q，意思是去世，不是浴室。"}, {"text": "议事", "is_correct": false, "explanation": "yì 与 yù 韵母不同，意思是商议事情，不是浴室。"}, {"text": "余事", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是剩下的事，不是浴室。"}, {"text": "语式", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是语法上的表达方式，不是浴室。"}], "explanations": {"浴室": "浴室：yù shì，指专门用来洗澡的房间。", "去世": "qù 比 yù 多了声母 q，意思是去世，不是浴室。", "议事": "yì 与 yù 韵母不同，意思是商议事情，不是浴室。", "余事": "yú（第二声）与 yù（第四声）声调不同，意思是剩下的事，不是浴室。", "语式": "yǔ（第三声）与 yù（第四声）声调不同，意思是语法上的表达方式，不是浴室。"}, "sentence_index": null, "correct_answer": "浴室"}, "level_3": {"options": [{"text": "浴室", "is_correct": true, "explanation": "“浴室外面有一排小柜子”，浴室是房间，外面可以放柜子，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“……外面”要求处所名词，“天气”不能作处所。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能放一排小柜子，句意不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋上不会放一排小柜子，与“外面有一排小柜子”的语境矛盾。"}], "explanations": {"浴室": "“浴室外面有一排小柜子”，浴室是房间，外面可以放柜子，句意通顺。", "天气": "搭配：“……外面”要求处所名词，“天气”不能作处所。", "太阳": "语义：太阳是天体，不能放一排小柜子，句意不通。", "海洋": "语义：海洋上不会放一排小柜子，与“外面有一排小柜子”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "浴室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车开进了浴室，乘客们纷纷下车。", "explanation": "这里应该用〈车站〉。浴室是专供洗澡的房间，火车停靠的地方应说车站。"}, {"text": "他每天早上去浴室里喂鸡、捡鸡蛋。", "explanation": "这里应该用〈鸡舍〉。浴室是专供洗澡的房间，养鸡的地方应说鸡舍。"}, {"text": "学生们每晚在浴室里的床上睡觉，十点熄灯。", "explanation": "这里应该用〈宿舍〉。浴室是专供洗澡的房间，学生睡觉的地方应说宿舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务员昨天把浴室打扫干净。", "corrected_sentence": "服务员昨天把浴室打扫干净了。", "error_description": "错误：叙述已经发生的事，句末要有表示完成的「了」。「服务员昨天把浴室打扫干净」少了「了」，句子不自然。正确说法是「服务员昨天把浴室打扫干净了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校新建了两张浴室。", "corrected_sentence": "学校新建了两间浴室。", "error_description": "错误：量词“张”用于桌子、纸等平面的东西，浴室是房间，应该用“间”。正确说法是“两间浴室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
