INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97338, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能在水下航行的军用舰艇。", "primary_collocate": null, "pronunciation": "qián tǐng", "ipa": "tɕʰjɛn˧˥ tʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "海军的新潜艇今天出海了。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘潜艇属于海军，能在水下航行好几个月。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人们坐着潜艇，在深海里执行任务。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜艇上的水兵很少能看到太阳。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的雷达发现了敌人的潜艇。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一艘军用潜艇，不能随便参观。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜艇从海底浮上来，水兵走出舱门。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷年轻时在潜艇上当过兵。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，潜艇常常躲在海底。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军为新潜艇举行了欢迎仪式。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艘", "label": "量词"}, {"form": "核潜艇", "label": "复合词"}, {"form": "潛艇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "海军使用的水下军舰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c091977-6e47-4361-b22e-fc75be886fea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜艇", "is_correct": true, "explanation": "潜艇：能在水下航行的军用舰艇，与海军新舰艇出海的语境相符。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机在空中飞行，不能在海上出海，“出海”只用于船只舰艇。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“出海”只与船只、舰艇搭配，不能说房子出海。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车在陆地上行驶，不能在海上出海。"}], "explanations": {"潜艇": "潜艇：能在水下航行的军用舰艇，与海军新舰艇出海的语境相符。", "飞机": "语义：飞机在空中飞行，不能在海上出海，“出海”只用于船只舰艇。", "房子": "搭配：“出海”只与船只、舰艇搭配，不能说房子出海。", "汽车": "语义：汽车在陆地上行驶，不能在海上出海。"}, "sentence_index": 0, "correct_answer": "潜艇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渔民的潜艇每天一早出港捕鱼。", "explanation": "这里应该用〈渔船〉。捕鱼是渔船的用途，潜艇是军用舰艇，不用来捕鱼。"}, {"text": "潜艇在马路上堵了好久，司机们都在按喇叭。", "explanation": "这里应该用〈汽车〉。堵在马路上、司机按喇叭的是汽车，潜艇是水下军舰，不在马路上行驶。"}, {"text": "这艘潜艇靠风力在海上前进。", "explanation": "这里应该用〈帆船〉。靠风力前进是帆船的做法，潜艇靠动力在水下航行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜艇", "is_correct": true, "explanation": "潜艇：能在水下航行的舰艇，可以从海底浮上来，与舱门、水兵的语境相符。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁在地下轨道上行驶，不会从海底浮上来。"}, {"text": "大楼", "is_correct": false, "explanation": "搭配：“浮上来”一般不与建筑搭配，大楼不能从海底浮上来。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有动力，不能自己从海底浮上来并让水兵走出舱门。"}], "explanations": {"潜艇": "潜艇：能在水下航行的舰艇，可以从海底浮上来，与舱门、水兵的语境相符。", "地铁": "语义：地铁在地下轨道上行驶，不会从海底浮上来。", "大楼": "搭配：“浮上来”一般不与建筑搭配，大楼不能从海底浮上来。", "石头": "语义：石头没有动力，不能自己从海底浮上来并让水兵走出舱门。"}, "sentence_index": 6, "correct_answer": "潜艇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘潜艇的甲板上停着几架战斗机，随时准备起飞。", "explanation": "这里应该用〈航母〉。战斗机停放、起飞依靠甲板，这是航空母舰的特征，潜艇没有飞行甲板。"}, {"text": "下班高峰期，马路上堵着一排潜艇。", "explanation": "这里应该用〈公交车〉。堵在马路上的是公交车这类陆上车辆，潜艇只能在水下航行。"}, {"text": "小朋友们在公园里坐潜艇，在天上转圈。", "explanation": "这里应该用〈摩天轮〉。在公园里坐着在空中转圈的是摩天轮，潜艇是在水下航行的军用舰艇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把潜艇慢慢浮上来了。", "corrected_sentence": "这艘潜艇慢慢浮上来了。", "error_description": "量词错误：“把”用于有柄的器物，潜艇是船只，量词应用“艘”。应说“这艘潜艇慢慢浮上来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "潜艇终于飞下去了。", "corrected_sentence": "潜艇终于沉下去了。", "error_description": "搭配错误：“飞”用于能在空中飞行的物体，潜艇在水下，应说“沉下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
