INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97342, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来访问和查看网页的软件。", "primary_collocate": null, "pronunciation": "liú lǎn qì", "ipa": "liou˧˥ lan˨˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "我的电脑里装了两个浏览器。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个浏览器打开网页很快。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先打开浏览器，再输入网址。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把浏览器的主页改成了新闻网站。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上的浏览器可以看视频。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浏览器太旧了，网页打不开。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用哪个浏览器上网？", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款浏览器有很多好用的插件。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把浏览器里的历史记录都删了。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么在浏览器里收藏网址。", "target_word": "浏览器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "款", "label": "量词"}, {"form": "手机浏览器", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来访问和查看网页的软件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是独立的设备，不能装在电脑里，电脑里装的是软件。"}, {"text": "鼠标", "is_correct": false, "explanation": "语义：鼠标是外接的硬件，不是装进电脑的软件。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：“装”用于程序、软件，不说“装文件”，文件应说“存”。"}, {"text": "浏览器", "is_correct": true, "explanation": "正确：“装”与软件搭配，“两个浏览器”指两款浏览器软件。"}], "explanations": {"手机": "语义：手机是独立的设备，不能装在电脑里，电脑里装的是软件。", "鼠标": "语义：鼠标是外接的硬件，不是装进电脑的软件。", "文件": "搭配：“装”用于程序、软件，不说“装文件”，文件应说“存”。", "浏览器": "正确：“装”与软件搭配，“两个浏览器”指两款浏览器软件。"}, "sentence_index": 0, "correct_answer": "浏览器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用浏览器拍了一张全家福。", "explanation": "这里应该用〈相机〉。拍照要用相机，浏览器只是访问网页的软件，不能用来拍照。"}, {"text": "我把浏览器复制到了地址栏里。", "explanation": "这里应该用〈网址〉。复制进地址栏的是网址，浏览器本身不能放进地址栏。"}, {"text": "这个浏览器的旋律很好听。", "explanation": "这里应该用〈歌曲〉。旋律属于歌曲，浏览器是打开网页的软件，没有旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网页", "is_correct": false, "explanation": "语义：网页是上网时看到的内容，不是用来上网的工具。"}, {"text": "浏览器", "is_correct": true, "explanation": "正确：浏览器是上网用的软件，“用…上网”搭配工具。"}, {"text": "文件夹", "is_correct": false, "explanation": "语义：文件夹用来存放文件，不能用来上网。"}, {"text": "打印机", "is_correct": false, "explanation": "语义：打印机是输出纸质文件的设备，不能用来上网。"}], "explanations": {"网页": "语义：网页是上网时看到的内容，不是用来上网的工具。", "浏览器": "正确：浏览器是上网用的软件，“用…上网”搭配工具。", "文件夹": "语义：文件夹用来存放文件，不能用来上网。", "打印机": "语义：打印机是输出纸质文件的设备，不能用来上网。"}, "sentence_index": 6, "correct_answer": "浏览器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑里有一张浏览器。", "explanation": "这里应该用〈个〉或〈款〉。浏览器是软件，“张”用于纸张、桌子这类平面的东西，不能用来数软件。"}, {"text": "我下载了一只浏览器。", "explanation": "这里应该用〈款〉。“只”多用于动物和成对物品中的一个，不用来数软件。"}, {"text": "他在平板上安装了一块浏览器。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，不用来数软件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把浏览器关了掉。", "corrected_sentence": "我把浏览器关掉了。", "error_description": "错误：“关了掉”，正确：“关掉了”。“掉”是结果补语，要紧跟动词“关”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我浏览器上网。", "corrected_sentence": "我用浏览器上网。", "error_description": "错误：漏掉了“用”，应说“用浏览器上网”。“用”引出工具，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
