INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不用线，把声音送到很远地方的东西。", "primary_collocate": null, "pronunciation": "wú xiàn diàn", "ipa": "u ɕjɛn tjɛn", "syllable_count": 3, "sentences": [{"text": "爷爷有一台旧无线电。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在无线电里听到了天气预报。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开无线电，听了一首老歌。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台无线电不用线，也能听到声音。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，家里的无线电是最贵的东西。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有电池，无线电不响了。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把无线电放在桌子上。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无线电里传来一个熟悉的声音。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的人靠无线电知道外面的事。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的无线电坏了，我帮他修过。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "無線電", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不用线传送声音的设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无线电", "is_correct": true, "explanation": "正确：无线电是不用线传送声音的设备，量词用“台”，与“一台旧”相符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“台”不用于书籍，“一台旧书”不成立。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不是器械，不能说“一台旧花”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头不用量词“台”计量，“一台旧石头”不成立。"}], "explanations": {"无线电": "正确：无线电是不用线传送声音的设备，量词用“台”，与“一台旧”相符。", "书": "搭配：量词“台”不用于书籍，“一台旧书”不成立。", "花": "语义：花不是器械，不能说“一台旧花”。", "石头": "搭配：石头不用量词“台”计量，“一台旧石头”不成立。"}, "sentence_index": 0, "correct_answer": "无线电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋子里的无线电亮着，照得满屋子都是光。", "explanation": "这里应该用〈电灯〉。无线电不发光，“亮着”和“照得满屋光”只能用于电灯。"}, {"text": "无线电里有很多精彩的图片。", "explanation": "这里应该用〈书〉。无线电只传送声音，不能呈现图片。"}, {"text": "无线电里有很多牛奶。", "explanation": "这里应该用〈冰箱〉。无线电用于传送声音，不能存放食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无线电", "is_correct": true, "explanation": "正确：无线电是可以搬动的具体设备，能放在桌子上。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法被搬动，不能放在桌子上。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是广阔的自然现象，不能放在桌子上。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“把……放在……”的受事要求是可以搬动的具体物品，“空气”不能被搬放。"}], "explanations": {"无线电": "正确：无线电是可以搬动的具体设备，能放在桌子上。", "大海": "语义：大海无法被搬动，不能放在桌子上。", "天空": "语义：天空是广阔的自然现象，不能放在桌子上。", "空气": "配价：“把……放在……”的受事要求是可以搬动的具体物品，“空气”不能被搬放。"}, "sentence_index": 6, "correct_answer": "无线电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑无线电去上班。", "explanation": "这里应该用〈自行车〉。无线电是收听声音的机器，不能骑。"}, {"text": "他冬天穿着无线电出门。", "explanation": "这里应该用〈大衣〉。无线电不能穿，“穿着”只能用于衣物。"}, {"text": "妈妈用无线电炒菜。", "explanation": "这里应该用〈锅〉。无线电不能用来炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家那只无线电声音很清楚。", "corrected_sentence": "我家那台无线电声音很清楚。", "error_description": "“无线电”作为设备，量词应用“台”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他无线电放在客厅里。", "corrected_sentence": "他把无线电放在客厅里。", "error_description": "错误：漏掉了「把」。「把」用来引出被处置的对象「无线电」，没有「把」，「无线电」直接放在主语后面，句子不通顺。正确说法是「他把无线电放在客厅里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
