INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用无线电波传送信息的技术或设备。", "primary_collocate": null, "pronunciation": "wú xiàn diàn", "ipa": "u ɕjɛn tjɛn", "syllable_count": 3, "sentences": [{"text": "无线电可以把信息传到很远的地方。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习无线电技术。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的船靠无线电和岸上联系。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无线电的发明改变了人们的生活。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工程师研究无线电已经很多年。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机也用了无线电技术。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上的人用无线电和机场说话。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无线电在战争中起到了很重要的作用。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对无线电很有兴趣。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里没有网络，只能用无线电。", "target_word": "无线电", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无线电波", "label": "复合"}, {"form": "無線電", "label": "繁体"}], "register": "中性", "sense_fingerprint": "利用电波传送信息的技术或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无线电", "is_correct": true, "explanation": "正确：无线电利用电波传送信息，能把信息传到很远的地方。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯用于照明，不能把信息传到远处。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用于冷藏食物，与传递信息无关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“把信息传到……”的主语须能传递信息，“天气”不能。"}], "explanations": {"无线电": "正确：无线电利用电波传送信息，能把信息传到很远的地方。", "电灯": "语义：电灯用于照明，不能把信息传到远处。", "冰箱": "语义：冰箱用于冷藏食物，与传递信息无关。", "天气": "搭配：“把信息传到……”的主语须能传递信息，“天气”不能。"}, "sentence_index": 0, "correct_answer": "无线电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台无线电每天早上帮我洗衣服。", "explanation": "这里应该用〈洗衣机〉。无线电只传送信息，不能洗衣服。"}, {"text": "咖啡馆的无线电正在给客人理发。", "explanation": "这里应该用〈理发师〉。无线电不能给人理发。"}, {"text": "我用无线电烧了一壶水。", "explanation": "这里应该用〈水壶〉。无线电不能烧水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无线电", "is_correct": true, "explanation": "正确：无线电能与机场双向通信，符合“用……和机场说话”。"}, {"text": "水壶", "is_correct": false, "explanation": "语义：水壶用于烧水，不能用来与机场通话。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“用……和……说话”要求工具能够通话，“沙发”不能。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只能定时响铃，不能与机场双向通话。"}], "explanations": {"无线电": "正确：无线电能与机场双向通信，符合“用……和机场说话”。", "水壶": "语义：水壶用于烧水，不能用来与机场通话。", "沙发": "搭配：“用……和……说话”要求工具能够通话，“沙发”不能。", "闹钟": "语义：闹钟只能定时响铃，不能与机场双向通话。"}, "sentence_index": 6, "correct_answer": "无线电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的无线电里烤着面包。", "explanation": "这里应该用〈烤箱〉。无线电只传送信息，不能用来烤东西。"}, {"text": "无线电能拍很清楚的照片。", "explanation": "这里应该用〈相机〉。无线电只传送信息，不能用来拍照。"}, {"text": "无线电能开到山上。", "explanation": "这里应该用〈汽车〉。无线电是传送信息的技术或设备，不能行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的船上装了一只无线电。", "corrected_sentence": "他的船上装了一台无线电。", "error_description": "“无线电”作为设备，量词应用“台”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那台无线电修了好。", "corrected_sentence": "他把那台无线电修好了。", "error_description": "错误：结果补语「好」应紧跟动词「修」，「了」放在补语之后。「修了好」语序有误，正确说法是「修好了」，即「他把那台无线电修好了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
