INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97349, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说一些话，让别人很生气，去做坏事。", "primary_collocate": null, "pronunciation": "shān dòng", "ipa": "ʂan˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他故意说难听的话，煽动大家去砸车。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的几句话煽动了大家，人们生气地冲了出去。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人煽动居民去围住市政府大门。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上煽动大家，说老板一直骗人。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸煽动读者对那家公司的愤怒。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不停地煽动弟弟，让弟弟去打邻居。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只会煽动别人吵架，自己不动手。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话是用来煽动仇恨的，千万别信。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他煽动了一群年轻人，让他们去砸警车。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的坏话煽动着人们，越来越多的人生气了。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "煽动了", "label": "体标"}, {"form": "煽动过", "label": "体标"}, {"form": "煽动着", "label": "体标"}, {"form": "煽动者", "label": "复合"}, {"form": "煽動", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用话激怒别人去做坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "煽动", "is_correct": true, "explanation": "煽动：怂恿他人去做坏事，与“故意说难听的话”后面的行为相符。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”是安抚人心，与“故意说难听的话”后的行为不搭。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，不能用来说明故意挑动大家去砸车。"}, {"text": "保护", "is_correct": false, "explanation": "配价：“保护”的宾语是人或事物，不能直接带“去砸车”这样的小句。"}], "explanations": {"煽动": "煽动：怂恿他人去做坏事，与“故意说难听的话”后面的行为相符。", "安慰": "语义：“安慰”是安抚人心，与“故意说难听的话”后的行为不搭。", "表扬": "语义：“表扬”是称赞，不能用来说明故意挑动大家去砸车。", "保护": "配价：“保护”的宾语是人或事物，不能直接带“去砸车”这样的小句。"}, "sentence_index": 0, "correct_answer": "煽动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会上煽动大家，说会议下午三点开始。", "explanation": "这里应该用〈通知〉。煽动是怂恿他人做坏事，告知开会时间要用通知。"}, {"text": "他在会上煽动大家冷静下来。", "explanation": "这里应该用〈劝〉。煽动多指怂恿他人去做坏事，劝大家冷静下来要用劝。"}, {"text": "他煽动大家保护环境。", "explanation": "这里应该用〈呼吁〉。煽动指怂恿他人做坏事，号召大家保护环境要用呼吁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煽动", "is_correct": true, "explanation": "煽动：用话语怂恿他人去做坏事，与“别人吵架”的句意相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，不能用来说她让别人吵架。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象多是事物或作品，不能接“别人吵架”这样的动作。"}, {"text": "吓唬", "is_correct": false, "explanation": "语义：“吓唬”是恐吓，与“只会……吵架”的意思不符。"}], "explanations": {"煽动": "煽动：用话语怂恿他人去做坏事，与“别人吵架”的句意相符。", "夸奖": "语义：“夸奖”是称赞，不能用来说她让别人吵架。", "欣赏": "搭配：“欣赏”的对象多是事物或作品，不能接“别人吵架”这样的动作。", "吓唬": "语义：“吓唬”是恐吓，与“只会……吵架”的意思不符。"}, "sentence_index": 6, "correct_answer": "煽动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师煽动学生要诚实。", "explanation": "这里应该用〈教育〉。煽动是怂恿他人做坏事，教导学生诚实要用教育。"}, {"text": "妈妈煽动伤心的孩子，说别难过了。", "explanation": "这里应该用〈安慰〉。煽动指怂恿他人做坏事，让伤心的人安心要用安慰。"}, {"text": "老师煽动他去擦黑板。", "explanation": "这里应该用〈安排〉。煽动是怂恿他人做坏事，安排值日擦黑板要用安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
