INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97350, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用言语或行为鼓动别人做事，多指坏事。", "primary_collocate": null, "pronunciation": "shān dòng", "ipa": "ʂan˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "有人在网上煽动大家去打砸商店。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他煽动工人打架，结果自己跑了。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，是他煽动了这次闹事。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别听那个人煽动，他只想让你去犯错。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用谎话煽动同学一起欺负新来的孩子。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人煽动过很多人去做违法的事。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个主持人总是煽动观众互相骂人。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们煽动村民把路堵上，不让车过去。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评他煽动同学逃课。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有人煽动着大家去攻击那位老人。", "target_word": "煽动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "煽动了", "label": "体标"}, {"form": "煽动过", "label": "体标"}, {"form": "煽动着", "label": "体标"}, {"form": "煽动者", "label": "复合"}, {"form": "煽動", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用言行鼓动别人去做坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "煽动", "is_correct": true, "explanation": "煽动：用言语鼓动他人去做坏事，与“打砸商店”的句意相符。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”是劝人安心，与“打砸商店”的煽动正好相反。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞好的行为，不能用来鼓动他人打砸。"}, {"text": "歌颂", "is_correct": false, "explanation": "配价：“歌颂”的宾语多是英雄、祖国等，不能带“大家去打砸商店”这样的小句。"}], "explanations": {"煽动": "煽动：用言语鼓动他人去做坏事，与“打砸商店”的句意相符。", "安慰": "语义：“安慰”是劝人安心，与“打砸商店”的煽动正好相反。", "表扬": "语义：“表扬”是称赞好的行为，不能用来鼓动他人打砸。", "歌颂": "配价：“歌颂”的宾语多是英雄、祖国等，不能带“大家去打砸商店”这样的小句。"}, "sentence_index": 0, "correct_answer": "煽动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教练煽动大家在比赛前冷静下来。", "explanation": "这里应该用〈安抚〉。煽动是怂恿他人做坏事，让大家平静下来要用安抚。"}, {"text": "老师煽动我们认真思考。", "explanation": "这里应该用〈启发〉。煽动指怂恿他人做坏事，引导学生思考要用启发。"}, {"text": "医生煽动病人按时吃药。", "explanation": "这里应该用〈提醒〉。煽动指怂恿他人做坏事，叮嘱病人按时吃药要用提醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煽动", "is_correct": true, "explanation": "煽动：用言语怂恿他人去做坏事，与“观众互相骂人”的句意相符。"}, {"text": "安抚", "is_correct": false, "explanation": "语义：“安抚”是使人平静，与“互相骂人”的句意相反。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，不能用来说观众互相骂人。"}, {"text": "维护", "is_correct": false, "explanation": "配价：“维护”的宾语多是秩序、权益，不能接“观众互相骂人”这样的小句。"}], "explanations": {"煽动": "煽动：用言语怂恿他人去做坏事，与“观众互相骂人”的句意相符。", "安抚": "语义：“安抚”是使人平静，与“互相骂人”的句意相反。", "夸奖": "语义：“夸奖”是称赞，不能用来说观众互相骂人。", "维护": "配价：“维护”的宾语多是秩序、权益，不能接“观众互相骂人”这样的小句。"}, "sentence_index": 6, "correct_answer": "煽动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师煽动学生不要抄作业。", "explanation": "这里应该用〈劝〉。煽动多指鼓动他人做坏事，劝学生不要抄作业要用劝。"}, {"text": "他总是煽动同事之间的关系。", "explanation": "这里应该用〈挑拨〉。煽动的对象是人并使其去做某事；挑拨用于人际关系。"}, {"text": "妈妈煽动孩子诚实的品质。", "explanation": "这里应该用〈赞美〉。煽动多指鼓动他人做坏事，称赞孩子诚实的品质要用赞美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在群里煽动去围堵那家公司。", "corrected_sentence": "他在群里煽动大家去围堵那家公司。", "error_description": "错误：“煽动去围堵”，煽动是及物动词，后面漏掉了宾语“大家”。正确：“煽动大家去围堵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没煽动了工人去打架。", "corrected_sentence": "他没煽动工人去打架。", "error_description": "错误：“没煽动了”，否定副词“没”不能与完成标记“了”同用。正确：“没煽动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
