INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97351, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很凶，一点也不心软。", "primary_collocate": null, "pronunciation": "hěn", "ipa": "xən˨˩", "syllable_count": 1, "sentences": [{"text": "那个老板对工人很狠，一点也不心软。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下手太狠了，把对方打伤了。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么说，话也太狠了。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人心很狠，连亲人都不帮。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对孩子不狠，总是舍不得骂他。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己也很狠，每天只睡四个小时。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看起来很温柔，其实做事很狠。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛裁判判罚得很狠，有好几个球员被罚下场了。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气，话说得特别狠。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对作弊的学生一点也不心软，处理得很狠。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "狠狠", "label": "重叠"}, {"form": "狠心", "label": "复合"}, {"form": "狠毒", "label": "复合"}], "register": "口语", "sense_fingerprint": "对人凶、不留情、不心软", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恨", "is_correct": false, "explanation": "hèn（第四声）与 hěn（第三声）声调不同，意思是怨恨，不是狠"}, {"text": "粉", "is_correct": false, "explanation": "fěn 与 hěn 声母不同，f 与 h 不同，意思是粉末"}, {"text": "狠", "is_correct": true, "explanation": "hěn（第三声），意思是对人凶、不心软，即本词的意思"}, {"text": "肯", "is_correct": false, "explanation": "kěn 与 hěn 声母不同，k 与 h 不同，意思是愿意"}, {"text": "喊", "is_correct": false, "explanation": "hǎn 与 hěn 韵母不同，ǎn 与 ěn 不同，意思是大声叫"}], "explanations": {"恨": "hèn（第四声）与 hěn（第三声）声调不同，意思是怨恨，不是狠", "粉": "fěn 与 hěn 声母不同，f 与 h 不同，意思是粉末", "狠": "hěn（第三声），意思是对人凶、不心软，即本词的意思", "肯": "kěn 与 hěn 声母不同，k 与 h 不同，意思是愿意", "喊": "hǎn 与 hěn 韵母不同，ǎn 与 ěn 不同，意思是大声叫"}, "sentence_index": null, "correct_answer": "狠"}, "level_3": {"options": [{"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”与后半句“一点也不心软”意思相反，句子不通"}, {"text": "狠", "is_correct": true, "explanation": "“狠”指对人凶、不留情，与“一点也不心软”相呼应"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容外形，不能用来说老板对工人的态度"}, {"text": "仁慈", "is_correct": false, "explanation": "语义：“仁慈”与“一点也不心软”意思相反，句子不通"}], "explanations": {"温柔": "语义：“温柔”与后半句“一点也不心软”意思相反，句子不通", "狠": "“狠”指对人凶、不留情，与“一点也不心软”相呼应", "高大": "体貌：“高大”形容外形，不能用来说老板对工人的态度", "仁慈": "语义：“仁慈”与“一点也不心软”意思相反，句子不通"}, "sentence_index": 0, "correct_answer": "狠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈对孩子很狠，每天都耐心地陪他读书。", "explanation": "这里应该用〈温柔〉。“狠”指凶恶、不心软，形容对孩子的态度要用“温柔”，与“耐心地陪他读书”的做法矛盾，词义用错了。"}, {"text": "这位医生对病人很狠，总是温和地安慰每一位病人。", "explanation": "这里应该用〈温和〉。“狠”指凶恶、不心软，而后半句说他总是安慰病人，态度很温和，前后矛盾，词义用错了。"}, {"text": "他对朋友很狠，每次有困难都主动帮忙。", "explanation": "这里应该用〈热心〉。“狠”指凶恶、不心软，形容对朋友的态度要用“热心”，与“主动帮忙”的表现相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97351, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "痕", "is_correct": false, "explanation": "hén（第二声）与 hěn（第三声）声调不同，意思是痕迹"}, {"text": "忍", "is_correct": false, "explanation": "rěn 与 hěn 声母不同，r 与 h 不同，意思是忍耐"}, {"text": "狠", "is_correct": true, "explanation": "hěn（第三声），意思是对人凶、不心软，即本词的意思"}, {"text": "稳", "is_correct": false, "explanation": "wěn 与 hěn 声母不同，w 与 h 不同，意思是稳定"}], "explanations": {"痕": "hén（第二声）与 hěn（第三声）声调不同，意思是痕迹", "忍": "rěn 与 hěn 声母不同，r 与 h 不同，意思是忍耐", "狠": "hěn（第三声），意思是对人凶、不心软，即本词的意思", "稳": "wěn 与 hěn 声母不同，w 与 h 不同，意思是稳定"}, "sentence_index": null, "correct_answer": "狠"}, "level_3": {"options": [{"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来形容做事的方式"}, {"text": "狠", "is_correct": true, "explanation": "“狠”指做事不留情、不心软，与前半句“看起来很温柔”形成“其实”的转折"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身形，不能用来形容做事的方式"}, {"text": "红", "is_correct": false, "explanation": "搭配：“红”多指颜色或受欢迎，不能用来形容做事的方式"}], "explanations": {"矮": "体貌：“矮”形容身高，不能用来形容做事的方式", "狠": "“狠”指做事不留情、不心软，与前半句“看起来很温柔”形成“其实”的转折", "瘦": "体貌：“瘦”形容身形，不能用来形容做事的方式", "红": "搭配：“红”多指颜色或受欢迎，不能用来形容做事的方式"}, "sentence_index": 6, "correct_answer": "狠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个老师对学生很狠，每次都笑着夸奖大家的进步。", "explanation": "这里应该用〈和善〉。“狠”指凶恶、不心软，与“笑着夸奖大家的进步”的态度矛盾，词义用错了。"}, {"text": "这只小猫对人很狠，每天都让大家抱着它玩。", "explanation": "这里应该用〈温顺〉。“狠”指凶恶、不留情，形容小猫的性情要用“温顺”，与后面“让大家抱着它玩”的亲近表现矛盾。"}, {"text": "这把椅子很狠，坐上去很舒服。", "explanation": "这里应该用〈结实〉。“狠”形容人的凶恶或残忍，不能用来形容椅子，应说“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那个小偷打很狠，警察都吓了一跳。", "corrected_sentence": "他把那个小偷打得很狠，警察都吓了一跳。", "error_description": "“狠”作补语时，动词与补语之间要用结构助词“得”，应说“打得很狠”，漏掉“得”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对你一点也狠，你别害怕。", "corrected_sentence": "我对你一点也不狠，你别害怕。", "error_description": "错误：“一点也”表示完全否定，后面要接否定词“不”，应说“一点也不狠”；“一点也狠”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
