INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97352, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "凶恶；残忍，也表示程度很深。", "primary_collocate": null, "pronunciation": "hěn", "ipa": "xən˨˩", "syllable_count": 1, "sentences": [{"text": "这条狗看起来很狠，孩子们都不敢靠近。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人下手真狠，一点都不留情。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段时间咱们得狠抓一下质量，不能再出问题了。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板狠批了迟到的员工。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气，狠踢了桌子一脚。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼神很狠，让我有点害怕。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小偷手段狠，大家都怕他。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试他狠下功夫，成绩提高了很多。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人又狠又坏，大家都躲着他。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机狠踩一脚油门，车一下子冲了出去。", "target_word": "狠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "狠狠", "label": "重叠"}, {"form": "狠心", "label": "复合"}, {"form": "狠毒", "label": "复合"}], "register": "口语", "sense_fingerprint": "凶恶残忍；用力、程度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "痕", "is_correct": false, "explanation": "hén（第二声）与 hěn（第三声）声调不同，意思是痕迹"}, {"text": "狠", "is_correct": true, "explanation": "hěn（第三声），意思是凶恶残忍，或表示程度很深，即本词的意思"}, {"text": "稳", "is_correct": false, "explanation": "wěn 与 hěn 声母不同，w 与 h 不同，意思是稳定"}, {"text": "忍", "is_correct": false, "explanation": "rěn 与 hěn 声母不同，r 与 h 不同，意思是忍耐"}], "explanations": {"痕": "hén（第二声）与 hěn（第三声）声调不同，意思是痕迹", "狠": "hěn（第三声），意思是凶恶残忍，或表示程度很深，即本词的意思", "稳": "wěn 与 hěn 声母不同，w 与 h 不同，意思是稳定", "忍": "rěn 与 hěn 声母不同，r 与 h 不同，意思是忍耐"}, "sentence_index": null, "correct_answer": "狠"}, "level_3": {"options": [{"text": "温顺", "is_correct": false, "explanation": "语义：“温顺”与后半句“孩子们都不敢靠近”矛盾，句子不通"}, {"text": "狠", "is_correct": true, "explanation": "“狠”表示凶恶，与“孩子们都不敢靠近”相呼应"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好”与后半句“孩子们都不敢靠近”矛盾，句子不通"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”（指可爱）与后半句“孩子们都不敢靠近”矛盾，句子不通"}], "explanations": {"温顺": "语义：“温顺”与后半句“孩子们都不敢靠近”矛盾，句子不通", "狠": "“狠”表示凶恶，与“孩子们都不敢靠近”相呼应", "友好": "语义：“友好”与后半句“孩子们都不敢靠近”矛盾，句子不通", "甜": "语义：“甜”（指可爱）与后半句“孩子们都不敢靠近”矛盾，句子不通"}, "sentence_index": 0, "correct_answer": "狠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位护士对病人很狠，说话总是轻声细语的。", "explanation": "这里应该用〈温柔〉。“狠”表示凶恶残忍，与“说话总是轻声细语”的态度矛盾，词义用错了。"}, {"text": "这个孩子很狠，每天都主动帮妈妈做家务。", "explanation": "这里应该用〈懂事〉。“狠”形容凶恶残忍，与“主动帮妈妈做家务”的表现相反，词义用错了。"}, {"text": "这只小猫很狠，每天都窝在我怀里撒娇。", "explanation": "这里应该用〈温顺〉。“狠”表示凶恶残忍，形容小猫的性情要用“温顺”，与“窝在我怀里撒娇”的表现矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恨", "is_correct": false, "explanation": "hèn（第四声）与 hěn（第三声）声调不同，意思是怨恨，不是狠"}, {"text": "粉", "is_correct": false, "explanation": "fěn 与 hěn 声母不同，f 与 h 不同，意思是粉末"}, {"text": "狠", "is_correct": true, "explanation": "hěn（第三声），意思是凶恶残忍，或表示程度很深，即本词的意思"}, {"text": "肯", "is_correct": false, "explanation": "kěn 与 hěn 声母不同，k 与 h 不同，意思是愿意"}, {"text": "喊", "is_correct": false, "explanation": "hǎn 与 hěn 韵母不同，ǎn 与 ěn 不同，意思是大声叫"}], "explanations": {"恨": "hèn（第四声）与 hěn（第三声）声调不同，意思是怨恨，不是狠", "粉": "fěn 与 hěn 声母不同，f 与 h 不同，意思是粉末", "狠": "hěn（第三声），意思是凶恶残忍，或表示程度很深，即本词的意思", "肯": "kěn 与 hěn 声母不同，k 与 h 不同，意思是愿意", "喊": "hǎn 与 hěn 韵母不同，ǎn 与 ěn 不同，意思是大声叫"}, "sentence_index": null, "correct_answer": "狠"}, "level_3": {"options": [{"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”不能用来形容手段，且与后半句“大家都怕他”矛盾"}, {"text": "狠", "is_correct": true, "explanation": "“狠”表示手段凶恶、不留情，与“大家都怕他”相呼应"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”与后半句“大家都怕他”矛盾，句子不通"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容体形，不能用来形容手段"}], "explanations": {"可爱": "搭配：“可爱”不能用来形容手段，且与后半句“大家都怕他”矛盾", "狠": "“狠”表示手段凶恶、不留情，与“大家都怕他”相呼应", "温和": "语义：“温和”与后半句“大家都怕他”矛盾，句子不通", "胖": "体貌：“胖”形容体形，不能用来形容手段"}, "sentence_index": 6, "correct_answer": "狠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个饭馆的服务员很狠，主动给我们添茶换碗。", "explanation": "这里应该用〈热情〉。“狠”表示凶恶残忍，形容服务员的态度要用“热情”，与“主动给我们添茶换碗”的表现相反。"}, {"text": "妈妈很狠地抱着孩子，轻轻地哄他睡觉。", "explanation": "这里应该用〈温柔〉。“狠”表示用力或凶狠，形容抱孩子的动作要用“温柔”，与“轻轻地哄他睡觉”矛盾。"}, {"text": "这只杯子很狠，喝水很方便。", "explanation": "这里应该用〈结实〉。“狠”形容人的凶恶或残忍，不能用来形容杯子，应说“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机把油门踩很狠，车一下子冲了出去。", "corrected_sentence": "司机把油门踩得很狠，车一下子冲了出去。", "error_description": "“狠”作补语时，动词与补语之间要用结构助词“得”，应说“踩得很狠”，漏掉“得”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他狠很地踢了桌子一脚。", "corrected_sentence": "他狠狠地踢了桌子一脚。", "error_description": "错误：“狠”作状语表示用力时，要用重叠式“狠狠地”，不能说“狠很地”。正确：“狠狠地踢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97355, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97355, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97355, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恭敬地把东西交给别人。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "孩子们给客人献花。", "target_word": "献", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们向老师献上一束花。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他双手给奶奶献上一杯茶。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们给老人献上生日礼物。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出结束后，小女孩给演员献花。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向朋友献上了一份礼物。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过节的时候，我们给老师献花。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生代表给校长献上一面锦旗。", "target_word": "献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着向客人献上一杯酒。", "target_word": "献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在会上向专家献上鲜花。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "獻", "label": "繁体"}, {"form": "献花", "label": "复合"}, {"form": "献上", "label": "复合"}], "register": "中性", "sense_fingerprint": "双手恭敬地把花、茶、礼物等交给对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97355, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "献", "is_correct": true, "explanation": "献（xiàn）：恭敬地把东西交给别人。本题正确答案。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后、首先。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是空闲。"}, {"text": "险", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是朝、向。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 xiàn 声母不同（q 与 x），声调相同，意思是欠债。"}], "explanations": {"献": "献（xiàn）：恭敬地把东西交给别人。本题正确答案。", "先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后、首先。", "闲": "xián（第二声）与 xiàn（第四声）声调不同，意思是空闲。", "险": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险。", "向": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是朝、向。", "欠": "qiàn 与 xiàn 声母不同（q 与 x），声调相同，意思是欠债。"}, "sentence_index": null, "correct_answer": "献"}, "level_3": {"options": [{"text": "献", "is_correct": true, "explanation": "献：与“给客人”搭配，表示恭敬地把花交给客人，符合句意。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚压踏，“踩花”会伤害花，与恭敬地把花交给客人的意思相反。"}, {"text": "拔", "is_correct": false, "explanation": "语义：“拔”是把植物连根拔起，“拔花”与送花给客人的意思不合。"}, {"text": "陪", "is_correct": false, "explanation": "配价：“陪”的宾语应为人，不能带“花”作宾语。"}], "explanations": {"献": "献：与“给客人”搭配，表示恭敬地把花交给客人，符合句意。", "踩": "语义：“踩”是用脚压踏，“踩花”会伤害花，与恭敬地把花交给客人的意思相反。", "拔": "语义：“拔”是把植物连根拔起，“拔花”与送花给客人的意思不合。", "陪": "配价：“陪”的宾语应为人，不能带“花”作宾语。"}, "sentence_index": 0, "correct_answer": "献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把纸巾献给了同学。", "explanation": "这里应该用〈递〉。献表示恭敬郑重地奉上，把纸巾随手递给同学是寻常小事，不用献。"}, {"text": "他把房租献给了房东。", "explanation": "这里应该用〈付〉。献表示恭敬地奉上，交房租是平常的付款，不用献。"}, {"text": "他把花献在了桌上。", "explanation": "这里应该用〈放〉。献要把东西恭敬地交给某人，只是摆放在某处不用献。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97355, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "献", "is_correct": true, "explanation": "献（xiàn）：恭敬地把东西交给别人。本题正确答案。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸味。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。"}, {"text": "像", "is_correct": false, "explanation": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是相似。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），声调相同，意思是看见。"}], "explanations": {"献": "献（xiàn）：恭敬地把东西交给别人。本题正确答案。", "鲜": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜。", "咸": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸味。", "显": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。", "像": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是相似。", "见": "jiàn 与 xiàn 声母不同（j 与 x），声调相同，意思是看见。"}, "sentence_index": null, "correct_answer": "献"}, "level_3": {"options": [{"text": "献", "is_correct": true, "explanation": "献：与“给老师”搭配，表示恭敬地把花送给老师，符合句意。"}, {"text": "掐", "is_correct": false, "explanation": "语义：“掐”是用指甲按断，“掐花”会损伤花朵，与送给老师的意思不合。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是重重地落下或扔下，“摔花”与恭敬地奉上的意思相反。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语应是歌曲，不能说“唱花”。"}], "explanations": {"献": "献：与“给老师”搭配，表示恭敬地把花送给老师，符合句意。", "掐": "语义：“掐”是用指甲按断，“掐花”会损伤花朵，与送给老师的意思不合。", "摔": "语义：“摔”是重重地落下或扔下，“摔花”与恭敬地奉上的意思相反。", "唱": "配价：“唱”的宾语应是歌曲，不能说“唱花”。"}, "sentence_index": 6, "correct_answer": "献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把球献给了小狗。", "explanation": "这里应该用〈送〉。献的接受者应是值得尊敬的人，把球送给小狗不能用献。"}, {"text": "我把试卷献给了老师。", "explanation": "这里应该用〈交〉。献表示恭敬地奉上，交试卷是平常的事，不用献。"}, {"text": "我把这张CD献给了同学，借他听一天。", "explanation": "这里应该用〈借〉。献是恭敬地奉上，不能用于暂时让同学听一天、之后还回来的情形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明给爷爷献下一杯热茶。", "corrected_sentence": "小明给爷爷献上一杯热茶。", "error_description": "错误形式：“献下”；正确形式：“献上”。“献”的趋向补语应用“上”表示奉上，“献下”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一束玫瑰献了妈妈。", "corrected_sentence": "他把一束玫瑰献给了妈妈。", "error_description": "错误形式：“献了妈妈”；正确形式：“献给了妈妈”。“献”带接受者时要用“献给”，这里缺少“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97356, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "索取：与“奉献”互为反义，指向别人要东西、只求取，与“献出生命”的意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "与“献”无反义关系：研究是探究事理，不是交付或奉献。"}, {"text": "修建", "is_correct": false, "explanation": "与“献”无反义关系：修建是建造工程，不涉及交付或奉献。"}, {"text": "保持", "is_correct": false, "explanation": "与“献”无反义关系：保持是维持原样，与交付或奉献无关。"}], "correct_answer": "索取", "explanations": {"索取": "索取：与“奉献”互为反义，指向别人要东西、只求取，与“献出生命”的意思相反。", "研究": "与“献”无反义关系：研究是探究事理，不是交付或奉献。", "修建": "与“献”无反义关系：修建是建造工程，不涉及交付或奉献。", "保持": "与“献”无反义关系：保持是维持原样，与交付或奉献无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97356, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "索取：与“奉献”互为反义，指向别人要东西、只求取，与“献”的无私奉献相反。"}, {"text": "观察", "is_correct": false, "explanation": "与“献”无反义关系：观察是仔细看，不涉及交付或奉献。"}, {"text": "翻译", "is_correct": false, "explanation": "与“献”无反义关系：翻译是转换语言，不是奉献。"}, {"text": "散步", "is_correct": false, "explanation": "与“献”无反义关系：散步是随意走动，与交付或奉献无关。"}], "correct_answer": "索取", "explanations": {"索取": "索取：与“奉献”互为反义，指向别人要东西、只求取，与“献”的无私奉献相反。", "观察": "与“献”无反义关系：观察是仔细看，不涉及交付或奉献。", "翻译": "与“献”无反义关系：翻译是转换语言，不是奉献。", "散步": "与“献”无反义关系：散步是随意走动，与交付或奉献无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恭敬庄重地送给；贡献。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他把一生献给了教育事业。", "target_word": "献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把一生都献给了病人。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把青春献给了学生。", "target_word": "献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愿意为国家献出生命。", "target_word": "献", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人为这个城市献出了力量。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把所有的钱都献给了孤儿院。", "target_word": "献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都愿意为小城献出力量。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家们为人类的健康献出了毕生的精力。", "target_word": "献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们为和平献出了生命。", "target_word": "献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把自己的爱心献给了山区的孩子。", "target_word": "献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獻", "label": "繁体"}, {"form": "献身", "label": "复合"}, {"form": "献血", "label": "复合"}], "register": "书面", "sense_fingerprint": "把生命、青春、力量等珍贵的东西无私地奉献给国家或事业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97356, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "献", "is_correct": true, "explanation": "献（xiàn）：恭敬庄重地送给；无私地奉献。本题正确答案。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后、首先。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是空闲。"}, {"text": "险", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是朝、向。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 xiàn 声母不同（q 与 x），声调相同，意思是欠债。"}], "explanations": {"献": "献（xiàn）：恭敬庄重地送给；无私地奉献。本题正确答案。", "先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后、首先。", "闲": "xián（第二声）与 xiàn（第四声）声调不同，意思是空闲。", "险": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险。", "向": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是朝、向。", "欠": "qiàn 与 xiàn 声母不同（q 与 x），声调相同，意思是欠债。"}, "sentence_index": null, "correct_answer": "献"}, "level_3": {"options": [{"text": "献", "is_correct": true, "explanation": "献：与“把一生……给了”搭配，表示无私地奉献，符合句意。"}, {"text": "收", "is_correct": false, "explanation": "语义：“收”是接受，与“把一生……给了教育事业”的给予方向相反。"}, {"text": "埋", "is_correct": false, "explanation": "语义：“埋”是掩藏于土中，与奉献事业的意思不合。"}, {"text": "赚", "is_correct": false, "explanation": "配价：“赚”的宾语应是钱财，不能说“赚一生”。"}], "explanations": {"献": "献：与“把一生……给了”搭配，表示无私地奉献，符合句意。", "收": "语义：“收”是接受，与“把一生……给了教育事业”的给予方向相反。", "埋": "语义：“埋”是掩藏于土中，与奉献事业的意思不合。", "赚": "配价：“赚”的宾语应是钱财，不能说“赚一生”。"}, "sentence_index": 0, "correct_answer": "献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一本书献在了书架上。", "explanation": "这里应该用〈放〉。献要把东西恭敬地交给某人，只是摆放在书架上不用献。"}, {"text": "为了买一台电视，他献出了全部积蓄。", "explanation": "这里应该用〈付出〉。“献出”用于崇高的事业或他人的利益，为个人消费买电视只能用〈付出〉。"}, {"text": "他把一把雨伞献给了路人。", "explanation": "这里应该用〈送〉。献带有恭敬郑重的意味，把雨伞随手送给路人是寻常小事，不用献。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97356, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "献", "is_correct": true, "explanation": "献（xiàn）：恭敬庄重地送给；无私地奉献。本题正确答案。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸味。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。"}, {"text": "像", "is_correct": false, "explanation": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是相似。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），声调相同，意思是看见。"}], "explanations": {"献": "献（xiàn）：恭敬庄重地送给；无私地奉献。本题正确答案。", "鲜": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜。", "咸": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸味。", "显": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。", "像": "xiàng 与 xiàn 韵尾不同（ang 与 an），声调相同，意思是相似。", "见": "jiàn 与 xiàn 声母不同（j 与 x），声调相同，意思是看见。"}, "sentence_index": null, "correct_answer": "献"}, "level_3": {"options": [{"text": "献", "is_correct": true, "explanation": "献：与“出力量”搭配，表示为小城无私地付出，符合句意。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是暗中拿走别人的东西，与为小城付出的意思相反。"}, {"text": "掏", "is_correct": false, "explanation": "语义：“掏”是从口袋等处取出东西，“掏出力量”与句意不合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃出”多指尝出味道，不能说“吃出力量”。"}], "explanations": {"献": "献：与“出力量”搭配，表示为小城无私地付出，符合句意。", "偷": "语义：“偷”是暗中拿走别人的东西，与为小城付出的意思相反。", "掏": "语义：“掏”是从口袋等处取出东西，“掏出力量”与句意不合。", "吃": "搭配：“吃出”多指尝出味道，不能说“吃出力量”。"}, "sentence_index": 6, "correct_answer": "献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把一块橡皮献给了同桌。", "explanation": "这里应该用〈送〉。献带有恭敬郑重的意味，把橡皮送给同桌是随意的小事，不用献。"}, {"text": "学生把作业献给了老师。", "explanation": "这里应该用〈交〉。作业是交上去的，不是恭敬奉献的东西，不用献。"}, {"text": "我把这本书献给了同桌，让他看一下。", "explanation": "这里应该用〈借〉。借是暂时让别人使用，献是恭敬地奉上，借给同桌看不能用献。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把全部心血献出给了科研工作。", "corrected_sentence": "她把全部心血献给了科研工作。", "error_description": "错误形式：“献出给”；正确形式：“献给”。“献出”带宾语“心血”，接受者由“给”引出，两者不能叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把旧书都献了给希望小学。", "corrected_sentence": "我们把旧书都献给了希望小学。", "error_description": "错误形式：“献了给”；正确形式：“献给了”。动态助词“了”要放在“献给”之后，不能插在“献”和“给”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
