INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97361, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97361, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家到做事的地方开的会，现场看。", "primary_collocate": null, "pronunciation": "xiàn chǎng huì", "ipa": "ɕjɛn˥˩ ʈʂʰɑŋ˨˩˦ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "县里明天在养猪场开现场会，大家都要去看。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次现场会在新工厂开，我们先看车间再开会。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理带大家到工地开了一个现场会。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的现场会开在果园里，大家边看边说。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加现场会以前，请先带好帽子和笔记本。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开完现场会，大家都学到了种菜的好办法。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天上午的现场会在哪儿开？我还不知道。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们到新菜园开现场会，看孩子种菜。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现场会上，工人给大家讲了机器怎么用。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂长说，下个月再开一次现场会。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "现场会议", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家到工作地点边看边开的会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现场会", "is_correct": true, "explanation": "现场会：大家到养猪场现场边看边开的会，与句意相符。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：“开玩笑”是戏谑之意，不能让大家去现场观看，与养猪场的句意不符。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“开”可以搭配“会”，但“教室”是场所，不能说“开教室”。"}, {"text": "猪圈", "is_correct": false, "explanation": "搭配：“猪圈”是养猪的设施，不能说“开猪圈”。"}], "explanations": {"现场会": "现场会：大家到养猪场现场边看边开的会，与句意相符。", "玩笑": "语义：“开玩笑”是戏谑之意，不能让大家去现场观看，与养猪场的句意不符。", "教室": "搭配：“开”可以搭配“会”，但“教室”是场所，不能说“开教室”。", "猪圈": "搭配：“猪圈”是养猪的设施，不能说“开猪圈”。"}, "sentence_index": 0, "correct_answer": "现场会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新年前夕，我们开了一次现场会，互相送礼物。", "explanation": "这里应该用〈联欢会〉。现场会是为了在工作地点观摩、讨论工作而召开的会议，互相送礼物的节日聚会应说“联欢会”。"}, {"text": "专家在礼堂开了一场现场会，大家认真听。", "explanation": "这里应该用〈讲座〉。现场会要在事情发生或工作所在地召开，专家在礼堂讲课应说“讲座”。"}, {"text": "大家在公园里开现场会，边吃点心边聊天。", "explanation": "这里应该用〈茶话会〉。现场会是为了现场观摩、讨论工作，吃点心聊天应说“茶话会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现场会", "is_correct": true, "explanation": "现场会：在工作地点召开、可以有人参加的会议，与句意相符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是能“在哪儿开”的会议。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是粮食，不会被“开”在某个地方。"}, {"text": "考卷", "is_correct": false, "explanation": "搭配：考卷可以“发”或“做”，不能说“开考卷”。"}], "explanations": {"现场会": "现场会：在工作地点召开、可以有人参加的会议，与句意相符。", "早饭": "语义：早饭是一顿饭，不是能“在哪儿开”的会议。", "大米": "语义：大米是粮食，不会被“开”在某个地方。", "考卷": "搭配：考卷可以“发”或“做”，不能说“开考卷”。"}, "sentence_index": 6, "correct_answer": "现场会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在酒店开了一次现场会，专家讨论了很多理论问题。", "explanation": "这里应该用〈研讨会〉。现场会要在事情发生或工作所在地召开，在酒店讨论理论问题应说“研讨会”。"}, {"text": "他们在饭店开现场会，很多亲友来祝贺。", "explanation": "这里应该用〈婚礼〉。现场会是在工作地点召开的会议，不用于办喜事，办喜事应说“婚礼”。"}, {"text": "学校开现场会，学生们比赛跑步、跳远。", "explanation": "这里应该用〈运动会〉。现场会是在工作地点观摩、讨论的会议，不用于体育比赛，学生比赛跑步、跳远应说“运动会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们参加了一张现场会，学到了很多东西。", "corrected_sentence": "我们参加了一次现场会，学到了很多东西。", "error_description": "错误：“一张现场会”，量词用错。会议用“次”或“个”。正确：“一次现场会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前参加过一条现场会，学到了很多。", "corrected_sentence": "我以前参加过一次现场会，学到了很多。", "error_description": "错误：“一条现场会”，量词用错。会议用“次”或“个”。正确：“一次现场会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
