INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97362, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在事情发生或工作所在地召开的会议。", "primary_collocate": null, "pronunciation": "xiàn chǎng huì", "ipa": "ɕjɛn˥˩ ʈʂʰɑŋ˨˩˦ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "大桥出了问题，领导当天就开了现场会。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现场会开了半个小时，问题很快解决了。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾发生后，消防队在门口开了一个现场会。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地上的现场会让大家都看清了问题在哪儿。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理在现场会上说，要马上换新机器。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的路不安全，区里开现场会讨论。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的现场会有二十多个人参加。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个现场会很短，说完大家就回去工作了。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了解决水的问题，村长在河边开了现场会。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出事以后，公司在车间里开了现场会。", "target_word": "现场会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "现场会议", "label": "复合"}], "register": "中性", "sense_fingerprint": "在事发地或工作地点召开的会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现场会", "is_correct": true, "explanation": "现场会：在大桥出问题的地方召开的会议，与句意相符。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：大桥出了问题，领导不会去开演唱会，句意不通。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是喜事，与大桥出问题后领导的处理不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“开考试”与大桥出问题后领导当天的处理不相干，句意不通。"}], "explanations": {"现场会": "现场会：在大桥出问题的地方召开的会议，与句意相符。", "演唱会": "语义：大桥出了问题，领导不会去开演唱会，句意不通。", "婚礼": "语义：婚礼是喜事，与大桥出问题后领导的处理不符。", "考试": "语义：“开考试”与大桥出问题后领导当天的处理不相干，句意不通。"}, "sentence_index": 0, "correct_answer": "现场会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "领导在酒店开了一次现场会，大家谈了很多理论问题。", "explanation": "这里应该用〈座谈会〉。现场会要在事情发生或工作所在地召开、边看边议，在酒店谈理论应说“座谈会”。"}, {"text": "现场会上大家唱歌跳舞，玩得很开心。", "explanation": "这里应该用〈晚会〉。现场会要在事发或工作地点边看边议，不用于唱歌跳舞，娱乐活动应说“晚会”。"}, {"text": "现场会上大家喝茶聊天，很轻松。", "explanation": "这里应该用〈茶话会〉。现场会是为了现场观摩、讨论问题，喝茶聊天应说“茶话会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现场会", "is_correct": true, "explanation": "现场会：有人可以参加的、在工作地点召开的会议，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能有人“参加”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是可以让人参加的活动。"}, {"text": "荣誉", "is_correct": false, "explanation": "搭配：“参加”可以搭配活动，不能说“参加荣誉”。"}], "explanations": {"现场会": "现场会：有人可以参加的、在工作地点召开的会议，与句意相符。", "天气": "语义：天气是自然现象，不能有人“参加”。", "课本": "语义：课本是书，不是可以让人参加的活动。", "荣誉": "搭配：“参加”可以搭配活动，不能说“参加荣誉”。"}, "sentence_index": 6, "correct_answer": "现场会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司在饭店为新员工开了一次现场会，大家一起吃饭。", "explanation": "这里应该用〈聚餐〉。现场会是在工作地点讨论、观摩的会议，在饭店一起吃饭应说“聚餐”。"}, {"text": "工厂开现场会，给立功的工人发奖、喝酒庆祝。", "explanation": "这里应该用〈庆功会〉。现场会是在工作地点讨论、观摩的会议，不用于庆祝，庆功应说“庆功会”。"}, {"text": "现场会上运动员跑得很快。", "explanation": "这里应该用〈运动会〉。现场会不用于体育竞技，运动员比赛跑步应说“运动会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂里出了事故，经理当天就开了一本现场会。", "corrected_sentence": "厂里出了事故，经理当天就开了一次现场会。", "error_description": "错误：“一本现场会”，量词用错。会议用“次”或“个”。正确：“一次现场会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导在工地开完一件现场会就回去了。", "corrected_sentence": "领导在工地开完一个现场会就回去了。", "error_description": "错误：“一件现场会”，量词用错。会议用“个”或“次”。正确：“一个现场会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97365, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冲动", "is_correct": true, "explanation": "冲动：与“理智”反义，指不经考虑、凭一时情绪行事。"}, {"text": "快乐", "is_correct": false, "explanation": "快乐：与“理智”没有反义关系，指心里高兴。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：与“理智”没有反义关系，形容外表好看。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭：与“理智”没有反义关系，形容山势或坡度很陡。"}], "correct_answer": "冲动", "explanations": {"冲动": "冲动：与“理智”反义，指不经考虑、凭一时情绪行事。", "快乐": "快乐：与“理智”没有反义关系，指心里高兴。", "漂亮": "漂亮：与“理智”没有反义关系，形容外表好看。", "陡峭": "陡峭：与“理智”没有反义关系，形容山势或坡度很陡。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97365, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冲动", "is_correct": true, "explanation": "冲动：与“理智”反义，指不经考虑、凭一时情绪行事。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：与“理智”没有反义关系，形容人多或场面喧闹。"}, {"text": "干净", "is_correct": false, "explanation": "干净：与“理智”没有反义关系，指没有污物。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远：与“理智”没有反义关系，指距离很远。"}], "correct_answer": "冲动", "explanations": {"冲动": "冲动：与“理智”反义，指不经考虑、凭一时情绪行事。", "热闹": "热闹：与“理智”没有反义关系，形容人多或场面喧闹。", "干净": "干净：与“理智”没有反义关系，指没有污物。", "遥远": "遥远：与“理智”没有反义关系，指距离很远。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97365, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "遇事头脑很清醒，不乱来。", "primary_collocate": null, "pronunciation": "lǐ zhì", "ipa": "li˨˩ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "遇到大事，他总是很理智，不乱来。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很理智，没有听信那些谣言。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要理智地面对考试成绩。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了事以后，他还是很理智。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时要理智，别看到便宜就买。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很理智，从不做冲动的决定。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都说她是一个理智的人。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到有人吵架，他理智地走开了。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别太冲动，理智一点儿好不好？", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大火面前，理智的人先找出口。", "target_word": "理智", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不理智", "label": "否定式"}, {"form": "理智地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "遇事头脑清醒不乱来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "理智", "is_correct": true, "explanation": "理智：遇事头脑清醒，不乱来。"}, {"text": "立志", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，意思是下定决心要达到某个目标。"}, {"text": "荔枝", "is_correct": false, "explanation": "lì zhī 与 lǐ zhì 两个音节声调都不同，意思是一种水果。"}, {"text": "理事", "is_correct": false, "explanation": "理事的第二个音节 shì（翘舌）与 zhì 声母不同，意思是负责管理的人。"}], "explanations": {"理智": "理智：遇事头脑清醒，不乱来。", "立志": "lì（第四声）与 lǐ（第三声）声调不同，意思是下定决心要达到某个目标。", "荔枝": "lì zhī 与 lǐ zhì 两个音节声调都不同，意思是一种水果。", "理事": "理事的第二个音节 shì（翘舌）与 zhì 声母不同，意思是负责管理的人。"}, "sentence_index": null, "correct_answer": "理智"}, "level_3": {"options": [{"text": "理智", "is_correct": true, "explanation": "理智：遇事头脑清醒，符合“遇到大事……不乱来”的句意。"}, {"text": "冲动", "is_correct": false, "explanation": "语义：“冲动”指不经思考就行动，与“不乱来”矛盾。"}, {"text": "鲁莽", "is_correct": false, "explanation": "语义：“鲁莽”即行事莽撞，正与“不乱来”相反。"}, {"text": "疯狂", "is_correct": false, "explanation": "语义：“疯狂”指言行失去控制，与“不乱来”正相反，句意矛盾。"}], "explanations": {"理智": "理智：遇事头脑清醒，符合“遇到大事……不乱来”的句意。", "冲动": "语义：“冲动”指不经思考就行动，与“不乱来”矛盾。", "鲁莽": "语义：“鲁莽”即行事莽撞，正与“不乱来”相反。", "疯狂": "语义：“疯狂”指言行失去控制，与“不乱来”正相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "理智"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很理智，一学就会。", "explanation": "这里应该用〈聪明〉。理智指遇事头脑清醒、不乱来，说人学东西快要用聪明。"}, {"text": "他对朋友很理智，经常请大家吃饭。", "explanation": "这里应该用〈大方〉。理智描述的是处事时头脑是否清醒，对人慷慨、舍得花钱要用大方。"}, {"text": "这个房间很理智，东西摆得整整齐齐。", "explanation": "这里应该用〈整齐〉。理智只用来形容人的头脑和处事态度，不用来形容房间；形容东西摆放有序要用整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理智", "is_correct": true, "explanation": "理智：遇事头脑清醒，符合“她是一个……的人”的评价。"}, {"text": "英俊", "is_correct": false, "explanation": "体貌：“英俊”形容男子的外貌，用来形容“她”不合适。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气、地方或东西含水分多，不能用来评价人。"}, {"text": "方形", "is_correct": false, "explanation": "搭配：“方形”描述物体的形状，不能用来修饰人的性格。"}], "explanations": {"理智": "理智：遇事头脑清醒，符合“她是一个……的人”的评价。", "英俊": "体貌：“英俊”形容男子的外貌，用来形容“她”不合适。", "潮湿": "搭配：“潮湿”形容空气、地方或东西含水分多，不能用来评价人。", "方形": "搭配：“方形”描述物体的形状，不能用来修饰人的性格。"}, "sentence_index": 6, "correct_answer": "理智"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他修电脑很理智，三下五除二就修好了。", "explanation": "这里应该用〈熟练〉。理智指头脑清醒、不乱来，做事手法熟练要用熟练。"}, {"text": "他做作业很理智，一遇到难题就哭个不停。", "explanation": "这里应该用〈娇气〉。理智指能控制情绪，遇到难题就哭个不停要用娇气。"}, {"text": "她很理智，一听到考试成绩就冲到老师办公室闹。", "explanation": "这里应该用〈冲动〉。理智指遇事头脑清醒、不乱来，遇事就冲动乱闹要用冲动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遇事要理智的想一想。", "corrected_sentence": "遇事要理智地想一想。", "error_description": "错误：“理智的想”，应改为“理智地想”。理智在这里作状语修饰动词，要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐遇事很理智得，从不冲动。", "corrected_sentence": "姐姐遇事很理智，从不冲动。", "error_description": "错误：“很理智得”，形容词后面不能直接加“得”，“得”要接在动词后作补语。正确：“很理智”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
