INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日常生活要用的东西。", "primary_collocate": null, "pronunciation": "yòng pǐn", "ipa": "jʊŋ˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "我去超市买一些生活用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店有很多婴儿用品。", "target_word": "用品", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "家里的日常用品都放在这个柜子里。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行前，她准备好了洗漱用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在网上给小猫买了宠物用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以后，我们要买很多家庭用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些厨房用品又便宜又好用。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校旁边有一家卖学习用品的小店。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年前，大家都去买节日用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门旅游要带上自己的个人用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "生活用品", "label": "复合"}, {"form": "日常用品", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常生活中使用的各类物品，如生活用品、婴儿用品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用品", "is_correct": true, "explanation": "用品：与“生活”搭配，指日常生活中用的东西，符合句意。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“生活”指日常必需的东西，乐器不属于日常用品，与“超市”也不相配。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物的部分，不是日常生活中用的物品，不能说“生活花朵”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是能在超市买的东西，“买生活天气”说不通。"}], "explanations": {"用品": "用品：与“生活”搭配，指日常生活中用的东西，符合句意。", "乐器": "语义：“生活”指日常必需的东西，乐器不属于日常用品，与“超市”也不相配。", "花朵": "语义：花朵是植物的部分，不是日常生活中用的物品，不能说“生活花朵”。", "天气": "语义：天气不是能在超市买的东西，“买生活天气”说不通。"}, "sentence_index": 0, "correct_answer": "用品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行前，她准备好了一只洗漱用品。", "explanation": "这里应该用〈套〉或〈件〉。“只”用于动物或成对物件中的一个，洗漱用品要用“套”或“件”。"}, {"text": "这幅画是这位画家的用品。", "explanation": "这里应该用〈作品〉。用品指日常使用的东西，画作属于作品，不是用品。"}, {"text": "孩子最喜欢这个用品，每天都玩。", "explanation": "这里应该用〈玩具〉。用品指日常生活要用的东西，孩子每天玩的东西要用〈玩具〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用品", "is_correct": true, "explanation": "用品：与“厨房”搭配，指日常使用的物品，符合句意。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指人的总数，与厨房里的东西无关，不能“又便宜又好用”。"}, {"text": "信件", "is_correct": false, "explanation": "搭配：“便宜”“好用”描述商品，不说信件便宜、好用。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的符号，与厨房物品无关。"}], "explanations": {"用品": "用品：与“厨房”搭配，指日常使用的物品，符合句意。", "人口": "语义：人口指人的总数，与厨房里的东西无关，不能“又便宜又好用”。", "信件": "搭配：“便宜”“好用”描述商品，不说信件便宜、好用。", "乐谱": "语义：乐谱是记录音乐的符号，与厨房物品无关。"}, "sentence_index": 6, "correct_answer": "用品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "超市里的用品很新鲜。", "explanation": "这里应该用〈食品〉。“新鲜”形容食物，用品是日常使用的物品，不能说新鲜。"}, {"text": "这首诗是这位诗人的用品。", "explanation": "这里应该用〈作品〉。用品指日常使用的东西，诗作不属于用品。"}, {"text": "这座房子是我的用品。", "explanation": "这里应该用〈财产〉。用品指日常使用的小件物品，房子属于财产，不是用品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我买了一只洗澡用品。", "corrected_sentence": "妈妈给我买了一套洗澡用品。", "error_description": "错误形式：“一只洗澡用品”；正确形式：“一套洗澡用品”。“只”用于动物或成对物件中的一个，洗澡用品一般用“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把家里的用品们都整理好了。", "corrected_sentence": "我们把家里的用品都整理好了。", "error_description": "错误形式：“用品们”；正确形式：“用品”。“们”只用于指人的名词，“用品”是物，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
