INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日常生活或工作所需的物品。", "primary_collocate": null, "pronunciation": "yòng pǐn", "ipa": "jʊŋ˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "办公室需要买一些办公用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给新同事发了办公用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店专门卖体育用品。", "target_word": "用品", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医院里的医疗用品都要保持干净。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们开学前要买学习用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作需要的用品，公司都会准备好。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理让小王去买清洁用品。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工地上的安全用品一定要带好。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们店里的美术用品很齐全。", "target_word": "用品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在网上订了一些摄影用品，工作时要用。", "target_word": "用品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "办公用品", "label": "复合"}, {"form": "体育用品", "label": "复合"}], "register": "中性", "sense_fingerprint": "生活或工作中需要的某一类物品，如办公用品、体育用品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用品", "is_correct": true, "explanation": "用品：与“办公”搭配，指办公需要的物品，符合句意。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物是有生命的动物，不是办公用的物品，“办公宠物”说不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是办公需要买的物品，与“办公”不相配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能买，“办公天气”说不通。"}], "explanations": {"用品": "用品：与“办公”搭配，指办公需要的物品，符合句意。", "宠物": "语义：宠物是有生命的动物，不是办公用的物品，“办公宠物”说不通。", "乐器": "语义：乐器不是办公需要买的物品，与“办公”不相配。", "天气": "语义：天气不能买，“办公天气”说不通。"}, "sentence_index": 0, "correct_answer": "用品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们买了一只办公用品。", "explanation": "这里应该用〈套〉或〈件〉。“只”用于动物或成对物件中的一个，办公用品不用“只”。"}, {"text": "这本小说是这位作家的用品。", "explanation": "这里应该用〈作品〉。用品指工作或生活中使用的物品，小说属于作品，不是用品。"}, {"text": "工厂从国外引进了一批先进用品。", "explanation": "这里应该用〈设备〉。用品指日常或工作中需要的一般物品，引进的先进机器要用〈设备〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用品", "is_correct": true, "explanation": "用品：与“清洁”搭配，指清洁需要的物品，符合句意。"}, {"text": "教材", "is_correct": false, "explanation": "语义：“清洁”修饰用来清洁的东西，教材与清洁无关。"}, {"text": "诗集", "is_correct": false, "explanation": "语义：诗集是文学作品，不是用来清洁的东西。"}, {"text": "花束", "is_correct": false, "explanation": "搭配：“清洁”搭配清洁用具，“清洁花束”搭配不当。"}], "explanations": {"用品": "用品：与“清洁”搭配，指清洁需要的物品，符合句意。", "教材": "语义：“清洁”修饰用来清洁的东西，教材与清洁无关。", "诗集": "语义：诗集是文学作品，不是用来清洁的东西。", "花束": "搭配：“清洁”搭配清洁用具，“清洁花束”搭配不当。"}, "sentence_index": 6, "correct_answer": "用品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的用品很新鲜。", "explanation": "这里应该用〈食材〉。“新鲜”形容食物，用品是日常使用的物品，不能说新鲜。"}, {"text": "这部电影的用品很感人。", "explanation": "这里应该用〈故事〉。用品是使用的物品，不能说感人，打动人的是电影的故事。"}, {"text": "这座桥是我们城市的用品。", "explanation": "这里应该用〈建筑〉。用品指日常或工作中使用的小件物品，桥是建筑，不是用品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板给员工准备了一位办公用品。", "corrected_sentence": "老板给员工准备了一套办公用品。", "error_description": "错误形式：“一位”；正确形式：“一套”。“位”只用于人，办公用品是物品，应该用量词“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库里的清洁用品们都很齐全。", "corrected_sentence": "仓库里的清洁用品都很齐全。", "error_description": "错误形式：“清洁用品们”；正确形式：“清洁用品”。“们”只用于指人的名词，“用品”是物，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
