INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用处；用途。", "primary_collocate": null, "pronunciation": "yòng chǎng", "ipa": "jʊŋ˥˩ tʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "学会这门技术，将来肯定有用场。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学的外语在工作中派上了大用场。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱留着，总有一天会派上用场。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新办法在实际工作中大有用场。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑的用场越来越多了。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典在考试时没有用场。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的这些知识，我觉得没什么用场。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种工具在日常生活里派上用场的地方很多。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料的用场很多。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好主意在比赛中派上了用场。", "target_word": "用场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用场：用处、用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用场", "is_correct": true, "explanation": "“用场”指用处、用途，“将来肯定有用场”说的是这门技术有用。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性情，学技术不会带来脾气，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：技术没有颜色，“将来肯定有颜色”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体形，学技术不会带来身材。"}], "explanations": {"用场": "“用场”指用处、用途，“将来肯定有用场”说的是这门技术有用。", "脾气": "语义：脾气是人的性情，学技术不会带来脾气，句子不通。", "颜色": "语义：技术没有颜色，“将来肯定有颜色”说不通。", "身材": "体貌：身材描述人的体形，学技术不会带来身材。"}, "sentence_index": 0, "correct_answer": "用场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司担任了一个重要用场。", "explanation": "这里应该用〈职务〉。“担任”后接“职务”表示担任职位，“用场”指用处，不指职位。"}, {"text": "这份工作的用场很辛苦。", "explanation": "“用场”指用处，不能用“辛苦”形容；形容劳动的辛苦应说“这份工作很辛苦”。"}, {"text": "这次比赛的用场很紧张。", "explanation": "这里应该用〈名额〉。“用场”不指可分配的数量，不能说“紧张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用场", "is_correct": true, "explanation": "“用场”指用处，句中说知识没有用处，正合语境。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是物体的外形，不能用来评价知识的用处。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是日用品，与“知识有没有用处”的说法不搭。"}, {"text": "皮肤", "is_correct": false, "explanation": "体貌：皮肤指人体的外观，与知识的用处无关。"}], "explanations": {"用场": "“用场”指用处，句中说知识没有用处，正合语境。", "形状": "语义：形状是物体的外形，不能用来评价知识的用处。", "手套": "语义：手套是日用品，与“知识有没有用处”的说法不搭。", "皮肤": "体貌：皮肤指人体的外观，与知识的用处无关。"}, "sentence_index": 6, "correct_answer": "用场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个药的用场很苦。", "explanation": "这里应该用〈味道〉。“用场”指用处，不指味道，不能用“苦”来形容。"}, {"text": "这件衣服的用场很漂亮。", "explanation": "这里应该用〈颜色〉。“用场”指用处，不能用来形容外观的漂亮。"}, {"text": "这个会议的用场很短。", "explanation": "这里应该用〈时间〉。“用场”不指时长，不能用“很短”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学会这门外语，将来肯定用场。", "corrected_sentence": "学会这门外语，将来肯定有用场。", "error_description": "错误在动词：“用场”前要加“有”，应说“肯定有用场”，漏掉“有”就不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的好建议在比赛中派了用场。", "corrected_sentence": "她的好建议在比赛中派上了用场。", "error_description": "动补错误：“派”后要接结果补语“上”，应说“派上了用场”。漏掉“上”，说“派了用场”，搭配不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
