INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97377, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把这个东西看成了别的东西来用。", "primary_collocate": null, "pronunciation": "dàng zuò", "ipa": "tɑŋ˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他把旧桌子当做书架用。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把这个房间当做办公室。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把空瓶子当做花瓶。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在山里，人们把石头当做椅子坐。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大衣当做被子盖在身上。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把纸箱当做小房子玩。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常把手机当做闹钟用。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把旧衬衫当做抹布。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那把伞当做拐杖用。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们把操场当做球场。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当做了", "label": "体标（了）"}, {"form": "當做", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把物品用作别的东西：把A当做B来用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当做", "is_correct": true, "explanation": "正确：“把旧桌子当做书架用”表示把桌子用作书架，与句意相符。"}, {"text": "留给", "is_correct": false, "explanation": "语义：“留给”表示遗留供人使用，不表示把桌子用作书架。"}, {"text": "送给", "is_correct": false, "explanation": "搭配：“送给”要求接受者能接收物品，“书架”不能接收。"}, {"text": "交给", "is_correct": false, "explanation": "配价：“交给”的接收者须能承接物品，“书架”不能承接。"}], "explanations": {"当做": "正确：“把旧桌子当做书架用”表示把桌子用作书架，与句意相符。", "留给": "语义：“留给”表示遗留供人使用，不表示把桌子用作书架。", "送给": "搭配：“送给”要求接受者能接收物品，“书架”不能接收。", "交给": "配价：“交给”的接收者须能承接物品，“书架”不能承接。"}, "sentence_index": 0, "correct_answer": "当做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他当做了一次跑步。", "explanation": "这里应该用〈进行〉。“当做”表示看成或用作，不能直接接“一次跑步”这类动作。"}, {"text": "他当做了一顿晚饭。", "explanation": "这里应该用〈做〉。“当做”表示看成或用作，不表示烹调食物。"}, {"text": "他当做了一封信。", "explanation": "这里应该用〈写〉。“当做”表示看成或用作，不表示书写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当做", "is_correct": true, "explanation": "正确：“把手机当做闹钟用”表示把手机用作闹钟，与句意相符。"}, {"text": "寄给", "is_correct": false, "explanation": "搭配：“寄给”要求收件对象能收取邮件，“闹钟”不能。"}, {"text": "赠给", "is_correct": false, "explanation": "语义：“赠给”表示送人，不表示把手机用作闹钟。"}, {"text": "托给", "is_correct": false, "explanation": "配价：“托给”的对象须能承担托付的事务，“闹钟”不能承担。"}], "explanations": {"当做": "正确：“把手机当做闹钟用”表示把手机用作闹钟，与句意相符。", "寄给": "搭配：“寄给”要求收件对象能收取邮件，“闹钟”不能。", "赠给": "语义：“赠给”表示送人，不表示把手机用作闹钟。", "托给": "配价：“托给”的对象须能承担托付的事务，“闹钟”不能承担。"}, "sentence_index": 6, "correct_answer": "当做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈当做了一句道歉。", "explanation": "这里应该用〈说〉。“当做”表示看成或用作，不表示说话。"}, {"text": "他当做了一张照片。", "explanation": "这里应该用〈拍〉。“当做”表示看成或用作，不表示拍摄。"}, {"text": "我们当做了一个决定。", "explanation": "这里应该用〈作出〉。“当做”表示看成或用作，不表示作出决定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他旧纸箱当做凳子坐。", "corrected_sentence": "他把旧纸箱当做凳子坐。", "error_description": "“当做”的受事前要用“把”，应为“他把旧纸箱当做凳子坐”，缺少“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧纸箱当做的书柜用。", "corrected_sentence": "他把旧纸箱当做书柜用。", "error_description": "“当做”后直接接宾语，不能加“的”，应为“他把旧纸箱当做书柜用”，多出的“的”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
