INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某人或某事看成另一种人或事；认为是。", "primary_collocate": null, "pronunciation": "dàng zuò", "ipa": "tɑŋ˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他把我当做他最好的朋友。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把我的话当做玩笑。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把每个学生都当做自己的孩子。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别把这件小事当做大问题。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来没有把钱当做最重要的东西。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该把错误当做学习的机会。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这次失败当做一个新的开始。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把周末当做休息的好时间。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把我说的话当做耳边风。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们把他当做自己人。", "target_word": "当做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当做了", "label": "体标（了）"}, {"form": "當做", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把甲看成乙：把A当做B，表示看待、认为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当做", "is_correct": true, "explanation": "正确：“把我当做朋友”表示看待，与句意相符。"}, {"text": "寄给", "is_correct": false, "explanation": "语义：“寄给”表示邮寄，不表示把人看作朋友。"}, {"text": "抄给", "is_correct": false, "explanation": "语义：“抄给”表示誊写后递送，不表示看待。"}, {"text": "扔给", "is_correct": false, "explanation": "语义：“扔给”表示抛掷，不表示看待。"}], "explanations": {"当做": "正确：“把我当做朋友”表示看待，与句意相符。", "寄给": "语义：“寄给”表示邮寄，不表示把人看作朋友。", "抄给": "语义：“抄给”表示誊写后递送，不表示看待。", "扔给": "语义：“扔给”表示抛掷，不表示看待。"}, "sentence_index": 0, "correct_answer": "当做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他当做了一座桥。", "explanation": "这里应该用〈建〉。“当做”表示看成或用作，不表示建造。"}, {"text": "学校当做了一场运动会。", "explanation": "这里应该用〈举办〉。“当做”表示看待或用作，不能用来表示组织活动。"}, {"text": "我们当做了这次讨论。", "explanation": "这里应该用〈进行〉。“当做”与“讨论”不搭配，应说“进行讨论”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当做", "is_correct": true, "explanation": "正确：“把这次失败当做一个新的开始”表示看待，与句意相符。"}, {"text": "赠予", "is_correct": false, "explanation": "语义：“赠予”表示送给，不表示把失败看作开始。"}, {"text": "推给", "is_correct": false, "explanation": "语义：“推给”表示推卸责任，与“新的开始”的积极含义相反。"}, {"text": "寄给", "is_correct": false, "explanation": "搭配：“寄给”要求接收对象能收件，“开始”不能接收邮件。"}], "explanations": {"当做": "正确：“把这次失败当做一个新的开始”表示看待，与句意相符。", "赠予": "语义：“赠予”表示送给，不表示把失败看作开始。", "推给": "语义：“推给”表示推卸责任，与“新的开始”的积极含义相反。", "寄给": "搭配：“寄给”要求接收对象能收件，“开始”不能接收邮件。"}, "sentence_index": 6, "correct_answer": "当做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司当做了一名新员工去分公司。", "explanation": "这里应该用〈派遣〉。“当做”表示看待或用作，不表示派出人员。"}, {"text": "他当做了这条路。", "explanation": "这里应该用〈选择〉。“当做”表示看待或用作，不表示挑选。"}, {"text": "工厂当做了一百辆汽车。", "explanation": "这里应该用〈生产〉。“当做”表示看待或用作，不表示制造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这件事当做重要的任务。", "corrected_sentence": "他把这件事当做重要的任务。", "error_description": "“当做”的受事前要用“把”，应为“他把这件事当做重要的任务”，缺少“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我她把当做好朋友。", "corrected_sentence": "我把她当做好朋友。", "error_description": "“把”的位置有误：“把”须紧接在受事“她”之前，应为“我把她当做好朋友”，“她把”颠倒了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
