INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某地当地所用的标准时间。", "primary_collocate": null, "pronunciation": "dāng dì shí jiān", "ipa": "taŋ˥ ti˥˩ ʂʅ˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "飞机在当地时间下午三点到达北京。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是当地时间早上八点。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛将在当地时间晚上七点开始。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手表调成当地时间。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按当地时间吃了晚饭。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纽约的当地时间比北京晚十几个小时。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，地震发生在当地时间凌晨两点。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了机场，先看看当地时间是几点。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地时间已经是半夜了，他还没睡。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出在当地时间周六上午十点开始。", "target_word": "当地时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某地区所采用的标准时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当地时间", "is_correct": true, "explanation": "正确：「当地时间」指飞机抵达地的标准时刻，与「下午三点」搭配，能填入空格。"}, {"text": "时区", "is_correct": false, "explanation": "语义：时区是地理上的划分，不是某个时刻，不能说「在时区下午三点」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是时间，句子说的是飞机到达的钟点。"}, {"text": "时辰", "is_correct": false, "explanation": "语域：「时辰」是古代的计时单位，现代不用来指具体钟点，与「下午三点」冲突。"}], "explanations": {"当地时间": "正确：「当地时间」指飞机抵达地的标准时刻，与「下午三点」搭配，能填入空格。", "时区": "语义：时区是地理上的划分，不是某个时刻，不能说「在时区下午三点」。", "天气": "语义：天气不是时间，句子说的是飞机到达的钟点。", "时辰": "语域：「时辰」是古代的计时单位，现代不用来指具体钟点，与「下午三点」冲突。"}, "sentence_index": 0, "correct_answer": "当地时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国属于当地时间。", "explanation": "这里应该用〈时区〉。当地时间是某一时刻，说一个地区属于哪个时区要用时区。"}, {"text": "这段路程的当地时间是三个小时。", "explanation": "这里应该用〈用时〉。当地时间是某地的钟点，说这段路程花了多久要用用时。"}, {"text": "这里的当地时间很冷，大家都穿上了大衣。", "explanation": "这里应该用〈天气〉。当地时间是某地的钟点，不能用“冷”来形容，说冷热要用天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当地时间", "is_correct": true, "explanation": "正确：「当地时间」指地震发生地的标准时刻，与「凌晨两点」搭配，能填入空格。"}, {"text": "震级", "is_correct": false, "explanation": "语义：震级是衡量地震强弱的数值，不是时刻，「发生在震级」不成立。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：「清晨」与「凌晨两点」时段矛盾，两者不能并列。"}, {"text": "吉时", "is_correct": false, "explanation": "语域：「吉时」是婚礼、祭祀等场合的说法，新闻报道里不用。"}], "explanations": {"当地时间": "正确：「当地时间」指地震发生地的标准时刻，与「凌晨两点」搭配，能填入空格。", "震级": "语义：震级是衡量地震强弱的数值，不是时刻，「发生在震级」不成立。", "清晨": "语义：「清晨」与「凌晨两点」时段矛盾，两者不能并列。", "吉时": "语域：「吉时」是婚礼、祭祀等场合的说法，新闻报道里不用。"}, "sentence_index": 6, "correct_answer": "当地时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在当地时间工作了三年。", "explanation": "这里把〈当地时间〉当成了地点。它是时刻，不指地方，「在……工作」后面要接的是地点。"}, {"text": "我们一直住在当地时间。", "explanation": "这里把〈当地时间〉当成了地方。它表示时刻，不能用来说居住在哪里。"}, {"text": "这条大路通往当地时间。", "explanation": "这里把〈当地时间〉当成了地方。它是时刻，不能作为道路的终点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店对当地时间早上七点开门。", "corrected_sentence": "这家店按当地时间早上七点开门。", "error_description": "错误：引出“当地时间”作为依据要用“按”，“对”不能这样用。正确：“按当地时间早上七点开门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板说明天按当地时间九点的开会。", "corrected_sentence": "老板说明天按当地时间九点开会。", "error_description": "错误：“九点”后面不能加“的”再接动词“开会”。“的”是定语标记，要放在名词前。正确：“按当地时间九点开会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
