INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97383, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97383, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体某个地方很难受，一碰就疼。", "primary_collocate": null, "pronunciation": "téng tòng", "ipa": "tʰɤŋ˧˥ tʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的膝盖很疼痛，一碰就受不了。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口还很疼痛，你别用手碰它。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚踝肿了，走路时特别疼痛。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙齿疼痛得睡不着觉。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的腰很疼痛，坐久了站不起来。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手指夹到了门缝里，现在非常疼痛。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生轻轻按了一下，我的肩膀立刻疼痛起来。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方一碰就疼痛，可能骨头有问题。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的耳朵很疼痛，哭了一晚上。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的胃疼痛得厉害，只好躺着休息。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疼痛感", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容身体某处难受、一碰就疼的状态，作谓语，常带程度副词（很疼痛、特别疼痛）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疼痛", "is_correct": true, "explanation": "疼痛形容身体某处一碰就疼，与“很”搭配，并与后文“一碰就受不了”相合。"}, {"text": "舒服", "is_correct": false, "explanation": "语义：“舒服”表示身体舒适，与“一碰就受不了”矛盾。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”指身体没有病痛，与“一碰就受不了”矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描写膝盖的身体感受。"}], "explanations": {"疼痛": "疼痛形容身体某处一碰就疼，与“很”搭配，并与后文“一碰就受不了”相合。", "舒服": "语义：“舒服”表示身体舒适，与“一碰就受不了”矛盾。", "健康": "语义：“健康”指身体没有病痛，与“一碰就受不了”矛盾。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描写膝盖的身体感受。"}, "sentence_index": 0, "correct_answer": "疼痛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份工作很疼痛，每天都要加班。", "explanation": "这里应该用〈辛苦〉。“疼痛”只指身体的痛感，不能形容工作的累，说工作累要用〈辛苦〉。"}, {"text": "这次旅行玩得很疼痛，大家都很开心。", "explanation": "这里应该用〈痛快〉。“疼痛”形容身体难受，玩得尽兴、开心要用〈痛快〉。"}, {"text": "这个笑话很疼痛，大家都笑了。", "explanation": "这里应该用〈好笑〉。“疼痛”只用于身体的痛感，形容笑话要用〈好笑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疼痛", "is_correct": true, "explanation": "疼痛形容肩膀被按后身体的不适，与“立刻……起来”搭配，语义通顺。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音或动作，不能形容肩膀的身体感受。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容智力，不能用来形容肩膀的身体状态。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体形，与按压后身体感受的变化不符。"}], "explanations": {"疼痛": "疼痛形容肩膀被按后身体的不适，与“立刻……起来”搭配，语义通顺。", "安静": "语义：“安静”指没有声音或动作，不能形容肩膀的身体感受。", "聪明": "语义：“聪明”形容智力，不能用来形容肩膀的身体状态。", "高大": "体貌：“高大”形容身材或体形，与按压后身体感受的变化不符。"}, "sentence_index": 6, "correct_answer": "疼痛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很疼痛，我吃不下去。", "explanation": "这里应该用〈辣〉。“疼痛”只指身体的痛感，不能形容菜的味道；菜太辣吃不下要用〈辣〉。"}, {"text": "这次考试很疼痛，我考得很差。", "explanation": "这里应该用〈难〉。“疼痛”只指身体的痛感，形容考试难要用〈难〉。"}, {"text": "今天天气很疼痛，我们都想出去玩。", "explanation": "这里应该用〈好〉。“疼痛”只用于身体的痛感，不能形容天气；与后句“我们都想出去玩”相合的是“天气很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的脚踝有点疼痛地，走路要慢一点。", "corrected_sentence": "我的脚踝有点疼痛，走路要慢一点。", "error_description": "结构错误：“地”引出的状语后面没有动词，“有点疼痛地，”结构残缺；直接说“有点疼痛”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的肩膀一用力就疼痛得，只好停下来。", "corrected_sentence": "他的肩膀一用力就疼痛，只好停下来。", "error_description": "补语错误：“得”需要后接补语（如“疼痛得厉害”），这里“得”后面空缺，应删去“得”，写作“一用力就疼痛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
