INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因受伤或生病而感到的痛楚。", "primary_collocate": null, "pronunciation": "téng tòng", "ipa": "tʰɤŋ˧˥ tʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他忍着疼痛走回了家。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我疼痛是从什么时候开始的。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可以减轻疼痛。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤以后，他一直感到疼痛。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术后的疼痛让她睡不好觉。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疼痛一般会持续两三天。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，疼痛慢慢消失了。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能告诉我疼痛的位置吗？", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病的疼痛让老人很难过。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她咬着牙，不让别人看出疼痛。", "target_word": "疼痛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵疼痛", "label": "量词"}, {"form": "疼痛感", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指受伤或生病时感受到的痛楚，可作宾语或主语（感到疼痛、减轻疼痛、疼痛消失）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疼痛", "is_correct": true, "explanation": "疼痛指受伤或生病时感受到的痛楚，与“忍着”相合，语义通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”是具体物品，不能与“忍着”搭配。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“忍着”后接的应是痛苦、疲劳等感受，不能接具体事物“书包”。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“忍着”后接的应是感受，“钥匙”是具体物品，搭配不当。"}], "explanations": {"疼痛": "疼痛指受伤或生病时感受到的痛楚，与“忍着”相合，语义通顺。", "椅子": "搭配：“椅子”是具体物品，不能与“忍着”搭配。", "书包": "搭配：“忍着”后接的应是痛苦、疲劳等感受，不能接具体事物“书包”。", "钥匙": "搭配：“忍着”后接的应是感受，“钥匙”是具体物品，搭配不当。"}, "sentence_index": 0, "correct_answer": "疼痛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里很疼痛，大家都不想出去。", "explanation": "这里应该用〈暖和〉。“疼痛”只指身体的痛感，不能形容屋里的温度；屋里温暖、舒适要用〈暖和〉。"}, {"text": "吃了这块蛋糕，他感到一阵疼痛，非常满足。", "explanation": "这里应该用〈快感〉。“疼痛”指难受的感觉，吃到美味带来的愉悦要用〈快感〉。"}, {"text": "这壶水的疼痛很高，不能喝。", "explanation": "这里应该用〈温度〉。“疼痛”是身体的感觉，不能用来说水的高低，说水的冷热要用〈温度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疼痛", "is_correct": true, "explanation": "疼痛指受伤或生病时的痛楚，与“慢慢消失”的变化相合，语义通顺。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“消失”多用于疼痛、症状等，不能搭配“名字”作主语。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“吃了药”能让疼痛消失，湿度不会因为吃药而消失，句子荒谬。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是具体物体，不会因为吃药而慢慢消失，句子荒谬。"}], "explanations": {"疼痛": "疼痛指受伤或生病时的痛楚，与“慢慢消失”的变化相合，语义通顺。", "名字": "搭配：“消失”多用于疼痛、症状等，不能搭配“名字”作主语。", "湿度": "语义：“吃了药”能让疼痛消失，湿度不会因为吃药而消失，句子荒谬。", "黑板": "语义：黑板是具体物体，不会因为吃药而慢慢消失，句子荒谬。"}, "sentence_index": 6, "correct_answer": "疼痛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的疼痛很香，大家都围过来看。", "explanation": "这里应该用〈气味〉。“疼痛”指身体的痛感，形容花的香味要用〈气味〉。"}, {"text": "这首歌的疼痛很动听，大家都在听。", "explanation": "这里应该用〈旋律〉。“疼痛”不能用来形容歌曲，描写歌曲的好听要用〈旋律〉。"}, {"text": "这幅画的疼痛很鲜艳，很多人来看。", "explanation": "这里应该用〈颜色〉。“疼痛”不能形容画面，描写鲜艳要用〈颜色〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说，这种方法能缓解一只疼痛。", "corrected_sentence": "医生说，这种方法能缓解疼痛。", "error_description": "量词错误：“疼痛”指痛楚，不能用量词“只”，此处直接说“缓解疼痛”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他摔倒后，一只疼痛立刻出现了。", "corrected_sentence": "他摔倒后，一阵疼痛立刻出现了。", "error_description": "量词错误：“疼痛”指一阵一阵的痛感，应用量词“阵”，不能说“一只疼痛”。正确：应说“一阵疼痛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
