INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个圆形，从这头穿过中间到那头的长度。", "primary_collocate": null, "pronunciation": "zhí jìng", "ipa": "ʈʂɻ̩˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个盘子的直径是二十厘米。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵大树的直径有一米多。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个球的直径不到十厘米，可以放进包里。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你量一下这个杯子口的直径是多少。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个井口的直径很小，大人下不去。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月饼的直径大约八厘米。", "target_word": "直径", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个碗直径十五厘米，比那个大。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想买一个直径一米的大圆桌。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要买管子，先量一量它的直径。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种硬币的直径比一元硬币小一点。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "直徑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常物体圆形部分的宽度，如盘子、树干、井口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ff3a29a-476f-42a0-b870-bfa7edf8908b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97387, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径（zhí jìng）：圆形从这头穿过圆心到那头的长度，本词。"}, {"text": "止境", "is_correct": false, "explanation": "zhǐ jìng 与 zhí jìng 第一音节声调不同（第三声与第二声），意思是尽头、限度。"}, {"text": "直井", "is_correct": false, "explanation": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。"}, {"text": "直进", "is_correct": false, "explanation": "第二音节韵尾不同（jìn 是 n，jìng 是 ng），意思是笔直前进。"}, {"text": "石径", "is_correct": false, "explanation": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是石头铺成的小路。"}], "explanations": {"直径": "直径（zhí jìng）：圆形从这头穿过圆心到那头的长度，本词。", "止境": "zhǐ jìng 与 zhí jìng 第一音节声调不同（第三声与第二声），意思是尽头、限度。", "直井": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。", "直进": "第二音节韵尾不同（jìn 是 n，jìng 是 ng），意思是笔直前进。", "石径": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是石头铺成的小路。"}, "sentence_index": null, "correct_answer": "直径"}, "level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径：指圆的长度，可以说“盘子的直径是二十厘米”。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”要用平方单位计量，不能说“二十厘米”。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量指轻重，不是用厘米量的长度。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱数，不能用厘米计量。"}], "explanations": {"直径": "直径：指圆的长度，可以说“盘子的直径是二十厘米”。", "面积": "搭配：“面积”要用平方单位计量，不能说“二十厘米”。", "重量": "语义：重量指轻重，不是用厘米量的长度。", "价格": "语义：价格是钱数，不能用厘米计量。"}, "sentence_index": 0, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块黑板的直径是两米。", "explanation": "这里应该用〈宽度〉。直径只用于圆形物体，穿过圆心的线段；黑板是长方形，要说宽度。"}, {"text": "这条路的直径是两公里。", "explanation": "这里应该用〈长度〉。直径只用于圆形，路没有圆心；一条路的长短要说长度。"}, {"text": "他的直径是一米七五。", "explanation": "这里应该用〈身高〉。直径只用于圆形物体，人的高矮要说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97387, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径（zhí jìng）：圆形从这头穿过圆心到那头的长度，本词。"}, {"text": "至境", "is_correct": false, "explanation": "zhì jìng 与 zhí jìng 只差第一音节声调（第四声与第二声），意思是最高的境界。"}, {"text": "实境", "is_correct": false, "explanation": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是真实的环境。"}, {"text": "直井", "is_correct": false, "explanation": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。"}], "explanations": {"直径": "直径（zhí jìng）：圆形从这头穿过圆心到那头的长度，本词。", "至境": "zhì jìng 与 zhí jìng 只差第一音节声调（第四声与第二声），意思是最高的境界。", "实境": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是真实的环境。", "直井": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。"}, "sentence_index": null, "correct_answer": "直径"}, "level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径：指碗口的长度，可以说“碗的直径十五厘米”。"}, {"text": "容量", "is_correct": false, "explanation": "搭配：“容量”用毫升、升计量，不说“十五厘米”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是能用长度计量的东西。"}, {"text": "材质", "is_correct": false, "explanation": "语义：材质指材料种类，不能用厘米计量。"}], "explanations": {"直径": "直径：指碗口的长度，可以说“碗的直径十五厘米”。", "容量": "搭配：“容量”用毫升、升计量，不说“十五厘米”。", "颜色": "语义：颜色不是能用长度计量的东西。", "材质": "语义：材质指材料种类，不能用厘米计量。"}, "sentence_index": 6, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的直径是二十厘米。", "explanation": "这里应该用〈长度〉或〈宽度〉。直径只用于圆形物体，书是长方形的。"}, {"text": "这扇门的直径是两米。", "explanation": "这里应该用〈高度〉。直径只用于圆形物体，门的高矮要说高度。"}, {"text": "这张方桌的直径是一米。", "explanation": "这里应该用〈边长〉或〈宽度〉。方桌不是圆形，没有直径。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个杯子的一个直径是八厘米。", "corrected_sentence": "这个杯子的直径是八厘米。", "error_description": "“一个直径”错误：直径表示被测的长度数值，不能用“一个”去计数；应说“这个杯子的直径是八厘米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个碗直径的十厘米，很小。", "corrected_sentence": "这个碗直径十厘米，很小。", "error_description": "多余的“的”：“直径”后面直接接数量，不加“的”，应说“直径十厘米”；加“的”后“直径的十厘米”缺少中心语，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
