INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97399, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对人要有的好样子，比如问好、鞠躬。", "primary_collocate": null, "pronunciation": "lǐ", "ipa": "li˨˩˦", "syllable_count": 1, "sentences": [{"text": "他从小就懂礼，见人先问好。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对老人要有礼，不能大声说话。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子进门先问好，大人都夸他懂礼。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居之间要讲礼，不要为小事吵架。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他见了老师就鞠躬，真是个有礼的孩子。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国人很重视礼，吃饭时先请长辈坐。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做人要知礼，对客人不能不理。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很不客气，一点也不讲礼。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弯腰鞠躬，说声你好，都是待人的礼。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家的孩子个个守礼，客人都很喜欢。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "禮", "label": "繁体"}, {"form": "礼貌", "label": "复合"}, {"form": "礼节", "label": "复合"}], "register": "中性", "sense_fingerprint": "待人接物应有的礼节和规矩，如问好、鞠躬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ff3a29a-476f-42a0-b870-bfa7edf8908b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼（lǐ，第三声）：待人接物的礼节，本词。"}, {"text": "力", "is_correct": false, "explanation": "lì 与 lǐ 声调不同（第四声与第三声），意思是力量。"}, {"text": "梨", "is_correct": false, "explanation": "lí 与 lǐ 声调不同（第二声与第三声），意思是水果梨。"}, {"text": "你", "is_correct": false, "explanation": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。"}, {"text": "米", "is_correct": false, "explanation": "mǐ 与 lǐ 声母不同（m 与 l），声调相同，意思是大米。"}], "explanations": {"礼": "礼（lǐ，第三声）：待人接物的礼节，本词。", "力": "lì 与 lǐ 声调不同（第四声与第三声），意思是力量。", "梨": "lí 与 lǐ 声调不同（第二声与第三声），意思是水果梨。", "你": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。", "米": "mǐ 与 lǐ 声母不同（m 与 l），声调相同，意思是大米。"}, "sentence_index": null, "correct_answer": "礼"}, "level_3": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼：待人的礼节，“懂礼”指懂得待人的规矩。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能被“懂”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能被“懂”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不能被“懂”。"}], "explanations": {"礼": "礼：待人的礼节，“懂礼”指懂得待人的规矩。", "椅子": "语义：椅子是家具，不能被“懂”。", "桌子": "语义：桌子是家具，不能被“懂”。", "冰箱": "语义：冰箱是电器，不能被“懂”。"}, "sentence_index": 0, "correct_answer": "礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿了一身礼去参加宴会。", "explanation": "这里应该用〈礼服〉。“礼”不指服装，正式的衣服要说礼服。"}, {"text": "他从小就懂礼，过生日收到很多礼。", "explanation": "这里应该用〈礼物〉。本义项的“礼”指待人的礼节，不指送的东西。"}, {"text": "学校举行了一场礼。", "explanation": "这里应该用〈典礼〉。“礼”单独不指仪式，表示仪式要说典礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97399, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼（lǐ，第三声）：待人接物的礼节，本词。"}, {"text": "利", "is_correct": false, "explanation": "lì 与 lǐ 声调不同（第四声与第三声），意思是利益。"}, {"text": "离", "is_correct": false, "explanation": "lí 与 lǐ 声调不同（第二声与第三声），意思是离开。"}, {"text": "你", "is_correct": false, "explanation": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。"}], "explanations": {"礼": "礼（lǐ，第三声）：待人接物的礼节，本词。", "利": "lì 与 lǐ 声调不同（第四声与第三声），意思是利益。", "离": "lí 与 lǐ 声调不同（第二声与第三声），意思是离开。", "你": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。"}, "sentence_index": null, "correct_answer": "礼"}, "level_3": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼：待人的礼节，“知礼”指懂得礼节。"}, {"text": "冷水", "is_correct": false, "explanation": "语义：冷水是液体，不能被“知”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“知”后面不接颜色，应说“认识颜色”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不能被“知”。"}], "explanations": {"礼": "礼：待人的礼节，“知礼”指懂得礼节。", "冷水": "语义：冷水是液体，不能被“知”。", "颜色": "搭配：“知”后面不接颜色，应说“认识颜色”。", "石头": "语义：石头是物体，不能被“知”。"}, "sentence_index": 6, "correct_answer": "礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在礼里排队等候。", "explanation": "这里应该用〈礼堂〉。“礼”不表示场所，要说礼堂。"}, {"text": "他们明天要办一场礼。", "explanation": "这里应该用〈婚礼〉。“礼”单独不指仪式，表示仪式要说婚礼。"}, {"text": "妈妈给我买了一个礼，是个新书包。", "explanation": "这里应该用〈礼物〉。本义项的“礼”指待人的礼节规矩，不指具体的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说话很礼讲，大家都喜欢他。", "corrected_sentence": "他说话很讲礼，大家都喜欢他。", "error_description": "语序错误：“讲礼”是动宾结构，应说“讲礼”，不说“礼讲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做人要守一个礼，对谁都要尊重。", "corrected_sentence": "做人要守礼，对谁都要尊重。", "error_description": "量词错误：“守礼”的“礼”是抽象的礼节，不用量词“个”修饰；应说“做人要守礼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
