INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97400, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示尊敬的言语或动作；也指礼物。", "primary_collocate": null, "pronunciation": "lǐ", "ipa": "li˨˩˦", "syllable_count": 1, "sentences": [{"text": "他向老人行了一个礼。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生向老师行礼，老师笑着回了礼。", "target_word": "礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事过生日，我准备了一份礼。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他收了我的礼，高兴地笑了。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友结婚，我们要送一份礼。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份礼不贵，但是心意很重。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不收礼，也从来不送礼。", "target_word": "礼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈说，去亲戚家过节，要准备一份礼。", "target_word": "礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送的礼太重了，我不敢收。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "见到校长，他站好，向校长行了个礼。", "target_word": "礼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "禮", "label": "繁体"}, {"form": "礼物", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示敬意的动作，或送给别人的礼物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ff3a29a-476f-42a0-b870-bfa7edf8908b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼（lǐ，第三声）：表示敬意的动作或送人的礼物，本词。"}, {"text": "力", "is_correct": false, "explanation": "lì 与 lǐ 声调不同（第四声与第三声），意思是力量。"}, {"text": "梨", "is_correct": false, "explanation": "lí 与 lǐ 声调不同（第二声与第三声），意思是水果梨。"}, {"text": "你", "is_correct": false, "explanation": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。"}, {"text": "米", "is_correct": false, "explanation": "mǐ 与 lǐ 声母不同（m 与 l），声调相同，意思是大米。"}], "explanations": {"礼": "礼（lǐ，第三声）：表示敬意的动作或送人的礼物，本词。", "力": "lì 与 lǐ 声调不同（第四声与第三声），意思是力量。", "梨": "lí 与 lǐ 声调不同（第二声与第三声），意思是水果梨。", "你": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。", "米": "mǐ 与 lǐ 声母不同（m 与 l），声调相同，意思是大米。"}, "sentence_index": null, "correct_answer": "礼"}, "level_3": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼：表示敬意的动作，“行了一个礼”指鞠了一个躬或行了一次礼。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能被“行”。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能被“行”。"}, {"text": "词", "is_correct": false, "explanation": "搭配：“行”后面接的是礼、礼节这类动作，不接“词”。"}], "explanations": {"礼": "礼：表示敬意的动作，“行了一个礼”指鞠了一个躬或行了一次礼。", "饺子": "语义：饺子是食物，不能被“行”。", "花瓶": "语义：花瓶是器物，不能被“行”。", "词": "搭配：“行”后面接的是礼、礼节这类动作，不接“词”。"}, "sentence_index": 0, "correct_answer": "礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老人行了一份礼。", "explanation": "这里应该用〈个〉。行礼的量词是“个”或“次”，“份”用于礼物。"}, {"text": "我送给他一只礼。", "explanation": "这里应该用〈份〉。礼物的量词是“份”或“件”，“只”不用于礼物。"}, {"text": "学校举办了一场礼。", "explanation": "这里应该用〈典礼〉。“礼”单独不指仪式，表示仪式要说典礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97400, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼（lǐ，第三声）：表示敬意的动作或送人的礼物，本词。"}, {"text": "利", "is_correct": false, "explanation": "lì 与 lǐ 声调不同（第四声与第三声），意思是利益。"}, {"text": "离", "is_correct": false, "explanation": "lí 与 lǐ 声调不同（第二声与第三声），意思是离开。"}, {"text": "你", "is_correct": false, "explanation": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。"}], "explanations": {"礼": "礼（lǐ，第三声）：表示敬意的动作或送人的礼物，本词。", "利": "lì 与 lǐ 声调不同（第四声与第三声），意思是利益。", "离": "lí 与 lǐ 声调不同（第二声与第三声），意思是离开。", "你": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你。"}, "sentence_index": null, "correct_answer": "礼"}, "level_3": {"options": [{"text": "礼", "is_correct": true, "explanation": "礼：送人的礼物，“不收礼”指不收别人送的礼物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以“收”的礼物。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的东西，不能被“收”。"}, {"text": "态度", "is_correct": false, "explanation": "搭配：“收”不接“态度”，收的是礼物、钱物等。"}], "explanations": {"礼": "礼：送人的礼物，“不收礼”指不收别人送的礼物。", "石头": "语义：石头不是可以“收”的礼物。", "空气": "语义：空气是无形的东西，不能被“收”。", "态度": "搭配：“收”不接“态度”，收的是礼物、钱物等。"}, "sentence_index": 6, "correct_answer": "礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿了一套礼去参加宴会。", "explanation": "这里应该用〈礼服〉。“礼”不指服装，正式的衣服要说礼服。"}, {"text": "我们在礼开了一个会。", "explanation": "这里应该用〈礼堂〉。“礼”不表示场所，要说“礼堂”。"}, {"text": "他向老师行了一把礼。", "explanation": "这里应该用〈个〉。行礼的量词是“个”或“次”，“把”用于有柄的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友搬新家，我买了一只礼送给他。", "corrected_sentence": "朋友搬新家，我买了一份礼送给他。", "error_description": "量词错误：礼物的量词是“份”，应说“一份礼”，不说“一只礼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生向老师了行礼。", "corrected_sentence": "学生向老师行了礼。", "error_description": "了的位置错误：“了”应放在动词“行”后面，应说“行了礼”，不说“了行礼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
