INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97401, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用好办法把工作安排得更好。", "primary_collocate": null, "pronunciation": "kē xué guǎn lǐ", "ipa": "kʰɤ˥ ɕɥe˧˥ kwan˨˩ li˨˩", "syllable_count": 4, "sentences": [{"text": "公司用科学管理，工作做得更快了。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校需要科学管理，才能更有秩序。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学管理让我们的工作更轻松。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理学过科学管理，把工作安排得很好。", "target_word": "科学管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了科学管理，大家不再加班了。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店靠科学管理，越做越好。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想学科学管理，把团队带好。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事要依靠科学管理，不能乱来。", "target_word": "科学管理", "complexity_tier": "T3", "furigana": "zuòshì yào yīkào kēxué guǎnlǐ, bùnéng luànlái.", "sentence_source": "generated"}, {"text": "科学管理能节省很多时间。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小饭馆也需要科学管理。", "target_word": "科学管理", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用好办法把工作安排得更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97401, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体育锻炼", "is_correct": false, "explanation": "语义：“体育锻炼”是锻炼身体的活动，不能用来安排工作。"}, {"text": "美术设计", "is_correct": false, "explanation": "语义：“美术设计”与安排工作无关，不能让工作做得更快。"}, {"text": "大锅饭", "is_correct": false, "explanation": "语义：“大锅饭”指不讲效率的平均分配，与“做得更快”相悖。"}, {"text": "科学管理", "is_correct": true, "explanation": "正确：“科学管理”是用科学办法安排工作的做法，与“工作做得更快了”相符。"}], "explanations": {"体育锻炼": "语义：“体育锻炼”是锻炼身体的活动，不能用来安排工作。", "美术设计": "语义：“美术设计”与安排工作无关，不能让工作做得更快。", "大锅饭": "语义：“大锅饭”指不讲效率的平均分配，与“做得更快”相悖。", "科学管理": "正确：“科学管理”是用科学办法安排工作的做法，与“工作做得更快了”相符。"}, "sentence_index": 0, "correct_answer": "科学管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提出了一只科学管理。", "explanation": "量词错误：“只”用于动物或成对物品中的一个，不能计量“科学管理”这类理论，应说〈一套〉。"}, {"text": "张经理是一位科学管理。", "explanation": "这里应该用〈管理者〉。科学管理指理论或做法，不指人，不能说某人是科学管理；指人应说〈管理者〉。"}, {"text": "他吃了一顿科学管理。", "explanation": "搭配错误：“吃”的宾语应是食物，“科学管理”是理论或做法，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书法", "is_correct": false, "explanation": "语义：“书法”是写字的艺术，学了它不能用来把团队带好。"}, {"text": "篆刻", "is_correct": false, "explanation": "语义：“篆刻”是刻印章的技艺，学了它不能用来把团队带好。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“学”的宾语应是技能或知识，“体力”不能用“学”来表达。"}, {"text": "科学管理", "is_correct": true, "explanation": "正确：“科学管理”是可以学习的管理知识，学了之后能把团队带好。"}], "explanations": {"书法": "语义：“书法”是写字的艺术，学了它不能用来把团队带好。", "篆刻": "语义：“篆刻”是刻印章的技艺，学了它不能用来把团队带好。", "体力": "搭配：“学”的宾语应是技能或知识，“体力”不能用“学”来表达。", "科学管理": "正确：“科学管理”是可以学习的管理知识，学了之后能把团队带好。"}, "sentence_index": 6, "correct_answer": "科学管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼科学管理得很结实，住了很多人。", "explanation": "这里应该用〈盖〉。科学管理指管理工作的做法，不能用来形容楼的结实程度；说楼盖得结实应用〈盖〉。"}, {"text": "我们在科学管理里吃了午饭。", "explanation": "处所误用：“科学管理”是理论或做法，不是地方，不能用“在……里”表示场所。"}, {"text": "这家饭馆的科学管理很胖。", "explanation": "这里应该用〈大〉。胖形容人或动物的体形，形容饭馆规模应说〈大〉；科学管理是抽象的做法，不能说胖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司用科学管理地方法，工作做得更快了。", "corrected_sentence": "公司用科学管理的方法，工作做得更快了。", "error_description": "结构助词错误：修饰名词“方法”时应用“的”，“地”只用于修饰动词。“科学管理地方法”应改为“科学管理的方法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想学一只科学管理，把团队带好。", "corrected_sentence": "他想学一门科学管理，把团队带好。", "error_description": "量词错误：“科学管理”作为学问应用“门”计量（一门科学管理），不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
