INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "运用科学的方法对生产和工作进行管理。", "primary_collocate": null, "pronunciation": "kē xué guǎn lǐ", "ipa": "kʰɤ˥ ɕɥe˧˥ kwan˨˩ li˨˩", "syllable_count": 4, "sentences": [{"text": "工厂用科学管理提高了生产效率。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学管理对工厂的生产很重要。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂实行了科学管理。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学管理是一门研究工作方法的学问。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "泰勒提出了科学管理的方法。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院也在学习科学管理的做法。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学了科学管理，他对生产更有办法。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学管理可以减少生产中的浪费。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板请专家来教大家科学管理。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书介绍了科学管理的历史。", "target_word": "科学管理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "运用科学方法管理生产和工作的理论与做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络游戏", "is_correct": false, "explanation": "语义：“网络游戏”是娱乐活动，不是管理生产的手段，不能提高生产效率。"}, {"text": "体育竞赛", "is_correct": false, "explanation": "语义：“体育竞赛”是比赛活动，与管理生产无关。"}, {"text": "大锅饭", "is_correct": false, "explanation": "语义：“大锅饭”指不讲效率的平均分配，与“提高生产效率”相悖。"}, {"text": "科学管理", "is_correct": true, "explanation": "正确：“科学管理”是用科学方法管理生产的做法，可以提高生产效率。"}], "explanations": {"网络游戏": "语义：“网络游戏”是娱乐活动，不是管理生产的手段，不能提高生产效率。", "体育竞赛": "语义：“体育竞赛”是比赛活动，与管理生产无关。", "大锅饭": "语义：“大锅饭”指不讲效率的平均分配，与“提高生产效率”相悖。", "科学管理": "正确：“科学管理”是用科学方法管理生产的做法，可以提高生产效率。"}, "sentence_index": 0, "correct_answer": "科学管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们工厂引进了一只科学管理。", "explanation": "量词错误：“只”用于动物等，不能计量“科学管理”这种做法，应说〈一套〉，或者不用量词。"}, {"text": "我们在科学管理里工作。", "explanation": "处所误用：“科学管理”是理论或做法，不是场所，不能用“在……里”表示地点。"}, {"text": "他喝了一杯科学管理。", "explanation": "搭配错误：“喝”的宾语应是饮料，“科学管理”不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书法", "is_correct": false, "explanation": "语义：“书法”是写字的艺术，学了它不会让人对生产更有办法。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器演奏的技能，学了它不会让人对生产更有办法。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“学”的宾语应是技能或知识，“体力”不能用“学”来表达。"}, {"text": "科学管理", "is_correct": true, "explanation": "正确：“科学管理”是可以学习的知识，学了之后对生产更有办法。"}], "explanations": {"书法": "语义：“书法”是写字的艺术，学了它不会让人对生产更有办法。", "钢琴": "语义：“钢琴”是乐器演奏的技能，学了它不会让人对生产更有办法。", "体力": "搭配：“学”的宾语应是技能或知识，“体力”不能用“学”来表达。", "科学管理": "正确：“科学管理”是可以学习的知识，学了之后对生产更有办法。"}, "sentence_index": 6, "correct_answer": "科学管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂科学管理了很多汽车。", "explanation": "这里应该用〈生产〉。科学管理指管理工作的做法，不能作及物动词带“很多汽车”作宾语；说造车应用〈生产〉。"}, {"text": "这本书的作者是一位科学管理。", "explanation": "这里指人，但科学管理是理论或做法，不指人；指人的身份应说〈学者〉或〈专家〉等。"}, {"text": "这座桥科学管理得很结实，车辆很多。", "explanation": "这里应该用〈修〉。科学管理指管理工作的做法，不能用来形容桥的结实程度；说桥修得结实应用〈修〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂实行了科学管理地方法。", "corrected_sentence": "这家工厂实行了科学管理的方法。", "error_description": "结构助词错误：修饰名词“方法”时应用“的”，“地”只用于修饰动词。“科学管理地方法”应改为“科学管理的方法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂的科学管理很有钱。", "corrected_sentence": "这家工厂的科学管理很有效。", "error_description": "搭配错误：“科学管理”是管理方法，不能说“很有钱”；应改为“很有效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
