INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97419, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人小时候的那段日子。", "primary_collocate": null, "pronunciation": "tóng nián", "ipa": "tʰʊŋ˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我很想念童年的日子。", "target_word": "童年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "童年的夏天总是很长。", "target_word": "童年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我对童年的记忆很清楚。", "target_word": "童年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "童年的回忆让他觉得很温暖。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶常说，她的童年很穷，但很快乐。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把童年的玩具放在盒子里。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到这张老照片，我想起了童年。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在童年的那些日子里，我们每天都在河边玩。", "target_word": "童年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "童年的朋友现在住在国外。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你还记得童年时最喜欢的游戏吗？", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人回忆中小时候的那段日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“想念……的日子”指可以回忆的过去时光，“天气”不是时段，句意不通。"}, {"text": "童年", "is_correct": true, "explanation": "童年指人小时候的那段日子，正好与“想念……的日子”相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“想念”的对象应是人、事或可以回忆的时期，“价格”不能被“想念”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不指一段日子，“颜色的日子”没有意义。"}], "explanations": {"天气": "语义：“想念……的日子”指可以回忆的过去时光，“天气”不是时段，句意不通。", "童年": "童年指人小时候的那段日子，正好与“想念……的日子”相合。", "价格": "搭配：“想念”的对象应是人、事或可以回忆的时期，“价格”不能被“想念”。", "颜色": "语义：“颜色”不指一段日子，“颜色的日子”没有意义。"}, "sentence_index": 0, "correct_answer": "童年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店专门卖童年。", "explanation": "这里应该用〈童装〉。童装指儿童穿的衣服，可以当作商品出售；童年指一段时期，不能当作商品来卖。"}, {"text": "他是一个充满热情的童年。", "explanation": "这里应该用〈青年〉。青年是指人的称呼；童年指一段时期，不能用来指人。"}, {"text": "妈妈每天晚上给我讲一个童年。", "explanation": "这里应该用〈童话〉。童话是讲给孩子听的故事，可以“讲一个”；童年指人小时候的那段时期，不能被“讲一个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽油", "is_correct": false, "explanation": "语义：“想起”的对象应是可以回忆的人或事，“汽油”不能作回忆的内容，句意不通。"}, {"text": "童年", "is_correct": true, "explanation": "童年是可以被回忆的一段时期，“想起了童年”表示想到小时候的日子。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：“想起了”后接的宾语须是可以回忆的人、事或时期，“电梯”不能与之搭配。"}, {"text": "海关", "is_correct": false, "explanation": "语义：“海关”是检查出入境人员和货物的机构，与老照片无关，无法被想起。"}], "explanations": {"汽油": "语义：“想起”的对象应是可以回忆的人或事，“汽油”不能作回忆的内容，句意不通。", "童年": "童年是可以被回忆的一段时期，“想起了童年”表示想到小时候的日子。", "电梯": "搭配：“想起了”后接的宾语须是可以回忆的人、事或时期，“电梯”不能与之搭配。", "海关": "语义：“海关”是检查出入境人员和货物的机构，与老照片无关，无法被想起。"}, "sentence_index": 6, "correct_answer": "童年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼神很有童年。", "explanation": "这里应该用〈童真〉。形容眼神天真无邪要说“童真”；“童年”指时期，不能形容眼神。"}, {"text": "她唱歌时的嗓音很童年，听起来很可爱。", "explanation": "这里应该用〈童声〉。“童声”指儿童的嗓音，形容嗓音稚嫩要说“童声”；“童年”指一段时期，不能用来形容嗓音。"}, {"text": "那位老人说话很童年。", "explanation": "这里应该用〈童心〉。形容人保持天真的心态要说“有童心”；“童年”不能形容说话的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很怀念那场童年。", "corrected_sentence": "我很怀念那段童年。", "error_description": "错误：量词“场”用于比赛、雨、梦等，不能用于童年。童年是一段时期，应改为“那段童年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的童年过很平静。", "corrected_sentence": "她的童年过得很平静。", "error_description": "错误：“过”之后漏掉了补语的结构助词“得”。应为“过得很平静”，“得”引出状态补语，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
