INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97420, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "儿童时期；一个人幼年的阶段。", "primary_collocate": null, "pronunciation": "tóng nián", "ipa": "tʰʊŋ˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我的童年在农村度过。", "target_word": "童年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的童年过得很快乐。", "target_word": "童年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "童年是人生最美好的阶段。", "target_word": "童年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在海边度过了童年。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多孩子的童年过得很辛苦。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷的童年没有电视，也没有手机。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "童年的经历会影响一个人的性格。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常给孩子讲自己童年的故事。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多作家都喜欢写自己的童年。", "target_word": "童年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "童年时期的朋友，长大以后很难见面了。", "target_word": "童年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人生中儿童时期这一阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市", "is_correct": false, "explanation": "搭配：“度过”的对象应是一段时间，“城市”是地方，“我的城市在农村度过”不成立。"}, {"text": "童年", "is_correct": true, "explanation": "童年指儿童时期，可以作“度过”的宾语，与“在农村”搭配。"}, {"text": "家乡", "is_correct": false, "explanation": "搭配：“度过”要求的对象是一段时间，“家乡”是地方，不能被“度过”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不是一段时间，“我的作业在农村度过”无法成立。"}], "explanations": {"城市": "搭配：“度过”的对象应是一段时间，“城市”是地方，“我的城市在农村度过”不成立。", "童年": "童年指儿童时期，可以作“度过”的宾语，与“在农村”搭配。", "家乡": "搭配：“度过”要求的对象是一段时间，“家乡”是地方，不能被“度过”。", "作业": "搭配：“作业”不是一段时间，“我的作业在农村度过”无法成立。"}, "sentence_index": 0, "correct_answer": "童年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上摆满了童年和漫画。", "explanation": "这里应该用〈童话〉。童话是一种文学体裁，讲给孩子听的故事；童年指人小时候的那段时期，不能和“漫画”一起作为书籍摆放。"}, {"text": "他是一个充满热情的童年。", "explanation": "这里应该用〈青年〉。青年指正在成长、充满热情的人，是人的称呼；童年指一段时期，不能用来指人。"}, {"text": "妈妈给妹妹买了一件漂亮的童年。", "explanation": "这里应该用〈童装〉。童装是儿童穿的衣服，可以“买一件”；童年指一段时期，不能用“件”，也不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“童年的价格”不成搭配，“价格”也无法“影响一个人的性格”。"}, {"text": "童年", "is_correct": true, "explanation": "童年指一段时期，“童年的经历”指这段时期的人生经历，能够影响性格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人的经历，不能与“经历”同类，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是经历，“童年的颜色”影响性格没有意义。"}], "explanations": {"价格": "搭配：“童年的价格”不成搭配，“价格”也无法“影响一个人的性格”。", "童年": "童年指一段时期，“童年的经历”指这段时期的人生经历，能够影响性格。", "天气": "语义：“天气”不是人的经历，不能与“经历”同类，句意不通。", "颜色": "语义：“颜色”不是经历，“童年的颜色”影响性格没有意义。"}, "sentence_index": 6, "correct_answer": "童年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个人很有童年，做事总是很认真。", "explanation": "这里应该用〈童心〉。形容人保持孩子般的天真要说“有童心”；“童年”指一段时期，不能用来形容人的性格。"}, {"text": "这个小姑娘的笑容很童年。", "explanation": "这里应该用〈童真〉。形容笑容天真无邪要说“童真”；“童年”是时期名词，不能描写笑容。"}, {"text": "孩子的童年很清脆，像一串铃铛。", "explanation": "这里应该用〈童声〉。“童声”指儿童的嗓音，形容声音清脆要说“童声”；“童年”指一段时期，不能用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的童年过很幸福。", "corrected_sentence": "我的童年过得很幸福。", "error_description": "错误：“过”之后漏掉了补语的结构助词“得”。应为“过得很幸福”，“得”引出状态补语，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他度过了一只快乐的童年。", "corrected_sentence": "他度过了一个快乐的童年。", "error_description": "错误：量词“只”用于动物等，不能用于童年。童年应说“一个快乐的童年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
