INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脸上笑起来的样子。", "primary_collocate": null, "pronunciation": "xiào róng", "ipa": "ɕjɑʊ̯⁵¹ ɻʊŋ³⁵", "syllable_count": 2, "sentences": [{"text": "她的笑容很好看。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢他的笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片里，孩子的笑容特别可爱。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容像太阳一样温暖。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑容甜美，大家都喜欢她。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女孩有一个很好看的笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家画下了老人的笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容跟爸爸一模一样。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑容让我想起了家乡。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘不了她第一次见面时的笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "丝", "label": "量词"}, {"form": "抹", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人笑起来的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笑容", "is_correct": true, "explanation": "正确答案。“她的笑容很好看”说的是脸上的神情。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“好看”用于外貌或景象，一般不说声音好看。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“好看”用于可以看见的对象，不能形容脚步。"}, {"text": "怒火", "is_correct": false, "explanation": "语义：“怒火”表示愤怒，与“很好看”的赞美相悖。"}], "explanations": {"笑容": "正确答案。“她的笑容很好看”说的是脸上的神情。", "声音": "搭配：“好看”用于外貌或景象，一般不说声音好看。", "脚步": "搭配：“好看”用于可以看见的对象，不能形容脚步。", "怒火": "语义：“怒火”表示愤怒，与“很好看”的赞美相悖。"}, "sentence_index": 0, "correct_answer": "笑容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的笑容清脆悦耳。", "explanation": "这里应该用〈笑声〉。清脆悦耳形容声音，笑容没有声音。"}, {"text": "他听完她的笑容，哈哈大笑起来。", "explanation": "这里应该用〈笑话〉。笑容是看得见的神情，没有声音，不能用“听”；听到的是“笑话”。"}, {"text": "他的脸上有一把笑容。", "explanation": "这里应该用〈抹〉。“把”用于有柄的器具，笑容应该用“抹”“丝”或“个”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笑容", "is_correct": true, "explanation": "正确答案。“画家画下了老人的笑容”表示把老人的笑容画了出来。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温看不见，无法被画下来。"}, {"text": "脉搏", "is_correct": false, "explanation": "语义：脉搏看不见，无法被画下来。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是声音，不能被绘画表现。"}], "explanations": {"笑容": "正确答案。“画家画下了老人的笑容”表示把老人的笑容画了出来。", "体温": "语义：体温看不见，无法被画下来。", "脉搏": "语义：脉搏看不见，无法被画下来。", "嗓音": "语义：嗓音是声音，不能被绘画表现。"}, "sentence_index": 6, "correct_answer": "笑容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的笑容很响亮。", "explanation": "这里应该用〈笑声〉。笑容没有声音，“响亮”只能形容声音，笑起来的声音才叫笑声。"}, {"text": "她的笑容很动听。", "explanation": "这里应该用〈笑声〉。“动听”形容声音，笑容是看得见的神情，不能动听。"}, {"text": "厨房里飘着笑容。", "explanation": "这里应该用〈香味〉。笑容不能飘散，香味才会飘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她听完笑话，脸上露出了一条笑容。", "corrected_sentence": "她听完笑话，脸上露出了一丝笑容。", "error_description": "错误形式：“一条笑容”；正确形式：“一丝笑容”。“条”用于细长的东西，笑容应该用“丝”“抹”“个”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他收到信以后，脸上浮现出一张笑容。", "corrected_sentence": "他收到信以后，脸上浮现出一抹笑容。", "error_description": "错误形式：“一张笑容”；正确形式：“一抹笑容”。“张”多用于纸张、桌子等平面的东西，笑容应该用“抹”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
