INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脸上现出的笑的神情。", "primary_collocate": null, "pronunciation": "xiào róng", "ipa": "ɕjɑʊ̯⁵¹ ɻʊŋ³⁵", "syllable_count": 2, "sentences": [{"text": "她脸上带着甜甜的笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子，妈妈露出了笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸上很少有笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的笑容让我不紧张了。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，大家脸上都有了笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收起笑容，认真地看着我。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩给了我一个笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人满脸笑容地走进来。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生总是带着温暖的笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的脸上挂满了笑容。", "target_word": "笑容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "丝", "label": "量词"}, {"form": "抹", "label": "量词"}], "register": "中性", "sense_fingerprint": "脸上现出的笑的神情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笑容", "is_correct": true, "explanation": "正确答案。“甜甜的笑容”指脸上带着的愉快神情。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“甜甜的”形容味道或感觉，不能修饰“石头”。"}, {"text": "皱纹", "is_correct": false, "explanation": "语义：皱纹是皮肤上的纹路，不可能是“甜甜的”。"}, {"text": "怒气", "is_correct": false, "explanation": "语义：“甜甜”与“怒气”的情绪正好相反。"}], "explanations": {"笑容": "正确答案。“甜甜的笑容”指脸上带着的愉快神情。", "石头": "搭配：“甜甜的”形容味道或感觉，不能修饰“石头”。", "皱纹": "语义：皱纹是皮肤上的纹路，不可能是“甜甜的”。", "怒气": "语义：“甜甜”与“怒气”的情绪正好相反。"}, "sentence_index": 0, "correct_answer": "笑容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的笑容很香，走近就能闻到。", "explanation": "这里应该用〈香味〉。笑容是脸上的神情，没有气味，不能用来形容气味；有香味才会说“香”。"}, {"text": "他讲了一个笑容。", "explanation": "这里应该用〈笑话〉。笑容是脸上的神情，不能被“讲”。"}, {"text": "她脸上带着一本笑容。", "explanation": "这里应该用〈抹〉。“本”用于书册，笑容应该用“抹”“丝”或“个”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笑容", "is_correct": true, "explanation": "正确答案。“给了我一个笑容”表示小女孩对我露出笑脸。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”要用“场”计量，而且不能说“给”一个雨。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子是物质，不能表示善意，“给了我一个沙子”不通。"}, {"text": "尘土", "is_correct": false, "explanation": "语义：尘土是脏的物质，与“给”的善意语境相反。"}], "explanations": {"笑容": "正确答案。“给了我一个笑容”表示小女孩对我露出笑脸。", "雨": "搭配：“雨”要用“场”计量，而且不能说“给”一个雨。", "沙子": "语义：沙子是物质，不能表示善意，“给了我一个沙子”不通。", "尘土": "语义：尘土是脏的物质，与“给”的善意语境相反。"}, "sentence_index": 6, "correct_answer": "笑容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的笑容很好听。", "explanation": "这里应该用〈声音〉。笑容是脸上的神情，没有声音，不能说“好听”。"}, {"text": "孩子的笑容响彻了整个房间。", "explanation": "这里应该用〈笑声〉。笑容没有声音，不能“响彻”。"}, {"text": "这首歌充满了笑容。", "explanation": "这里应该用〈喜悦〉。笑容指脸上的神情，不能用来形容歌曲的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她脸上露出了一只笑容。", "corrected_sentence": "她脸上露出了一丝笑容。", "error_description": "错误形式：“一只笑容”；正确形式：“一丝笑容”。“只”多用于动物或小件物品，笑容应该用“丝”“抹”“个”等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子听完故事，脸上露出了一块笑容。", "corrected_sentence": "孩子听完故事，脸上露出了一个笑容。", "error_description": "错误形式：“一块笑容”；正确形式：“一个笑容”。“块”用于成块的东西，笑容应该用“个”“丝”“抹”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
