INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97423, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用绳子或带子绑上去，打个结。", "primary_collocate": null, "pronunciation": "jì shang", "ipa": "tɕi˥˩ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "请把鞋带系上。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在树上系上一根绳子。", "target_word": "系上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她给小狗系上了红带子。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在盒子上系上蝴蝶结。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先把绳子系上，再打个结。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲下来，把鞋带系上了。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩头发上系上了一条丝带。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，快把帽子的带子系上。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在礼物上系上一条金色的带子。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用绳子把两只箱子系上。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "系上了", "label": "体标"}, {"form": "系上过", "label": "体标"}], "register": "口语", "sense_fingerprint": "用绳子、带子绑住并打结", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d9e4b5-858a-436f-a0ee-7c5a7eef59b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97423, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "系上", "is_correct": true, "explanation": "正确答案：系上 jì shang，用绳子或带子绑上并打结。"}, {"text": "骑上", "is_correct": false, "explanation": "声母不同：qí 与 jì 声母不同，意思是骑到车、马等上面。"}, {"text": "地上", "is_correct": false, "explanation": "声母不同：dì 与 jì 声母不同，意思是地面之上。"}, {"text": "机上", "is_correct": false, "explanation": "声调不同：jī（第一声）与 jì（第四声）不同，意思是飞机上。"}], "explanations": {"系上": "正确答案：系上 jì shang，用绳子或带子绑上并打结。", "骑上": "声母不同：qí 与 jì 声母不同，意思是骑到车、马等上面。", "地上": "声母不同：dì 与 jì 声母不同，意思是地面之上。", "机上": "声调不同：jī（第一声）与 jì（第四声）不同，意思是飞机上。"}, "sentence_index": null, "correct_answer": "系上"}, "level_3": {"options": [{"text": "扔上", "is_correct": false, "explanation": "语义：“扔”是抛掷，与整理鞋带的意思不符。"}, {"text": "系上", "is_correct": true, "explanation": "系上指用绳子或带子绑住并打结，符合语境。"}, {"text": "烤上", "is_correct": false, "explanation": "语义：“烤”是加热，鞋带不会被烤上。"}, {"text": "吃上", "is_correct": false, "explanation": "搭配：“吃”不能用于鞋带，不能说“吃上鞋带”。"}], "explanations": {"扔上": "语义：“扔”是抛掷，与整理鞋带的意思不符。", "系上": "系上指用绳子或带子绑住并打结，符合语境。", "烤上": "语义：“烤”是加热，鞋带不会被烤上。", "吃上": "搭配：“吃”不能用于鞋带，不能说“吃上鞋带”。"}, "sentence_index": 0, "correct_answer": "系上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她系上一副眼镜，看清了黑板。", "explanation": "这里应用〈戴上〉。眼镜戴在脸上，“系”只用于带子、绳子。"}, {"text": "她系上了一个电话，接通了对方。", "explanation": "这里应用〈接〉。电话要用“接”，“系”只用于绳子、带子。"}, {"text": "他在墙上系上了海报。", "explanation": "这里应用〈贴上〉。海报要用“贴”，不用“系”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服，丝带系在头发上，不说“穿”。"}, {"text": "系上", "is_correct": true, "explanation": "系上指用丝带绑在头发上，符合语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”与丝带无关，不能用在头发上。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是燃烧或加热，与系丝带不符。"}], "explanations": {"穿": "搭配：“穿”用于衣服，丝带系在头发上，不说“穿”。", "系上": "系上指用丝带绑在头发上，符合语境。", "写": "语义：“写”与丝带无关，不能用在头发上。", "烧": "语义：“烧”是燃烧或加热，与系丝带不符。"}, "sentence_index": 6, "correct_answer": "系上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把被子系上，准备睡觉。", "explanation": "这里应用〈盖上〉。被子要用“盖”，“系”只用于绳子、带子。"}, {"text": "他系上地毯，准备吃饭。", "explanation": "这里应用〈铺上〉。地毯要用“铺”，“系”只用于绳子、带子。"}, {"text": "他系上了一把椅子，准备坐下。", "explanation": "这里应用〈摆上〉。椅子要用“摆”，“系”只用于绳子、带子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用绳子把行李系上了了。", "corrected_sentence": "他用绳子把行李系上了。", "error_description": "错误：“系上了了”。“了”只能用一次，应为“系上了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
