INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "系结；扣上或绑紧。", "primary_collocate": null, "pronunciation": "jì shang", "ipa": "tɕi˥˩ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "开车前请系上安全带。", "target_word": "系上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机要起飞了，请系上安全带。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天冷，他系上了围巾。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他系上领带，去参加面试。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈系上围裙开始做饭。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她系上腰带，显得很精神。", "target_word": "系上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把安全带系上，车要开了。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上车后他先系上安全带才发动车。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他系上头盔的带子，骑上了车。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐船时，大家都要系上救生衣。", "target_word": "系上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "系上了", "label": "体标"}, {"form": "系上过", "label": "体标"}], "register": "口语", "sense_fingerprint": "把安全带、领带、围裙等扣好或系紧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d9e4b5-858a-436f-a0ee-7c5a7eef59b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "系上", "is_correct": true, "explanation": "正确答案：系上 jì shang，扣上或绑紧。"}, {"text": "骑上", "is_correct": false, "explanation": "声母不同：qí 与 jì 声母不同，意思是骑到车、马等上面。"}, {"text": "地上", "is_correct": false, "explanation": "声母不同：dì 与 jì 声母不同，意思是地面之上。"}, {"text": "机上", "is_correct": false, "explanation": "声调不同：jī（第一声）与 jì（第四声）不同，意思是飞机上。"}], "explanations": {"系上": "正确答案：系上 jì shang，扣上或绑紧。", "骑上": "声母不同：qí 与 jì 声母不同，意思是骑到车、马等上面。", "地上": "声母不同：dì 与 jì 声母不同，意思是地面之上。", "机上": "声调不同：jī（第一声）与 jì（第四声）不同，意思是飞机上。"}, "sentence_index": null, "correct_answer": "系上"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于安全带，不能说“唱安全带”。"}, {"text": "系上", "is_correct": true, "explanation": "系上指扣好安全带，符合开车前的要求。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开，与开车前扣好安全带的意思相反。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，与安全带无关。"}], "explanations": {"唱": "搭配：“唱”不能用于安全带，不能说“唱安全带”。", "系上": "系上指扣好安全带，符合开车前的要求。", "拆": "语义：“拆”是拆开，与开车前扣好安全带的意思相反。", "煮": "语义：“煮”是加热食物，与安全带无关。"}, "sentence_index": 0, "correct_answer": "系上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他系上袜子，准备出门。", "explanation": "这里应用〈穿上〉。袜子要用“穿”，“系”只用于领带、带子等。"}, {"text": "他系上眼镜，去参加面试。", "explanation": "这里应用〈戴上〉。眼镜戴在脸上，不用“系”。"}, {"text": "他把一块蛋糕系上了盘子。", "explanation": "这里应用〈摆上〉。蛋糕要用“摆”，“系”只用于绳子、带子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能用于安全带，不能说“咬安全带”。"}, {"text": "系上", "is_correct": true, "explanation": "系上指扣好安全带，符合车要开了的语境。"}, {"text": "脱", "is_correct": false, "explanation": "语义：“脱”是脱下，与车要开了时扣好安全带的意思相反。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是用力扔下，不能表示扣好安全带。"}], "explanations": {"咬": "搭配：“咬”不能用于安全带，不能说“咬安全带”。", "系上": "系上指扣好安全带，符合车要开了的语境。", "脱": "语义：“脱”是脱下，与车要开了时扣好安全带的意思相反。", "摔": "语义：“摔”是用力扔下，不能表示扣好安全带。"}, "sentence_index": 6, "correct_answer": "系上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给宝宝系上被子，让他睡觉。", "explanation": "这里应用〈盖上〉。被子用“盖”，“系”只用于带子、绳子。"}, {"text": "他系上一碗汤，端给妈妈。", "explanation": "这里应用〈端〉。汤要用“端”，“系”只用于带子、绳子。"}, {"text": "他在客厅系上地毯。", "explanation": "这里应用〈铺上〉。地毯用“铺”，不用“系”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坐车时，他先把安全带系上了了。", "corrected_sentence": "坐车时，他先把安全带系上了。", "error_description": "错误：“系上了了”。“了”只能用一次，应为“系上了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "离开前，她把围巾系上了了。", "corrected_sentence": "离开前，她把围巾系上了。", "error_description": "错误：“系上了了”。“了”只能用一次，应为“系上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
