INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97425, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97425, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以前攒下来的钱或本事，用来过日子。", "primary_collocate": null, "pronunciation": "lǎo běn", "ipa": "lau˨˩˦ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他没有工作，只能吃老本过日子。", "target_word": "老本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷退休后，每月都花一点老本。", "target_word": "老本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的老本不多，买房子还不够。", "target_word": "老本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司这两年没赚钱，一直在吃老本。", "target_word": "老本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王靠着年轻时攒的老本，开了一家小店。", "target_word": "老本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想一辈子吃老本，得学点新本事。", "target_word": "老本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的老本是十年前学的手艺，现在不太够用了。", "target_word": "老本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅光靠老本，也能把这台机器修好。", "target_word": "老本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店生意不好，老本都快花完了。", "target_word": "老本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别总想着吃老本，要多学新东西。", "target_word": "老本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "老本：以前攒下来的钱或本事，用来过日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97425, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老本", "is_correct": true, "explanation": "老本：以前攒下来的钱或本事，用来过日子。没有工作时只能靠攒下的钱生活，正合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：没有工作就没有工资，与句首的“没有工作”矛盾。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“吃”一般不跟“收入”搭配，应说“靠收入”；且没有工作就没有收入，与句意矛盾。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“吃”不能带“工作”作宾语，“吃工作过日子”不成话。"}], "explanations": {"老本": "老本：以前攒下来的钱或本事，用来过日子。没有工作时只能靠攒下的钱生活，正合句意。", "工资": "语义：没有工作就没有工资，与句首的“没有工作”矛盾。", "收入": "搭配：“吃”一般不跟“收入”搭配，应说“靠收入”；且没有工作就没有收入，与句意矛盾。", "工作": "搭配：“吃”不能带“工作”作宾语，“吃工作过日子”不成话。"}, "sentence_index": 0, "correct_answer": "老本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月的老本都是五千块，正好够用。", "explanation": "这里应该用〈工资〉。老本指以前攒下来的钱，不是每个月发的工资，所以不能说“每个月的老本都是五千块”。"}, {"text": "他攒下了一座老本，够用一辈子。", "explanation": "这里应该用〈笔〉。“座”用于山、楼等大型固定物，把老本当成了大件东西来数；攒下的钱应说“一笔老本”。"}, {"text": "他每天都去商店买老本。", "explanation": "这里应该用〈东西〉。老本指以前攒下来的钱或本事，不是商店里卖的商品，不能说“买老本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老本", "is_correct": true, "explanation": "老本：以前攒下来的钱或本事。这里指十年前学来、现在用不上多少的手艺，正合句意。"}, {"text": "存款", "is_correct": false, "explanation": "搭配：“学”的对象是手艺、本事，不能说“学存款”，“存款是十年前学的”不成话。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是交给学校的钱，不是学来的东西，与“学的手艺”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是学来的，“房子是十年前学的手艺”与句意不符。"}], "explanations": {"老本": "老本：以前攒下来的钱或本事。这里指十年前学来、现在用不上多少的手艺，正合句意。", "存款": "搭配：“学”的对象是手艺、本事，不能说“学存款”，“存款是十年前学的”不成话。", "学费": "语义：学费是交给学校的钱，不是学来的东西，与“学的手艺”矛盾。", "房子": "语义：房子不是学来的，“房子是十年前学的手艺”与句意不符。"}, "sentence_index": 6, "correct_answer": "老本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块老本太重了，我一个人搬不动。", "explanation": "这里应该用〈石头〉。老本指攒下来的钱或本事，不是有重量、能搬动的东西。"}, {"text": "这次生意他赚了二十万老本。", "explanation": "这里应该用〈利润〉。老本是攒下来用来过日子的钱，做生意赚来的要说“利润”，不能说“赚老本”。"}, {"text": "我在这家公司当了十年老本。", "explanation": "这里应该用〈老板〉。老本指钱或本事，不指人；“当了十年”的是老板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这几年一直在动了老本。", "corrected_sentence": "他这几年一直在动老本。", "error_description": "体标错误：“一直在”表示动作持续，与“了”不能同用，应去掉“了”，说“一直在动老本”，不说“一直在动了老本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的老本们花得很快，三年就没了。", "corrected_sentence": "他的老本花得很快，三年就没了。", "error_description": "名词误用：“们”只用于人，不能加在“老本”后面，应去掉“们”，说“他的老本花得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97428, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97428, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97428, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听别人讲课或演讲。", "primary_collocate": null, "pronunciation": "tīng jiǎng", "ipa": "tʰiŋ˥ tɕiaŋ˨˩", "syllable_count": 2, "sentences": [{"text": "周末我去礼堂听讲。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听讲时一直在做笔记。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来听讲的人很多。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家要来学校讲课，大家都去听讲。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天去听讲了，收获很大。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们坐在台下认真听讲。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听讲的时候请关掉手机。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱听讲，总是看窗外。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了律师来讲法律，员工都来听讲。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演讲开始了，大家安静地听讲。", "target_word": "听讲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听讲了", "label": "体标"}, {"form": "听讲过", "label": "体标"}], "register": "中性", "sense_fingerprint": "听别人讲课或演讲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗澡", "is_correct": false, "explanation": "语义：礼堂不是洗澡的地方，句子不通。"}, {"text": "听讲", "is_correct": true, "explanation": "正确：去礼堂参加讲课或演讲，就是听讲。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：去礼堂睡觉与去礼堂听讲的情境不符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：礼堂里不能游泳，句子不通。"}], "explanations": {"洗澡": "语义：礼堂不是洗澡的地方，句子不通。", "听讲": "正确：去礼堂参加讲课或演讲，就是听讲。", "睡觉": "语义：去礼堂睡觉与去礼堂听讲的情境不符。", "游泳": "语义：礼堂里不能游泳，句子不通。"}, "sentence_index": 0, "correct_answer": "听讲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师站在讲台上听讲。", "explanation": "这里应该用〈讲课〉。听讲是听的一方，站在讲台上讲课的人应说“讲课”，不能说“听讲”。"}, {"text": "他站在台上听讲，台下的人都在鼓掌。", "explanation": "这里应该用〈演讲〉。台上发言的人是演讲，听讲是台下听众的动作。"}, {"text": "这台收音机每天都在听讲。", "explanation": "这里应该用〈播放〉。收音机是放出声音的，不是听讲的一方，不能说“听讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打电话", "is_correct": false, "explanation": "语义：句子要求关掉手机，而“打电话”需要用手机，句意矛盾。"}, {"text": "玩手机", "is_correct": false, "explanation": "语义：句子要求关掉手机，而“玩手机”正与之相反，句意矛盾。"}, {"text": "听讲", "is_correct": true, "explanation": "正确：“听讲的时候”指听讲的时段，与关掉手机的要求相符。"}, {"text": "喧哗", "is_correct": false, "explanation": "语域：“喧哗”偏书面，指吵闹，不用来表示一段听讲的时间。"}], "explanations": {"打电话": "语义：句子要求关掉手机，而“打电话”需要用手机，句意矛盾。", "玩手机": "语义：句子要求关掉手机，而“玩手机”正与之相反，句意矛盾。", "听讲": "正确：“听讲的时候”指听讲的时段，与关掉手机的要求相符。", "喧哗": "语域：“喧哗”偏书面，指吵闹，不用来表示一段听讲的时间。"}, "sentence_index": 6, "correct_answer": "听讲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱每天在厨房里听讲，很安静。", "explanation": "这里应该用〈制冷〉。冰箱是电器，不会听讲，应说“制冷”。"}, {"text": "这只小狗每天在院子里听讲，很开心。", "explanation": "这里应该用〈玩耍〉。听讲是听人讲课或演讲，小狗在院子里应说“玩耍”。"}, {"text": "这张沙发每天在客厅里听讲，很舒服。", "explanation": "这里应该用〈摆放〉。沙发是家具，不会听讲，应说“摆放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们教室里听讲。", "corrected_sentence": "学生们在教室里听讲。", "error_description": "错误：“学生们教室里听讲”，正确：“学生们在教室里听讲”。表示动作发生地点的词语要用“在”引出，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我上周去礼堂听讲着。", "corrected_sentence": "我上周去礼堂听讲了。", "error_description": "错误：“上周去礼堂听讲着”，正确：“上周去礼堂听讲了”。已经结束的过去动作要用“了”，“着”表示动作持续，不能用于“上周”这种已结束的时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97429, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
