INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97429, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己拿着手机给自己照相。", "primary_collocate": null, "pronunciation": "zì pāi", "ipa": "tsɿ˥˩ pʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "她举着手机自拍。", "target_word": "自拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢用手机自拍。", "target_word": "自拍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在公园里用手机自拍了一张照片。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机坏了，我今天不能自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿着手机，对着镜子自拍。", "target_word": "自拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在一起，用手机自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机前面的镜头最适合自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把手机放在桌上，开始自拍。", "target_word": "自拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬到山顶后，大家都拿出手机自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他伸长手臂，自拍了一张合影。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "自拍了", "label": "体标：了"}, {"form": "自拍着", "label": "体标：着"}, {"form": "自拍过", "label": "体标：过"}, {"form": "自拍杆", "label": "复合"}], "register": "口语", "sense_fingerprint": "自己拿着手机给自己拍照，强调用手机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abce999f-3fc1-404e-9d60-5f1209efb4c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97429, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自拍", "is_correct": true, "explanation": "正确答案：自拍 zì pāi，指自己拿着手机给自己拍照。"}, {"text": "自白", "is_correct": false, "explanation": "zì bái：声母 b（不送气）与 p（送气）不同，声调也不同（第二声与第一声），意思是坦白、供认。"}, {"text": "自排", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是汽车的自动变速。"}, {"text": "字牌", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，指麻将中的字牌。"}], "explanations": {"自拍": "正确答案：自拍 zì pāi，指自己拿着手机给自己拍照。", "自白": "zì bái：声母 b（不送气）与 p（送气）不同，声调也不同（第二声与第一声），意思是坦白、供认。", "自排": "pái（第二声）与 pāi（第一声）声调不同，意思是汽车的自动变速。", "字牌": "pái（第二声）与 pāi（第一声）声调不同，指麻将中的字牌。"}, "sentence_index": null, "correct_answer": "自拍"}, "level_3": {"options": [{"text": "自拍", "is_correct": true, "explanation": "正确：自拍指自己拿着手机给自己拍照，与“举着手机”相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、餐具等，不能说“举着手机洗”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，手机不能被吃，句子不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要送的东西和送给谁，单用“送”句子不完整。"}], "explanations": {"自拍": "正确：自拍指自己拿着手机给自己拍照，与“举着手机”相符。", "洗": "搭配：“洗”的对象是衣物、餐具等，不能说“举着手机洗”。", "吃": "搭配：“吃”的对象是食物，手机不能被吃，句子不通。", "送": "配价：“送”需要送的东西和送给谁，单用“送”句子不完整。"}, "sentence_index": 0, "correct_answer": "自拍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他请路人帮他自拍了一张照片。", "explanation": "这里应该用〈拍〉。自拍只能是自己给自己拍，请路人替他拍要说“拍了一张照片”。"}, {"text": "他用摄像机自拍下了演出的全过程。", "explanation": "这里应该用〈录〉。自拍的对象只能是拍的人自己，不能用来拍别人的演出。"}, {"text": "妈妈给我自拍了几张照片。", "explanation": "这里应该用〈拍〉。自拍只能是自己给自己拍，妈妈给我拍要说“给我拍了几张照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自拍", "is_correct": true, "explanation": "正确：自拍指自己给自己拍照，镜头“最适合”的就是这种用法。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食材，镜头不能被煮，句子不通。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”需要喂的对象，且对镜头说不通，单用“喂”句子不完整。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与手机镜头的用途无关。"}], "explanations": {"自拍": "正确：自拍指自己给自己拍照，镜头“最适合”的就是这种用法。", "煮": "搭配：“煮”的对象是食材，镜头不能被煮，句子不通。", "喂": "配价：“喂”需要喂的对象，且对镜头说不通，单用“喂”句子不完整。", "翻译": "语义：“翻译”指转换语言，与手机镜头的用途无关。"}, "sentence_index": 6, "correct_answer": "自拍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在海边用手机自拍了一段海浪的视频。", "explanation": "这里应该用〈拍摄〉。自拍的对象只能是拍的人自己，拍海浪的视频要说拍摄。"}, {"text": "他给孩子自拍了一张相。", "explanation": "这里应该用〈照〉。自拍只能是自己给自己拍，给孩子拍要说“照”。"}, {"text": "我用手机给爷爷自拍了一张照片。", "explanation": "这里应该用〈拍〉。自拍只能是自己给自己拍，给爷爷拍要说“拍了一张照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天用手机自拍了过两次。", "corrected_sentence": "我昨天用手机自拍了两次。", "error_description": "错误：「了」和「过」不能同时用在同一个动词后面。正确：我昨天用手机自拍了两次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在公园里很自拍。", "corrected_sentence": "她在公园里自拍。", "error_description": "错误：动词“自拍”前加了程度副词“很”，动作性动词不能受“很”修饰。正确：她在公园里自拍。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
