INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己给自己拍照。", "primary_collocate": null, "pronunciation": "zì pāi", "ipa": "tsɿ˥˩ pʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "她每天都自拍。", "target_word": "自拍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不喜欢自拍，更喜欢拍风景。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈学会了自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把相机放在三脚架上，开始自拍。", "target_word": "自拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多游客在景点门口自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她自拍过很多次，但都不满意。", "target_word": "自拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人帮忙拍照，他只好自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐喜欢自拍后再发给朋友。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说上课时不要自拍。", "target_word": "自拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着自拍，看起来很开心。", "target_word": "自拍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自拍了", "label": "体标：了"}, {"form": "自拍着", "label": "体标：着"}, {"form": "自拍过", "label": "体标：过"}, {"form": "自拍杆", "label": "复合"}], "register": "口语", "sense_fingerprint": "自己给自己拍照，不限于用手机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abce999f-3fc1-404e-9d60-5f1209efb4c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自拍", "is_correct": true, "explanation": "正确答案：自拍 zì pāi，指自己给自己拍照。"}, {"text": "自白", "is_correct": false, "explanation": "bái（第二声）与 pāi（第一声）声调不同，意思是坦白、供认。"}, {"text": "自排", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是汽车的自动变速。"}, {"text": "字牌", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，指麻将中的字牌。"}], "explanations": {"自拍": "正确答案：自拍 zì pāi，指自己给自己拍照。", "自白": "bái（第二声）与 pāi（第一声）声调不同，意思是坦白、供认。", "自排": "pái（第二声）与 pāi（第一声）声调不同，意思是汽车的自动变速。", "字牌": "pái（第二声）与 pāi（第一声）声调不同，指麻将中的字牌。"}, "sentence_index": null, "correct_answer": "自拍"}, "level_3": {"options": [{"text": "自拍", "is_correct": true, "explanation": "正确：自拍指自己给自己拍照，与“每天都”的习惯义相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”是一生中一次性的事，不能每天都做。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”只发生一次，不能说“每天都毕业”。"}, {"text": "嫁", "is_correct": false, "explanation": "配价：“嫁”需要说明嫁给谁，单用“嫁”句子不完整。"}], "explanations": {"自拍": "正确：自拍指自己给自己拍照，与“每天都”的习惯义相符。", "结婚": "语义：“结婚”是一生中一次性的事，不能每天都做。", "毕业": "语义：“毕业”只发生一次，不能说“每天都毕业”。", "嫁": "配价：“嫁”需要说明嫁给谁，单用“嫁”句子不完整。"}, "sentence_index": 0, "correct_answer": "自拍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他请路人帮他自拍了一张照片。", "explanation": "这里应该用〈拍〉。自拍只能是自己给自己拍，请路人替他拍要说“拍了一张照片”。"}, {"text": "他在公园里用手机自拍了一段猫的视频。", "explanation": "这里应该用〈拍摄〉。自拍的对象只能是拍的人自己，拍猫要说拍摄。"}, {"text": "老师站在前面，给全班同学自拍了一张照片。", "explanation": "这里应该用〈拍〉。老师站在前面给同学们拍，自己不在照片里，不是自拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自拍", "is_correct": true, "explanation": "正确：没人帮忙拍照时，只能自己给自己拍，与句意相符。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要送的东西和送给谁，单用“送”句子不完整。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”需要修的对象（如“修车”），“只好修”没有着落，与拍照的语境不合。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与“没人帮忙拍照”的语境无关。"}], "explanations": {"自拍": "正确：没人帮忙拍照时，只能自己给自己拍，与句意相符。", "送": "配价：“送”需要送的东西和送给谁，单用“送”句子不完整。", "修": "搭配：“修”需要修的对象（如“修车”），“只好修”没有着落，与拍照的语境不合。", "翻译": "语义：“翻译”指转换语言，与“没人帮忙拍照”的语境无关。"}, "sentence_index": 6, "correct_answer": "自拍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我自拍了几张照片。", "explanation": "这里应该用〈拍〉。自拍只能是自己给自己拍，妈妈给我拍要说“给我拍了几张照片”。"}, {"text": "爸爸给弟弟自拍了一张照片。", "explanation": "这里应该用〈拍〉。自拍只能是自己给自己拍，爸爸给弟弟拍要说“拍了一张照片”。"}, {"text": "他用摄像机自拍下了老师讲课的过程。", "explanation": "这里应该用〈录〉。自拍的对象只能是拍的人自己，不能用来录别人讲课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天自拍了过两次。", "corrected_sentence": "我昨天自拍了两次。", "error_description": "错误：「了」和「过」不能同时用在同一个动词后面。正确：我昨天自拍了两次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在海边很自拍。", "corrected_sentence": "他在海边自拍。", "error_description": "错误：动词“自拍”前加了程度副词“很”，动作性动词不能受“很”修饰。正确：他在海边自拍。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
