INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97433, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97433, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种电路里的东西，两个信号都来才通。", "primary_collocate": null, "pronunciation": "yǔ mén", "ipa": "y˨˩˦ mən˧˥", "syllable_count": 2, "sentences": [{"text": "与门要两个信号都来才通。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个与门坏了，灯不亮。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电路图里有一个与门和一个灯。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥给我讲了与门是什么。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个开关都打开，与门才通。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电路里加了一个与门。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图上的与门画错了。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天学了与门的用法。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与门只有一个信号时，灯不会亮。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把与门接在两个开关后面。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "与门电路", "label": "复合"}], "register": "专业", "sense_fingerprint": "电路里要两个信号都来才通的部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97433, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "与门", "is_correct": true, "explanation": "正确：与门是两个信号都来才通的电路部件，与句意一致。"}, {"text": "或门", "is_correct": false, "explanation": "语义：或门只需一个信号就能通，与“要两个信号都来才通”的条件矛盾。"}, {"text": "灯", "is_correct": false, "explanation": "搭配：“通”用于说电路或线路能否接通，灯不说“才通”。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电势差，不是能“通”或“不通”的部件，句子说的是部件。"}], "explanations": {"与门": "正确：与门是两个信号都来才通的电路部件，与句意一致。", "或门": "语义：或门只需一个信号就能通，与“要两个信号都来才通”的条件矛盾。", "灯": "搭配：“通”用于说电路或线路能否接通，灯不说“才通”。", "电压": "语义：电压是电势差，不是能“通”或“不通”的部件，句子说的是部件。"}, "sentence_index": 0, "correct_answer": "与门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "与门的输入只要有一个为一，输出就为一。", "explanation": "这里应该用〈或门〉。或门只要一个输入为一就输出为一；与门要两个输入都为一。"}, {"text": "与门的输出与输入正好相反。", "explanation": "这里应该用〈非门〉。非门的输出与输入正好相反；与门有两个输入，只有两个输入都为一时输出才为一。"}, {"text": "与门的输出只有两个输入都是一时才是零。", "explanation": "这里应该用〈与非门〉。与非门在两个输入都为一时输出为零；与门则是两个输入都为一时输出才为一。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与门", "is_correct": true, "explanation": "正确：图上画的是与门电路，与句意一致。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“画”不搭配“歌曲”，歌曲不能画在图上。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的，不能画在图上，句子说的是具体的图。"}, {"text": "作文", "is_correct": false, "explanation": "搭配：作文是写出来的文字，不是图，不能说“画错了”。"}], "explanations": {"与门": "正确：图上画的是与门电路，与句意一致。", "歌曲": "搭配：“画”不搭配“歌曲”，歌曲不能画在图上。", "道理": "语义：道理是抽象的，不能画在图上，句子说的是具体的图。", "作文": "搭配：作文是写出来的文字，不是图，不能说“画错了”。"}, "sentence_index": 6, "correct_answer": "与门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的与门是木头做的，很结实。", "explanation": "与门指逻辑电路中的门电路，不指房屋的门；这里说的是木门，与门的意思不符。"}, {"text": "只要有一个信号来，与门就通。", "explanation": "这里应该用〈或门〉。或门只要有一个信号来就通；与门要两个信号都来才通。"}, {"text": "与门把信号反过来，有信号来时就不通。", "explanation": "这里应该用〈非门〉。非门把信号反过来；与门是两个信号都来才通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的电路板上有一把与门。", "corrected_sentence": "我的电路板上有一个与门。", "error_description": "量词错误：与门是电路元件，应用量词“个”；“把”用于有柄的东西。应改为“一个与门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给我们演示了一座与门。", "corrected_sentence": "老师给我们演示了一个与门。", "error_description": "量词错误：与门是小型电路元件，应用量词“个”；“座”用于山、楼等大型物体。应改为“一个与门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
