INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "逻辑电路中实现逻辑乘（与）运算的门电路。", "primary_collocate": null, "pronunciation": "yǔ mén", "ipa": "y˨˩˦ mən˧˥", "syllable_count": 2, "sentences": [{"text": "与门有两个输入端，只有两个都是一，输出才是一。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个与门。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个与门是用两个开关做的。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与门的两个信号都来了，灯才会亮。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两个信号接到了与门上。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要有一个信号没来，与门就不通。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在讲与门和或门的不同。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块板子上有三个与门。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与门的输出要看两个输入端。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用面包板搭过一个简单的与门。", "target_word": "与门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "与门电路", "label": "复合"}], "register": "专业", "sense_fingerprint": "逻辑电路中的与运算门电路，输入都为一时输出才为一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "与门", "is_correct": true, "explanation": "正确：与门是逻辑乘门电路，两个输入都为一时输出才为一，与句中描述一致。"}, {"text": "或门", "is_correct": false, "explanation": "语义：或门只要一个输入为一就输出为一，与“只有两个都是一，输出才是一”的条件相反。"}, {"text": "信号", "is_correct": false, "explanation": "搭配：“输入端”是电路元件的结构，不说“信号有两个输入端”。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是用电器，没有逻辑运算的输入端，句子讲的是逻辑判断。"}], "explanations": {"与门": "正确：与门是逻辑乘门电路，两个输入都为一时输出才为一，与句中描述一致。", "或门": "语义：或门只要一个输入为一就输出为一，与“只有两个都是一，输出才是一”的条件相反。", "信号": "搭配：“输入端”是电路元件的结构，不说“信号有两个输入端”。", "灯": "语义：灯是用电器，没有逻辑运算的输入端，句子讲的是逻辑判断。"}, "sentence_index": 0, "correct_answer": "与门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "与门的输出，只有两个输入都是一时才是零。", "explanation": "这里应该用〈与非门〉。与非门在两个输入都为一时输出为零；与门要两个输入都为一时输出才为一，两者正好相反。"}, {"text": "与门只要有一个输入是一，输出就是一。", "explanation": "这里应该用〈或门〉。或门只要有一个输入为一就输出为一；与门则要求两个输入都为一。"}, {"text": "与门的两个输入不同时，输出才是一。", "explanation": "这里应该用〈异或门〉。异或门在两个输入不同时输出为一；与门要两个输入都为一。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与门", "is_correct": true, "explanation": "正确：句中要讲的是与门，与或门相对照。"}, {"text": "门道", "is_correct": false, "explanation": "语域：门道是口语里的窍门，讲电路的课堂上不用它指代门电路。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不是电路元件，和或门谈不上可比较的“不同”。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是逻辑门，讲它和或门的不同不成立。"}], "explanations": {"与门": "正确：句中要讲的是与门，与或门相对照。", "门道": "语域：门道是口语里的窍门，讲电路的课堂上不用它指代门电路。", "鸡蛋": "语义：鸡蛋不是电路元件，和或门谈不上可比较的“不同”。", "公园": "语义：公园不是逻辑门，讲它和或门的不同不成立。"}, "sentence_index": 6, "correct_answer": "与门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的与门是木头做的，每次都要用力推。", "explanation": "与门指逻辑电路中的门电路，不指房屋的门；这里说的是家里的门，与门的意思对不上。"}, {"text": "与门的两个输入都是零时，输出才是一。", "explanation": "这里应该用〈或非门〉。或非门在两个输入都为零时输出为一；与门要两个输入都为一时输出才为一。"}, {"text": "与门只有一个输入端，输出和输入正好相反。", "explanation": "这里应该用〈非门〉。非门只有一个输入，输出与输入相反；与门有两个输入，都为一时输出才为一。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块电路板上有两只与门。", "corrected_sentence": "这块电路板上有两个与门。", "error_description": "量词错误：与门是电路元件，量词应用“个”，“只”用于动物等。应改为“两个与门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们组装了一座与门。", "corrected_sentence": "我们组装了一个与门。", "error_description": "量词错误：与门是小型电路元件，应用量词“个”；“座”用于山、楼等大型物体。应改为“一个与门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
