INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97437, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船上职位最高、负责管理全船的人。", "primary_collocate": null, "pronunciation": "chuán zhǎng", "ipa": "ʈʂʰwan˧˥ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "船长是这条船上最大的人。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都听船长的话。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长站在前面，看着大海。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位船长已经开了二十年船。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长告诉我们，明天会有大风。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上出了问题，要先告诉船长。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥想长大以后当船长。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长的房间在船的最上面。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位很有经验的船长。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长和工人一起吃了晚饭。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副船长", "label": "复合"}, {"form": "船長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "船上职位最高、管事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。船长指船上管事的最高负责人。"}, {"text": "船厂", "is_correct": false, "explanation": "chǎng 与 zhǎng 声母不同（ch 与 zh），意思是造船的地方。"}, {"text": "船展", "is_correct": false, "explanation": "zhǎn 与 zhǎng 韵母不同（-an 与 -ang），意思是船只的展览。"}, {"text": "船中", "is_correct": false, "explanation": "zhōng 与 zhǎng 韵母和声调都不同（-ong 第一声 与 -ang 第三声），意思是船的中间。"}], "explanations": {"船长": "正确。船长指船上管事的最高负责人。", "船厂": "chǎng 与 zhǎng 声母不同（ch 与 zh），意思是造船的地方。", "船展": "zhǎn 与 zhǎng 韵母不同（-an 与 -ang），意思是船只的展览。", "船中": "zhōng 与 zhǎng 韵母和声调都不同（-ong 第一声 与 -ang 第三声），意思是船的中间。"}, "sentence_index": null, "correct_answer": "船长"}, "level_3": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。船长是船上负责全船的最高负责人，与“这条船上最大的人”相符。"}, {"text": "水手", "is_correct": false, "explanation": "语义：水手只是船上的普通船员，不是船上最大的人。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是搭船的人，不负责管船，与“最大的人”不符。"}, {"text": "船只", "is_correct": false, "explanation": "搭配：“船只”指船，不能指人，不能说“船只是最大的人”。"}], "explanations": {"船长": "正确。船长是船上负责全船的最高负责人，与“这条船上最大的人”相符。", "水手": "语义：水手只是船上的普通船员，不是船上最大的人。", "乘客": "语义：乘客是搭船的人，不负责管船，与“最大的人”不符。", "船只": "搭配：“船只”指船，不能指人，不能说“船只是最大的人”。"}, "sentence_index": 0, "correct_answer": "船长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位船长已经开了二十年飞机。", "explanation": "这里应该用〈机长〉。船长指船上的负责人，驾驶飞机的人要说机长。"}, {"text": "这位船长每天开车去上班。", "explanation": "这里应该用〈司机〉。船长只指船上的负责人，开车的人要说司机。"}, {"text": "这位船长已经放了二十年羊。", "explanation": "这里应该用〈牧民〉。船长只指船上的负责人，放羊的人要说牧民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97437, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。船长指船上管事的最高负责人。"}, {"text": "船闸", "is_correct": false, "explanation": "zhá 与 zhǎng 韵母与声调不同（-a 第二声 与 -ang 第三声），意思是河道上升降水位的闸门。"}, {"text": "船上", "is_correct": false, "explanation": "shàng 与 zhǎng 声母与声调不同（sh 与 zh；第四声 与 第三声），意思是船的上面或船的上边。"}, {"text": "传唱", "is_correct": false, "explanation": "chuán chàng 与 chuán zhǎng 第二个字声母和声调不同（ch 第四声 与 zh 第三声），意思是广泛地唱、流传。"}], "explanations": {"船长": "正确。船长指船上管事的最高负责人。", "船闸": "zhá 与 zhǎng 韵母与声调不同（-a 第二声 与 -ang 第三声），意思是河道上升降水位的闸门。", "船上": "shàng 与 zhǎng 声母与声调不同（sh 与 zh；第四声 与 第三声），意思是船的上面或船的上边。", "传唱": "chuán chàng 与 chuán zhǎng 第二个字声母和声调不同（ch 第四声 与 zh 第三声），意思是广泛地唱、流传。"}, "sentence_index": null, "correct_answer": "船长"}, "level_3": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。“想长大以后当”后面接职业，船长是指挥全船的职业。"}, {"text": "船票", "is_correct": false, "explanation": "搭配：“当”后面要接职业，“船票”是乘船的凭证，不能说“当船票”。"}, {"text": "船舱", "is_correct": false, "explanation": "语义：“船舱”是船上的房间，不是职业，句子不通。"}, {"text": "船坞", "is_correct": false, "explanation": "语义：“船坞”是修船、停船的场所，不能作为长大后的职业。"}], "explanations": {"船长": "正确。“想长大以后当”后面接职业，船长是指挥全船的职业。", "船票": "搭配：“当”后面要接职业，“船票”是乘船的凭证，不能说“当船票”。", "船舱": "语义：“船舱”是船上的房间，不是职业，句子不通。", "船坞": "语义：“船坞”是修船、停船的场所，不能作为长大后的职业。"}, "sentence_index": 6, "correct_answer": "船长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位船长管理着一家大工厂。", "explanation": "这里应该用〈厂长〉。船长指船上的负责人，管理工厂的人要说厂长。"}, {"text": "这位船长每天给病人看病。", "explanation": "这里应该用〈医生〉。船长指船上的负责人，给病人看病的人要说医生。"}, {"text": "这位船长在比赛中带领全队拿到了冠军。", "explanation": "这里应该用〈队长〉。船长指船上指挥全船的人，带领球队的人要说队长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只船长今天很高兴。", "corrected_sentence": "这位船长今天很高兴。", "error_description": "量词错误：“船长”指人，量词应用“位”，不能用“只”（“只”多用于动物或成对物件中的一个）。应说“这位船长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我叔叔是一位很有经验船长。", "corrected_sentence": "我叔叔是一位很有经验的船长。", "error_description": "的字缺失：“很有经验”是修饰“船长”的定语，两字以上的修饰语后面要加“的”，应说“很有经验的船长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
