INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船上负责指挥全船的人。", "primary_collocate": null, "pronunciation": "chuán zhǎng", "ipa": "ʈʂʰwan˧˥ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "船长说开船，大家就开始工作。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨了，船长让船回到了港口。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长用无线电叫来了别的船。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了事，船长要先想到客人的安全。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位船长指挥船慢慢靠近了码头。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长走进驾驶室，看了看地图。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的船长总是戴着一顶白帽子。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长对船员们说：“大家别害怕。”", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长最后一个离开了那条船。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘大船的船长是一位女士。", "target_word": "船长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副船长", "label": "复合"}, {"form": "船長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "负责指挥全船行动的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。船长指船上负责指挥全船行动的人。"}, {"text": "船厂", "is_correct": false, "explanation": "chǎng 与 zhǎng 声母不同（ch 与 zh），意思是造船的地方。"}, {"text": "船闸", "is_correct": false, "explanation": "zhá 与 zhǎng 韵母与声调不同（-a 第二声 与 -ang 第三声），意思是河道上升降水位的闸门。"}, {"text": "船中", "is_correct": false, "explanation": "zhōng 与 zhǎng 韵母和声调都不同（-ong 第一声 与 -ang 第三声），意思是船的中间。"}], "explanations": {"船长": "正确。船长指船上负责指挥全船行动的人。", "船厂": "chǎng 与 zhǎng 声母不同（ch 与 zh），意思是造船的地方。", "船闸": "zhá 与 zhǎng 韵母与声调不同（-a 第二声 与 -ang 第三声），意思是河道上升降水位的闸门。", "船中": "zhōng 与 zhǎng 韵母和声调都不同（-ong 第一声 与 -ang 第三声），意思是船的中间。"}, "sentence_index": null, "correct_answer": "船长"}, "level_3": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。船长负责指挥全船，说开船、大家开始工作符合这一身份。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不负责开船，也不指挥全船。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是乘船观光的人，不负责指挥开船。"}, {"text": "码头", "is_correct": false, "explanation": "配价：“说”要求人作主语，“码头”是地方，不能说话。"}], "explanations": {"船长": "正确。船长负责指挥全船，说开船、大家开始工作符合这一身份。", "厨师": "语义：厨师负责做饭，不负责开船，也不指挥全船。", "游客": "语义：游客是乘船观光的人，不负责指挥开船。", "码头": "配价：“说”要求人作主语，“码头”是地方，不能说话。"}, "sentence_index": 0, "correct_answer": "船长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位船长驾驶飞机安全降落在跑道上。", "explanation": "这里应该用〈机长〉。船长指船上指挥全船的人，驾驶飞机的人要说机长。"}, {"text": "这位船长指挥着全军的行动。", "explanation": "这里应该用〈司令〉。船长只指船上的指挥者，指挥全军的人要说司令。"}, {"text": "这位船长率领全团出征。", "explanation": "这里应该用〈团长〉。船长只指船上的指挥者，率领全团的人要说团长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97438, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。船长指船上负责指挥全船行动的人。"}, {"text": "船展", "is_correct": false, "explanation": "zhǎn 与 zhǎng 韵母不同（-an 与 -ang），意思是船只的展览。"}, {"text": "船上", "is_correct": false, "explanation": "shàng 与 zhǎng 声母与声调不同（sh 与 zh；第四声 与 第三声），意思是船的上面或船的上边。"}, {"text": "传唱", "is_correct": false, "explanation": "chuán chàng 与 chuán zhǎng 第二个字声母和声调不同（ch 第四声 与 zh 第三声），意思是广泛地唱、流传。"}], "explanations": {"船长": "正确。船长指船上负责指挥全船行动的人。", "船展": "zhǎn 与 zhǎng 韵母不同（-an 与 -ang），意思是船只的展览。", "船上": "shàng 与 zhǎng 声母与声调不同（sh 与 zh；第四声 与 第三声），意思是船的上面或船的上边。", "传唱": "chuán chàng 与 chuán zhǎng 第二个字声母和声调不同（ch 第四声 与 zh 第三声），意思是广泛地唱、流传。"}, "sentence_index": null, "correct_answer": "船长"}, "level_3": {"options": [{"text": "船长", "is_correct": true, "explanation": "正确。电影里常见的船长形象是戴着帽子的人物，与句意相符。"}, {"text": "灯塔", "is_correct": false, "explanation": "搭配：“戴帽子”的主语必须是人，灯塔是建筑，不能戴帽子。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不能戴帽子，与“总是戴着一顶白帽子”搭配不当。"}, {"text": "船票", "is_correct": false, "explanation": "语义：“船票”是乘船的凭证，不是人物，句子不通。"}], "explanations": {"船长": "正确。电影里常见的船长形象是戴着帽子的人物，与句意相符。", "灯塔": "搭配：“戴帽子”的主语必须是人，灯塔是建筑，不能戴帽子。", "桌子": "搭配：“桌子”不能戴帽子，与“总是戴着一顶白帽子”搭配不当。", "船票": "语义：“船票”是乘船的凭证，不是人物，句子不通。"}, "sentence_index": 6, "correct_answer": "船长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位船长负责管理火车站的工作。", "explanation": "这里应该用〈站长〉。船长指船上指挥全船的人，管理车站的人要说站长。"}, {"text": "这位船长负责管理全村的事务。", "explanation": "这里应该用〈村长〉。船长只指船上指挥全船的人，管理村子的人要说村长。"}, {"text": "这位船长在篮球赛里带领全队夺得了冠军。", "explanation": "这里应该用〈队长〉。船长指船上指挥全船的人，带领球队的人要说队长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只船长站在驾驶室里，指挥着全船。", "corrected_sentence": "这名船长站在驾驶室里，指挥着全船。", "error_description": "量词错误：“船长”指人，量词应用“名”或“位”，不能用“只”。应说“这名船长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只很有经验的船长指挥着全船。", "corrected_sentence": "那位很有经验的船长指挥着全船。", "error_description": "量词错误：“船长”指人，量词应用“位”或“名”，不能用“只”（多用于动物）。应说“那位很有经验的船长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97441, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合理", "is_correct": true, "explanation": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。"}, {"text": "简单", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“简单”只表示不复杂，与合理与否无关。"}, {"text": "明白", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“明白”指清楚易懂，不表示合理与否。"}, {"text": "普通", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“普通”指平常、不特别，不是“荒谬”的对立面。"}], "correct_answer": "合理", "explanations": {"合理": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。", "简单": "与“荒谬”没有反义关系：“简单”只表示不复杂，与合理与否无关。", "明白": "与“荒谬”没有反义关系：“明白”指清楚易懂，不表示合理与否。", "普通": "与“荒谬”没有反义关系：“普通”指平常、不特别，不是“荒谬”的对立面。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97441, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合理", "is_correct": true, "explanation": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。"}, {"text": "清楚", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“清楚”指明白、不模糊，与合理与否无关。"}, {"text": "平凡", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“平凡”指不出众，不表示有没有道理。"}, {"text": "严肃", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“严肃”指态度认真庄重，与合理与否无关。"}], "correct_answer": "合理", "explanations": {"合理": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。", "清楚": "与“荒谬”没有反义关系：“清楚”指明白、不模糊，与合理与否无关。", "平凡": "与“荒谬”没有反义关系：“平凡”指不出众，不表示有没有道理。", "严肃": "与“荒谬”没有反义关系：“严肃”指态度认真庄重，与合理与否无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97441, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说的话太奇怪了，一点道理都没有。", "primary_collocate": null, "pronunciation": "huāng miù", "ipa": "xuɑŋ˥ mi̯ou˥˩", "syllable_count": 2, "sentences": [{"text": "他说的话太荒谬了，没有一点道理。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法听起来很荒谬。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说月亮是用纸做的，真荒谬。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都觉得他的说法荒谬极了。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种荒谬的话，谁也不会相信。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说吃糖能让人长高，这种说法很荒谬。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么能说出这么荒谬的话？", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的解释荒谬得让人想笑。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一个荒谬的说法，说人不用睡觉。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他的话荒谬，所以没有回答。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "荒谬绝伦", "label": "复合"}, {"form": "荒谬性", "label": "复合"}], "register": "书面", "sense_fingerprint": "说法奇怪毫无道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荒谬", "is_correct": true, "explanation": "荒谬：说的话毫无道理，与后半句“没有一点道理”相呼应。"}, {"text": "合理", "is_correct": false, "explanation": "语义：“合理”指有道理，与后半句“没有一点道理”正相反，句意不通。"}, {"text": "茂盛", "is_correct": false, "explanation": "搭配：“茂盛”形容草木生长得多，不能用来形容说的话。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，不能用来形容说的话。"}], "explanations": {"荒谬": "荒谬：说的话毫无道理，与后半句“没有一点道理”相呼应。", "合理": "语义：“合理”指有道理，与后半句“没有一点道理”正相反，句意不通。", "茂盛": "搭配：“茂盛”形容草木生长得多，不能用来形容说的话。", "高大": "体貌：“高大”形容人或物的体形，不能用来形容说的话。"}, "sentence_index": 0, "correct_answer": "荒谬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很荒谬，又硬又重。", "explanation": "这里应该用〈沉〉。荒谬形容说法、做法极不合理，不用来形容物体的轻重，形容石头重应说“沉”。"}, {"text": "他长得很荒谬，大家都在看他。", "explanation": "这里应该用〈古怪〉。荒谬不用来形容人的外貌，形容长相奇特应说“古怪”。"}, {"text": "这个房间很荒谬，东西到处都是。", "explanation": "这里应该用〈乱〉。荒谬不用来形容房间的整洁程度，形容房间杂乱应说“乱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荒谬", "is_correct": true, "explanation": "荒谬：说的话毫无道理，与“你怎么能说出这么……的话”的反问语气相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不能用来形容话。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来形容话。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或物的体形，不能用来形容话。"}], "explanations": {"荒谬": "荒谬：说的话毫无道理，与“你怎么能说出这么……的话”的反问语气相符。", "冷清": "搭配：“冷清”形容场所或气氛，不能用来形容话。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来形容话。", "瘦小": "体貌：“瘦小”形容人或物的体形，不能用来形容话。"}, "sentence_index": 6, "correct_answer": "荒谬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡很荒谬，喝一口就皱眉。", "explanation": "这里应该用〈苦〉。荒谬只用于说法、做法，不用来形容咖啡的味道，形容味道苦应说“苦”。"}, {"text": "我今天的心情很荒谬，不想说话。", "explanation": "这里应该用〈糟糕〉。荒谬不用来形容心情，心情不好应说“糟糕”。"}, {"text": "这列火车很荒谬，一个小时就到了。", "explanation": "这里应该用〈快〉。荒谬不用来形容速度，形容速度快应说“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很荒谬想法，没有人相信。", "corrected_sentence": "这是一个很荒谬的想法，没有人相信。", "error_description": "错误：“很荒谬想法”。“很荒谬”修饰名词“想法”时，中间要加“的”，应说“很荒谬的想法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛的规则荒谬的让人生气。", "corrected_sentence": "这次比赛的规则荒谬得让人生气。", "error_description": "“荒谬”后面引出结果补语时要用“得”，不能写成“的”，应说“荒谬得让人生气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97442, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合理", "is_correct": true, "explanation": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。"}, {"text": "热闹", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“热闹”形容场面喧闹，与合理与否无关。"}, {"text": "严肃", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“严肃”指态度认真庄重，与合理与否无关。"}, {"text": "平凡", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“平凡”指不出众，不表示有没有道理。"}], "correct_answer": "合理", "explanations": {"合理": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。", "热闹": "与“荒谬”没有反义关系：“热闹”形容场面喧闹，与合理与否无关。", "严肃": "与“荒谬”没有反义关系：“严肃”指态度认真庄重，与合理与否无关。", "平凡": "与“荒谬”没有反义关系：“平凡”指不出众，不表示有没有道理。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97442, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合理", "is_correct": true, "explanation": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。"}, {"text": "简单", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“简单”只表示不复杂，与合理与否无关。"}, {"text": "明白", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“明白”指清楚易懂，不表示合理与否。"}, {"text": "普通", "is_correct": false, "explanation": "与“荒谬”没有反义关系：“普通”指平常、不特别，不是“荒谬”的对立面。"}], "correct_answer": "合理", "explanations": {"合理": "与“荒谬”构成反义：“荒谬”指极不合理，“合理”指有道理、符合道理。", "简单": "与“荒谬”没有反义关系：“简单”只表示不复杂，与合理与否无关。", "明白": "与“荒谬”没有反义关系：“明白”指清楚易懂，不表示合理与否。", "普通": "与“荒谬”没有反义关系：“普通”指平常、不特别，不是“荒谬”的对立面。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97442, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "极不合理，十分可笑。", "primary_collocate": null, "pronunciation": "huāng miù", "ipa": "xuɑŋ˥ mi̯ou˥˩", "syllable_count": 2, "sentences": [{"text": "这个规定太荒谬了，谁听了都想笑。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了一点小事就关门一个月，真荒谬。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事荒谬得让人哭笑不得。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为荒谬可笑，大家都笑了。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个电影的故事很荒谬，可是很好笑。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让小孩每天做十个小时作业，太荒谬了。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情的结果荒谬极了，没有人想到。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的比赛规则实在荒谬。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了一件荒谬的事，把鞋放进冰箱里。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家觉得这种做法既荒谬又可笑。", "target_word": "荒谬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "荒谬绝伦", "label": "复合"}, {"form": "荒谬性", "label": "复合"}], "register": "书面", "sense_fingerprint": "做法或事情极不合理而可笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荒谬", "is_correct": true, "explanation": "荒谬：极不合理而可笑，与“谁听了都想笑”相符。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”指感觉或态度和善，与“谁听了都想笑”的可笑之意不符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容规定。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或物的体形，不能用来形容规定。"}], "explanations": {"荒谬": "荒谬：极不合理而可笑，与“谁听了都想笑”相符。", "温暖": "语义：“温暖”指感觉或态度和善，与“谁听了都想笑”的可笑之意不符。", "清脆": "搭配：“清脆”形容声音，不能用来形容规定。", "瘦小": "体貌：“瘦小”形容人或物的体形，不能用来形容规定。"}, "sentence_index": 0, "correct_answer": "荒谬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很荒谬，阳光明媚。", "explanation": "这里应该用〈晴朗〉。荒谬形容做法、说法等极不合理而可笑的事，不用来形容天气，天气好应说“晴朗”。"}, {"text": "这辆汽车很荒谬，一下子就到了。", "explanation": "这里应该用〈快〉。荒谬不用来形容速度，形容车速快应说“快”。"}, {"text": "这块蛋糕很荒谬，入口很软。", "explanation": "这里应该用〈松软〉。荒谬形容做法、说法等极不合理而可笑的事，不用来形容蛋糕的口感，形容蛋糕入口柔软应说“松软”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荒谬", "is_correct": true, "explanation": "荒谬：结果极不合理而可笑，与“没有人想到”的意外之感相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不能用来形容结果。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来形容结果。"}, {"text": "细长", "is_correct": false, "explanation": "体貌：“细长”形容人或物的形状，不能用来形容结果。"}], "explanations": {"荒谬": "荒谬：结果极不合理而可笑，与“没有人想到”的意外之感相符。", "冷清": "搭配：“冷清”形容场所或气氛，不能用来形容结果。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来形容结果。", "细长": "体貌：“细长”形容人或物的形状，不能用来形容结果。"}, "sentence_index": 6, "correct_answer": "荒谬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫长得很荒谬，大家都在看它。", "explanation": "这里应该用〈古怪〉。荒谬不用来形容动物的外貌，形容样子奇特应说“古怪”。"}, {"text": "这杯水很荒谬，喝起来很舒服。", "explanation": "这里应该用〈凉〉。荒谬不用来形容水的温度，形容水凉爽好喝应说“凉”。"}, {"text": "教室里很荒谬，同学们都在认真听课。", "explanation": "这里应该用〈安静〉。荒谬不用来形容环境的静与闹，形容教室安静应说“安静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的做法荒谬的让人吃惊。", "corrected_sentence": "他的做法荒谬得让人吃惊。", "error_description": "“荒谬”后面引出结果补语时要用“得”，不能用“的”，应说“荒谬得让人吃惊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个主意太荒谬了了，没有人同意。", "corrected_sentence": "这个主意太荒谬了，没有人同意。", "error_description": "“荒谬”后只用一个“了”，应说“太荒谬了”，多出的一个“了”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
