INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出门旅行时带的箱子和包。", "primary_collocate": null, "pronunciation": "xíng li", "ipa": "ɕiŋ˧˥ li", "syllable_count": 2, "sentences": [{"text": "这次去北京，我只带了一件行李。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把行李放在门口。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人提着两件行李慢慢上了楼。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门旅行，行李越轻越好。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，行李可以放在哪儿？", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明帮妈妈拿行李，一点也不累。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们下了车，先去取行李。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的行李里有两件毛衣和一双鞋。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机时，大件行李要先托运。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天要走，她今晚就收拾行李。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件行李", "label": "量词"}, {"form": "行李箱", "label": "复合"}, {"form": "行李架", "label": "复合"}], "register": "中性", "sense_fingerprint": "行李：出门旅行时带的箱子和包", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事故", "is_correct": false, "explanation": "语义：事故不是可以随身带去北京的东西，句子说不通。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗行为，不能被带去北京。"}, {"text": "行李", "is_correct": true, "explanation": "正确：行李指出门旅行时带的箱包，“带了一件”正好指随身携带的物品。"}, {"text": "事件", "is_correct": false, "explanation": "搭配：“带”不能和“事件”搭配，事件无法随身携带。"}], "explanations": {"事故": "语义：事故不是可以随身带去北京的东西，句子说不通。", "手术": "语义：手术是医疗行为，不能被带去北京。", "行李": "正确：行李指出门旅行时带的箱包，“带了一件”正好指随身携带的物品。", "事件": "搭配：“带”不能和“事件”搭配，事件无法随身携带。"}, "sentence_index": 0, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把行李存进银行，每个月都有利息。", "explanation": "这里应该用〈存款〉。存进银行、有利息的是钱，要说〈存款〉；“行李”指出门旅行时带的箱子和包。"}, {"text": "他每天下班后背着行李去健身房。", "explanation": "这里应该用〈运动包〉。去健身房背装备要用〈运动包〉，“行李”指出门旅行时带的箱子和包，不用于健身。"}, {"text": "他每次买菜都提着一件行李，装了很多蔬菜。", "explanation": "这里应该用〈购物袋〉。买菜装蔬菜要用〈购物袋〉，“行李”指出门旅行时带的箱子和包，不用来买菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方向", "is_correct": false, "explanation": "语义：方向不是可以拿走的东西，“取”的语境不合。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是一项活动，不能去“取”。"}, {"text": "行李", "is_correct": true, "explanation": "正确：下车后去取的是旅行时携带的箱包，“取”正好搭配行李。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“取”不能和“天气”搭配，天气无法被拿走。"}], "explanations": {"方向": "语义：方向不是可以拿走的东西，“取”的语境不合。", "演唱会": "语义：演唱会是一项活动，不能去“取”。", "行李": "正确：下车后去取的是旅行时携带的箱包，“取”正好搭配行李。", "天气": "搭配：“取”不能和“天气”搭配，天气无法被拿走。"}, "sentence_index": 6, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天的行李安排得很满，要去三个景点。", "explanation": "这里应该用〈行程〉。“安排得很满”“去三个景点”说的是出行计划，要用〈行程〉；“行李”指出门带的箱子和包。"}, {"text": "我们的行李定在下午三点，不能再改了。", "explanation": "这里应该用〈日程〉。时间定下来、不能再改，要说〈日程〉；“行李”指出门带的箱子和包，不能用来定时间。"}, {"text": "快递送来一件行李，是我在网上买的书。", "explanation": "这里应该用〈包裹〉。网购的东西寄来要说〈包裹〉，“行李”指出门旅行时带的箱子和包，不用于快递。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带了两张行李来北京找朋友。", "corrected_sentence": "他带了两件行李来北京找朋友。", "error_description": "量词错误：“行李”应该用量词“件”，说“两件行李”。“张”用于纸张、桌子等平面的东西，不能用来数行李。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本行李已经装上车了。", "corrected_sentence": "这件行李已经装上车了。", "error_description": "量词错误：“行李”应该用量词“件”，说“这件行李”。“本”用于书籍、本子等，不能用来数行李。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97453, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97453, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97453, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "比赛时，说谁对谁错、谁赢的人。", "primary_collocate": null, "pronunciation": "cái pàn", "ipa": "tsʰai˧˥ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "两个孩子下棋，爷爷当裁判。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁跑得快，请裁判来看。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们玩拔河，小李当裁判。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判说红队赢了，大家都鼓掌。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛没有裁判，大家就会吵架。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判认真地看着每个人的动作。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不同意裁判的决定，但是要听他的。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的跳绳比赛请了一位老师当裁判。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这个裁判很公平。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判走过来，告诉他们谁输了。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "裁判员", "label": "复合"}], "register": "中性", "sense_fingerprint": "比赛中说谁对谁错、谁赢的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁判", "is_correct": true, "explanation": "正确：“裁判”是游戏中说谁赢、谁输的人，爷爷当裁判符合语境。"}, {"text": "棋子", "is_correct": false, "explanation": "语义：棋子是下棋用的棋具，不能被“当”去做裁判。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是摆棋子的器具，不是裁判，与“当”不合。"}, {"text": "棋谱", "is_correct": false, "explanation": "搭配：“当”后接人或职务，“棋谱”是书籍，不能说“当棋谱”。"}], "explanations": {"裁判": "正确：“裁判”是游戏中说谁赢、谁输的人，爷爷当裁判符合语境。", "棋子": "语义：棋子是下棋用的棋具，不能被“当”去做裁判。", "棋盘": "语义：棋盘是摆棋子的器具，不是裁判，与“当”不合。", "棋谱": "搭配：“当”后接人或职务，“棋谱”是书籍，不能说“当棋谱”。"}, "sentence_index": 0, "correct_answer": "裁判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁判在比赛中认真下棋。", "explanation": "这里应该用〈选手〉。裁判只负责判定输赢，不下棋。"}, {"text": "裁判坐在看台上为红队加油。", "explanation": "这里应该用〈观众〉。观众在看台上为一队加油；裁判在场上判定谁赢，不为任何一队加油。"}, {"text": "裁判在比赛结束后替球队领奖。", "explanation": "这里应该用〈运动员〉。领奖的是获胜的选手，裁判只负责判定，不领奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁判", "is_correct": true, "explanation": "正确：“裁判”是说谁对谁错的人，“听他的”指裁判的决定。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“决定”需要人作主语，“天气”不能下决定。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不做决定，与“听他的”不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不做决定，与“听他的”不合。"}], "explanations": {"裁判": "正确：“裁判”是说谁对谁错的人，“听他的”指裁判的决定。", "天气": "搭配：“决定”需要人作主语，“天气”不能下决定。", "月亮": "语义：月亮不做决定，与“听他的”不合。", "石头": "语义：石头不做决定，与“听他的”不合。"}, "sentence_index": 6, "correct_answer": "裁判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "裁判把球踢进了球门。", "explanation": "这里应该用〈球员〉。“踢进球门”是球员的动作，裁判不参加比赛。"}, {"text": "裁判决定了本队的战术。", "explanation": "这里应该用〈队长〉。队长代表本队决定战术，裁判不属于任何一队。"}, {"text": "裁判做了一桌饭。", "explanation": "这里应该用〈厨师〉。“做饭”是厨师的工作，裁判只负责判定比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班请了一只裁判。", "corrected_sentence": "我们班请了一位裁判。", "error_description": "错误：量词用错。“裁判”指人，量词应用“位”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们以前请过一只裁判。", "corrected_sentence": "他们以前请过一位裁判。", "error_description": "错误：量词用错。“裁判”指人，量词应用“位”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97454, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97454, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "体育比赛中执行规则、评判胜负的人。", "primary_collocate": null, "pronunciation": "cái pàn", "ipa": "tsʰai˧˥ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "足球比赛开始前，裁判检查了球员的鞋。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判吹哨，比赛结束了。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场篮球赛的裁判很公平。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当过游泳比赛的裁判。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判举起红牌，把那个球员罚下了场。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷对裁判的决定很不满意。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，裁判必须按规则做决定。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判看错了，球其实没有出界。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当一名足球裁判。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员都要听裁判的话。", "target_word": "裁判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "裁判员", "label": "复合"}], "register": "中性", "sense_fingerprint": "体育比赛中执行规则的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁判", "is_correct": true, "explanation": "正确：“裁判”指比赛中执行规则的人，赛前检查装备是其职责。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众不执行规则，无权检查球员的装备。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“检查”需要人作主语，“比赛”是事件，不能检查球员的鞋。"}, {"text": "球场", "is_correct": false, "explanation": "搭配：“检查”需要人作主语，“球场”是场地，不能检查球员的鞋。"}], "explanations": {"裁判": "正确：“裁判”指比赛中执行规则的人，赛前检查装备是其职责。", "观众": "语义：观众不执行规则，无权检查球员的装备。", "比赛": "搭配：“检查”需要人作主语，“比赛”是事件，不能检查球员的鞋。", "球场": "搭配：“检查”需要人作主语，“球场”是场地，不能检查球员的鞋。"}, "sentence_index": 0, "correct_answer": "裁判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁判在看台上大声加油。", "explanation": "这里应该用〈球迷〉。裁判负责执行规则、判定胜负，不会在看台上加油。"}, {"text": "裁判按规则参加比赛。", "explanation": "这里应该用〈运动员〉。裁判不参加比赛，不能“参加比赛”。"}, {"text": "比赛中，裁判给受伤的球员治疗。", "explanation": "这里应该用〈队医〉。裁判负责执行规则、判定胜负，不负责治疗伤员；给受伤球员治疗的是队医。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁判", "is_correct": true, "explanation": "正确：“裁判”负责比赛中按规则做决定，符合句意。"}, {"text": "比分", "is_correct": false, "explanation": "搭配：“做决定”需要人作主语，“比分”是结果，不能按规则做决定。"}, {"text": "啦啦队", "is_correct": false, "explanation": "语义：啦啦队负责助威，不负责按规则做决定。"}, {"text": "解说员", "is_correct": false, "explanation": "语义：解说员负责讲解比赛，不负责按规则判定。"}], "explanations": {"裁判": "正确：“裁判”负责比赛中按规则做决定，符合句意。", "比分": "搭配：“做决定”需要人作主语，“比分”是结果，不能按规则做决定。", "啦啦队": "语义：啦啦队负责助威，不负责按规则做决定。", "解说员": "语义：解说员负责讲解比赛，不负责按规则判定。"}, "sentence_index": 6, "correct_answer": "裁判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "裁判要带领队员训练。", "explanation": "这里应该用〈教练〉。裁判不带队训练，职责是执行规则、判定胜负。"}, {"text": "裁判决定了本队的战术。", "explanation": "这里应该用〈队长〉。裁判不属于任何一队，不能决定本队的战术。"}, {"text": "裁判在场上踢球。", "explanation": "这里应该用〈球员〉。裁判不参加比赛，不踢球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们请了两裁判。", "corrected_sentence": "他们请了两位裁判。", "error_description": "错误：数词后漏掉量词。“裁判”指人，数词“两”后要加量词，应说“两位裁判”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐当过一只裁判。", "corrected_sentence": "我姐姐当过一位裁判。", "error_description": "错误：量词用错。“裁判”指人，量词应用“位”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
