INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97457, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97457, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看好看的花或景色，觉得很高兴。", "primary_collocate": null, "pronunciation": "guān shǎng", "ipa": "kwan˥ ʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈观赏着满院的花，笑得很开心。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山上观赏秋景，心里特别高兴。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷最爱观赏菊花，一看就是一下午。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观赏了一个小时的荷花，大家都很愉快。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边观赏江边的夜景，一边高兴地唱歌。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们观赏过雪景，都开心得又跳又叫。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花开了，邻居们都来院子里观赏。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢在阳台上观赏自己种的花。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公园观赏美丽的春色，我的心情好极了。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在湖边观赏着风景，脸上带着笑。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "观赏了", "label": "体标"}, {"form": "观赏着", "label": "体标"}, {"form": "观赏过", "label": "体标"}, {"form": "观赏鱼", "label": "复合"}, {"form": "观赏性", "label": "复合"}], "register": "书面", "sense_fingerprint": "看美丽的花或景色并感到愉快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与后面的“笑得很开心”矛盾。"}, {"text": "观赏", "is_correct": true, "explanation": "观赏：看并欣赏美好的花，与“笑得很开心”的愉快情绪相合。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或言行，不能说批评满院的花。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是践踏，与观花时的愉快心情相反。"}], "explanations": {"讨厌": "语义：“讨厌”表示反感，与后面的“笑得很开心”矛盾。", "观赏": "观赏：看并欣赏美好的花，与“笑得很开心”的愉快情绪相合。", "批评": "搭配：“批评”的对象是人或言行，不能说批评满院的花。", "踩": "语义：“踩”是践踏，与观花时的愉快心情相反。"}, "sentence_index": 0, "correct_answer": "观赏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈整天观赏生病的孩子。", "explanation": "这里应该用〈照顾〉。观赏针对美好的景物，不用于人；料理生病孩子的日常起居要用照顾。"}, {"text": "工人观赏了厂里的管道。", "explanation": "这里应该用〈检查〉。观赏是欣赏美景，检查管道是为了看是否有问题，要用检查。"}, {"text": "我观赏这篇文章的结构。", "explanation": "这里应该用〈欣赏〉。观赏用于可看见的美景，对文章结构这类抽象事物表示赞赏要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关闭", "is_correct": false, "explanation": "搭配：“关闭”多用于门窗、店铺等，不能说来院子里关闭。"}, {"text": "观赏", "is_correct": true, "explanation": "观赏：看并欣赏美景，与“花开了”和“院子里”搭配，表示来看花。"}, {"text": "讲述", "is_correct": false, "explanation": "语义：“讲述”的内容是故事或经历，与花开的景象无关。"}, {"text": "发送", "is_correct": false, "explanation": "配价：“发送”需要被发送的内容作宾语，句中没有宾语，也不合情境。"}], "explanations": {"关闭": "搭配：“关闭”多用于门窗、店铺等，不能说来院子里关闭。", "观赏": "观赏：看并欣赏美景，与“花开了”和“院子里”搭配，表示来看花。", "讲述": "语义：“讲述”的内容是故事或经历，与花开的景象无关。", "发送": "配价：“发送”需要被发送的内容作宾语，句中没有宾语，也不合情境。"}, "sentence_index": 6, "correct_answer": "观赏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保安观赏着停车场的车辆。", "explanation": "这里应该用〈监视〉。观赏是欣赏美景，看守车辆是为了盯住情况，要用监视。"}, {"text": "她观赏着老师的讲解。", "explanation": "这里应该用〈聆听〉。观赏针对可看见的美景，听讲解要用聆听。"}, {"text": "警察观赏了案件的经过。", "explanation": "这里应该用〈调查〉。观赏表示欣赏美景，了解案件经过要用调查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐在船上观赏着一只荷花。", "corrected_sentence": "我们坐在船上观赏着一朵荷花。", "error_description": "错误在量词“只”。“荷花”应配量词“朵”，说“观赏着一朵荷花”；“只”用于动物、手等，不能修饰荷花。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们冬天常常很观赏雪景。", "corrected_sentence": "孩子们冬天常常观赏雪景。", "error_description": "错误在“很”放在动作动词“观赏”前。“很”一般修饰形容词，不修饰“观赏”这类动作动词，应删去，说“常常观赏雪景”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
