INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97458, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "观看并欣赏美好的事物。", "primary_collocate": null, "pronunciation": "guān shǎng", "ipa": "kwan˥ ʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "春天，很多人去公园观赏樱花。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客站在山上观赏日落。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船观赏了河两岸的风景。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖很美，适合慢慢观赏。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我带孩子去植物园观赏荷花。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在窗前观赏着外面的大雪。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你观赏过海上的日出吗？", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的香山，人们都来观赏红叶。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围在池边观赏那些漂亮的金鱼。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把花摆在桌上，每天观赏。", "target_word": "观赏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "观赏了", "label": "体标"}, {"form": "观赏着", "label": "体标"}, {"form": "观赏过", "label": "体标"}, {"form": "观赏鱼", "label": "复合"}, {"form": "观赏性", "label": "复合"}], "register": "书面", "sense_fingerprint": "观看并欣赏美好的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed74c15d-419d-4ab1-b028-8ae81febcec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "砍伐", "is_correct": false, "explanation": "语义：“砍伐”是伐倒树木，与去公园赏花的意思不合。"}, {"text": "观赏", "is_correct": true, "explanation": "观赏：看并欣赏美景，与“去公园”和“樱花”搭配，表示去赏花。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”是把人或动物赶走，不能用于樱花，与去公园赏花的意思不合。"}, {"text": "倾听", "is_correct": false, "explanation": "搭配：“倾听”的对象是声音或意见，不能说倾听樱花。"}], "explanations": {"砍伐": "语义：“砍伐”是伐倒树木，与去公园赏花的意思不合。", "观赏": "观赏：看并欣赏美景，与“去公园”和“樱花”搭配，表示去赏花。", "驱赶": "语义：“驱赶”是把人或动物赶走，不能用于樱花，与去公园赏花的意思不合。", "倾听": "搭配：“倾听”的对象是声音或意见，不能说倾听樱花。"}, "sentence_index": 0, "correct_answer": "观赏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院观赏生病的奶奶。", "explanation": "这里应该用〈看望〉。观赏针对美好的景物，不用于生病的人；探望病人要说看望。"}, {"text": "周末我们去工厂观赏堆积的废料。", "explanation": "这里应该用〈清理〉。观赏针对美好的景物，堆积的废料要用清理。"}, {"text": "医生仔细观赏病人的反应。", "explanation": "这里应该用〈观察〉。观赏是欣赏美好事物，仔细看病人的反应以了解病情要用观察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "搭配：“修建”多用于建筑、道路等，不能说修建海上的日出。"}, {"text": "观赏", "is_correct": true, "explanation": "观赏：看并欣赏美景，与“海上的日出”搭配，表示看过这一景象。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑或设施，与日出无关。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的宾语须是可买卖的商品，日出不能购买。"}], "explanations": {"修建": "搭配：“修建”多用于建筑、道路等，不能说修建海上的日出。", "观赏": "观赏：看并欣赏美景，与“海上的日出”搭配，表示看过这一景象。", "拆除": "语义：“拆除”指拆掉建筑或设施，与日出无关。", "购买": "配价：“购买”的宾语须是可买卖的商品，日出不能购买。"}, "sentence_index": 6, "correct_answer": "观赏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我观赏他的勇气。", "explanation": "这里应该用〈欣赏〉。观赏用于可看见的美景，对他人的勇气这类品质表示赞赏要用欣赏。"}, {"text": "他一直观赏着路口的红绿灯。", "explanation": "这里应该用〈注视〉。观赏是欣赏美好的景物，只是盯着红绿灯看要用注视。"}, {"text": "他观赏了汽车的油量。", "explanation": "这里应该用〈查看〉。观赏是欣赏美景，检查油量是为了了解情况，要用查看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天都很观赏风景。", "corrected_sentence": "我每天都观赏风景。", "error_description": "错误在“很”放在动作动词“观赏”前。“很”一般修饰形容词，不修饰“观赏”这类动作动词，应删去，说“每天都观赏风景”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲站在山顶观赏着一只雪景。", "corrected_sentence": "父亲站在山顶观赏着一片雪景。", "error_description": "错误在量词“只”。“雪景”应配量词“片”（或“场”），说“一片雪景”；“只”用于动物、手等，不能修饰雪景。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f5425f-9072-43da-af92-fcc24f81c187') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
