INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97461, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "有些事好像早就已经定好，不能改变。", "primary_collocate": null, "pronunciation": "zhù dìng", "ipa": "ʈʂu˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他们俩注定要在一起。", "target_word": "注定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她觉得自己注定会成为一个歌手。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们注定在那个夏天相遇。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总觉得自己注定一辈子不会成功。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段感情注定没有好结果。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人说，两个人能不能在一起是注定的。", "target_word": "注定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就觉得自己注定要离开这个小城。", "target_word": "注定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一切都注定了，我们还努力做什么？", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说自己这一生注定要走很远的路。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人相信，每个人的命运都是注定的。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "注定了", "label": "体标（了）"}, {"form": "註定", "label": "繁体"}], "register": "中性", "sense_fingerprint": "命运早已定好、无法改变：注定要…、是注定的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注定", "is_correct": true, "explanation": "正确：“注定”表示命运早已定好，与“要在一起”相符。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示躲开，与“要在一起”的意愿相反。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“要在一起”的意思冲突。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”后应接具体的事情，且与“要在一起”的愿望矛盾。"}], "explanations": {"注定": "正确：“注定”表示命运早已定好，与“要在一起”相符。", "逃避": "语义：“逃避”表示躲开，与“要在一起”的意愿相反。", "反对": "语义：“反对”表示不同意，与“要在一起”的意思冲突。", "拒绝": "配价：“拒绝”后应接具体的事情，且与“要在一起”的愿望矛盾。"}, "sentence_index": 0, "correct_answer": "注定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天注定也许买一台新电脑。", "explanation": "这里误用了〈注定〉。注定表示必然，与表示不确定的“也许”矛盾。"}, {"text": "我下个月注定说不定去北京旅游。", "explanation": "这里误用了〈注定〉。注定表示必然，与表示不确定的“说不定”矛盾。"}, {"text": "我注定希望他明天来看我。", "explanation": "这里误用了〈注定〉。注定说的是早已定好、无法改变的事，表达个人心愿与此不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注定", "is_correct": true, "explanation": "正确：“注定”表示自己一生的命运早已定好，与“要离开这个小城”相符。"}, {"text": "抗拒", "is_correct": false, "explanation": "语义：“抗拒”表示反抗，与“要离开”的自觉相反。"}, {"text": "否认", "is_correct": false, "explanation": "语义：“否认”表示不承认，与“觉得自己……要离开”的想法矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "配价：“躲避”后不能接“要离开这个小城”这样的内容，句子不通。"}], "explanations": {"注定": "正确：“注定”表示自己一生的命运早已定好，与“要离开这个小城”相符。", "抗拒": "语义：“抗拒”表示反抗，与“要离开”的自觉相反。", "否认": "语义：“否认”表示不承认，与“觉得自己……要离开”的想法矛盾。", "躲避": "配价：“躲避”后不能接“要离开这个小城”这样的内容，句子不通。"}, "sentence_index": 6, "correct_answer": "注定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条规定是注定的，大家都要遵守。", "explanation": "这里误用了〈注定〉。注定指命中早已安排好、无法改变的事，不能用来说明人为制定的规章。"}, {"text": "他能不能考上大学，是注定的，要看他的努力。", "explanation": "这里应该用〈取决于〉。注定指与努力无关的命运，要看努力时应用“取决于”。"}, {"text": "明天开会的时间是注定的，你们今天就通知大家。", "explanation": "这里应该用〈确定〉。注定指命运早定，人为安排的时间要用“确定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一生很注定要吃苦。", "corrected_sentence": "他的一生注定要吃苦。", "error_description": "错误：“很注定”。正确：“注定要”。“注定”是动词，前面不能加程度副词“很”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这孩子从小就觉得自己注定过要成名。", "corrected_sentence": "这孩子从小就觉得自己注定要成名。", "error_description": "错误：“注定过”。正确：“注定要”。“注定”说的是早已定好的未来，不表示经历，不能加“过”，应删去“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
