INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "事先已经决定，必然如此。", "primary_collocate": null, "pronunciation": "zhù dìng", "ipa": "ʈʂu˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这样做注定会失败。", "target_word": "注定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有准备的人注定会输。", "target_word": "注定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不努力学习，成绩注定不会好。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划太冒险，注定得不到支持。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骗人的生意注定做不长。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的队员太少，这场比赛注定要输。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方法不对，再努力也注定没有用。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的位置太偏，生意注定好不了。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直迟到，注定拿不到奖金。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对手这么强，我们注定赢不了这场比赛。", "target_word": "注定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "注定了", "label": "体标（了）"}, {"form": "註定", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由原因推出必然结果：注定会失败、注定不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注定", "is_correct": true, "explanation": "正确：“注定”表示由原因推出的必然结果，与“会失败”相符。"}, {"text": "成功", "is_correct": false, "explanation": "语义：“成功”与“会失败”意义相反，句子自相矛盾。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”后接活动或组织，不能接“会失败”这样的结果，句子不通。"}, {"text": "避免", "is_correct": false, "explanation": "语义：“避免”表示防止，与“会失败”的结果冲突。"}], "explanations": {"注定": "正确：“注定”表示由原因推出的必然结果，与“会失败”相符。", "成功": "语义：“成功”与“会失败”意义相反，句子自相矛盾。", "参加": "配价：“参加”后接活动或组织，不能接“会失败”这样的结果，句子不通。", "避免": "语义：“避免”表示防止，与“会失败”的结果冲突。"}, "sentence_index": 0, "correct_answer": "注定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我注定明天去看电影，票已经买好了。", "explanation": "这里应该用〈打算〉。注定表示由原因推出的必然结果，不能用来说自己安排好的计划。"}, {"text": "这次比赛我注定可能赢，你们别担心。", "explanation": "这里误用了〈注定〉。注定表示必然，与表示不确定的“可能”矛盾。"}, {"text": "我们注定必须准时到校，否则会被处罚。", "explanation": "这里误用了〈注定〉。注定说的是命中早已定好的结果，不能用来表示规章强制的义务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注定", "is_correct": true, "explanation": "正确：“注定”表示必然的结果，与“再努力也……没有用”相符。"}, {"text": "发生", "is_correct": false, "explanation": "搭配：“发生”后不能直接接“没有用”这样的评价，句子不通。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”表示终止，与“再努力”的语境不符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“再努力”的意思不相关，句子意思不通。"}], "explanations": {"注定": "正确：“注定”表示必然的结果，与“再努力也……没有用”相符。", "发生": "搭配：“发生”后不能直接接“没有用”这样的评价，句子不通。", "停止": "语义：“停止”表示终止，与“再努力”的语境不符。", "忘记": "语义：“忘记”与“再努力”的意思不相关，句子意思不通。"}, "sentence_index": 6, "correct_answer": "注定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我注定努力学习，因为我已经决定了。", "explanation": "这里误用了〈注定〉。注定说的是早已定好、无法改变的结果，不能用来说明自己主动做出的选择。"}, {"text": "我注定故意输给他这场比赛。", "explanation": "这里误用了〈注定〉。注定说的是必然发生的结果，不能与有意识的行为搭配。"}, {"text": "这场比赛的结果注定还不清楚，我们等等看。", "explanation": "这里误用了〈注定〉。注定表示事先已定，与“还不清楚”的未定状态矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试我们很注定会输。", "corrected_sentence": "这次考试我们注定会输。", "error_description": "错误：“很注定”。正确：“注定会”。“注定”是动词，前面不能加程度副词“很”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个队太弱，我们注定过会输。", "corrected_sentence": "这个队太弱，我们注定会输。", "error_description": "错误：“注定过”。正确：“注定会”。“注定”表示事先已定的必然结果，不表示经历，不能加“过”，应删去“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
