INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "临别时互相说告别的话。", "primary_collocate": null, "pronunciation": "huà bié", "ipa": "xwa˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "临别时，两位老人话别了很久。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在门前话别，说了许多祝福的话。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话别时，她送给我一封信。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在餐桌上举杯话别，说着心里话。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临行前夜，兄弟二人彻夜话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她与家人话别，叮嘱了很多事。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围坐着话别，气氛有点伤感。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们与乡亲们依依话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老校长和毕业生们话别，互相道了珍重。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临别的晚上，我们只想好好话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "话别了", "label": "体标（了）"}], "register": "书面", "sense_fingerprint": "话别：临别时彼此交谈、说告别的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ff3a29a-476f-42a0-b870-bfa7edf8908b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话别", "is_correct": true, "explanation": "正确：话别指临别时彼此交谈、说告别的话，与“临别时”的语境相合。"}, {"text": "拜年", "is_correct": false, "explanation": "语义：“拜年”是春节的贺岁问候，与“临别时”的离别语境不符。"}, {"text": "迎接", "is_correct": false, "explanation": "配价：“迎接”需带宾语（迎接某人），单用“迎接了很久”句子不完整，且与“临别”语境相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎来，与“临别时”的离别语境相反。"}], "explanations": {"话别": "正确：话别指临别时彼此交谈、说告别的话，与“临别时”的语境相合。", "拜年": "语义：“拜年”是春节的贺岁问候，与“临别时”的离别语境不符。", "迎接": "配价：“迎接”需带宾语（迎接某人），单用“迎接了很久”句子不完整，且与“临别”语境相反。", "欢迎": "语义：“欢迎”表示迎来，与“临别时”的离别语境相反。"}, "sentence_index": 0, "correct_answer": "话别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚见到老同学，两人就话别了几句。", "explanation": "这里应该用〈寒暄〉。话别只用于临别之时，刚见面时的客套不能说话别。"}, {"text": "我们在车站为远道而来的朋友话别。", "explanation": "这里应该用〈接风〉。话别是送人离开时的道别，朋友刚到应当说接风，不能说话别。"}, {"text": "大年初一，我们挨家挨户话别。", "explanation": "这里应该用〈拜年〉。话别是临行时的告别，春节走访只能说拜年，不能说话别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话别", "is_correct": true, "explanation": "正确：话别指临别时彼此交谈、说告别的话，与“大家围坐着”的临别场景一致。"}, {"text": "欢庆", "is_correct": false, "explanation": "语义：“欢庆”表示喜庆，与“气氛有点伤感”的语气矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需带宾语（感谢某人），“围坐着感谢”句子缺宾语。"}, {"text": "欢聚", "is_correct": false, "explanation": "语义：“欢聚”表示欢乐地聚在一起，与“伤感”的气氛冲突。"}], "explanations": {"话别": "正确：话别指临别时彼此交谈、说告别的话，与“大家围坐着”的临别场景一致。", "欢庆": "语义：“欢庆”表示喜庆，与“气氛有点伤感”的语气矛盾。", "感谢": "配价：“感谢”需带宾语（感谢某人），“围坐着感谢”句子缺宾语。", "欢聚": "语义：“欢聚”表示欢乐地聚在一起，与“伤感”的气氛冲突。"}, "sentence_index": 6, "correct_answer": "话别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚回到母校，就和老师话别了几句。", "explanation": "这里应该用〈问候〉。话别只用于临别之时，刚回到母校时的寒暄应说问候，不能说话别。"}, {"text": "我们每天上课前见面时互相话别。", "explanation": "这里应该用〈打招呼〉。话别只用于临别之时，日常见面不能说话别。"}, {"text": "重逢的那天，我们兴奋地话别。", "explanation": "这里应该用〈叙旧〉。话别用于临别时，重逢后互相聊往事应说叙旧，不能说话别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "临别前，母女俩话别妈妈，说了很多话。", "corrected_sentence": "临别前，母女俩话别，说了很多话。", "error_description": "错误：“话别”不能直接带人称宾语“妈妈”。去掉宾语，说“母女俩话别”；若要指明对象，应用“和”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们互相话别同学，说了很多心里话。", "corrected_sentence": "他们互相话别，说了很多心里话。", "error_description": "错误：“话别”后直接带人称宾语“同学”。正确为“互相话别”，互相道别不带宾语；若要指明对象，应用“和”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf0c292c-b135-4db4-b710-83566dabfb46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
