INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接待旅客住宿的场所，常指较好的旅馆。", "primary_collocate": null, "pronunciation": "bīn guǎn", "ipa": "pin˥˥ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家宾馆的服务很好，客人都很满意。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在宾馆前台办理了入住手续。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家宾馆离火车站很近，坐车只要五分钟。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上订了一家宾馆。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宾馆的早餐有面包、牛奶和水果。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国客人住在这家五星级宾馆里。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，附近有没有便宜一点的宾馆？", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宾馆经理亲自到门口迎接客人。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，代表们回到宾馆休息。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家宾馆有游泳池，孩子们都很喜欢。", "target_word": "宾馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "国宾馆", "label": "复合"}], "register": "中性", "sense_fingerprint": "接待旅客住宿的较好旅馆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宾馆", "is_correct": true, "explanation": "“宾馆”指接待旅客住宿的较好旅馆，与“服务很好，客人都很满意”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱不提供“服务”，不能说“这家冰箱的服务”。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱不接待客人，与“客人都很满意”不相符。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：一般不说“电脑的服务很好”。"}], "explanations": {"宾馆": "“宾馆”指接待旅客住宿的较好旅馆，与“服务很好，客人都很满意”相符。", "冰箱": "搭配：冰箱不提供“服务”，不能说“这家冰箱的服务”。", "监狱": "语义：监狱不接待客人，与“客人都很满意”不相符。", "电脑": "搭配：一般不说“电脑的服务很好”。"}, "sentence_index": 0, "correct_answer": "宾馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一只宾馆里住了三天。", "explanation": "这里应该用〈家〉。“宾馆”是建筑，量词用“家”；“只”用于动物等。"}, {"text": "那是一条很大的宾馆。", "explanation": "这里应该用〈家〉。“宾馆”是建筑，量词用“家”；“条”用于细长的东西。"}, {"text": "我把宾馆放进书包里，带去学校。", "explanation": "这里应该用〈课本〉。“宾馆”是供旅客住宿的建筑，不能放进书包里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宾馆", "is_correct": true, "explanation": "“宾馆”指可以住宿的旅馆，与“附近有没有便宜一点的”相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能被租住，不说“便宜一点的河流”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被租住或出售，不说“便宜一点的天气”。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“地铁”不说“便宜一点的”，它是交通设施，不是住宿场所。"}], "explanations": {"宾馆": "“宾馆”指可以住宿的旅馆，与“附近有没有便宜一点的”相符。", "河流": "语义：河流不能被租住，不说“便宜一点的河流”。", "天气": "语义：天气不能被租住或出售，不说“便宜一点的天气”。", "地铁": "搭配：“地铁”不说“便宜一点的”，它是交通设施，不是住宿场所。"}, "sentence_index": 6, "correct_answer": "宾馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天有一位重要的宾馆来访。", "explanation": "这里应该用〈宾客〉。“宾馆”指建筑，不能指来访的人。"}, {"text": "宾馆们在车站排队买票。", "explanation": "这里应该用〈旅客〉。“宾馆”指建筑，不能指排队买票的人。"}, {"text": "宾馆在门口等候。", "explanation": "这里应该用〈访客〉。“宾馆”指建筑，不能指在门口等候的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在网上订了一只宾馆。", "corrected_sentence": "我在网上订了一家宾馆。", "error_description": "量词错误：“宾馆”是营业场所，量词用“家”，不用“只”。应说“一家宾馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们找到了一家离车站很近宾馆。", "corrected_sentence": "我们找到了一家离车站很近的宾馆。", "error_description": "错误形式：“离车站很近宾馆”；正确形式：“离车站很近的宾馆”。作定语的短语修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
