INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97477, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "action", "definition": "发出很大的响声。", "primary_collocate": null, "pronunciation": "hōng", "ipa": "xʊŋ˥", "syllable_count": 1, "sentences": [{"text": "轰的一声，大树倒了。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处轰地响了一声。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空中轰的一声，下起了大雨。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轰的一声，汽车撞到了墙上。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子倒下时，轰的一声很吓人。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轰的一下，墙角的旧柜子倒了。", "target_word": "轰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，门轰的一声关上了。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟花轰地在夜空中炸开。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的石头轰的一声滚了下来。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥轰的一声塌了，大家都吓坏了。", "target_word": "轰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "轟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "突然发出很大的响声，常说“轰的一声”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abce999f-3fc1-404e-9d60-5f1209efb4c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97477, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轰", "is_correct": true, "explanation": "正确答案：轰 hōng，指发出很大的响声。"}, {"text": "红", "is_correct": false, "explanation": "hóng（第二声）与 hōng（第一声）声调不同，意思是颜色的红。"}, {"text": "哼", "is_correct": false, "explanation": "hēng 与 hōng 韵母不同（eng 与 ong），意思是低声哼唱或发出鼻音。"}, {"text": "哄", "is_correct": false, "explanation": "hǒng（第三声）与 hōng（第一声）声调不同，意思是哄骗、哄劝。"}], "explanations": {"轰": "正确答案：轰 hōng，指发出很大的响声。", "红": "hóng（第二声）与 hōng（第一声）声调不同，意思是颜色的红。", "哼": "hēng 与 hōng 韵母不同（eng 与 ong），意思是低声哼唱或发出鼻音。", "哄": "hǒng（第三声）与 hōng（第一声）声调不同，意思是哄骗、哄劝。"}, "sentence_index": null, "correct_answer": "轰"}, "level_3": {"options": [{"text": "轰", "is_correct": true, "explanation": "正确：“轰的一声”形容很大的响声，与句中大树倒下的声音相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不表示声音，“吃的一声”说不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”不能用来形容响声，搭配不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与响声无关，“睡的一声”句子不通。"}], "explanations": {"轰": "正确：“轰的一声”形容很大的响声，与句中大树倒下的声音相符。", "吃": "语义：“吃”不表示声音，“吃的一声”说不通。", "穿": "搭配：“穿”不能用来形容响声，搭配不通。", "睡": "语义：“睡”与响声无关，“睡的一声”句子不通。"}, "sentence_index": 0, "correct_answer": "轰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果轰的一声很甜。", "explanation": "这里误用了〈轰〉。〈轰〉只形容很大的响声，不能用来形容味道。"}, {"text": "这块布轰的一下很柔软。", "explanation": "这里误用了〈轰〉。〈轰〉只形容很大的响声，不能用来形容触感。"}, {"text": "他轻轻地轰了一声，把门关上了。", "explanation": "这里误用了〈轰〉。〈轰〉形容很大的响声，不能与“轻轻地”搭配，应改为“他轻轻地把门关上了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轰", "is_correct": true, "explanation": "正确：“轰的一声”形容关门时的巨响，与“风一吹”的语境相符。"}, {"text": "开", "is_correct": false, "explanation": "语义：“开”不是拟声，不能用来形容关门的声音。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”与声音无关，“喝的一声”句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能修饰关门的声音，搭配不通。"}], "explanations": {"轰": "正确：“轰的一声”形容关门时的巨响，与“风一吹”的语境相符。", "开": "语义：“开”不是拟声，不能用来形容关门的声音。", "喝": "语义：“喝”与声音无关，“喝的一声”句子不通。", "洗": "搭配：“洗”不能修饰关门的声音，搭配不通。"}, "sentence_index": 6, "correct_answer": "轰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮轰的一声从云后面钻了出来。", "explanation": "这里误用了〈轰〉。〈轰〉只形容很大的响声，月亮出来没有声音，应说“月亮悄悄地从云后面钻了出来”。"}, {"text": "饭菜的香味轰的一下飘了过来。", "explanation": "这里误用了〈轰〉。〈轰〉只形容很大的响声，香味没有声音，应说“饭菜的香味飘了过来”。"}, {"text": "小草轰的一声长高了。", "explanation": "这里误用了〈轰〉。〈轰〉只形容很大的响声，小草生长没有声音，应说“小草慢慢长高了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户轰了的一声碎了。", "corrected_sentence": "窗户轰的一声碎了。", "error_description": "错误：“轰”和“的一声”之间多加了“了”。正确：窗户轰的一声碎了。“轰的一声”中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙一声轰的倒下了。", "corrected_sentence": "墙轰的一声倒下了。", "error_description": "错误：语序不对，“一声”放在了“轰的”前面。正确：墙轰的一声倒下了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "送走", "is_correct": true, "explanation": "送走：与“迎来”相对，指送走离去的人或时期。"}, {"text": "休息", "is_correct": false, "explanation": "与“迎来”没有反义关系，指停止劳动或活动。"}, {"text": "生长", "is_correct": false, "explanation": "与“迎来”没有反义关系，指植物或人逐渐长大。"}, {"text": "思考", "is_correct": false, "explanation": "与“迎来”没有反义关系，指用脑子考虑问题。"}], "correct_answer": "送走", "explanations": {"送走": "送走：与“迎来”相对，指送走离去的人或时期。", "休息": "与“迎来”没有反义关系，指停止劳动或活动。", "生长": "与“迎来”没有反义关系，指植物或人逐渐长大。", "思考": "与“迎来”没有反义关系，指用脑子考虑问题。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "送别", "is_correct": true, "explanation": "送别：与“迎来”相对，指送行告别离去的人。"}, {"text": "写作", "is_correct": false, "explanation": "与“迎来”没有反义关系，指写文章或作品。"}, {"text": "游泳", "is_correct": false, "explanation": "与“迎来”没有反义关系，指在水中划动身体前进。"}, {"text": "说话", "is_correct": false, "explanation": "与“迎来”没有反义关系，指用语言表达想法。"}], "correct_answer": "送别", "explanations": {"送别": "送别：与“迎来”相对，指送行告别离去的人。", "写作": "与“迎来”没有反义关系，指写文章或作品。", "游泳": "与“迎来”没有反义关系，指在水中划动身体前进。", "说话": "与“迎来”没有反义关系，指用语言表达想法。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有人或好日子来了，大家高兴地迎接。", "primary_collocate": null, "pronunciation": "yíng lái", "ipa": "iŋ˧˥ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "全家人站在门口，迎来了远方的客人。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年的努力，农民迎来了丰收的好日子。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里，大家迎来了回国的运动员。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了三天雨，村里终于迎来了晴天。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口，孩子们迎来了放假回家的哥哥。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家迎来了一个可爱的小宝宝。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节到了，我们高高兴兴地迎来新年。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人迎来了幸福的晚年。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们敲锣打鼓，迎来了新来的老师。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈笑着迎来了下班回家的爸爸。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎来了", "label": "完成体"}, {"form": "迎来过", "label": "经历体"}, {"form": "迎來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "高兴地接来客人或好日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c091977-6e47-4361-b22e-fc75be886fea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迎来", "is_correct": true, "explanation": "迎来：高兴地接来远方的客人，与“站在门口”的语境相符。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：全家人站在门口是热情接待，“抛弃”的语义与之相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”含有赶走的意思，与热情接待客人的语境冲突。"}, {"text": "吸收", "is_correct": false, "explanation": "搭配：“吸收”用于知识、营养等，不能用于接待客人。"}], "explanations": {"迎来": "迎来：高兴地接来远方的客人，与“站在门口”的语境相符。", "抛弃": "语义：全家人站在门口是热情接待，“抛弃”的语义与之相反。", "驱赶": "语义：“驱赶”含有赶走的意思，与热情接待客人的语境冲突。", "吸收": "搭配：“吸收”用于知识、营养等，不能用于接待客人。"}, "sentence_index": 0, "correct_answer": "迎来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌人来犯，士兵们奋起迎来了敌人。", "explanation": "这里应该用〈迎战〉。迎来表示高兴地接来人或好日子，不用于对敌作战。"}, {"text": "春节刚过，我们迎来了旧年。", "explanation": "这里应该用〈送走〉。迎来用于将要到来的人或时期，旧年已经过去。"}, {"text": "他不小心迎来了一场大病，住了一个月医院。", "explanation": "这里应该用〈得了〉。迎来表示高兴地接来人或好日子，生病不是值得高兴的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎来", "is_correct": true, "explanation": "迎来：高兴地迎接新的一年，与“春节到了”和“高高兴兴”的语境相符。"}, {"text": "送走", "is_correct": false, "explanation": "语义：春节刚到，新年才开始，不能说送走新年。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”不与节日或“新年”搭配，不能说推迟新年。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“高高兴兴”的情绪相反，语境不合。"}], "explanations": {"迎来": "迎来：高兴地迎接新的一年，与“春节到了”和“高高兴兴”的语境相符。", "送走": "语义：春节刚到，新年才开始，不能说送走新年。", "推迟": "搭配：“推迟”不与节日或“新年”搭配，不能说推迟新年。", "拒绝": "语义：“拒绝”与“高高兴兴”的情绪相反，语境不合。"}, "sentence_index": 6, "correct_answer": "迎来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他迎来了那个没用的计划，再也不做了。", "explanation": "这里应该用〈放弃〉。不再做一个计划是放弃，迎来指高兴地接来人或好日子。"}, {"text": "工人们迎来了那条旧铁路，地上只剩下碎石。", "explanation": "这里应该用〈拆除〉。把铁路拆掉是拆除，迎来指高兴地接来人或好日子。"}, {"text": "他迎来了那些旧习惯。", "explanation": "这里应该用〈丢掉〉。迎来指高兴地接来人或好日子，旧习惯既不是人，也不是好日子，不能迎来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开学那天，学校迎来在三个新同学。", "corrected_sentence": "开学那天，学校迎来了三个新同学。", "error_description": "“在”位置错误：“在”不能直接放在“迎来”之后引出数量短语，应去掉“在”，说“学校迎来了三个新同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
