INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97482, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "告别", "is_correct": true, "explanation": "告别：与“迎来”相对，指告别旧的时期或事物。"}, {"text": "劳动", "is_correct": false, "explanation": "与“迎来”没有反义关系，指从事体力或脑力工作。"}, {"text": "怀念", "is_correct": false, "explanation": "与“迎来”没有反义关系，指思念过去的人或事。"}, {"text": "观看", "is_correct": false, "explanation": "与“迎来”没有反义关系，指仔细地看。"}], "correct_answer": "告别", "explanations": {"告别": "告别：与“迎来”相对，指告别旧的时期或事物。", "劳动": "与“迎来”没有反义关系，指从事体力或脑力工作。", "怀念": "与“迎来”没有反义关系，指思念过去的人或事。", "观看": "与“迎来”没有反义关系，指仔细地看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97482, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "告别", "is_correct": true, "explanation": "告别：与“迎来”相对，指告别旧的时期或事物。"}, {"text": "讨论", "is_correct": false, "explanation": "与“迎来”没有反义关系，指大家交换意见。"}, {"text": "歌唱", "is_correct": false, "explanation": "与“迎来”没有反义关系，指用声音唱出歌曲。"}, {"text": "整理", "is_correct": false, "explanation": "与“迎来”没有反义关系，指把东西理顺摆放好。"}], "correct_answer": "告别", "explanations": {"告别": "告别：与“迎来”相对，指告别旧的时期或事物。", "讨论": "与“迎来”没有反义关系，指大家交换意见。", "歌唱": "与“迎来”没有反义关系，指用声音唱出歌曲。", "整理": "与“迎来”没有反义关系，指把东西理顺摆放好。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97482, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迎接到来；遇到新的时期或事物。", "primary_collocate": null, "pronunciation": "yíng lái", "ipa": "iŋ˧˥ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "这座城市迎来了新的发展时期。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国迎来了一个新的时代。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，公园迎来了新的游览季节。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校迎来了建校一百周年。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过多年努力，公司迎来了新机会。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方迎来了今年的第一场雪。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活迎来了很大的变化。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了十二月，商店迎来了购物高峰。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇迎来了第一条高速公路。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，球队迎来了新的赛季。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎来了", "label": "完成体"}, {"form": "迎来过", "label": "经历体"}, {"form": "迎來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到新的时期或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c091977-6e47-4361-b22e-fc75be886fea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迎来", "is_correct": true, "explanation": "迎来：遇到新的发展时期，与“这座城市”的语境相符。"}, {"text": "送走", "is_correct": false, "explanation": "语义：“新的”发展时期刚开始，不能说送走它。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”不与时期搭配，不能说购买发展时期。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：“驱散”用于人群、云雾等，与“新的发展时期”的语境冲突。"}], "explanations": {"迎来": "迎来：遇到新的发展时期，与“这座城市”的语境相符。", "送走": "语义：“新的”发展时期刚开始，不能说送走它。", "购买": "搭配：“购买”不与时期搭配，不能说购买发展时期。", "驱散": "语义：“驱散”用于人群、云雾等，与“新的发展时期”的语境冲突。"}, "sentence_index": 0, "correct_answer": "迎来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城市在地震中迎来了巨大的损失。", "explanation": "这里应该用〈遭受〉。迎来表示迎接新的事物或时期，损失是坏结果，应说“遭受”。"}, {"text": "我们终于迎来了那段早已过去的旧时代。", "explanation": "这里应该用〈告别〉。迎来指遇到新的时期，过去的旧时代不能迎来。"}, {"text": "我们迎来了过去的一切。", "explanation": "这里应该用〈遗忘〉。迎来只用于新的事物，过去的一切不能迎来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎来", "is_correct": true, "explanation": "迎来：遇到新的变化，与“生活”和“很大的变化”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不与“变化”搭配，不能说吃了很大的变化。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”的对象是地方景点，不能用于生活的变化。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”搭配责任、任务，不能说承担变化。"}], "explanations": {"迎来": "迎来：遇到新的变化，与“生活”和“很大的变化”的语境相符。", "吃": "搭配：“吃”不与“变化”搭配，不能说吃了很大的变化。", "游览": "语义：“游览”的对象是地方景点，不能用于生活的变化。", "承担": "搭配：“承担”搭配责任、任务，不能说承担变化。"}, "sentence_index": 6, "correct_answer": "迎来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们迎来了刚刚结束的假期。", "explanation": "这里应该用〈送走〉。迎来指迎接即将到来的新时期，已经结束的假期只能送走，不能迎来。"}, {"text": "小镇迎来了那条被拆掉的旧铁路。", "explanation": "这里应该用〈告别〉。迎来指遇到新的事物，被拆掉的旧铁路已经离开，只能告别。"}, {"text": "他迎来了那些旧习惯。", "explanation": "这里应该用〈丢掉〉。迎来指遇到新的事物，旧习惯不能迎来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家迎来在三个新时期。", "corrected_sentence": "这个国家迎来了三个新时期。", "error_description": "“在”位置错误：“在”不能直接放在“迎来”之后引出数量短语，应去掉“在”，说“这个国家迎来了三个新时期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年学校不迎来新生。", "corrected_sentence": "去年学校没迎来新生。", "error_description": "否定副词错误：过去发生的事应用“没”否定，不能用“不”。应说“去年学校没迎来新生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
