INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "舞台上很快走过去,没有说什么。", "primary_collocate": null, "pronunciation": "guò chǎng", "ipa": "kuɔ˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这一幕只有一个过场,演员没说话。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在戏里只有一个过场。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上有个过场,几个人快步走过。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个过场很短,不到十秒。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演的是过场,连台词也没有。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演让他在第二幕加一个过场。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过场一结束,灯光就暗了下来。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上的过场,观众几乎没注意到。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在剧中只有一次过场,没说话。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个过场里,士兵们从台右走到台左。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过场戏", "label": "复合"}], "register": "中性", "sense_fingerprint": "演员在舞台上快速走过、不说台词的一段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过场", "is_correct": true, "explanation": "正确：过场指台上快速走过、不说台词的一段，与“演员没说话”相符。"}, {"text": "独白", "is_correct": false, "explanation": "语义：独白要说话，与“演员没说话”矛盾。"}, {"text": "对白", "is_correct": false, "explanation": "语义：对白是对话，演员没说话就不会有对白。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“灯光”一般说“一束”“一盏”，不说“一个”。"}], "explanations": {"过场": "正确：过场指台上快速走过、不说台词的一段，与“演员没说话”相符。", "独白": "语义：独白要说话，与“演员没说话”矛盾。", "对白": "语义：对白是对话，演员没说话就不会有对白。", "灯光": "搭配：“灯光”一般说“一束”“一盏”，不说“一个”。"}, "sentence_index": 0, "correct_answer": "过场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演员在过场里大段地念台词，观众听得很入迷。", "explanation": "这里应该用〈独白〉。过场是很快走过、不说话的场面，不能大段念台词；大段念白应说“独白”。"}, {"text": "过场缓缓拉开，灯光亮起。", "explanation": "这里应该用〈幕布〉。过场指台上快速走过的场面，不是幕布，不能说“拉开”。"}, {"text": "剧终时，演员一起过场，观众站起来鼓掌。", "explanation": "这里应该用〈谢幕〉。过场是名词，指台上快速走过的一段场面，不能作动词说“一起过场”；演员一起出来答谢观众应说“谢幕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过场", "is_correct": true, "explanation": "正确：过场结束后灯光暗下来，符合舞台上的过渡。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”不能“结束”后让灯光暗下来，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能作为“结束”的对象，句子说不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能和“结束”组成这样的句子，灯光与它无关。"}], "explanations": {"过场": "正确：过场结束后灯光暗下来，符合舞台上的过渡。", "呼吸": "语义：“呼吸”不能“结束”后让灯光暗下来，句子不通。", "年龄": "语义：“年龄”不能作为“结束”的对象，句子说不通。", "体温": "搭配：“体温”不能和“结束”组成这样的句子，灯光与它无关。"}, "sentence_index": 6, "correct_answer": "过场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "剧中这段过场很动人，观众都在跟着唱。", "explanation": "这里应该用〈插曲〉。过场是台上短暂的过渡场面，不是可以唱的曲子，“跟着唱”说的是歌曲。"}, {"text": "过场的时候，观众都去大厅喝水。", "explanation": "这里应该用〈幕间休息〉。过场是台上的过渡场面，不指观众的休息时间。"}, {"text": "演员在过场里一个人说了十分钟的心里话。", "explanation": "这里应该用〈独白〉。过场是很快走过、不说话的场面，一个人长时间说心里话应说“独白”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一幕里有台过场，几个演员快步走过。", "corrected_sentence": "这一幕里有个过场，几个演员快步走过。", "error_description": "量词用错：“过场”应用“个”计量，写成“台”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一幕有根过场，演得很快，观众没注意。", "corrected_sentence": "这一幕有个过场，演得很快，观众没注意。", "error_description": "量词用错：“过场”应用“个”计量，写成“根”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97490, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97490, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏剧中交代情节的短暂场面;也指只走形式。", "primary_collocate": null, "pronunciation": "guò chǎng", "ipa": "kuɔ˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这场戏里有个过场，交代了主角的去向。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两幕之间有个过场,说明主角已经离开。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过场很短,但故事因此更清楚。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演用一个过场,交代了三年的变化。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段过场很简短，只交代了他离开的原因。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次检查只是过场,没人认真看。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会只是个过场,结果早就定了。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这次面试不过是过场。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导来看了一下,完全是过场。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前的讲话只是过场,大家都不听。", "target_word": "过场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过场戏", "label": "复合"}], "register": "中性", "sense_fingerprint": "戏中交代情节的短场面;引申为只做表面、走形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过场", "is_correct": true, "explanation": "正确：过场指戏中交代情节的短场面，“交代了主角的去向”正对应此义。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形，不能用来交代情节。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能交代情节，句子说不通。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”不能交代情节，句子说不通。"}], "explanations": {"过场": "正确：过场指戏中交代情节的短场面，“交代了主角的去向”正对应此义。", "身高": "体貌：“身高”是人的外形，不能用来交代情节。", "颜色": "语义：“颜色”不能交代情节，句子说不通。", "年纪": "语义：“年纪”不能交代情节，句子说不通。"}, "sentence_index": 0, "correct_answer": "过场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作者用一句过场，把三年前的事讲清楚了。", "explanation": "这里应该用〈旁白〉。过场是戏中的场面，不是一句话；讲清往事的话语应说“旁白”。"}, {"text": "演员用一个过场，把台词大声唱了出来。", "explanation": "这里应该用〈唱段〉。过场是交代情节的短暂场面，不是用来演唱的段落。"}, {"text": "屏幕上打出过场，交代了三年的变化。", "explanation": "这里应该用〈字幕〉。过场是戏中的场面，不是屏幕上的文字；屏幕上的文字应说“字幕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过场", "is_correct": true, "explanation": "正确：“只是个过场”指只走形式，结果早已定下，与句意相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”与“开会”“结果早就定了”毫无关系，句子不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不能指走形式的会议，句子说不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能和“只是个”搭配，句子说不通。"}], "explanations": {"过场": "正确：“只是个过场”指只走形式，结果早已定下，与句意相符。", "花园": "语义：“花园”与“开会”“结果早就定了”毫无关系，句子不通。", "歌曲": "语义：“歌曲”不能指走形式的会议，句子说不通。", "体温": "搭配：“体温”不能和“只是个”搭配，句子说不通。"}, "sentence_index": 6, "correct_answer": "过场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次谈判的过场很长，双方都在认真讨论价格。", "explanation": "这里应该用〈磋商〉。过场指只走形式，认真讨论价格是实际的磋商，不是走形式。"}, {"text": "这次面试的过场做得很认真，考官逐条记录。", "explanation": "这里应该用〈环节〉。过场指只走形式，认真逐条记录不是走形式；认真对待的步骤应说“环节”。"}, {"text": "这座桥的过场很长，车辆都在慢慢通过。", "explanation": "这里应该用〈路段〉。过场指只走形式的环节，不指桥的路段；说路的长度应用“路段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条过场交代得很清楚。", "corrected_sentence": "这段过场交代得很清楚。", "error_description": "量词用错：“过场”应用“段”计量，写成“条”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次谈判只是根过场，双方早有约定。", "corrected_sentence": "这次谈判只是个过场，双方早有约定。", "error_description": "量词用错：“过场”应用“个”计量，写成“根”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
