INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97493, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人学到的本事和功夫。", "primary_collocate": null, "pronunciation": "dào heng", "ipa": "tɑʊ̯˥˩ xəŋ", "syllable_count": 2, "sentences": [{"text": "他学了二十年,道行很深。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅的道行,我比不上。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的道行还不够,再练练吧。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生道行很高,病人都信他。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟师父学了很多年,道行越来越深。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李刚入行,道行还浅。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论做菜的道行,谁也比不过他。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的道行不是一天练成的。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学好木工,道行要靠时间磨出来。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别小看他,他的道行深着呢。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "靠多年学习和练习积累的本事、功夫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道行", "is_correct": true, "explanation": "正确：道行指学到的本事和功夫，“学了二十年”之后说“很深”正合适。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说“很大”“很好”，不说“很深”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“很深”形容功夫的深度，年龄只说“大”或“小”，句子说不通。"}, {"text": "信心", "is_correct": false, "explanation": "搭配：“信心”说“很足”“很大”，不说“很深”。"}], "explanations": {"道行": "正确：道行指学到的本事和功夫，“学了二十年”之后说“很深”正合适。", "脾气": "搭配：“脾气”说“很大”“很好”，不说“很深”。", "年龄": "语义：“很深”形容功夫的深度，年龄只说“大”或“小”，句子说不通。", "信心": "搭配：“信心”说“很足”“很大”，不说“很深”。"}, "sentence_index": 0, "correct_answer": "道行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座房子的道行很大，住了三代人。", "explanation": "这里应该用〈面积〉。道行指功夫和本事，不指房子的大小；说房子的大小应用“面积”。"}, {"text": "这条路的道行很长，我走了一个小时。", "explanation": "这里应该用〈路程〉。道行指本事和功夫，不指路的长短；说路长应用“路程”。"}, {"text": "这把刀的道行很快，一下就切完了。", "explanation": "这里应该用〈速度〉。道行指功夫和本事，不指刀的快慢；说刀切得快应用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道行", "is_correct": true, "explanation": "正确：道行指做菜的本事，“比不过”比较的正是这种功夫。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形，与做菜的本事无关。"}, {"text": "食量", "is_correct": false, "explanation": "语义：“食量”指一顿能吃多少，不指做菜的本事。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不能拿来和做菜的本事比较。"}], "explanations": {"道行": "正确：道行指做菜的本事，“比不过”比较的正是这种功夫。", "身高": "体貌：“身高”是人的外形，与做菜的本事无关。", "食量": "语义：“食量”指一顿能吃多少，不指做菜的本事。", "体重": "语义：“体重”是身体的重量，不能拿来和做菜的本事比较。"}, "sentence_index": 6, "correct_answer": "道行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司干了三十年，道行很老，大家都很尊敬他。", "explanation": "这里的“道行”被当成从业年限，像形容〈资历〉那样说“很老”；道行指功夫和本事，应说“道行很深”。"}, {"text": "这家店的道行很好吃，客人天天来。", "explanation": "这里应该用〈味道〉。道行指做事的本事和功夫，不指食物的味道；说味道应用“味道”。"}, {"text": "他这些年攒下的道行，都花在了赌桌上。", "explanation": "这里应该用〈积蓄〉。道行指功夫和本事，攒下的是钱财，应说“积蓄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跟师父学了二十年，有一条深厚的道行。", "corrected_sentence": "他跟师父学了二十年，有一身深厚的道行。", "error_description": "量词用错：“道行”应用“身”计量，写成“条”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人这些年苦练，有一座好道行。", "corrected_sentence": "这位老人这些年苦练，有一身好道行。", "error_description": "量词用错：“道行”应用“身”计量，写成“座”不对，应为“一身好道行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
