INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97494, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "修行所达到的功夫和境界。", "primary_collocate": null, "pronunciation": "dào heng", "ipa": "tɑʊ̯˥˩ xəŋ", "syllable_count": 2, "sentences": [{"text": "这位老和尚修行多年,道行很深。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的道士道行高,大家都很尊敬他。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打坐了几十年,道行不浅。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小和尚的道行还浅,静不下心来。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说那位道长道行很高,能看出人的心事。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父说,道行要靠每天修炼。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上修行,道行一年比一年深。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的狐狸精道行不够,被道士发现了。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老道士的道行,没人说得清。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的道行还差得远呢,继续修行吧。", "target_word": "道行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "僧道修行所达到的功夫和境界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道行", "is_correct": true, "explanation": "正确：道行指修行的功夫，“修行多年”之后说“很深”正合适。"}, {"text": "香火", "is_correct": false, "explanation": "搭配：“香火”说“很旺”，不说“很深”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“很深”形容修行的功夫，年龄不能这样形容。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说“很大”“很好”，不说“很深”。"}], "explanations": {"道行": "正确：道行指修行的功夫，“修行多年”之后说“很深”正合适。", "香火": "搭配：“香火”说“很旺”，不说“很深”。", "年龄": "语义：“很深”形容修行的功夫，年龄不能这样形容。", "脾气": "搭配：“脾气”说“很大”“很好”，不说“很深”。"}, "sentence_index": 0, "correct_answer": "道行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的道行很高，游客都爱来。", "explanation": "这里应该用〈海拔〉。道行指修行的功夫，不指山的高度；说山的高度应用“海拔”。"}, {"text": "这条河的道行很深，水流很急。", "explanation": "这里应该用〈水〉。道行指修行的功夫，不指河水的深浅；河水的深浅应说“水”。"}, {"text": "这根绳子的道行很长，能拴住一头牛。", "explanation": "这里应该用〈长度〉。道行指修行的功夫，不指绳子的长短；说绳子的长短应用“长度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道行", "is_correct": true, "explanation": "正确：道行指修行的功夫，“一年比一年深”正描述它的增长。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“体力”说“好”“强”，不说“深”。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：“饭量”指吃饭的多少，与修行无关。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：“辈分”指世代排序，不能用“深”来形容它的增长。"}], "explanations": {"道行": "正确：道行指修行的功夫，“一年比一年深”正描述它的增长。", "体力": "搭配：“体力”说“好”“强”，不说“深”。", "饭量": "语义：“饭量”指吃饭的多少，与修行无关。", "辈分": "语义：“辈分”指世代排序，不能用“深”来形容它的增长。"}, "sentence_index": 6, "correct_answer": "道行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的道行很大，每天都要排队。", "explanation": "这里应该用〈规模〉。道行指修行的功夫，不指饭店的大小；说饭店的大小应用“规模”。"}, {"text": "山下这家小店的道行很甜，香客都爱买。", "explanation": "这里应该用〈点心〉。道行指修行的功夫，不指食物的甜味；甜的东西应说“点心”。"}, {"text": "他在山上修行多年，攒下的道行都寄回了老家。", "explanation": "这里应该用〈钱财〉。道行指修行的功夫，不能寄回家；寄回老家的应说“钱财”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位道长修行十年，有一座好道行。", "corrected_sentence": "这位道长修行十年，有一身好道行。", "error_description": "量词用错：“道行”应用“身”计量，写成“座”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只狐狸精苦修五百年，练出了一条好道行。", "corrected_sentence": "那只狐狸精苦修五百年，练出了一身好道行。", "error_description": "量词用错：“道行”应用“身”计量，写成“条”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
