INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在山里森林里的凶猛动物。", "primary_collocate": null, "pronunciation": "yě shòu", "ipa": "iɛ˨˩˦ ʂou˥˩", "syllable_count": 2, "sentences": [{"text": "山里有很多野兽，晚上不要一个人出去。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的野兽听到声音，马上跑远了。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只野兽的眼睛在黑夜里发着光。", "target_word": "野兽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人带着枪，走进了野兽很多的森林。", "target_word": "野兽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山路上遇到一头凶猛的野兽。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天食物少，野兽常常下山找吃的。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民在村子四周点火，防止野兽进来。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里山上传来野兽的叫声，孩子们都很害怕。", "target_word": "野兽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野兽受了伤，躲在山洞里不出来。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片山区有熊和狼，都是危险的野兽。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}], "register": "中性", "sense_fingerprint": "野兽：生活在山林里的凶猛动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野兽", "is_correct": true, "explanation": "野兽：生活在山林里的凶猛动物。山里的猛兽正是晚上需要防备的，与句意相合。"}, {"text": "城市", "is_correct": false, "explanation": "语义：山里不会有很多城市，与“山里”矛盾。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不会在山里成群出现，与句首语境矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“很多”一般不修饰“空气”，且空气不是晚上需要防备的东西。"}], "explanations": {"野兽": "野兽：生活在山林里的凶猛动物。山里的猛兽正是晚上需要防备的，与句意相合。", "城市": "语义：山里不会有很多城市，与“山里”矛盾。", "超市": "语义：超市不会在山里成群出现，与句首语境矛盾。", "空气": "搭配：“很多”一般不修饰“空气”，且空气不是晚上需要防备的东西。"}, "sentence_index": 0, "correct_answer": "野兽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猎人带着枪回到家，打开了一罐野兽罐头。", "explanation": "这里应该用〈肉〉。野兽指活的凶猛动物，不能装进罐头里。"}, {"text": "这只野兽很温顺，可以跟孩子一起玩。", "explanation": "这里应该用〈动物〉。野兽指凶猛的野生兽类，不能用来形容温顺、可以陪孩子玩的动物。"}, {"text": "农民在院子里养了几头野兽，每天喂它们吃草。", "explanation": "这里应该用〈家畜〉。野兽是野生的凶猛动物，不能在院子里饲养，应说“家畜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野兽", "is_correct": true, "explanation": "野兽：生活在山林里的凶猛动物。这里指会闯进村子的猛兽，与“防止……进来”相合。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：鲜花不会主动闯进村子，点火防它没有道理。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是人造的交通工具，村民点火不是为了防它。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“进来”一般不跟“玻璃”搭配，玻璃不会自己进来，也不必防。"}], "explanations": {"野兽": "野兽：生活在山林里的凶猛动物。这里指会闯进村子的猛兽，与“防止……进来”相合。", "鲜花": "语义：鲜花不会主动闯进村子，点火防它没有道理。", "汽车": "语义：汽车是人造的交通工具，村民点火不是为了防它。", "玻璃": "搭配：“进来”一般不跟“玻璃”搭配，玻璃不会自己进来，也不必防。"}, "sentence_index": 6, "correct_answer": "野兽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山林里的野兽在天上盘旋，寻找猎物。", "explanation": "这里应该用〈猛禽〉。野兽是陆地上的凶猛兽类，不会在天上盘旋；会飞的猛鸟才叫猛禽。"}, {"text": "周末我们去野兽里散步，空气很好。", "explanation": "这里应该用〈野外〉。野兽是动物，不能当作地点，去野外散步要说“去野外散步”。"}, {"text": "草原上长满了野兽，风吹过来一片绿。", "explanation": "这里应该用〈野草〉。野兽是动物，不能像草一样长满草原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上来了一个野兽，大家都躲了起来。", "corrected_sentence": "山上来了一头野兽，大家都躲了起来。", "error_description": "量词错误：“个”不用于“野兽”，应说“一头”或“一只”，“一个野兽”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山洞里躲着一本野兽，大家不敢进去。", "corrected_sentence": "山洞里躲着一头野兽，大家不敢进去。", "error_description": "量词错误：“本”用于书本，“野兽”是动物，应说“一头野兽”或“一只野兽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
