INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97498, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "野生的凶猛兽类。", "primary_collocate": null, "pronunciation": "yě shòu", "ipa": "iɛ˨˩˦ ʂou˥˩", "syllable_count": 2, "sentences": [{"text": "狮子和老虎都是凶猛的野兽。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野兽不是宠物，不能养在家里。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物园里的野兽，有的是从野外送来的。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在野外，人遇到野兽要慢慢后退。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位摄影师专门拍野外的野兽。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野兽跑得很快，人根本追不上它们。", "target_word": "野兽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上的野兽一看到火，就远远躲开了。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野兽靠鼻子找到猎物，再一口咬住。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小时候怕黑，总觉得床下有野兽。", "target_word": "野兽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护区里的野兽，不能随便喂东西给它们。", "target_word": "野兽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}], "register": "中性", "sense_fingerprint": "野兽：野生的凶猛兽类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野兽", "is_correct": true, "explanation": "野兽：野生的凶猛兽类。狮子和老虎正属于这一类，与“凶猛”相合。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：狮子和老虎不是宠物，说它们是宠物与事实不符。"}, {"text": "小猫", "is_correct": false, "explanation": "体貌：“凶猛”形容兽类的攻击性，“小猫”指体形小、模样可爱的动物，形象不合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵没有凶猛的特点，与句意不符。"}], "explanations": {"野兽": "野兽：野生的凶猛兽类。狮子和老虎正属于这一类，与“凶猛”相合。", "宠物": "语义：狮子和老虎不是宠物，说它们是宠物与事实不符。", "小猫": "体貌：“凶猛”形容兽类的攻击性，“小猫”指体形小、模样可爱的动物，形象不合。", "花朵": "语义：花朵没有凶猛的特点，与句意不符。"}, "sentence_index": 0, "correct_answer": "野兽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在野外，人走进了野兽，觉得很安静。", "explanation": "这里应该用〈树林〉。“野兽”是动物，不能当作可以走进去的地方。"}, {"text": "草原上的野兽在天上盘旋，等待猎物。", "explanation": "这里应该用〈猛禽〉。野兽是陆地上的兽类，不会在天上盘旋；会飞的凶猛鸟类才叫猛禽。"}, {"text": "那只野兽很温顺，可以抱在怀里。", "explanation": "这里应该用〈家猫〉。野兽凶猛、不能驯养，不能说它温顺到可以抱在怀里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野兽", "is_correct": true, "explanation": "野兽：野生的凶猛兽类。草原上的猛兽见了火会远远躲开，正合句意。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“躲开”要求能自主移动的主语，石头不能躲。"}, {"text": "火车", "is_correct": false, "explanation": "语义：“一看到火就远远躲开”是动物的本能反应，用在火车上不合常理。"}, {"text": "房子", "is_correct": false, "explanation": "配价：房子不能自己“躲开”，“躲开”要求能动的主语。"}], "explanations": {"野兽": "野兽：野生的凶猛兽类。草原上的猛兽见了火会远远躲开，正合句意。", "石头": "配价：“躲开”要求能自主移动的主语，石头不能躲。", "火车": "语义：“一看到火就远远躲开”是动物的本能反应，用在火车上不合常理。", "房子": "配价：房子不能自己“躲开”，“躲开”要求能动的主语。"}, "sentence_index": 6, "correct_answer": "野兽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "树上结满了野兽，我们摘下来吃。", "explanation": "这里应该用〈野果〉。野兽是动物，不能挂在树上当果实，说“结满野果”。"}, {"text": "妈妈在山上采了些野兽，回家炒着吃。", "explanation": "这里应该用〈野菜〉。野兽是动物，不能采来炒着吃，采摘的植物应说“野菜”。"}, {"text": "农场里养着几头野兽，每天喂它们饲料。", "explanation": "这里应该用〈猪〉这类家畜。野兽是野生的凶猛兽类，不能在农场里饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草原上有一张野兽。", "corrected_sentence": "草原上有一只野兽。", "error_description": "量词错误：“野兽”是动物，量词应用“只”；“张”用于纸、桌子等平面物，应说“一只野兽”，不说“一张野兽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保护区里有一把野兽，游客都不敢靠近。", "corrected_sentence": "保护区里有一只野兽，游客都不敢靠近。", "error_description": "量词错误：“把”用于有把手的东西，“野兽”是动物，应说“一只野兽”或“一头野兽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落选", "is_correct": true, "explanation": "落选：没有被录取，与“录取”意思相反。"}, {"text": "保存", "is_correct": false, "explanation": "保存：指留存、不丢失，与“录取”不构成反义。"}, {"text": "出版", "is_correct": false, "explanation": "出版：指书刊印行发表，与“录取”不构成反义。"}, {"text": "调查", "is_correct": false, "explanation": "调查：指查访、了解情况，与“录取”不构成反义。"}], "correct_answer": "落选", "explanations": {"落选": "落选：没有被录取，与“录取”意思相反。", "保存": "保存：指留存、不丢失，与“录取”不构成反义。", "出版": "出版：指书刊印行发表，与“录取”不构成反义。", "调查": "调查：指查访、了解情况，与“录取”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落选", "is_correct": true, "explanation": "落选：没有被录取，与“录取”意思相反。"}, {"text": "准备", "is_correct": false, "explanation": "准备：指事先做好安排，与“录取”没有反义关系。"}, {"text": "考虑", "is_correct": false, "explanation": "考虑：指思量、斟酌，与“录取”不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "参加：指加入某项活动，与“录取”不构成反义。"}], "correct_answer": "落选", "explanations": {"落选": "落选：没有被录取，与“录取”意思相反。", "准备": "准备：指事先做好安排，与“录取”没有反义关系。", "考虑": "考虑：指思量、斟酌，与“录取”不构成反义。", "参加": "参加：指加入某项活动，与“录取”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学校或工作的地方，选了你，你可以来。", "primary_collocate": null, "pronunciation": "lù qǔ", "ipa": "lu˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我考得很好，学校录取我了。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家公司录取了我，我下周上班。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈很高兴，因为大学录取了我姐姐。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想去那家公司工作，可是公司没录取他。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的成绩这么好，那所大学肯定会录取你。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说，那所中学录取了他。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说医院只录取了两个护士。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她申请过三所大学，只有一所录取了她。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校录取了我，我马上告诉了爸爸。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他试了两次，这次公司终于录取他了。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "录取了", "label": "体标"}, {"form": "录取过", "label": "体标"}, {"form": "录取通知书", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校或公司选中某人，同意他来上学或上班", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示学校选中学生，符合句意。"}, {"text": "开除", "is_correct": false, "explanation": "语义：“开除”是让人离开，与前句“考得很好”的语境相矛盾。"}, {"text": "辞退", "is_correct": false, "explanation": "搭配：“辞退”用于解雇员工，学校不能辞退学生。"}, {"text": "驳回", "is_correct": false, "explanation": "搭配：“驳回”用于申请、请求等，不能直接用于人。"}], "explanations": {"录取": "“录取”表示学校选中学生，符合句意。", "开除": "语义：“开除”是让人离开，与前句“考得很好”的语境相矛盾。", "辞退": "搭配：“辞退”用于解雇员工，学校不能辞退学生。", "驳回": "搭配：“驳回”用于申请、请求等，不能直接用于人。"}, "sentence_index": 0, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校录取了我的申请。", "explanation": "这里应该用〈接受〉。录取的对象是人，申请要说“接受”，不能说“录取”。"}, {"text": "这份工作录取了我。", "explanation": "这里应该用〈公司〉作主语。录取的主语必须是挑选人的学校或单位，“工作”是事物，不能挑选人，应说“公司录取了我”。"}, {"text": "我录取了那所大学。", "explanation": "这里应该用〈考上〉。录取的主语是挑选学生的学校，学生是被挑选的一方，应说“我考上了那所大学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示医院之类的机构选拔并接收人员，符合句意。"}, {"text": "保送", "is_correct": false, "explanation": "搭配：“保送”是学校为学生办理升学，医院不能保送护士。"}, {"text": "入学", "is_correct": false, "explanation": "配价：“入学”是不及物动词，不能带“两个护士”作宾语。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能带宾语，护士也不是在医院毕业。"}], "explanations": {"录取": "“录取”表示医院之类的机构选拔并接收人员，符合句意。", "保送": "搭配：“保送”是学校为学生办理升学，医院不能保送护士。", "入学": "配价：“入学”是不及物动词，不能带“两个护士”作宾语。", "毕业": "配价：“毕业”是不及物动词，不能带宾语，护士也不是在医院毕业。"}, "sentence_index": 6, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆录取了这首歌。", "explanation": "这里应该用〈收录〉。收录指把作品收进去，录取只用于选拔人员。"}, {"text": "他在比赛里被录取了第一名。", "explanation": "这里应该用〈获得〉。录取指选拔人员入学或入职，比赛名次要说“他在比赛里获得了第一名”。"}, {"text": "那家餐厅录取了这位顾客。", "explanation": "这里应该用〈接待〉。餐厅招待顾客要说“接待”；录取只用于按标准选拔人员入学或入职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校录取着我，我特别开心。", "corrected_sentence": "学校录取了我，我特别开心。", "error_description": "“录取”是一次性完成的动作，不能加“着”表示持续，应说“录取了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那所学校没录取了他，他很难过。", "corrected_sentence": "那所学校没录取他，他很难过。", "error_description": "“没”与“了”不能同用，否定句应说“没录取他”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
