INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按标准挑选并接收为学生或员工。", "primary_collocate": null, "pronunciation": "lù qǔ", "ipa": "lu˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "这所大学今年录取了三千名新生。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司录取了十个新员工。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的分数够高，学校一定会录取他。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京大学去年没有录取这个学生。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司只录取有经验的人。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校按成绩录取学生。", "target_word": "录取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是我们公司去年录取的第一个人。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医学院录取学生时，很看重成绩。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他申请过这所学校两次，学校都没有录取他。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把录取的同学叫到办公室。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "录取了", "label": "体标"}, {"form": "录取过", "label": "体标"}, {"form": "录取通知书", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校或单位按成绩、条件挑选并接收新生或新员工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示学校经过选拔接收新生，符合句意。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：“欢送”是送别，新生刚入学，与句子的意思不合。"}, {"text": "派遣", "is_correct": false, "explanation": "搭配：“派遣”用于派出人员或部队，不能用于学校招收新生。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能带“三千名新生”作宾语，且新生尚未毕业。"}], "explanations": {"录取": "“录取”表示学校经过选拔接收新生，符合句意。", "欢送": "语义：“欢送”是送别，新生刚入学，与句子的意思不合。", "派遣": "搭配：“派遣”用于派出人员或部队，不能用于学校招收新生。", "毕业": "配价：“毕业”是不及物动词，不能带“三千名新生”作宾语，且新生尚未毕业。"}, "sentence_index": 0, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他录取了北京大学。", "explanation": "这里应该用〈考上〉。录取的主语是挑选学生的学校，学生是“考上”学校，不能说“录取”学校。"}, {"text": "老板录取了一个好主意。", "explanation": "这里应该用〈采纳〉。录取指按标准挑选并接收学生或员工，对象只能是人；接受别人的主意、建议要说“采纳”。"}, {"text": "这份工作录取了我。", "explanation": "这里应该用〈公司〉作主语。录取的主语必须是挑选人的学校或单位，“工作”是事物，不能挑选人，应说“公司录取了我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示公司或学校挑选并接收人员，符合句意。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”只用于学生完成学业，不能说“公司毕业”。"}, {"text": "保送", "is_correct": false, "explanation": "搭配：“保送”是学校为学生办理升学，公司不能保送人。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”指一节课结束，与“第一个人”的语境不合。"}], "explanations": {"录取": "“录取”表示公司或学校挑选并接收人员，符合句意。", "毕业": "搭配：“毕业”只用于学生完成学业，不能说“公司毕业”。", "保送": "搭配：“保送”是学校为学生办理升学，公司不能保送人。", "下课": "语义：“下课”指一节课结束，与“第一个人”的语境不合。"}, "sentence_index": 6, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆录取了这本新书。", "explanation": "这里应该用〈收录〉。收录指把书籍、作品收进去，录取只用于选拔人员。"}, {"text": "这次比赛，我们录取了第一名。", "explanation": "这里应该用〈获得〉。比赛名次靠成绩取得，不是选拔接收入学或入职，应说“我们获得了第一名”。"}, {"text": "医院录取了那位病人。", "explanation": "这里应该用〈收治〉。医院接收病人住院治疗要说“收治”；录取只用于按标准选拔人员入学或入职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学去年没录取了我的朋友。", "corrected_sentence": "这所大学去年没录取我的朋友。", "error_description": "“没”表示否定，不能与“了”同用。否定句应去掉“了”，说“没录取我的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听说学校录取着小王，真好。", "corrected_sentence": "我听说学校录取了小王，真好。", "error_description": "“录取”是一次性完成的动作，不能加“着”表示持续，应改为“录取了小王”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97505, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“短暂”指时间很短，与“长久”构成反义关系。"}, {"text": "热烈", "is_correct": false, "explanation": "“热烈”形容气氛或感情强烈，与“长久”的时间义不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与婚姻能否维持很长时间无关，不是“长久”的反义词。"}, {"text": "宽阔", "is_correct": false, "explanation": "“宽阔”形容面积或空间大，与“长久”的时间义没有对立关系。"}], "correct_answer": "短暂", "explanations": {"短暂": "正确：“短暂”指时间很短，与“长久”构成反义关系。", "热烈": "“热烈”形容气氛或感情强烈，与“长久”的时间义不构成反义。", "明亮": "“明亮”形容光线或颜色，与婚姻能否维持很长时间无关，不是“长久”的反义词。", "宽阔": "“宽阔”形容面积或空间大，与“长久”的时间义没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97505, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“短暂”指时间很短，与“长久”构成反义关系。"}, {"text": "艰难", "is_correct": false, "explanation": "“艰难”形容处境或事情困难，与“长久”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、清晰，与“长久”的时间义不构成反义。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容空间广大，与“长久”的时间义没有对立关系。"}], "correct_answer": "短暂", "explanations": {"短暂": "正确：“短暂”指时间很短，与“长久”构成反义关系。", "艰难": "“艰难”形容处境或事情困难，与“长久”没有反义关系。", "清楚": "“清楚”形容明白、清晰，与“长久”的时间义不构成反义。", "辽阔": "“辽阔”形容空间广大，与“长久”的时间义没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97505, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以过很长很长的时间。", "primary_collocate": null, "pronunciation": "cháng jiǔ", "ipa": "tʂʰɑŋ˧˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这样的好日子不会长久。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们希望这份友谊能长久。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "靠骗人得来的钱，不可能长久。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们希望自己的婚姻能长久。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店能长久开下去吗？", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长久的和平是大家的希望。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种办法只能用一时，不能长久。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情要长久，需要两个人一起努力。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "希望我们两家公司能长久合作。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好景不常在，好花也不会长久。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "长久地", "label": "状语形式"}, {"form": "长久的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "指事物能够维持很长的时间，多用于说明将来能否持续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长久", "is_correct": true, "explanation": "正确：“长久”指能持续很长时间，与“不会”搭配，说明这样的好日子持续不了多久。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容明白、分明，与好日子能否持续没有关系，句子说不通。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面不光滑，不能用来修饰“好日子”。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”形容人的狠毒态度，不能用来描述好日子能否持续，句子说不通。"}], "explanations": {"长久": "正确：“长久”指能持续很长时间，与“不会”搭配，说明这样的好日子持续不了多久。", "清楚": "语义：“清楚”形容明白、分明，与好日子能否持续没有关系，句子说不通。", "粗糙": "搭配：“粗糙”形容表面不光滑，不能用来修饰“好日子”。", "凶狠": "语义：“凶狠”形容人的狠毒态度，不能用来描述好日子能否持续，句子说不通。"}, "sentence_index": 0, "correct_answer": "长久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路很长久，走了一整天还没到。", "explanation": "这里应该用〈长〉。“长久”说的是时间持续得久，描写路的远近、长短要用“长”。"}, {"text": "他拿到了长久居留证，可以在这里定居。", "explanation": "这里应该用〈永久〉。“永久居留证”是固定说法，表示没有期限；“长久”只说持续的时间长，不能这样用。"}, {"text": "他跑步的耐力很长久，跑了很远也不累。", "explanation": "这里应该用〈持久〉。耐力、颜料效果等多用“持久”，“长久”多用于关系、日子、和平等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长久", "is_correct": true, "explanation": "正确：“长久”表示能持续很久，与“不能”搭配，说明办法不能持续下去。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与“办法只能用一时”的意思无关，句子说不通。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”形容速度快，不用来说办法能否持续，放在这里不通。"}, {"text": "光亮", "is_correct": false, "explanation": "搭配：“光亮”形容发光或表面明亮，不能用来评价办法能否持续。"}], "explanations": {"长久": "正确：“长久”表示能持续很久，与“不能”搭配，说明办法不能持续下去。", "热闹": "语义：“热闹”形容场面喧闹，与“办法只能用一时”的意思无关，句子说不通。", "迅速": "搭配：“迅速”形容速度快，不用来说办法能否持续，放在这里不通。", "光亮": "搭配：“光亮”形容发光或表面明亮，不能用来评价办法能否持续。"}, "sentence_index": 6, "correct_answer": "长久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他长久地眨了一下眼，然后笑了。", "explanation": "这里应该用〈一瞬间〉。眨眼是瞬间完成的动作，“长久”指持续很久，不能修饰极短的动作；表示时间极短要用“一瞬间”。"}, {"text": "这根绳子很长久，可以绕房子一圈。", "explanation": "这里应该用〈长〉。“长久”说的是时间持续得久，说绳子的长短要用“长”。"}, {"text": "这位老人的寿命很长久，活到了一百零五岁。", "explanation": "这里应该用〈长寿〉。说人活得久要用“长寿”或“寿命长”，“长久”指持续的时间，不说“寿命很长久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合作能长久的，离不开双方的努力。", "corrected_sentence": "这份合作能长久，离不开双方的努力。", "error_description": "“长久”作谓语（“能长久”）后面不能加“的”，应写成“能长久”，加“的”后句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门手艺能长久的传下去，靠的是师傅的耐心。", "corrected_sentence": "这门手艺能长久地传下去，靠的是师傅的耐心。", "error_description": "“长久”修饰动词“传”时要用状语形式“长久地”，写成“长久的”是错误的，“的”用于修饰名词，不能放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97506, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“短暂”指持续的时间很短，与“长久”构成反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容身材或建筑的体积，与“长久”的时间义不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与“长久”没有反义关系。"}, {"text": "嘹亮", "is_correct": false, "explanation": "“嘹亮”形容声音高亢，与“长久”的时间义没有对立关系。"}], "correct_answer": "短暂", "explanations": {"短暂": "正确：“短暂”指持续的时间很短，与“长久”构成反义关系。", "高大": "“高大”形容身材或建筑的体积，与“长久”的时间义不构成反义。", "柔软": "“柔软”形容质地，与“长久”没有反义关系。", "嘹亮": "“嘹亮”形容声音高亢，与“长久”的时间义没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97506, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“短暂”指时间很短，与“长久”构成反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "“宽阔”形容空间广大，与“长久”的时间义没有对立关系。"}, {"text": "艰难", "is_correct": false, "explanation": "“艰难”形容处境或事情困难，与“长久”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、清晰，与“长久”的时间义不构成反义。"}], "correct_answer": "短暂", "explanations": {"短暂": "正确：“短暂”指时间很短，与“长久”构成反义关系。", "宽阔": "“宽阔”形容空间广大，与“长久”的时间义没有对立关系。", "艰难": "“艰难”形容处境或事情困难，与“长久”没有反义关系。", "清楚": "“清楚”形容明白、清晰，与“长久”的时间义不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97506, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "时间很长；持续很久。", "primary_collocate": null, "pronunciation": "cháng jiǔ", "ipa": "tʂʰɑŋ˧˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "长久以来，他一直住在这个小镇。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们长久地站在门口，谁也没说话。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长久的等待让她很累。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她长久地望着窗外。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种长久的沉默让人难受。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长久的阴雨让大家心情不好。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们长久没有见面了。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长久的练习让他的手变得很稳。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个长久存在的问题。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长久在外工作的他，很想念家乡。", "target_word": "长久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "长久地", "label": "状语形式"}, {"form": "长久的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "指某种状态或动作已经持续了很长的时间，多用于描述过去到现在的时间长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长久", "is_correct": true, "explanation": "正确：“长久以来”表示从过去一直持续到现在，这几个选项中只有“长久”能和“以来”搭配。"}, {"text": "热烈", "is_correct": false, "explanation": "搭配：“以来”前只能接表示时间持续的词，“热烈”不能这样用，句子不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能与“以来”组成时间起点的说法。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容声音很小、很安静，与“他一直住在这个小镇”的时间叙述无关。"}], "explanations": {"长久": "正确：“长久以来”表示从过去一直持续到现在，这几个选项中只有“长久”能和“以来”搭配。", "热烈": "搭配：“以来”前只能接表示时间持续的词，“热烈”不能这样用，句子不通。", "明亮": "搭配：“明亮”形容光线或颜色，不能与“以来”组成时间起点的说法。", "寂静": "语义：“寂静”形容声音很小、很安静，与“他一直住在这个小镇”的时间叙述无关。"}, "sentence_index": 0, "correct_answer": "长久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河很长久，流经了好几个省。", "explanation": "这里应该用〈长〉。“长久”说的是时间持续得久，描写河流的长短要用“长”。"}, {"text": "这台电脑运行速度很长久，打开文件要等半天。", "explanation": "这里应该用〈快〉。描述速度要用“快”或“慢”，“长久”只说时间持续得久，不能用来形容速度。"}, {"text": "他长久地打了一个喷嚏。", "explanation": "这里应该用〈一下子〉。打喷嚏是瞬间完成的动作，表示极短的时间要用“一下子”，“长久”指持续很久，不能修饰瞬间动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长久", "is_correct": true, "explanation": "正确：“长久没有见面”是常用说法，表示很长时间没有见面，只有“长久”能放在这里。"}, {"text": "灿烂", "is_correct": false, "explanation": "语义：“灿烂”形容光彩耀眼，与“没有见面”的时间状态无关，句子说不通。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等物体，不能修饰“见面”。"}, {"text": "苍白", "is_correct": false, "explanation": "搭配：“苍白”形容脸色或颜色，不能用来说明见面的时间。"}], "explanations": {"长久": "正确：“长久没有见面”是常用说法，表示很长时间没有见面，只有“长久”能放在这里。", "灿烂": "语义：“灿烂”形容光彩耀眼，与“没有见面”的时间状态无关，句子说不通。", "锋利": "搭配：“锋利”形容刀刃等物体，不能修饰“见面”。", "苍白": "搭配：“苍白”形容脸色或颜色，不能用来说明见面的时间。"}, "sentence_index": 6, "correct_answer": "长久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的耐力很长久，跑了一个小时也不累。", "explanation": "这里应该用〈持久〉。耐力、效果等多用“持久”，不说“耐力很长久”。"}, {"text": "这台机器的音量很长久，吵得大家睡不着。", "explanation": "这里应该用〈大〉。音量大小要说“大”或“小”，“长久”只说时间持续得久，不能形容音量。"}, {"text": "他的个子很长久，比同龄人高出一头。", "explanation": "这里应该用〈高〉。形容身高要说“高”，“长久”只说时间持续得久，不能形容身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她长久的站在路口，等着一个人。", "corrected_sentence": "她长久地站在路口，等着一个人。", "error_description": "“长久”修饰动词“站”时要用状语形式“长久地”，写成“长久的”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长久的坐在椅子上，一动不动。", "corrected_sentence": "他长久地坐在椅子上，一动不动。", "error_description": "“长久”修饰动词“坐”时要用状语形式“长久地”，“的”用于修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
