INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在一块地里种两种以上不同的庄稼。", "primary_collocate": null, "pronunciation": "jiàn zuò", "ipa": "tɕjɛn˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "这块地实行间作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "间作让这块田的收成更好。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的地多年来都是间作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "间作的田里有麦子和棉花。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业课上，老师讲了间作和轮作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "间作可以让土地更肥。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片田是间作，不是单种。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸打算明年改成间作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用间作来多收粮食。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，这是间作的玉米和花生。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "间作套种", "label": "复合"}], "register": "书面", "sense_fingerprint": "在一块地里种两种以上不同的庄稼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农药", "is_correct": false, "explanation": "搭配：“实行”后接政策或方法，“农药”是物质，不说“实行农药”。"}, {"text": "水稻", "is_correct": false, "explanation": "语义：水稻是作物，不是可以实行的做法。"}, {"text": "间作", "is_correct": true, "explanation": "正确：间作是在一块地里种两种以上庄稼的做法，可以“实行”。"}, {"text": "农具", "is_correct": false, "explanation": "语义：农具是工具，不是可以“实行”的做法，句子不通。"}], "explanations": {"农药": "搭配：“实行”后接政策或方法，“农药”是物质，不说“实行农药”。", "水稻": "语义：水稻是作物，不是可以实行的做法。", "间作": "正确：间作是在一块地里种两种以上庄稼的做法，可以“实行”。", "农具": "语义：农具是工具，不是可以“实行”的做法，句子不通。"}, "sentence_index": 0, "correct_answer": "间作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块田去年种麦子，今年换成棉花，这叫间作。", "explanation": "这里应该用〈轮作〉。轮作是不同季节换着种，间作是同一时期在同一块地上种不同作物。"}, {"text": "这块田只种棉花，这就是间作。", "explanation": "这里应该用〈单种〉。间作要在同一块地上种两种以上作物，只种棉花应说单种。"}, {"text": "这块田一半种麦子，一半闲着，农民管这叫间作。", "explanation": "这里应该用〈休耕〉。休耕是让部分土地闲置不种，间作要在同一块地里同时种两种以上作物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收成", "is_correct": false, "explanation": "语义：收成是收获的结果，不能与“单种”对照成一种种植方式。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：灌溉是浇水的动作，不是种植方式，不能与“单种”对照。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，不适合这样的书面对照，也不指种植方法。"}, {"text": "间作", "is_correct": true, "explanation": "正确：间作与单种相对，指在同一块地上种两种以上作物，符合“是……不是单种”的对照。"}], "explanations": {"收成": "语义：收成是收获的结果，不能与“单种”对照成一种种植方式。", "灌溉": "语义：灌溉是浇水的动作，不是种植方式，不能与“单种”对照。", "玩意儿": "语域：“玩意儿”是口语，不适合这样的书面对照，也不指种植方法。", "间作": "正确：间作与单种相对，指在同一块地上种两种以上作物，符合“是……不是单种”的对照。"}, "sentence_index": 6, "correct_answer": "间作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块田连着几年种棉花，这就是间作。", "explanation": "这里应该用〈连作〉。连作是同一块地连年种同一种作物，间作是同时种不同作物。"}, {"text": "收完麦子马上种玉米，也就是间作。", "explanation": "这里应该用〈复种〉。复种是一年内先后种几季，间作是同一时期种不同作物。"}, {"text": "这块田一年到头只种一种作物，农民管这叫间作。", "explanation": "这里应该用〈单种〉。间作要在一块地里种两种以上作物，只种一种应说单种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家今年改成了一条间作。", "corrected_sentence": "他家今年改成了一种间作。", "error_description": "量词错误：“间作”的量词应是“种”，“条”用于细长的东西，不能用于种植方法。应改为“一种间作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看，这是一条间作，玉米和花生一起种。", "corrected_sentence": "看，这是一种间作，玉米和花生一起种。", "error_description": "量词错误：“间作”的量词应是“种”，“条”用于细长的东西，不能修饰种植方法。应改为“一种间作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
