INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在同一块田地上相间种植不同作物的方法。", "primary_collocate": null, "pronunciation": "jiàn zuò", "ipa": "tɕjɛn˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "这块地用的是间作的方法。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "间作可以更好地利用土地。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在玉米中间种豆子，这就是间作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "间作能减少病虫害。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学了间作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，间作比单种好。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的果园也用间作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "间作要选合适的作物。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子多年来一直用间作。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了间作的好处。", "target_word": "间作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "间作套种", "label": "复合"}], "register": "书面", "sense_fingerprint": "在同一块田地上相间种植不同作物的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水稻", "is_correct": false, "explanation": "语义：水稻是作物名，不是种植方法，不能放在“用的是……的方法”里。"}, {"text": "间作", "is_correct": true, "explanation": "正确：间作指在同一块田里相间种植不同作物的方法，正好放在“方法”前。"}, {"text": "农具", "is_correct": false, "explanation": "语义：农具是工具，不是种植方法，不能说“用的是农具的方法”。"}, {"text": "病虫害", "is_correct": false, "explanation": "搭配：“用”后接的是方法或工具，“病虫害”是要防治的对象，不说“用病虫害的方法”。"}], "explanations": {"水稻": "语义：水稻是作物名，不是种植方法，不能放在“用的是……的方法”里。", "间作": "正确：间作指在同一块田里相间种植不同作物的方法，正好放在“方法”前。", "农具": "语义：农具是工具，不是种植方法，不能说“用的是农具的方法”。", "病虫害": "搭配：“用”后接的是方法或工具，“病虫害”是要防治的对象，不说“用病虫害的方法”。"}, "sentence_index": 0, "correct_answer": "间作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地今年种玉米，明年改种花生，这就是间作。", "explanation": "这里应该用〈轮作〉。轮作是不同季节换着种，间作是同一时期在同一块地上种两种以上作物。"}, {"text": "这块地只种小麦，这就是间作。", "explanation": "这里应该用〈单种〉。间作要在同一块地上种两种以上作物，只种小麦应说单种。"}, {"text": "玉米收完以后，同一年里又在这块地上种了花生，这叫间作。", "explanation": "这里应该用〈复种〉。复种是一年内在同一块地上先后种几季，间作是同一时期在同一块地上相间种植不同作物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收成", "is_correct": false, "explanation": "语义：收成是收获的结果，不能作为可以“用”的种植方式。"}, {"text": "间作", "is_correct": true, "explanation": "正确：间作是在同一块地上相间种植不同作物的方法，符合“用间作”的说法。"}, {"text": "地貌", "is_correct": false, "explanation": "语义：地貌指地表的形态，果园不能“用”它来种植。"}, {"text": "病害", "is_correct": false, "explanation": "搭配：“用”不接病害，应说“防治病害”。"}], "explanations": {"收成": "语义：收成是收获的结果，不能作为可以“用”的种植方式。", "间作": "正确：间作是在同一块地上相间种植不同作物的方法，符合“用间作”的说法。", "地貌": "语义：地貌指地表的形态，果园不能“用”它来种植。", "病害": "搭配：“用”不接病害，应说“防治病害”。"}, "sentence_index": 6, "correct_answer": "间作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地连续三年种玉米，农民管这叫间作。", "explanation": "这里应该用〈连作〉。连作是同一块地连年种同一种作物，间作是同时种不同作物。"}, {"text": "收完小麦后马上种玉米，这种做法是间作。", "explanation": "这里应该用〈复种〉。复种是一年内先后种几季，间作是同一时期在同一块地上种不同作物。"}, {"text": "玉米收完以后，这块地整个冬天都空着不种，农民管这叫间作。", "explanation": "这里应该用〈休耕〉。休耕是让土地闲置不种一段时间，间作要在同一时期种两种以上作物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地用的是一根间作。", "corrected_sentence": "这块地用的是一种间作。", "error_description": "量词错误：“间作”是一种方法，量词应用“种”，“根”用于细长的东西。应改为“一种间作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地的间作得很好。", "corrected_sentence": "这块地的间作做得很好。", "error_description": "补语错误：“这块地的间作”是名词性短语，后面不能直接接“得”补语；应在“间作”前加动词“做”，说“做得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
