INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97513, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最重要，要先做的。", "primary_collocate": null, "pronunciation": "shǒu yào", "ipa": "ʂoʊ˨˩˦ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "学好汉语是我的首要任务。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在首要的事是找到工作。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了新城市，首要问题是住在哪里。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨了，首要的事是找地方避雨。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说，安全是工作中的首要条件。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对学生来说，首要的事是认真听课。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把读书看作首要的事。", "target_word": "首要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧了，妈妈的首要任务是送他去医院。", "target_word": "首要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭之前，洗手是首要的一步。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经说过，首要的工作是修好路。", "target_word": "首要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首要任务", "label": "复合"}], "register": "中性", "sense_fingerprint": "最重要、必须最先去做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首要", "is_correct": true, "explanation": "“首要”表示最重要，修饰“任务”，符合句意。"}, {"text": "免费", "is_correct": false, "explanation": "搭配：“免费”说的是收费与否，不能修饰“任务”。"}, {"text": "精美", "is_correct": false, "explanation": "搭配：“精美”形容物品或作品，不能修饰“任务”。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”描述温度或感受，与句子表达的意思不合。"}], "explanations": {"首要": "“首要”表示最重要，修饰“任务”，符合句意。", "免费": "搭配：“免费”说的是收费与否，不能修饰“任务”。", "精美": "搭配：“精美”形容物品或作品，不能修饰“任务”。", "寒冷": "语义：“寒冷”描述温度或感受，与句子表达的意思不合。"}, "sentence_index": 0, "correct_answer": "首要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "首要，你要先洗手。", "explanation": "这里应该用〈首先〉。首要是形容词，表示“最重要”，不用来引出先后顺序。"}, {"text": "他是我们班的首要学生。", "explanation": "这里应该用〈优秀〉。首要强调事情的重要程度，形容学生成绩好、能力强要用“优秀”。"}, {"text": "他是这家公司的首要设计师。", "explanation": "这里应该用〈首席〉。首席是职务名称，如“首席设计师”；首要只表示“最重要”，不能用来指职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首要", "is_correct": true, "explanation": "“首要”表示最重要，修饰“的事”，符合句意。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水或眼神，与“读书”这件事的意思不合。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体质地，不能修饰“事”。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”描述空间，不能用来评价一件事。"}], "explanations": {"首要": "“首要”表示最重要，修饰“的事”，符合句意。", "清澈": "语义：“清澈”形容水或眼神，与“读书”这件事的意思不合。", "柔软": "搭配：“柔软”形容物体质地，不能修饰“事”。", "狭窄": "语义：“狭窄”描述空间，不能用来评价一件事。"}, "sentence_index": 6, "correct_answer": "首要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们首要见面是在北京。", "explanation": "这里应该用〈首次〉。首要表示最重要，不表示“第一次”。"}, {"text": "首要去北京开会。", "explanation": "这里应该用〈先〉。表示动作的先后用副词“先”；首要只表示“最重要”，不能作状语。"}, {"text": "他是全班首要到教室的人。", "explanation": "这里应该用〈第一个〉。首要表示“最重要”，不表示顺序上的第一个；应说“第一个到教室的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
