INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97514, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最重要的；放在第一位的。", "primary_collocate": null, "pronunciation": "shǒu yào", "ipa": "ʂoʊ˨˩˦ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "公司的首要目标是让客户满意。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛，安全是首要原则。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在他心里，家人永远排在首要位置。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济发展是这个国家的首要问题。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对老年人来说，健康是首要的。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，找出病因是治病的首要一步。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的首要任务是治理污染。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "质量是我们公司的首要追求，价格排在后面。", "target_word": "首要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把学生的安全当作首要责任。", "target_word": "首要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们当前的首要工作，别忘了。", "target_word": "首要", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "首要任务", "label": "复合"}], "register": "书面语", "sense_fingerprint": "在众多事项中最重要、应排在第一位的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首要", "is_correct": true, "explanation": "“首要”表示最重要，修饰“目标”，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”描述空气或物体，不能修饰“目标”。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”描述温度，与“目标”的意思不合。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人或声音的状态，不能用来修饰“目标”。"}], "explanations": {"首要": "“首要”表示最重要，修饰“目标”，符合句意。", "潮湿": "搭配：“潮湿”描述空气或物体，不能修饰“目标”。", "寒冷": "语义：“寒冷”描述温度，与“目标”的意思不合。", "沉默": "语义：“沉默”形容人或声音的状态，不能用来修饰“目标”。"}, "sentence_index": 0, "correct_answer": "首要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "首要，我们先讨论一下方案。", "explanation": "这里应该用〈首先〉。首要是形容词，表示“最重要”，不用来表示先后。"}, {"text": "我们公司有很多首要员工。", "explanation": "这里应该用〈优秀〉。首要强调事情的重要程度，形容员工能力突出要用“优秀”。"}, {"text": "这件衣服很首要。", "explanation": "这里应该用〈漂亮〉。首要表示“最重要”，不用来形容衣服；形容衣服好看要用“漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首要", "is_correct": true, "explanation": "“首要”表示最重要，修饰“任务”，符合句意。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体质地，不能修饰“任务”。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水或眼神，与“治理污染”的语境不合。"}, {"text": "炽热", "is_correct": false, "explanation": "语义：“炽热”形容温度或感情，不能用来修饰“任务”。"}], "explanations": {"首要": "“首要”表示最重要，修饰“任务”，符合句意。", "柔软": "搭配：“柔软”形容物体质地，不能修饰“任务”。", "清澈": "语义：“清澈”形容水或眼神，与“治理污染”的语境不合。", "炽热": "语义：“炽热”形容温度或感情，不能用来修饰“任务”。"}, "sentence_index": 6, "correct_answer": "首要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是他首要参加比赛。", "explanation": "这里应该用〈首次〉。首要表示最重要，不表示“第一次”。"}, {"text": "上课时，首要我们要认真听讲。", "explanation": "这里应该用〈首先〉。首先是副词，表示先后顺序；首要是形容词，表示“最重要”，不能这样作状语。"}, {"text": "他跑得很首要。", "explanation": "这里应该用〈快〉。首要表示“最重要”，不能作补语说动作快慢；描述跑的速度要用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的首要了目标是提高质量。", "corrected_sentence": "我们的首要目标是提高质量。", "error_description": "“首要”是形容词，后面不能加“了”，应说“我们的首要目标”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的首要地任务是改善交通。", "corrected_sentence": "这个城市的首要任务是改善交通。", "error_description": "“首要地任务”错在“地”。“首要”修饰名词“任务”时不用“地”，应说“首要任务”，即“这个城市的首要任务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
