INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一群人里最大的头儿。", "primary_collocate": null, "pronunciation": "shǒu lǐng", "ipa": "ʂoʊ˨˩˦ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个部落的首领是一位老人。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都听首领的话。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首领站起来，对大家说了几句话。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这群人的首领，大家都很尊敬他。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首领带着部落的人搬到了河边。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新首领是大家一起选出来的。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首领把食物分给了每个人。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人请首领来决定这件事。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老首领年纪大了，不再出门打猎。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部落的首领住在山边的大房子里。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "首领：一群人里最大的头儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97517, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首领", "is_correct": true, "explanation": "正确答案。首领指一群人里最大的头儿。"}, {"text": "受领", "is_correct": false, "explanation": "受领的受字 shòu（第四声）与首领的首字 shǒu（第三声）声调不同，受领意思是接受（任务、物资）。"}, {"text": "守灵", "is_correct": false, "explanation": "守灵的灵字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，守灵指在灵柩旁守夜。"}, {"text": "手铃", "is_correct": false, "explanation": "手铃的铃字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，手铃指手里拿着摇的小铃。"}], "explanations": {"首领": "正确答案。首领指一群人里最大的头儿。", "受领": "受领的受字 shòu（第四声）与首领的首字 shǒu（第三声）声调不同，受领意思是接受（任务、物资）。", "守灵": "守灵的灵字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，守灵指在灵柩旁守夜。", "手铃": "手铃的铃字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，手铃指手里拿着摇的小铃。"}, "sentence_index": null, "correct_answer": "首领"}, "level_3": {"options": [{"text": "首领", "is_correct": true, "explanation": "首领指部落的头目，可以用量词“位”数，与“部落”“老人”的语境相符。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是人，不能说“是一位老人”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“房子”。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”与“老人”矛盾，句子说的是一位老人。"}], "explanations": {"首领": "首领指部落的头目，可以用量词“位”数，与“部落”“老人”的语境相符。", "树": "语义：树不是人，不能说“是一位老人”。", "房子": "搭配：量词“位”只用于人，不能修饰“房子”。", "孩子": "语义：“孩子”与“老人”矛盾，句子说的是一位老人。"}, "sentence_index": 0, "correct_answer": "首领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵大树的首领很粗，两个人才抱得住。", "explanation": "这里应该用〈主干〉。首领指人群中的头儿，树的粗干应称主干。"}, {"text": "这首歌的首领很好听，大家都爱唱。", "explanation": "这里应该用〈主旋律〉。首领指人群中的头儿，歌曲的主要旋律应称主旋律。"}, {"text": "这篇文章的首领写得很清楚。", "explanation": "这里应该用〈主旨〉。首领指人群中的头儿，文章的中心意思应称主旨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首领", "is_correct": true, "explanation": "首领指能把食物分给大家的头目，与“分给了每个人”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能把食物分给每个人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能分配食物，句子说的是有人把食物分给大家。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“分给每个人”要求施事能分配东西，“河流”不能与“分给”搭配。"}], "explanations": {"首领": "首领指能把食物分给大家的头目，与“分给了每个人”相合。", "桌子": "语义：桌子不能把食物分给每个人。", "石头": "语义：石头不能分配食物，句子说的是有人把食物分给大家。", "河流": "搭配：“分给每个人”要求施事能分配东西，“河流”不能与“分给”搭配。"}, "sentence_index": 6, "correct_answer": "首领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的首领有两千米高，山顶常年有雪。", "explanation": "这里应该用〈主峰〉。首领指人群中的头儿，山的最高峰应称主峰。"}, {"text": "这条河的首领流过了三个省。", "explanation": "这里应该用〈干流〉。首领指人群中的头儿，河流的主干应称干流。"}, {"text": "这个句子的首领是“我”。", "explanation": "这里应该用〈主语〉。首领指人群中的头儿，句子的主体成分要用主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个部落的一只首领很有智慧，大家都服他。", "corrected_sentence": "这个部落的一位首领很有智慧，大家都服他。", "error_description": "量词错误：“首领”指人，应用量词“位”，不能用“只”（“只”多用于动物）。错误形式是“一只首领”，正确形式是“一位首领”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位首领一起去着山里。", "corrected_sentence": "三位首领一起去了山里。", "error_description": "体标错误：“去”后表示已完成的动作应用“了”，不能用“着”。“着”表示持续状态，“去着山里”不成立，正确形式为“一起去了山里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
