INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "领头的人；集团的头目。", "primary_collocate": null, "pronunciation": "shǒu lǐng", "ipa": "ʂoʊ˨˩˦ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察抓住了这伙强盗的首领。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织的首领一直躲在国外。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个犯罪集团的首领。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首领下令，手下人马上行动。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把这伙人的首领带到了警察局。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首领给手下的人发了很多钱。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗首领拿着刀站在船头。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是这个团伙的首领，没人知道。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的首领最后输了。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都怕这个首领，不敢说真话。", "target_word": "首领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "首领：领头的人、集团的头目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97518, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首领", "is_correct": true, "explanation": "正确答案。首领指领头的人、集团的头目。"}, {"text": "受领", "is_correct": false, "explanation": "受领的受字 shòu（第四声）与首领的首字 shǒu（第三声）声调不同，受领意思是接受（任务、物资）。"}, {"text": "守灵", "is_correct": false, "explanation": "守灵的灵字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，守灵指在灵柩旁守夜。"}, {"text": "手铃", "is_correct": false, "explanation": "手铃的铃字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，手铃指手里拿着摇的小铃。"}, {"text": "收领", "is_correct": false, "explanation": "收领的收字 shōu（第一声）与首领的首字 shǒu（第三声）声调不同，收领指收下、接受。"}], "explanations": {"首领": "正确答案。首领指领头的人、集团的头目。", "受领": "受领的受字 shòu（第四声）与首领的首字 shǒu（第三声）声调不同，受领意思是接受（任务、物资）。", "守灵": "守灵的灵字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，守灵指在灵柩旁守夜。", "手铃": "手铃的铃字 líng（第二声）与首领的领字 lǐng（第三声）声调不同，手铃指手里拿着摇的小铃。", "收领": "收领的收字 shōu（第一声）与首领的首字 shǒu（第三声）声调不同，收领指收下、接受。"}, "sentence_index": null, "correct_answer": "首领"}, "level_3": {"options": [{"text": "首领", "is_correct": true, "explanation": "首领指强盗团伙的头目，与“强盗”“这伙”的语境一致。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察与强盗对立，句中被抓的强盗的头目不能是警察。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不是人，不能是被警察抓住的强盗头目。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师与“强盗”的身份矛盾，句子说的是一伙强盗的头目。"}], "explanations": {"首领": "首领指强盗团伙的头目，与“强盗”“这伙”的语境一致。", "警察": "语义：警察与强盗对立，句中被抓的强盗的头目不能是警察。", "花": "语义：花不是人，不能是被警察抓住的强盗头目。", "老师": "语义：老师与“强盗”的身份矛盾，句子说的是一伙强盗的头目。"}, "sentence_index": 0, "correct_answer": "首领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的首领很宽，两辆车可以并排开。", "explanation": "这里应该用〈主干道〉。首领指领头的人，道路的主干应称主干道。"}, {"text": "这部手机的首领坏了，要拿去修。", "explanation": "这里应该用〈主板〉。首领指领头的人，手机里最核心的电路板应称主板。"}, {"text": "这份计划的首领写得很清楚。", "explanation": "这里应该用〈纲要〉。首领指领头的人，计划的总体框架应称纲要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首领", "is_correct": true, "explanation": "首领指海盗的头目，能拿着刀站在船头，与“海盗”相合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能拿着刀站在船头。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“海盗”修饰的应是人或船只，不能修饰“雨”。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能拿着刀站立，句子说的是一个人站在船头。"}], "explanations": {"首领": "首领指海盗的头目，能拿着刀站在船头，与“海盗”相合。", "窗户": "语义：窗户不能拿着刀站在船头。", "雨": "搭配：“海盗”修饰的应是人或船只，不能修饰“雨”。", "河": "语义：河不能拿着刀站立，句子说的是一个人站在船头。"}, "sentence_index": 6, "correct_answer": "首领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的首领很难理解。", "explanation": "这里应该用〈题干〉。首领指领头的人，题目的主要陈述部分应称题干。"}, {"text": "这顿饭的首领很好吃，大家都夸。", "explanation": "这里应该用〈主菜〉。首领指领头的人，一顿饭里最重要的那道菜应称主菜。"}, {"text": "首领带我们参观了博物馆。", "explanation": "这里应该用〈导游〉。首领指群体的头目，带游客参观要用导游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那伙强盗的一根首领很狡猾，大家都怕他。", "corrected_sentence": "那伙强盗的一个首领很狡猾，大家都怕他。", "error_description": "量词错误：“首领”指人，应用量词“个”（或“名”），不能用“根”（“根”用于细长的东西）。错误形式是“一根首领”，正确形式是“一个首领”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察抓住了三条首领。", "corrected_sentence": "警察抓住了三名首领。", "error_description": "量词错误：“首领”指人，应用量词“名”或“个”，不能用“条”（“条”多用于细长的东西）。错误形式是“三条首领”，正确形式是“三名首领”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
