INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97521, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "套在头发上，让头发不乱的小网。", "primary_collocate": null, "pronunciation": "fà wǎng", "ipa": "fa˥˩ waŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈用发网把长头发包起来。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳舞以前，她戴上了一个黑色的发网。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发网很小，只能套住头发。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在商店买了两个新发网。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天早上都用发网固定发型。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师戴着发网，头发不会掉进汤里。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈老师说，头发要先用发网套好。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的发网坏了，头发一直散下来。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的发网是红色的，很好看。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完澡，姐姐把发网从头上拿了下来。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "發網", "label": "繁体"}], "register": "中性", "sense_fingerprint": "套在头发上、固定头发的小网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97521, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发网", "is_correct": true, "explanation": "正确：发网（fà wǎng）指套在头发上、让头发不乱的小网。"}, {"text": "发往", "is_correct": false, "explanation": "发往 fā wǎng 第一音节是第一声，与 fà 声调不同，意思是“发送到”。"}, {"text": "放网", "is_correct": false, "explanation": "放网 fàng wǎng 第一音节多了韵尾 ng，声调相同，意思是“撒网”。"}, {"text": "法网", "is_correct": false, "explanation": "法网 fǎ wǎng 第一音节是第三声，与 fà 声调不同，指法律的约束。"}], "explanations": {"发网": "正确：发网（fà wǎng）指套在头发上、让头发不乱的小网。", "发往": "发往 fā wǎng 第一音节是第一声，与 fà 声调不同，意思是“发送到”。", "放网": "放网 fàng wǎng 第一音节多了韵尾 ng，声调相同，意思是“撒网”。", "法网": "法网 fǎ wǎng 第一音节是第三声，与 fà 声调不同，指法律的约束。"}, "sentence_index": null, "correct_answer": "发网"}, "level_3": {"options": [{"text": "锅", "is_correct": false, "explanation": "语义：锅是炊具，不能用来包住头发。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不能用来把头发包起来。"}, {"text": "扫帚", "is_correct": false, "explanation": "搭配：“扫帚”与“扫”搭配，不说用它“包”头发。"}, {"text": "发网", "is_correct": true, "explanation": "正确：发网是套在头发上的网，可以把长头发包起来。"}], "explanations": {"锅": "语义：锅是炊具，不能用来包住头发。", "钥匙": "语义：钥匙是开锁的工具，不能用来把头发包起来。", "扫帚": "搭配：“扫帚”与“扫”搭配，不说用它“包”头发。", "发网": "正确：发网是套在头发上的网，可以把长头发包起来。"}, "sentence_index": 0, "correct_answer": "发网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用发网把刘海别住。", "explanation": "这里应该用〈发夹〉。发夹用来别住头发，发网是套在头上的网，不能用来别刘海。"}, {"text": "她用发网梳头，把头发理顺。", "explanation": "这里应该用〈梳子〉。梳子用来梳理头发，发网只是套住头发，不能用来梳头。"}, {"text": "夏天她戴着发网出门，用来遮阳。", "explanation": "这里应该用〈草帽〉。草帽能遮阳，发网只是套住头发，不能用来遮阳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碗", "is_correct": false, "explanation": "语义：碗是盛东西的器皿，不能套在头发上。"}, {"text": "发网", "is_correct": true, "explanation": "正确：发网可以用来套住头发，“套好”的对象正是头发。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“套”需要有形的套子，不说“用水套好”。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔是写字的工具，不能套住头发。"}], "explanations": {"碗": "语义：碗是盛东西的器皿，不能套在头发上。", "发网": "正确：发网可以用来套住头发，“套好”的对象正是头发。", "水": "搭配：“套”需要有形的套子，不说“用水套好”。", "笔": "语义：笔是写字的工具，不能套住头发。"}, "sentence_index": 6, "correct_answer": "发网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用发网把课本包起来，免得弄脏。", "explanation": "这里应该用〈书皮〉。书皮用来包书，发网是套在头上的网，太小，不能用来包书。"}, {"text": "她给手机套上了发网，防止摔坏。", "explanation": "这里应该用〈手机壳〉。手机壳能保护手机，发网只是套住头发，不能防摔。"}, {"text": "骑车时她戴上发网，保护头部。", "explanation": "这里应该用〈头盔〉。头盔能保护头部，发网只是套住头发，不能保护头部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她戴上一条发网，把头发收好。", "corrected_sentence": "她戴上一个发网，把头发收好。", "error_description": "量词错误：发网的量词应是“个”，“条”用于细长的东西。应改为“一个发网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈戴上一条发网，才出门。", "corrected_sentence": "妈妈戴上一个发网，才出门。", "error_description": "量词错误：发网的量词应是“个”，“条”用于细长的东西。应改为“一个发网”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
