INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "套在头上，使头发不散乱的网罩。", "primary_collocate": null, "pronunciation": "fà wǎng", "ipa": "fa˥˩ waŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "护士上班要戴发网，头发才不会乱。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的工作人员都得戴发网。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前她在头上套了一个发网。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸笑着说：“你戴发网的样子很有意思。”", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂给每个工人发了一个发网。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，可是她戴着发网，头发没有乱。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发网是用细线做的，很轻。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩不喜欢戴发网，觉得头上不舒服。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买发网的时候，要选和头发一样的颜色。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员化好妆后，化妆师给她套上了发网。", "target_word": "发网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "發網", "label": "繁体"}], "register": "中性", "sense_fingerprint": "套在头上、让头发不散乱的网罩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '033c0cfc-c92b-48c7-a29c-413bfae576b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97522, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发网", "is_correct": true, "explanation": "正确：发网（fà wǎng）指套在头上、让头发不散乱的网罩。"}, {"text": "发往", "is_correct": false, "explanation": "发往 fā wǎng 第一音节是第一声，与 fà 声调不同，意思是“发送到”。"}, {"text": "放网", "is_correct": false, "explanation": "放网 fàng wǎng 第一音节多了韵尾 ng，声调相同，意思是“撒网”。"}, {"text": "法网", "is_correct": false, "explanation": "法网 fǎ wǎng 第一音节是第三声，与 fà 声调不同，指法律的约束。"}], "explanations": {"发网": "正确：发网（fà wǎng）指套在头上、让头发不散乱的网罩。", "发往": "发往 fā wǎng 第一音节是第一声，与 fà 声调不同，意思是“发送到”。", "放网": "放网 fàng wǎng 第一音节多了韵尾 ng，声调相同，意思是“撒网”。", "法网": "法网 fǎ wǎng 第一音节是第三声，与 fà 声调不同，指法律的约束。"}, "sentence_index": null, "correct_answer": "发网"}, "level_3": {"options": [{"text": "手套", "is_correct": false, "explanation": "语义：手套戴在手上，不能让头发不乱。"}, {"text": "耳环", "is_correct": false, "explanation": "语义：耳环戴在耳朵上，与头发乱不乱无关。"}, {"text": "肩带", "is_correct": false, "explanation": "搭配：“戴”不与“肩带”搭配，应说“背”或“系”。"}, {"text": "发网", "is_correct": true, "explanation": "正确：发网套在头上，能让头发不乱，符合语境。"}], "explanations": {"手套": "语义：手套戴在手上，不能让头发不乱。", "耳环": "语义：耳环戴在耳朵上，与头发乱不乱无关。", "肩带": "搭配：“戴”不与“肩带”搭配，应说“背”或“系”。", "发网": "正确：发网套在头上，能让头发不乱，符合语境。"}, "sentence_index": 0, "correct_answer": "发网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用发网把钥匙包起来，放进口袋。", "explanation": "这里应该用〈钥匙包〉。钥匙包用来装钥匙，发网是套在头上的网，不能用来包钥匙。"}, {"text": "她把发网别在鬓角上。", "explanation": "这里应该用〈发夹〉。发夹可以别在鬓角上，发网是套住头发的，不能用来别。"}, {"text": "护士戴上发网，遮住口鼻，防止感染。", "explanation": "这里应该用〈口罩〉。口罩能遮住口鼻，发网只是套住头发，不能遮口鼻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "铁块", "is_correct": false, "explanation": "语义：铁块很重，不是用细线做的，与“很轻”矛盾。"}, {"text": "钢筋", "is_correct": false, "explanation": "语义：钢筋是建筑材料，不是用细线做的。"}, {"text": "发网", "is_correct": true, "explanation": "正确：发网是用细线做成的，很轻，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是用细线做的，也不会很轻。"}], "explanations": {"铁块": "语义：铁块很重，不是用细线做的，与“很轻”矛盾。", "钢筋": "语义：钢筋是建筑材料，不是用细线做的。", "发网": "正确：发网是用细线做成的，很轻，符合语境。", "石头": "语义：石头不是用细线做的，也不会很轻。"}, "sentence_index": 6, "correct_answer": "发网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "骑车时要戴上发网，保护头部。", "explanation": "这里应该用〈头盔〉。头盔能保护头部，发网只是把头发收拢，不能保护头部。"}, {"text": "夏天出门戴发网遮阳。", "explanation": "这里应该用〈帽子〉。帽子能遮阳，发网只能收拢头发。"}, {"text": "天冷时她戴上发网暖手。", "explanation": "这里应该用〈手套〉。手套能保暖双手，发网只能套住头发，不能暖手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士戴上一条发网，头发才不会乱。", "corrected_sentence": "护士戴上一个发网，头发才不会乱。", "error_description": "量词错误：发网的量词应是“个”，“条”用于细长的东西。应改为“一个发网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨师戴上一根发网，才进厨房。", "corrected_sentence": "厨师戴上一个发网，才进厨房。", "error_description": "量词错误：发网的量词应是“个”，“根”用于细长的东西。应改为“一个发网”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51bd7276-5d92-4802-b3fc-63ae7a7518ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
