INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里很坏很吓人的怪物。", "primary_collocate": null, "pronunciation": "mó guǐ", "ipa": "mwo˧˥ kweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "故事里的魔鬼住在黑山上。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小弟弟怕魔鬼，晚上不敢关灯。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里有一个很大的魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王把魔鬼关进了山洞里。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的魔鬼有红眼睛和长牙。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英雄打败了魔鬼，大家都很高兴。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们听着魔鬼的故事，不敢睡觉。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一个有两只角的魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说，这座山以前有过魔鬼。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔鬼在夜里出来，吓坏了村里人。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小魔鬼", "label": "复合"}], "register": "中性", "sense_fingerprint": "童话、电影、故事里又坏又吓人的怪物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：魔鬼是故事里的怪物，可以住在黑山上。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“住”需要有生命的主体，电脑是机器，不能住在山上。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“住”不搭配“汽车”，汽车只能停在山上。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不会住在黑山上。"}], "explanations": {"魔鬼": "正确：魔鬼是故事里的怪物，可以住在黑山上。", "电脑": "语义：“住”需要有生命的主体，电脑是机器，不能住在山上。", "汽车": "搭配：“住”不搭配“汽车”，汽车只能停在山上。", "面包": "语义：面包是食物，不会住在黑山上。"}, "sentence_index": 0, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "圣诞夜，魔鬼悄悄给孩子们送来礼物。", "explanation": "这里应该用〈天使〉。魔鬼是凶恶的怪物，不会悄悄给孩子送礼物；带来礼物和祝福的要说天使。"}, {"text": "天上的魔鬼很善良，常常保佑人们。", "explanation": "这里应该用〈神仙〉。魔鬼是凶恶的怪物，不能说“很善良，常常保佑人们”。"}, {"text": "农夫在田边摆上供品，向魔鬼祈求丰收。", "explanation": "这里应该用〈土地公〉。魔鬼是凶恶的怪物，不能用来保佑丰收；求丰收要向土地公祈求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：魔鬼是让孩子害怕的怪物，所以他们不敢睡觉。"}, {"text": "糖果", "is_correct": false, "explanation": "语义：糖果的故事通常温馨，不会让孩子不敢睡觉。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气的故事一般不吓人，不会让孩子们不敢睡觉。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是日常用品，牙刷的故事不会让孩子害怕得不敢睡觉。"}], "explanations": {"魔鬼": "正确：魔鬼是让孩子害怕的怪物，所以他们不敢睡觉。", "糖果": "语义：糖果的故事通常温馨，不会让孩子不敢睡觉。", "天气": "语义：天气的故事一般不吓人，不会让孩子们不敢睡觉。", "牙刷": "语义：牙刷是日常用品，牙刷的故事不会让孩子害怕得不敢睡觉。"}, "sentence_index": 6, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "魔鬼挥了挥魔棒，帮灰姑娘变出了漂亮的衣服。", "explanation": "这里应该用〈仙女〉。魔鬼是又坏又吓人的怪物，不会好心帮灰姑娘变衣服；帮助别人的是仙女。"}, {"text": "魔鬼住在山上，一直保护村里人的平安。", "explanation": "这里应该用〈山神〉。魔鬼是凶恶的怪物，不会保护村民；保护一方平安的是山神。"}, {"text": "魔鬼长得又小又可爱，孩子们都想抱抱它。", "explanation": "这里应该用〈小精灵〉。魔鬼又坏又吓人，不会让孩子们想抱它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在山洞里看见了个一魔鬼。", "corrected_sentence": "他在山洞里看见了一个魔鬼。", "error_description": "语序错误：数量短语应说“一个”，不能说“个一”，应把“个一”改为“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里来了一条魔鬼，大家都躲了起来。", "corrected_sentence": "村里来了一个魔鬼，大家都躲了起来。", "error_description": "量词错误：“条”用于细长的东西，魔鬼要用“个”，应把“条”改为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "比喻极坏、极残忍的人。", "primary_collocate": null, "pronunciation": "mó guǐ", "ipa": "mwo˧˥ kweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那个人对动物很残忍，简直是魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏人像魔鬼一样，什么坏事都做。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对孩子那么狠，简直是魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都知道他杀过人，说他是魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人说那个独裁者是魔鬼，会毁掉一切。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他天天打人骂人，大家都叫他魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个骗子是个魔鬼，骗光了老人的钱。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小偷是个魔鬼，连穷人的钱也偷。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把前夫看成魔鬼，再也不想见他。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在受害者眼里，他就是魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小魔鬼", "label": "复合"}], "register": "中性", "sense_fingerprint": "比喻义：形容极坏、极残忍的人，常说“简直是魔鬼”“像魔鬼一样”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：“魔鬼”比喻极坏、极残忍的人，与“对动物很残忍”相符。"}, {"text": "天使", "is_correct": false, "explanation": "语义：“天使”比喻善良的人，与“很残忍”矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能用来形容残忍的人。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能用来比喻残忍的人。"}], "explanations": {"魔鬼": "正确：“魔鬼”比喻极坏、极残忍的人，与“对动物很残忍”相符。", "天使": "语义：“天使”比喻善良的人，与“很残忍”矛盾。", "桌子": "语义：桌子是家具，不能用来形容残忍的人。", "太阳": "语义：太阳不能用来比喻残忍的人。"}, "sentence_index": 0, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人心地善良，总是像魔鬼一样帮助大家。", "explanation": "这里应该用〈天使〉。魔鬼指极坏的人，与“心地善良、帮助大家”矛盾。"}, {"text": "这位老师是个魔鬼，从不骂学生。", "explanation": "这里应该用〈好人〉。魔鬼指极坏的人，与“从不骂学生”矛盾。"}, {"text": "这位医生是魔鬼，一生都在救治穷人。", "explanation": "这里应该用〈圣人〉。魔鬼指极坏的人，与“一生救治穷人”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：“魔鬼”指极坏的人，与“骗子”和“骗光了钱”相符。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使善良，与“骗光了老人的钱”矛盾。"}, {"text": "好人", "is_correct": false, "explanation": "语义：“好人”与“骗子”的身份矛盾。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“是个……”后的名词要能指人，“小猫”不能是骗子。"}], "explanations": {"魔鬼": "正确：“魔鬼”指极坏的人，与“骗子”和“骗光了钱”相符。", "天使": "语义：天使善良，与“骗光了老人的钱”矛盾。", "好人": "语义：“好人”与“骗子”的身份矛盾。", "小猫": "搭配：“是个……”后的名词要能指人，“小猫”不能是骗子。"}, "sentence_index": 6, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他天天照顾生病的邻居，真是个魔鬼。", "explanation": "这里应该用〈好人〉。魔鬼比喻极坏的人，与“天天照顾生病的邻居”矛盾。"}, {"text": "妈妈对我们特别温柔，是家里的魔鬼。", "explanation": "这里应该用〈天使〉。魔鬼比喻极坏的人，与“特别温柔”矛盾。"}, {"text": "这位警察救了很多人，大家都说他是魔鬼。", "explanation": "这里应该用〈英雄〉。魔鬼比喻极坏的人，与“救了很多人”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人简直是个一魔鬼，常常欺负弱小的孩子。", "corrected_sentence": "那个人简直是一个魔鬼，常常欺负弱小的孩子。", "error_description": "语序错误：数量短语应说“一个”，不能说“个一”，应把“个一”改为“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个老板是一颗魔鬼，工人们都很害怕他。", "corrected_sentence": "那个老板是个魔鬼，工人们都很害怕他。", "error_description": "量词错误：“颗”用于颗粒状的东西，指人要用“个”，应把“颗”改为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
